  if (!recs.length) return '';
  // (Ya viene ordenado globalmente desde bn_render; no re-ordenar la página.)
  const CUENTA_EMOJI = { Egresos:'💸', Ingresos:'💰', Activos:'📈', Pasivos:'📋', Capital:'💼' };
