/** Lista historial de reservaciones del mismo celular. */
/** Suma Gross (Total Líneas de cobro Lodgify) de los bookings del mismo
 *  teléfono cuya fecha de llegada caiga dentro del rango [ingreso, salida].
 *  Devuelve null si no encuentra ningún booking (para caer al fallback). */
function huComputeLodgifyGrossForStay(reservacion, ingresoRaw, salidaRaw) {
  const bookings = (typeof LG_STATE !== 'undefined' && LG_STATE && Array.isArray(LG_STATE.bookings))
    ? LG_STATE.bookings : [];
  if (!bookings.length) return null;
  const phone10 = (function(){
    const s = String(huValueFlexible(reservacion, ['Cel/Whatsapp (principal)','Cel/Whatsapp','Celular']) || '').replace(/\D/g,'');
    return s.length >= 10 ? s.slice(-10) : '';
  })();
  if (!phone10) return null;
  const toIso = (raw) => {
    if (!raw) return '';
    const s = String(raw).trim();
    let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (m) return `${m[1]}-${m[2]}-${m[3]}`;
    m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    if (m) return `${m[3]}-${String(m[1]).padStart(2,'0')}-${String(m[2]).padStart(2,'0')}`;
    return '';
  };
  const ingIso = toIso(ingresoRaw);
  const salIso = toIso(salidaRaw);
  if (!ingIso || !salIso) return null;
  let sum = 0; let matched = 0;
  for (const b of bookings) {
    const bPhone10 = String(b.GuestPhone || '').replace(/\D/g,'').slice(-10);
    if (bPhone10 !== phone10) continue;
    const bArrIso = toIso(b.DateArrival);
    if (!bArrIso) continue;
    if (bArrIso >= ingIso && bArrIso <= salIso) {
      sum += Number(b.Gross) || 0;
      matched++;
    }
  }
  return matched > 0 ? sum : null;
}

function huBuildHistoryList(currentR, allRows, selectedRecId, outerCardRecId) {
  const phoneTail = (v) => {
    const s = String(v || '').replace(/\D/g, '');
    return s.length >= 10 ? s.slice(-10) : '';
  };
  // La lista de "Reservas totales" SIEMPRE se basa en la fila del card
  // padre (sidebar), NO en la que el usuario acaba de clickear adentro.
  // Si clickea una probable con celular distinto, no queremos que el
  // historial se rebuilde alrededor de ese teléfono y pierda el contexto.
  const _allRowsSrc = allRows || HU_STATE.rows || [];
  const outerR = outerCardRecId
    ? (_allRowsSrc.find(x => String(x['ID']||x['row_number']||'') === String(outerCardRecId)) || currentR)
    : currentR;
  const cel  = huValueFlexible(outerR, ['Cel/Whatsapp (principal)']);
  const tail = phoneTail(cel);
  // 1) Match exacto por teléfono del outerR. Si no tiene celular, al menos
  //    incluimos outerR para que el matching por propiedad+fechas funcione.
  let exactList = _allRowsSrc.filter(x =>
    tail && phoneTail(huValueFlexible(x, ['Cel/Whatsapp (principal)'])) === tail);
  const _outerId = String(outerR['ID']||outerR['row_number']||'');
  if (!exactList.some(x => String(x['ID']||x['row_number']||'') === _outerId)) {
    exactList = [outerR, ...exactList];
  }
  // 2) Match probable: misma propiedad + fechas exactas, teléfono distinto
  const _exactIds = new Set(exactList.map(x => String(x['ID']||x['row_number']||'')));
  const _propDateKeys = new Set();
  for (const x of exactList) {
    const pk = (typeof lgNormPropName === 'function') ? lgPropDeptKey(huValueFlexible(x, ['Propiedad']), huValueFlexible(x, ['# Departamento','Departamento'])) : String(huValueFlexible(x, ['Propiedad'])||'').toLowerCase().trim();
    const ar = String(huValueFlexible(x, ['Fecha de ingreso'])||'').slice(0,10);
    const dp = String(huValueFlexible(x, ['Fecha de salida'])||'').slice(0,10);
    if (pk && ar && dp) _propDateKeys.add(`${pk}|${ar}|${dp}`);
  }
  const probableList = _allRowsSrc.filter(x => {
    const xid = String(x['ID']||x['row_number']||'');
    if (_exactIds.has(xid)) return false;
    const pk = (typeof lgNormPropName === 'function') ? lgPropDeptKey(huValueFlexible(x, ['Propiedad']), huValueFlexible(x, ['# Departamento','Departamento'])) : String(huValueFlexible(x, ['Propiedad'])||'').toLowerCase().trim();
    const ar = String(huValueFlexible(x, ['Fecha de ingreso'])||'').slice(0,10);
    const dp = String(huValueFlexible(x, ['Fecha de salida'])||'').slice(0,10);
    if (!pk || !ar || !dp) return false;
    return _propDateKeys.has(`${pk}|${ar}|${dp}`);
  });
  const _probIds = new Set(probableList.map(x => String(x['ID']||x['row_number']||'')));
  const list = [...exactList, ...probableList];
  list.sort((a, b) => {
    const da = huValueFlexible(a, ['Fecha de ingreso']) || '';
    const db = huValueFlexible(b, ['Fecha de ingreso']) || '';
    return db.localeCompare(da);
  });
  // Color por grupo (mismo prop+fechas con >1 fila)
  const _palette = ['#a78bfa','#f472b6','#34d399','#fb923c','#60a5fa','#facc15'];
  const _groupOfId = new Map();
  const _groupCount = new Map();
  list.forEach(x => {
    const xid = String(x['ID']||x['row_number']||'');
    const pk = (typeof lgNormPropName === 'function') ? lgPropDeptKey(huValueFlexible(x, ['Propiedad']), huValueFlexible(x, ['# Departamento','Departamento'])) : String(huValueFlexible(x, ['Propiedad'])||'').toLowerCase().trim();
    const ar = String(huValueFlexible(x, ['Fecha de ingreso'])||'').slice(0,10);
    const dp = String(huValueFlexible(x, ['Fecha de salida'])||'').slice(0,10);
    if (!pk || !ar || !dp) return;
    const gk = `${pk}|${ar}|${dp}`;
    _groupOfId.set(xid, gk);
    _groupCount.set(gk, (_groupCount.get(gk)||0)+1);
  });
  const _colorOfGroup = new Map();
  let _pi = 0;
  for (const [gk, n] of _groupCount) {
    if (n > 1) { _colorOfGroup.set(gk, _palette[_pi % _palette.length]); _pi++; }
  }
  // Identificar el "winner" (manual reg) por grupo, para el botón Unificar.
  const winnerOfGroup = new Map();
  list.forEach(x => {
    const xid = String(x['ID']||x['row_number']||'');
    const gk  = _groupOfId.get(xid) || '';
    if (!gk) return;
    const hasManual = (typeof huHasManualRegistration === 'function')
      ? huHasManualRegistration(x)
      : !!huValueFlexible(x, ['Nombres de TODOS los huéspedes (separados por comas)']);
    const cur = winnerOfGroup.get(gk);
    if (!cur) { winnerOfGroup.set(gk, { id: xid, manual: hasManual, row: x }); return; }
    // Preferir manual; en empate, fila con mayor ID por longitud (= la real)
    if (hasManual && !cur.manual) winnerOfGroup.set(gk, { id: xid, manual: true, row: x });
  });
  const itemsArr = list.map(x => {
    const xid     = String(x['ID'] || x['row_number'] || '');
    // Lookup del booking Lodgify vinculado: Lodgify es source-of-truth para
    // fechas/noches (cuando el huésped extiende). Caemos a la fila de
    // Reservaciones solo si no hay Lodgify Id o no se encuentra el booking.
    const _lodId = String(x['Lodgify Id'] || '').trim();
    const _lg    = _lodId
      ? ((LG_STATE.bookings || []).find(bk => String(bk.Id) === _lodId) || null)
      : null;
    const ingreso = (_lg && _lg.DateArrival)   || huValueFlexible(x, ['Fecha de ingreso']);
    const salida  = (_lg && _lg.DateDeparture) || huValueFlexible(x, ['Fecha de salida']);
    // Propiedad/Departamento: Lodgify es source-of-truth. Si el booking
    // vinculado existe, usamos lgPropOf(b) que resuelve "Propiedad - #Depto"
    // a partir de HouseId/HouseName. Si no, caemos al sheet.
    let prop = '', depto = '';
    if (_lg && typeof lgPropOf === 'function') {
      const _full = lgPropOf(_lg) || '';
      const _m = _full.match(/^(.*?)\s*-\s*#\s*([\w-]+)\s*$/);
      if (_m) { prop = _m[1].trim(); depto = _m[2].trim(); }
      else    { prop = _full; depto = ''; }
    } else {
      prop  = huValueFlexible(x, ['Propiedad']);
      depto = huValueFlexible(x, ['# Departamento']);
    }
    let   noches  = (_lg && Number(_lg.Nights) > 0) ? String(_lg.Nights) : huValueFlexible(x, ['# Noches']);
    // Si ingreso/salida vienen en Lodgify MM/DD/YYYY, huParseDate los interpreta
    // como DD/MM/YYYY (bug). Normalizar a ISO YYYY-MM-DD vía lgFmtDateUI.
    const _ingIso = (typeof lgFmtDateUI === 'function') ? lgFmtDateUI(ingreso) : ingreso;
    const _salIso = (typeof lgFmtDateUI === 'function') ? lgFmtDateUI(salida)  : salida;
    if (!noches || Number(noches) <= 0) {
      const di = huParseDate(_ingIso); const ds = huParseDate(_salIso);
      if (di && ds) {
        const n = Math.max(0, Math.round((ds - di) / 86400000));
        if (n > 0) noches = String(n);
      }
    }
    // Monto: prioridad 1 = Lodgify "Total" (Líneas de cobro = b.Gross) del
    // booking vinculado vía "Lodgify Id". Prioridad 2 (fallback) =
    // "$ Monto facturado Total" del sheet. Para reservaciones que no
    // tienen relación con Lodgify, sólo aplica el fallback.
    let monto = '';
    const lodId = String(x['Lodgify Id'] || '').trim();
    if (lodId) {
      const lg = (LG_STATE.bookings || []).find(bk => String(bk.Id) === lodId);
      if (lg && Number(lg.Gross) > 0) monto = String(lg.Gross);
    }
    if (!monto) monto = String(huValueFlexible(x, ['$ Monto facturado Total','($) Monto Total pagado']) || '');
    const status  = huGetFacturaStatus(x);
    const isSel   = xid === selectedRecId;
    // El punto representa estado de la estancia (no de la factura):
    // verde = en curso, gris = concluida, azul = próxima.
    // IMPORTANTE: usar _ingIso/_salIso (ya normalizados por lgFmtDateUI). Si
    // pasamos las fechas raw en formato Lodgify MM/DD/YYYY, huParseDate las
    // interpreta como DD/MM/YYYY y calcula estados invertidos (Próxima↔Concluida).
    const stayState = huGetStayState(_ingIso, _salIso);
    const dotMeta   = HU_STAY_DOT[stayState] || HU_STAY_DOT[''];
    const dotColor  = dotMeta.color;
    const dotTitle  = dotMeta.label;
    // Verde "Activa" pulsa suave; rojo "Salida hoy" pulsa más fuerte para llamar la atención.
    const dotPulse  = stayState === 'activa'      ? 'animation:hu-dot-pulse 1.4s ease-in-out infinite;'
                    : stayState === 'salida_hoy'  ? 'animation:hu-dot-pulse-strong 1s ease-in-out infinite;'
                    : stayState === 'entrada_hoy' ? 'animation:hu-dot-pulse 1.4s ease-in-out infinite;'
                    : '';
    const lgStateMeta = (typeof LG_STATE_META !== 'undefined') ? (LG_STATE_META[stayState] || LG_STATE_META.concluida) : null;
    const progBorder = lgStateMeta ? lgStateMeta.border : '#e2e8f0';
    // Chip Ticket (arriba de las fechas):
    //   · emitida → BOTÓN "Ver ticket - Folio #X" (link al ticketUrl)
    //   · pendiente Y ¿Requiere factura?=Sí → CHIP "Pendiente"
    //   · otro → nada
    const folioHist  = huValueFlexible(x, ['Folio facturapi','Folio Facturapi','Folio']);
    const reqFacHist = huValueFlexible(x, ['¿Requiere factura?']);
    const ticketUrlHist = (typeof huExtractTicketUrl === 'function') ? huExtractTicketUrl(x) : '';
    const medioHist    = String(huValueFlexible(x, ['Medio de emisión','Medio de emision']) || '').trim();
    let ticketChipHtml = '';
    if (status === 'emitida') {
      const lbl = `🧾 Ver ticket${folioHist ? ' - Folio #' + esc(folioHist) : ''}`;
      ticketChipHtml = ticketUrlHist
        ? `<a href="${esc(ticketUrlHist)}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="display:inline-block;padding:3px 9px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:800;font-size:9px;border:1px solid #86efac;text-decoration:none;letter-spacing:.02em">${lbl}</a>`
        : `<span style="display:inline-block;padding:3px 9px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:800;font-size:9px;border:1px solid #86efac;letter-spacing:.02em">${lbl}</span>`;
      // Chip que distingue si el ticket lo generó el HUÉSPED (auto-facturación,
      // color violeta) o el SISTEMA/admin (facturación sistema, color índigo).
      if (medioHist) {
        const isAuto = /auto/i.test(medioHist);
        const bg = isAuto ? '#ede9fe' : '#e0f2fe';
        const fg = isAuto ? '#5b21b6' : '#0369a1';
        const bd = isAuto ? '#c4b5fd' : '#7dd3fc';
        const emoji = isAuto ? '👤' : '🖥️';
        ticketChipHtml += ` <span title="Origen del ticket" style="display:inline-block;padding:3px 8px;border-radius:999px;background:${bg};color:${fg};font-weight:800;font-size:9px;border:1px solid ${bd};letter-spacing:.02em">${emoji} ${esc(medioHist)}</span>`;
      }
    } else if (status === 'pendiente' || /s[ií]/i.test(String(reqFacHist||''))) {
      ticketChipHtml = `<span style="display:inline-block;padding:3px 9px;border-radius:999px;background:#fff7ed;color:#c2410c;font-weight:800;font-size:9px;border:1px solid #fdba74;letter-spacing:.02em">🧾 Pendiente</span>`;
    }
    // Aseo Breezeway: busca task de housekeeping ligada a Lodgify Id
    let aseoChipHtml = '';
    if (lodId && typeof BZW_ALL_TASKS !== 'undefined' && BZW_ALL_TASKS.length) {
      if (!BZW_IDX_BY_LODID) { try { bzwBuildTaskIndexes_(); } catch(_) {} }
      const linkedB = (BZW_IDX_BY_LODID && BZW_IDX_BY_LODID.get(String(lodId))) || [];
      if (linkedB.length) {
        const scoreB = (tk) => {
          const dept = String(tk.task?.type || tk.raw?.type_department || '').toLowerCase();
          const nm = String(tk.task?.name || '').toLowerCase();
          let s = 0;
          if (dept === 'housekeeping') s += 10;
          if (/checkout|limpieza/.test(nm)) s += 5;
          if (tk.task?.finished_at) s += 1;
          return s;
        };
        linkedB.sort((a, b) => scoreB(b) - scoreB(a));
        const tk = linkedB[0];
        const tFinished = !!tk.task?.finished_at;
        let fechaTermStr = '';
        if (tFinished && tk.task.finished_at) {
          const d = new Date(tk.task.finished_at);
          if (!isNaN(d.getTime())) {
            fechaTermStr = `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
          }
        }
        // Chip de asignaciones (operarios asignados, nombres únicos abreviados)
        const tkAssignNames = Array.isArray(tk.raw?.assignments)
          ? Array.from(new Set(tk.raw.assignments.map(x => x?.full_name || x?.name).filter(Boolean)))
          : [];
        let tkAssignDisplay = '';
        if (tkAssignNames.length) {
          tkAssignDisplay = tkAssignNames.length <= 2
            ? tkAssignNames.join(', ')
            : `${tkAssignNames.slice(0,2).join(', ')} +${tkAssignNames.length - 2}`;
        }
        const asignacionesChip = tkAssignDisplay
          ? `<span title="Asignaciones: ${esc(tkAssignNames.join(', '))}" style="display:inline-block;padding:2px 8px;border-radius:999px;background:#fff7ed;color:#9a3412;font-weight:700;font-size:9px;border:1px solid #fdba74;letter-spacing:.02em;max-width:160px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">👥 ${esc(tkAssignDisplay)}</span>`
          : '';
        const _rt = tk.task?.guest_rating ?? tk.raw?.guest_rating ?? null;
        const _starsMini = (typeof bzwBuildGuestStarsChip === 'function') ? bzwBuildGuestStarsChip(_rt, { compact: true }) : '';
        aseoChipHtml = `
          <div style="margin-top:6px;display:flex;flex-direction:column;align-items:flex-end;gap:3px">
            ${tFinished
              ? '<span style="display:inline-block;padding:2px 8px;border-radius:999px;background:#dcfce7;color:#15803d;font-weight:800;font-size:9px;border:1px solid #86efac;letter-spacing:.02em">✓ Aseo · Finalizada</span>'
              : '<span style="display:inline-block;padding:2px 8px;border-radius:999px;background:#fee2e2;color:#b91c1c;font-weight:800;font-size:9px;border:1px solid #fca5a5;letter-spacing:.02em">✗ Aseo · Pendiente</span>'}
            ${_starsMini}
            ${asignacionesChip}
            ${fechaTermStr ? `<span style="font-size:9px;color:#64748b;font-weight:700;letter-spacing:.02em">${esc(fechaTermStr)}</span>` : ''}
          </div>`;
      }
    }
    const _gk = _groupOfId.get(xid) || '';
    const _gColor = _gk ? (_colorOfGroup.get(_gk) || '') : '';
    const _isProb = _probIds.has(xid);
    const _xCel = String(huValueFlexible(x, ['Cel/Whatsapp (principal)','Celular principal']) || '');
    const _groupBar = _gColor ? `box-shadow:inset 4px 0 0 ${_gColor};` : '';
    const _linkChip = _gColor
      ? `<span title="Esta card está relacionada con otra(s) del grupo (misma propiedad y fechas)" style="display:inline-flex;align-items:center;gap:3px;padding:1px 7px;border-radius:999px;background:${_gColor}22;color:#334155;font-weight:800;font-size:9px;border:1px solid ${_gColor}"><span style="color:${_gColor};font-size:11px;line-height:1">⇄</span> RELACIONADA</span>`
      : '';
    const _probChip = _isProb ? `<span style="font-size:9px;padding:1px 7px;border-radius:999px;background:#fef3c7;color:#92400e;font-weight:800;letter-spacing:.04em;border:1px solid #fcd34d">⚠ PROBABLE</span>` : '';
    const _xLodId = String(x['Lodgify Id'] || '').trim();
    return `
      <div onclick="event.stopPropagation();huSelectReservation('${esc(outerCardRecId)}','${esc(xid)}')"
           data-hu-history-id="${esc(xid)}"
           class="hu-history-item ${isSel?'hu-history-active':''}"
           style="position:relative;padding:11px 11px 11px 13px;border:none;border-left:7px solid ${progBorder};border-radius:10px;cursor:pointer;background:#fff;${_groupBar}transition:all 180ms cubic-bezier(.16,1,.3,1);${isSel?'box-shadow:0 4px 14px rgba(15,23,42,.14)'+(_gColor?', inset 4px 0 0 '+_gColor:'')+';transform:translateX(3px)':_gColor?'box-shadow:0 1px 2px rgba(15,23,42,.06), inset 4px 0 0 '+_gColor:'box-shadow:0 1px 2px rgba(15,23,42,.06)'}"
           onmouseover="if(!this.classList.contains('hu-history-active')){this.style.boxShadow='0 4px 10px rgba(15,23,42,.10)'+(${_gColor?`', inset 4px 0 0 ${_gColor}'`:`''`});this.style.transform='translateX(2px)'}"
           onmouseout="if(!this.classList.contains('hu-history-active')){this.style.boxShadow='0 1px 2px rgba(15,23,42,.06)'+(${_gColor?`', inset 4px 0 0 ${_gColor}'`:`''`});this.style.transform=''}">
        <button onclick="event.stopPropagation();lgHideCard('${esc(_xLodId)}','${esc(xid)}')"
                title="Ocultar esta reserva del frontend"
                style="position:absolute;top:4px;left:4px;z-index:5;width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;border:1px solid #fecaca;background:#fff;color:#dc2626;font-size:11px;font-weight:900;line-height:1;cursor:pointer;box-shadow:0 1px 2px rgba(15,23,42,.08)">×</button>
        ${(_linkChip || _probChip) ? `<div style="margin-bottom:6px;display:flex;gap:4px;flex-wrap:wrap;padding-left:22px">${_linkChip}${_probChip}</div>` : `<div style="height:18px"></div>`}
        ${_isProb && _xCel ? `<div style="font-size:10px;color:#92400e;margin-bottom:4px">📱 ${esc(_xCel)} <span style="color:#94a3b8">(celular distinto)</span></div>` : ''}
        ${ticketChipHtml ? `<div style="margin-bottom:6px">${ticketChipHtml}</div>` : ''}
        <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:4px;gap:8px">
          <div style="font-size:11px;font-weight:800;color:#1f2937;letter-spacing:.02em">${huFmtFecha(ingreso)} → ${huFmtFecha(salida)}</div>
          <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px">
            <span style="display:inline-flex;align-items:center;gap:5px" title="${dotTitle}">
              <span style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${dotColor};box-shadow:0 0 0 2px rgba(255,255,255,.7);${dotPulse}"></span>
              <span style="font-size:9px;font-weight:700;color:${dotColor};text-transform:uppercase;letter-spacing:.04em">${esc(dotTitle)}</span>
            </span>
            ${(() => {
              const co = lgFindCheckoutFor_(prop, depto, _salIso);
              if (!co) return '';
              const coTitle = co['Comentarios'] ? `Check-out registrado. Comentarios: ${String(co['Comentarios']).replace(/"/g,'&quot;')}` : 'Check-out registrado';
              return `<span title="${esc(coTitle)}" style="display:inline-block;padding:2px 8px;border-radius:999px;background:#dc2626;color:#fff;font-weight:800;font-size:9px;letter-spacing:.04em">🚪 Check-out</span>`;
            })()}
            ${aseoChipHtml}
          </div>
        </div>
        <div style="font-size:11px;color:#64748b;font-weight:600">${esc(prop || '—')}${depto?' · # '+esc(depto):''}</div>
        <div style="display:flex;align-items:center;justify-content:space-between;margin-top:4px">
          <span style="font-size:10px;color:#94a3b8">${esc(noches||'—')} noche${String(noches)==='1'?'':'s'}</span>
          ${monto ? `<span style="font-size:11px;font-weight:700;color:#0f766e">${huFmtMonto(monto)}</span>` : '<span style="font-size:11px;color:#94a3b8;font-weight:700">N/A</span>'}
        </div>
      </div>`;
  });
  // Juntar items intercalando botón "↕ Unificar" entre cards del mismo grupo
  const items = list.map((x, i) => {
    const xid  = String(x['ID']||x['row_number']||'');
    const html = itemsArr[i];
    if (i === 0) return html;
    const prevX = list[i-1];
    const prevId = String(prevX['ID']||prevX['row_number']||'');
    const gk     = _groupOfId.get(xid) || '';
    const gkPrev = _groupOfId.get(prevId) || '';
    if (!gk || gk !== gkPrev || !_colorOfGroup.get(gk)) return html;
    // Pareja del mismo grupo → insertar botón Unificar antes de esta card.
    const w = winnerOfGroup.get(gk);
    if (!w) return html;
    const winnerId = w.id;
    const loserId  = (winnerId === xid) ? prevId : xid;
    const gColor   = _colorOfGroup.get(gk);
    const unifyBtn = `
      <div style="display:flex;justify-content:center;margin:-2px 0 4px 0;position:relative">
        <button onclick="event.stopPropagation();lgUnifyReservaciones('${esc(winnerId)}','${esc(loserId)}')"
                title="Unificar estas dos reservaciones: llena los campos faltantes del registro manual con los del registro de Lodgify y oculta el de Lodgify"
                style="display:inline-flex;align-items:center;gap:5px;padding:3px 10px;border:1.5px solid ${gColor};background:#fff;color:#334155;border-radius:999px;font-size:10px;font-weight:800;letter-spacing:.04em;cursor:pointer;box-shadow:0 1px 4px rgba(15,23,42,.08);text-transform:uppercase">
          <span style="display:inline-flex;flex-direction:column;line-height:.8;color:${gColor}">
            <span style="font-size:9px">▲</span>
            <span style="font-size:9px">▼</span>
          </span>
          Unificar
        </button>
      </div>`;
    return unifyBtn + html;
  }).join('');

  // Estado por-card del colapso (persistente en sesión). Mobile: colapsado
  // por default; desktop: expandido.
  const _isMobile = (typeof window !== 'undefined') && window.matchMedia && window.matchMedia('(max-width: 768px)').matches;
  if (!window.__rtCollapse) window.__rtCollapse = new Map();
  const _key = 'rt:' + outerCardRecId;
  if (!window.__rtCollapse.has(_key)) window.__rtCollapse.set(_key, _isMobile);
  const _collapsed = window.__rtCollapse.get(_key);
  return `
    <div class="hu-col-card" style="background:#fff;border-radius:16px;padding:0;color:#0f172a;box-shadow:0 4px 16px rgba(15,23,42,.08);position:relative;overflow:hidden;border:1.5px solid #e2e8f0">
      <div style="height:4px;background:linear-gradient(90deg,#10b981,#06b6d4,#3b82f6)"></div>
      <div style="padding:14px 16px">
        <div onclick="window.__rtToggle('${esc(_key)}')" style="display:flex;align-items:center;justify-content:space-between;${_collapsed?'':'margin-bottom:12px;'}cursor:pointer;user-select:none">
          <div style="font-size:11px;letter-spacing:.18em;color:#64748b;font-weight:800;display:flex;align-items:center;gap:6px">
            <span style="font-size:14px;line-height:1;color:#94a3b8">${_collapsed?'▸':'▾'}</span>
            📚 RESERVAS TOTALES
          </div>
          <div style="display:flex;align-items:center;gap:5px">
            <div style="font-size:9px;color:#0d9488;text-transform:uppercase;font-weight:700;padding:2px 8px;background:#ccfbf1;border-radius:999px">${list.length} ${list.length===1?'reserva':'reservas'}</div>
            ${probableList.length ? `<div title="${probableList.length} reservación(es) relacionada(s) por propiedad+fechas con celular distinto" style="font-size:9px;color:#92400e;text-transform:uppercase;font-weight:800;padding:2px 8px;background:#fef3c7;border:1px solid #fcd34d;border-radius:999px;letter-spacing:.04em">+${probableList.length} probable${probableList.length===1?'':'s'}</div>` : ''}
          </div>
        </div>
        ${_collapsed ? '' : `<div style="display:flex;flex-direction:column;gap:6px;overflow-y:auto;max-height:680px;padding:8px;background:#f8fafc;border-radius:12px;border:1px solid #e2e8f0">
          ${items || '<div style="padding:20px;text-align:center;color:#94a3b8;font-size:12px;font-style:italic">Sin historial.</div>'}
        </div>`}
      </div>
    </div>`;
}
// Toggle del colapso de "Reservas totales" — preserva scroll + selección.
// __rtCollapse Map<key, boolean|null> almacena el colapsado actual.
// __rtSelected Map<key, recId> guarda la card seleccionada por card-padre,
// sobrevive el ciclo colapsar→expandir.
window.__rtSelected = window.__rtSelected || new Map();
window.__rtToggle = function(key) {
  if (!window.__rtCollapse) window.__rtCollapse = new Map();
  const cur = !!window.__rtCollapse.get(key);
  window.__rtCollapse.set(key, !cur);
  const prevY = window.scrollY;
  const rid = String(key).replace(/^rt:/, '');
  let historyCol = null;
  const evtTarget = (window.event && window.event.target) ? window.event.target : null;
  if (evtTarget) {
    const wrapper = evtTarget.closest('.hu-col-history');
    if (wrapper) historyCol = wrapper;
  }
  if (!historyCol) {
    const parentCard = document.querySelector(`.hu-record[data-record-id="${rid}"]`)
                    || document.querySelector(`.hu-record-body[data-hu-resv-id="${rid}"]`);
    historyCol = parentCard?.querySelector('.hu-col-history') || null;
  }
  if (!historyCol) {
    requestAnimationFrame(() => window.scrollTo({ top: prevY, behavior: 'instant' }));
    return;
  }
  // Antes de colapsar, capturar selección actual (si aún está en DOM).
  const activeItem = historyCol.querySelector('.hu-history-item.hu-history-active');
  if (activeItem) {
    const aid = activeItem.getAttribute('data-hu-history-id');
    if (aid) window.__rtSelected.set(key, aid);
  }
  const currentSelected = window.__rtSelected.get(key) || rid;
  const r = (HU_STATE.rows||[]).find(x => String(x['ID']||x['row_number']||'') === rid);
  if (!r || typeof huBuildHistoryList !== 'function') {
    requestAnimationFrame(() => window.scrollTo({ top: prevY, behavior: 'instant' }));
    return;
  }
  let html = huBuildHistoryList(r, HU_STATE.rows, currentSelected, rid);
  const bookingWrap = historyCol.closest('.hu-record-body');
  const bookingId = bookingWrap?.getAttribute('data-lg-booking-id');
  if (bookingId) {
    html = html.replace(/huSelectReservation\(([^)]+)\)/g, `lgHistorySelect('${esc(bookingId)}',$1)`);
  }
  historyCol.innerHTML = html;
  requestAnimationFrame(() => window.scrollTo({ top: prevY, behavior: 'instant' }));
};

/** Construye el contenido de la columna derecha (detalle de la reservación seleccionada).
 *  Incluye la caja de auto-facturación con sus inputs editables/calculados. */
/** Construye la caja "Ticket para auto-facturación" (inputs editables +
 *  cálculo Airbnb + botones). Extraída de huBuildReservationDetail para
 *  reutilizarla en la vista Detalles Lodgify (col 3 fusionada). */
function huBuildAirbnbBox(r, opts) {
  const status     = huGetFacturaStatus(r);
  const recId      = String(r['ID'] || r['row_number'] || '');
  const medio      = huValueFlexible(r, ['Medio de reservación']);
  const folio      = huValueFlexible(r, ['Folio facturapi','Folio Facturapi','Folio']);
  const ticketUrl  = huExtractTicketUrl(r);
  // "Es Airbnb" para el desglose (comisión 15.5%): se decide por la FUENTE real
  // de la reserva (Source del booking — lo que muestra el panel DETALLE), no por
  // "Medio de reservación", que es un campo editable que a veces queda en
  // "Airbnb" aunque la reserva sea Manual/otra fuente. Si el caller no pasa
  // fuente (p.ej. vista de huésped sin booking), se cae al Medio como antes.
  const fuente     = (opts && opts.source != null && String(opts.source).trim() !== '')
                       ? String(opts.source)
                       : String(medio || '');
  const esAirbnb   = fuente.toLowerCase().includes('airbnb');
  const montoFact  = huValueFlexible(r, ['$ Monto facturado Total']);
  let   montoAirbnb= huValueFlexible(r, ['$ Monto total Airbnb']);
  // Si el huésped marcó EXPLÍCITAMENTE "No" en ¿Requiere factura? y aún no
  // hay ticket emitido, NO mostramos la caja de auto-facturación (no aplica).
  const reqFactRaw = String(huValueFlexible(r, ['¿Requiere factura?','Requiere factura'])||'').trim().toLowerCase();
  const noRequiereExplicito = reqFactRaw === 'no';
  if (noRequiereExplicito && !ticketUrl && !folio) return '';
  // Auto-fill desde el Total de "Líneas de cobro" de Lodgify (opts.defaultMontoAirbnb)
  // cuando el sheet aún no tiene "$ Monto total Airbnb" y el medio es Airbnb.
  // Marcamos la caja con data-hu-airbnb-autofilled="1" para que el render
  // dispare la persistencia automática al sheet.
  let autoFilled = false;
  const defAirbnb = Number(opts && opts.defaultMontoAirbnb);
  if (esAirbnb && Number.isFinite(defAirbnb) && defAirbnb > 0 && huParseMontoAirbnb(montoAirbnb) <= 0) {
    montoAirbnb = defAirbnb.toFixed(2);
    autoFilled = true;
  }
  const airbnbVal    = esAirbnb ? huParseMontoAirbnb(montoAirbnb) : 0;
  const comisionPre  = esAirbnb && airbnbVal ? huCalcComisionAirbnb(airbnbVal).toFixed(2)        : '';
  const facturadoPre = esAirbnb && airbnbVal ? huCalcMontoFacturadoAirbnb(airbnbVal).toFixed(2) : montoFact;
  const mensajeConsulta = ticketUrl ? huBuildTicketConsultaMsg(ticketUrl) : '';
  // Botones: visibles según la disponibilidad real de los datos, no según
  // el "status" calculado (¿Requiere factura?). Esto asegura que SIEMPRE
  // se pueda generar/consultar un ticket, aunque el huésped haya marcado
  // que no requiere factura.
  const hasTicket = !!ticketUrl;
  const btnVerTicket = hasTicket ? `
    <a href="${esc(ticketUrl)}" target="_blank" rel="noopener" onclick="event.stopPropagation()"
       style="display:inline-block;padding:7px 14px;border:none;background:#16a34a;color:#fff;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer;text-decoration:none;margin-right:6px;box-shadow:0 2px 4px rgba(22,163,74,.3)">
      🧾 Ver ticket${folio ? ' - Folio #' + esc(folio) : ''}
    </a>` : '';
  const btnCopiarMsg = hasTicket && mensajeConsulta ? `
    <button type="button" onclick="event.stopPropagation();huespedesCopiarMsgConsulta(this,'${encodeURIComponent(mensajeConsulta)}')"
            style="padding:7px 14px;border:none;background:#475569;color:#fff;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer">
      📋 Copiar mensaje para consultar ticket emitido
    </button>` : '';
  // "Re-emitir ticket": archiva el folio actual en "Folio facturapi antiguo"
  // y abre Facturapi para generar uno nuevo con los mismos montos.
  const btnReemitir = hasTicket ? `
    <button type="button" onclick="event.stopPropagation();huespedesReemitirTicket('${esc(recId)}')"
            style="padding:7px 14px;border:none;background:linear-gradient(180deg,#f97316 0%,#c2410c 100%);color:#fff;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer;box-shadow:0 2px 4px rgba(194,65,12,.3)">
      🔄 Re-emitir ticket
    </button>` : '';
  const btnEnviarCorreo = hasTicket ? `
    <button type="button" onclick="event.stopPropagation();huespedesEnviarTicketCorreo('${esc(recId)}')"
            style="padding:7px 14px;border:none;background:linear-gradient(180deg,#0ea5e9 0%,#0369a1 100%);color:#fff;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer;box-shadow:0 2px 4px rgba(3,105,161,.3)">
      📧 Enviar ticket por correo
    </button>` : '';
  // "Generar Ticket" visible siempre que NO haya ticket emitido aún.
  const btnGenerar = !hasTicket ? `
    <button onclick="event.stopPropagation();huespedesGenerarTicket('${esc(recId)}')"
            style="padding:8px 22px;border:none;background:linear-gradient(180deg,#ef4444 0%,#b91c1c 100%);color:#fff;border-radius:8px;font-weight:700;font-size:13px;cursor:pointer;box-shadow:0 2px 6px rgba(185,28,28,.4)">
      Generar Ticket
    </button>` : '';
  return `
    <div data-hu-airbnb-box="1" ${autoFilled ? `data-hu-airbnb-autofilled="1" data-hu-airbnb-recid="${esc(recId)}"` : ''} style="border:1.5px solid #c4b5fd;border-radius:12px;padding:12px;background:linear-gradient(180deg,#faf5ff,#fff);margin-top:12px">
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#7c3aed;font-weight:800;margin-bottom:10px;display:flex;align-items:center;gap:6px">🧾 Ticket para auto-facturación</div>
      ${esAirbnb ? `
        <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:10px;margin-bottom:8px">
          <div style="font-size:11px;color:#1e40af;font-weight:700;margin-bottom:6px">(=) $ Monto total Airbnb</div>
          <input type="number" step="0.01" min="0" value="${esc(montoAirbnb)}" placeholder="0.00"
                 onclick="event.stopPropagation()"
                 oninput="huRecalcAirbnb(this)"
                 onblur="huMaybePersistCardMonto(this.closest('.hu-resv-detail') || this.closest('[data-hu-airbnb-box]')?.parentElement)"
                 onkeydown="if(event.key==='Enter'){event.preventDefault();this.blur()}"
                 style="width:100%;padding:7px 10px;border:1px solid #bfdbfe;border-radius:6px;background:#fff;font-size:13px;color:#1e40af;font-weight:700;outline:none">
          <div style="font-size:10px;color:#3b82f6;margin-top:4px">Base editable.</div>
        </div>
        <div style="background:#fde68a;border:1px solid #f59e0b;border-radius:8px;padding:10px;margin-bottom:8px">
          <div style="font-size:11px;color:#78350f;font-weight:700;margin-bottom:6px">(-) $ Comisión Airbnb</div>
          <input type="number" step="0.01" data-hu-airbnb-comision="1" value="${esc(comisionPre)}" readonly
                 onclick="event.stopPropagation()"
                 style="width:100%;padding:7px 10px;border:1px solid #f59e0b;border-radius:6px;background:#fef3c7;font-size:13px;color:#78350f;font-weight:700;cursor:not-allowed;outline:none">
          <div style="font-size:10px;color:#92400e;margin-top:4px;font-weight:600">🔒 Airbnb × 15.5%</div>
        </div>` : ''}
      <div style="background:${esAirbnb?'#ddd6fe':'#ede9fe'};border:1px solid #a78bfa;border-radius:8px;padding:10px;margin-bottom:10px">
        <div style="font-size:11px;color:#4c1d95;font-weight:700;margin-bottom:6px">(+) $ Monto facturado Total</div>
        <input type="number" step="0.01" data-hu-airbnb-facturado="1" value="${esc(facturadoPre)}" ${esAirbnb?'readonly':''}
               onclick="event.stopPropagation()"
               style="width:100%;padding:7px 10px;border:1px solid #a78bfa;border-radius:6px;background:${esAirbnb?'#c4b5fd':'#fff'};font-size:13px;color:#4c1d95;font-weight:700;outline:none">
        ${esAirbnb?'<div style="font-size:10px;color:#6d28d9;margin-top:4px;font-weight:600">🔒 Airbnb − Comisión</div>':''}
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px">${btnVerTicket}${btnCopiarMsg}${btnReemitir}${btnEnviarCorreo}${btnGenerar}</div>
    </div>`;
}

function huBuildReservationDetail(r) {
  const status     = huGetFacturaStatus(r);
  const recId      = String(r['ID'] || r['row_number'] || '');
  const ingreso    = huValueFlexible(r, ['Fecha de ingreso']);
  const salida     = huValueFlexible(r, ['Fecha de salida']);
  const horaIng    = huValueFlexible(r, ['Hora estimada de llegada','Hora de llegada']);
  const horaSal    = huValueFlexible(r, ['Hora estimada de salida','Hora de salida']);
  let noches       = huValueFlexible(r, ['# Noches']);
  // Si no viene en el row, calcúlalo a partir de fecha de ingreso/salida.
  if (!noches || Number(noches) <= 0) {
    const di = huParseDate(ingreso); const ds = huParseDate(salida);
    if (di && ds) {
      const n = Math.max(0, Math.round((ds - di) / 86400000));
      if (n > 0) noches = String(n);
    }
  }
  const huespedes  = huValueFlexible(r, ['# Huéspedes']);
  const propiedad  = huValueFlexible(r, ['Propiedad']);
  const departamento = huValueFlexible(r, ['# Departamento']);
  const motivo     = huValueFlexible(r, ['Motivo de tu hospedaje','Motivo hospedaje','Motivo']);
  const motivoOtro = huValueFlexible(r, ['Motivo otro']);
  const motivoTxt  = (motivo && motivo.toLowerCase() === 'otro') ? (motivoOtro || motivo) : motivo;
  const comentarios= huValueFlexible(r, ['Notas','Envía tus comentarios','Comentarios']);
  const comentFact = huValueFlexible(r, ['Envía tus comentarios con relación a la factura']);
  const nombresHues= huValueFlexible(r, ['Nombres de TODOS los huéspedes (separados por comas)']);
  const medio      = huValueFlexible(r, ['Medio de reservación']);
  const formaPago  = huValueFlexible(r, ['Forma de pago']);
  const montoFact  = huValueFlexible(r, ['$ Monto facturado Total']);
  const montoAirbnb= huValueFlexible(r, ['$ Monto total Airbnb']);
  const reqFactura = huValueFlexible(r, ['¿Requiere factura?']);
  const folio      = huValueFlexible(r, ['Folio facturapi','Folio Facturapi','Folio']);
  const ticketUrl  = huExtractTicketUrl(r);
  const esAirbnb   = String(medio||'').toLowerCase().includes('airbnb');
  const medioBadge = huMedioBadge(medio);

  // Pre-cálculo Airbnb
  const airbnbVal    = esAirbnb ? huParseMontoAirbnb(montoAirbnb) : 0;
  const comisionPre  = esAirbnb && airbnbVal ? huCalcComisionAirbnb(airbnbVal).toFixed(2)        : '';
  const facturadoPre = esAirbnb && airbnbVal ? huCalcMontoFacturadoAirbnb(airbnbVal).toFixed(2) : montoFact;

  const mensajeConsulta = ticketUrl ? huBuildTicketConsultaMsg(ticketUrl) : '';
  const btnVerTicket = (status === 'emitida' && ticketUrl) ? `
    <a href="${esc(ticketUrl)}" target="_blank" rel="noopener" onclick="event.stopPropagation()"
       style="display:inline-block;padding:7px 14px;border:none;background:#16a34a;color:#fff;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer;text-decoration:none;margin-right:6px;box-shadow:0 2px 4px rgba(22,163,74,.3)">
      🧾 Ver ticket${folio ? ' - Folio #' + esc(folio) : ''}
    </a>` : '';
  const btnCopiarMsg = (status === 'emitida' && mensajeConsulta) ? `
    <button type="button" onclick="event.stopPropagation();huespedesCopiarMsgConsulta(this,'${encodeURIComponent(mensajeConsulta)}')"
            style="padding:7px 14px;border:none;background:#475569;color:#fff;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer">
      📋 Copiar mensaje para consultar ticket emitido
    </button>` : '';
  const btnGenerar = (status === 'pendiente') ? `
    <button onclick="event.stopPropagation();huespedesGenerarTicket('${esc(recId)}')"
            style="padding:8px 22px;border:none;background:linear-gradient(180deg,#ef4444 0%,#b91c1c 100%);color:#fff;border-radius:8px;font-weight:700;font-size:13px;cursor:pointer;box-shadow:0 2px 6px rgba(185,28,28,.4)">
      Generar Ticket
    </button>` : '';

  const fldRow = (label, value) => `
    <div style="display:grid;grid-template-columns:140px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid #f1f5f9">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:700;align-self:center">${esc(label)}</div>
      <div style="font-size:13px;color:#1f2937">${value || '—'}</div>
    </div>`;

  const airbnbBox = `
    <div data-hu-airbnb-box="1" style="border:1.5px solid #c4b5fd;border-radius:12px;padding:12px;background:linear-gradient(180deg,#faf5ff,#fff);margin-top:12px">
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#7c3aed;font-weight:800;margin-bottom:10px;display:flex;align-items:center;gap:6px">🧾 Ticket para auto-facturación</div>
      ${esAirbnb ? `
        <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:10px;margin-bottom:8px">
          <div style="font-size:11px;color:#1e40af;font-weight:700;margin-bottom:6px">(=) $ Monto total Airbnb</div>
          <input type="number" step="0.01" min="0" value="${esc(montoAirbnb)}" placeholder="0.00"
                 onclick="event.stopPropagation()"
                 oninput="huRecalcAirbnb(this)"
                 onblur="huMaybePersistCardMonto(this.closest('.hu-resv-detail'))"
                 onkeydown="if(event.key==='Enter'){event.preventDefault();this.blur()}"
                 style="width:100%;padding:7px 10px;border:1px solid #bfdbfe;border-radius:6px;background:#fff;font-size:13px;color:#1e40af;font-weight:700;outline:none">
          <div style="font-size:10px;color:#3b82f6;margin-top:4px">Base editable.</div>
        </div>
        <div style="background:#fde68a;border:1px solid #f59e0b;border-radius:8px;padding:10px;margin-bottom:8px">
          <div style="font-size:11px;color:#78350f;font-weight:700;margin-bottom:6px">(-) $ Comisión Airbnb</div>
          <input type="number" step="0.01" data-hu-airbnb-comision="1" value="${esc(comisionPre)}" readonly
                 onclick="event.stopPropagation()"
                 style="width:100%;padding:7px 10px;border:1px solid #f59e0b;border-radius:6px;background:#fef3c7;font-size:13px;color:#78350f;font-weight:700;cursor:not-allowed;outline:none">
          <div style="font-size:10px;color:#92400e;margin-top:4px;font-weight:600">🔒 Airbnb × 15.5%</div>
        </div>` : ''}
      <div style="background:${esAirbnb?'#ddd6fe':'#ede9fe'};border:1px solid #a78bfa;border-radius:8px;padding:10px;margin-bottom:10px">
        <div style="font-size:11px;color:#4c1d95;font-weight:700;margin-bottom:6px">(+) $ Monto facturado Total</div>
        <input type="number" step="0.01" data-hu-airbnb-facturado="1" value="${esc(facturadoPre)}" ${esAirbnb?'readonly':''}
               onclick="event.stopPropagation()"
               style="width:100%;padding:7px 10px;border:1px solid #a78bfa;border-radius:6px;background:${esAirbnb?'#c4b5fd':'#fff'};font-size:13px;color:#4c1d95;font-weight:700;outline:none">
        ${esAirbnb?'<div style="font-size:10px;color:#6d28d9;margin-top:4px;font-weight:600">🔒 Airbnb − Comisión</div>':''}
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px">${btnVerTicket}${btnCopiarMsg}${btnGenerar}</div>
    </div>`;

  // Pill de estado
  const statusPill = status === 'emitida'
    ? `<span style="display:inline-block;padding:4px 12px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:10px;border:1px solid #86efac">EMITIDA${folio?' · '+esc(folio):''}</span>`
    : status === 'pendiente'
    ? `<span style="display:inline-block;padding:4px 12px;border-radius:999px;background:#fef3c7;color:#92400e;font-weight:700;font-size:10px;border:1px solid #fcd34d">PENDIENTE</span>`
    : `<span style="display:inline-block;padding:4px 12px;border-radius:999px;background:#f1f5f9;color:#475569;font-weight:700;font-size:10px;border:1px solid #cbd5e1">SIN FACTURA</span>`;

  return `
    <div class="hu-col-card hu-resv-detail" data-hu-resv-id="${esc(recId)}"
         style="background:#fff;border-radius:16px;padding:0;color:#0f172a;box-shadow:0 4px 16px rgba(15,23,42,.08);position:relative;overflow:hidden;border:1.5px solid #e2e8f0">
      <div style="height:4px;background:linear-gradient(90deg,#f59e0b,#ef4444,#a855f7)"></div>
      <div style="padding:14px 16px">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;padding-bottom:10px;border-bottom:1.5px solid #f1f5f9">
          <div>
            <div style="font-size:9px;letter-spacing:.18em;color:#64748b;font-weight:800;margin-bottom:4px">📑 DETALLE DE RESERVACIÓN</div>
            <div style="font-size:14px;font-weight:800;color:#0f172a">${huFmtFecha(ingreso)} → ${huFmtFecha(salida)}</div>
          </div>
          ${statusPill}
        </div>

        <div style="margin-bottom:8px">${medioBadge}</div>

      <div style="display:flex;flex-direction:column">
        ${fldRow('Propiedad', esc(propiedad))}
        ${fldRow('# Departamento', esc(departamento))}
        ${fldRow('Llegada estimada', horaIng ? esc(huFmtHoraSimple(horaIng)) : '—')}
        ${fldRow('Salida estimada', horaSal ? esc(huFmtHoraSimple(horaSal)) : '—')}
        ${fldRow('# Noches', (noches && Number(noches)>0) ? `<b>${esc(noches)}</b>` : '—')}
        ${fldRow('# Huéspedes', esc(huespedes))}
        ${nombresHues ? fldRow('Nombres de huéspedes', `<span style="font-size:12px;line-height:1.5">${esc(nombresHues)}</span>`) : ''}
        ${motivoTxt ? fldRow('Motivo del hospedaje', `<span style="display:inline-block;padding:3px 10px;border-radius:999px;background:#ede9fe;color:#5b21b6;font-weight:700;font-size:11px;border:1px solid #c4b5fd">${esc(motivoTxt)}</span>`) : ''}
        ${fldRow('Forma de pago', esc(formaPago))}
        ${fldRow('Monto Facturado', montoFact ? `<span data-hu-header-amount="1" style="font-weight:800;color:#0f172a">${huFmtMonto(montoFact)}</span>` : '<span data-hu-header-amount="1">—</span>')}
        ${fldRow('¿Requiere factura?', huReqFacturaBadge(reqFactura))}
        ${comentarios ? fldRow('Comentarios', `<div style="font-size:12px;line-height:1.5;background:#f8fafc;padding:8px 10px;border-radius:6px;border-left:3px solid #94a3b8;font-style:italic;color:#334155">${esc(comentarios)}</div>`) : ''}
        ${comentFact ? fldRow('Comentarios sobre factura', `<div style="font-size:12px;line-height:1.5;background:#fef3c7;padding:8px 10px;border-radius:6px;border-left:3px solid #f59e0b;font-style:italic;color:#78350f">${esc(comentFact)}</div>`) : ''}
      </div>

      ${airbnbBox}

        <div style="margin-top:14px;display:flex;justify-content:flex-end">
          <button onclick="event.stopPropagation();huespedesOpenDetail('${esc(recId)}')"
                  style="padding:7px 16px;border:1.5px solid #cbd5e1;background:#fff;color:#475569;border-radius:8px;font-weight:600;font-size:11px;cursor:pointer">
            Ver todos los campos
          </button>
        </div>
      </div>
    </div>`;
}

/** Click en una entrada del historial: re-renderiza la columna derecha y
 *  marca el nuevo seleccionado. outerRecId es el id del details outer. */
window.huSelectReservation = function(outerRecId, selectedRecId) {
  const r = (HU_STATE.rows||[]).find(x => String(x['ID']||x['row_number']||'') === String(selectedRecId));
  if (!r) return;
  const card = document.querySelector(`.hu-record[data-record-id="${outerRecId}"]`);
  if (!card) return;
  const detailCol = card.querySelector('.hu-col-detail');
  const historyCol = card.querySelector('.hu-col-history');
  // Preservar scroll: el re-render colapsa temporalmente la columna detalle
  // (más corta antes de que la sección Tareas relacionadas se re-inyecte),
  // lo que hace que el navegador ajuste scrollY hacia arriba.
  const _prevScrollY = window.scrollY;
  const _restoreScroll = () => { if (Math.abs(window.scrollY - _prevScrollY) > 1) window.scrollTo({ top: _prevScrollY, behavior: 'instant' }); };
  if (detailCol) {
    detailCol.innerHTML = huBuildReservationDetail(r);
    // Sin animación — fade causa salto visual + dispara reflow que mueve scroll.
    detailCol.style.animation = '';
  }
  if (historyCol) {
    historyCol.innerHTML = huBuildHistoryList(r, HU_STATE.rows, selectedRecId, outerRecId);
  }
  requestAnimationFrame(_restoreScroll);
  setTimeout(_restoreScroll, 50);
  setTimeout(_restoreScroll, 200);
  setTimeout(_restoreScroll, 500);
};

/** Devuelve { aseoChip, asignacionesChip, fechaTermStr } para el Lodgify Id dado,
 *  reutilizando exactamente los mismos estilos/lógica que las cards de
 *  "Reservas totales". Si no hay task ligada → strings vacíos. */
/** Mapea el estado raw de Breezeway a 3 estados simplificados:
 *  Terminado / En proceso / Pendiente.
 *  PRIORIDAD: si tk.task.status_label viene del backend, ese es source of
 *  truth (resolveStatusLabel en breezeway.js ya lo computó al persistir).
 *  Si no, caemos al cálculo local. */
function bzwResolveTaskStatus(input) {
  const FIN = { key:'finished', label:'Terminado', icon:'✓', bg:'#dcfce7', fg:'#15803d', border:'#86efac' };
  const PROC = { key:'in_progress', label:'En proceso', icon:'▶', bg:'#dbeafe', fg:'#1e40af', border:'#93c5fd' };
  const PEND = { key:'pending', label:'Pendiente', icon:'✗', bg:'#fee2e2', fg:'#b91c1c', border:'#fca5a5' };
  if (!input) return PEND;
  // Tolerante a 2 shapes: el caller puede pasar un alert completo
  // {task,raw,...} o solo el task object. Normalizamos para que ambos
  // funcionen — en algunos call sites se pasaba a.task directo y el chip
  // siempre caía a Pendiente porque task.finished_at era undefined.
  const task = input.task || input;
  const raw = input.raw || input;
  // 1) finished_at SIEMPRE gana
  if (task.finished_at || raw.finished_at) return FIN;
  // 2) started_at sin finished_at → En proceso
  if (task.started_at || raw.started_at) return PROC;
  // 3) Si el backend ya computó status_label, úsalo
  const labelFromBackend = String(task.status_label || raw.status_label || '').trim().toLowerCase();
  if (labelFromBackend === 'terminado') return FIN;
  if (labelFromBackend === 'en proceso' || labelFromBackend === 'enproceso') return PROC;
  if (labelFromBackend === 'pendiente') return PEND;
  // 4) Fallback: leer status raw
  const rawStatus = String(
    task.status?.name ||
    task.status ||
    raw.type_task_status?.code ||
    raw.type_task_status?.name ||
    raw.status?.name ||
    raw.status ||
    ''
  ).toLowerCase().replace(/[\s_-]+/g, '');
  if (/finish|complet|done/.test(rawStatus)) return FIN;
  if (/inprogress|progress|started|running|active|paus/.test(rawStatus)) return PROC;
  return PEND;
}
window.bzwResolveTaskStatus = bzwResolveTaskStatus;

/** Render de 5 estrellas para el rating (1..5) del huésped que dejó el personal
 *  de limpieza en el template "Limpieza Checkout" de Breezeway.
 *  Devuelve string vacío si rating no es válido. */
function bzwBuildGuestStarsChip(rating, opts) {
  const n = Number(rating);
  if (!Number.isFinite(n) || n < 1 || n > 5) return '';
  const filled = Math.round(n);
  const size = (opts && opts.size) || 13;
  const compact = !!(opts && opts.compact);
  const stars = Array.from({ length: 5 }, (_, i) =>
    `<span style="color:${i < filled ? '#f59e0b' : '#e5e7eb'};font-size:${size}px;line-height:1">★</span>`).join('');
  const label = compact ? '' : `<span style="font-size:10px;color:#64748b;font-weight:700;letter-spacing:.02em;text-transform:uppercase">Calificación del huésped</span>`;
  const wrap = compact
    ? `<span title="Calificación del huésped: ${filled}/5" style="display:inline-flex;align-items:center;gap:2px;padding:3px 8px;border-radius:999px;background:#fffbeb;border:1.5px solid #fcd34d">${stars}</span>`
    : `<div style="display:inline-flex;flex-direction:column;align-items:flex-start;gap:2px;padding:6px 10px;border-radius:10px;background:#fffbeb;border:1.5px solid #fcd34d">${label}<span style="display:inline-flex;gap:1px">${stars}</span></div>`;
  return wrap;
}
window.bzwBuildGuestStarsChip = bzwBuildGuestStarsChip;

/** Rating (1..5) para UN Lodgify Id — busca la task de housekeeping ganadora
 *  con rating persistido. Devuelve null si no hay. */
function bzwGetRatingForLodId(lodId) {
  if (!lodId || typeof BZW_ALL_TASKS === 'undefined' || !BZW_ALL_TASKS.length) return null;
  if (!BZW_IDX_BY_LODID) { try { bzwBuildTaskIndexes_(); } catch(_) {} }
  const linked = (BZW_IDX_BY_LODID && BZW_IDX_BY_LODID.get(String(lodId))) || [];
  if (!linked.length) return null;
  // Preferir housekeeping con finished_at + rating
  const scored = linked.map(tk => {
    const dept = String(tk.task?.type || tk.raw?.type_department || '').toLowerCase();
    const nm = String(tk.task?.name || '').toLowerCase();
    const r = tk.task?.guest_rating ?? tk.raw?.guest_rating ?? null;
    let s = 0;
    if (dept === 'housekeeping') s += 10;
    if (/checkout|limpieza/.test(nm)) s += 5;
    if (tk.task?.finished_at) s += 1;
    return { tk, s, r };
  }).filter(x => x.r != null && Number.isFinite(Number(x.r)));
  if (!scored.length) return null;
  scored.sort((a,b) => b.s - a.s);
  return Number(scored[0].r);
}
window.bzwGetRatingForLodId = bzwGetRatingForLodId;

/** Promedio de guest_rating a lo largo de TODAS las reservas del huésped
 *  (usando el índice __huGuestIndex por phone tail). Devuelve {avg, count} o null. */
function huAvgGuestRatingForRecord(r) {
  if (!r) return null;
  const phoneTail = (v) => {
    const s = String(v || '').replace(/\D/g, '');
    return s.length >= 10 ? s.slice(-10) : '';
  };
  const tail = phoneTail(huValueFlexible(r, ['Cel/Whatsapp (principal)','Celular principal','Cel/Whatsapp','Cel principal']));
  // Colecciona lodIds candidatos: primero el índice por teléfono; si no hay,
  // fallback al Lodgify Id del propio registro.
  let lodIds = [];
  if (tail) {
    const rows = HU_STATE.rows || [];
    const sig = `${rows.length}`;
    if (!window.__huGuestIndex || window.__huGuestIndexSig !== sig) {
      try { huBuildGuestIndex_(rows); } catch(_) {}
    }
    const list = (window.__huGuestIndex && window.__huGuestIndex.get(tail)) || [];
    lodIds = list.map(x => String(x['Lodgify Id']||'').trim()).filter(Boolean);
  }
  if (!lodIds.length) {
    const self = String(r['Lodgify Id']||'').trim();
    if (self) lodIds = [self];
  }
  const ratings = [];
  for (const lodId of lodIds) {
    const rating = bzwGetRatingForLodId(lodId);
    if (rating != null && Number.isFinite(rating)) ratings.push(rating);
  }
  if (!ratings.length) return null;
  const avg = ratings.reduce((a,b) => a+b, 0) / ratings.length;
  return { avg, count: ratings.length, values: ratings };
}
window.huAvgGuestRatingForRecord = huAvgGuestRatingForRecord;

function huBuildAseoBadgesForLodId(lodId) {
  if (!lodId || typeof BZW_ALL_TASKS === 'undefined' || !BZW_ALL_TASKS.length) {
    return { aseoChip: '', asignacionesChip: '', fechaTermStr: '', starsChip: '' };
  }
  if (!BZW_IDX_BY_LODID) { try { bzwBuildTaskIndexes_(); } catch(_) {} }
  const linked = (BZW_IDX_BY_LODID && BZW_IDX_BY_LODID.get(String(lodId))) || [];
  if (!linked.length) return { aseoChip: '', asignacionesChip: '', fechaTermStr: '', starsChip: '' };
  const score = (tk) => {
    const dept = String(tk.task?.type || tk.raw?.type_department || '').toLowerCase();
    const nm = String(tk.task?.name || '').toLowerCase();
    let s = 0;
    if (dept === 'housekeeping') s += 10;
    if (/checkout|limpieza/.test(nm)) s += 5;
    if (tk.task?.finished_at) s += 1;
    return s;
  };
  linked.sort((a, b) => score(b) - score(a));
  const tk = linked[0];
  const tFinished = !!tk.task?.finished_at;
  let fechaTermStr = '';
  if (tFinished && tk.task.finished_at) {
    const d = new Date(tk.task.finished_at);
    if (!isNaN(d.getTime())) {
      fechaTermStr = `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;
    }
  }
  const assignNames = Array.isArray(tk.raw?.assignments)
    ? Array.from(new Set(tk.raw.assignments.map(x => x?.full_name || x?.name).filter(Boolean)))
    : [];
  let assignDisplay = '';
  if (assignNames.length) {
    assignDisplay = assignNames.length <= 2
      ? assignNames.join(', ')
      : `${assignNames.slice(0,2).join(', ')} +${assignNames.length - 2}`;
  }
  // Status real (Finalizada / Pausada / En progreso / Pendiente / Rechazada)
  const st = bzwResolveTaskStatus(tk);
  const aseoChip = `<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:999px;background:${st.bg};color:${st.fg};font-weight:800;font-size:11px;border:1.5px solid ${st.border};letter-spacing:.02em">${st.icon} Aseo · ${st.label}</span>`;
  const asignacionesChip = assignDisplay
    ? `<span title="Asignaciones: ${esc(assignNames.join(', '))}" style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:999px;background:#fff7ed;color:#9a3412;font-weight:700;font-size:11px;border:1.5px solid #fdba74;letter-spacing:.02em;max-width:200px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">👥 ${esc(assignDisplay)}</span>`
    : '';
  // Estrellas del huésped: solo si hay guest_rating en la task ganadora
  const rating = tk.task?.guest_rating ?? tk.raw?.guest_rating ?? null;
  const starsChip = bzwBuildGuestStarsChip(rating, { compact: true });
  return { aseoChip, asignacionesChip, fechaTermStr, starsChip };
}

function huBuildRecordCard(r) {
  const status     = huGetFacturaStatus(r);
  const recId      = String(r['ID'] || r['row_number'] || '');
  const nombre     = huValueFlexible(r, ['Nombre de la persona que hizo la reservación','mbre de la persona que hizo la reservación']);
  const ingreso    = huValueFlexible(r, ['Fecha de ingreso','Fecha de entrada']);
  const salida     = huValueFlexible(r, ['Fecha de salida']);
  let   noches     = huValueFlexible(r, ['# Noches']);
  if (!noches || Number(noches) <= 0) {
    const di = huParseDate(ingreso); const ds = huParseDate(salida);
    if (di && ds) {
      const n = Math.max(0, Math.round((ds - di) / 86400000));
      if (n > 0) noches = String(n);
    }
  }
  const horaIng    = huValueFlexible(r, ['Hora estimada de llegada','Hora de llegada']);
  const horaSal    = huValueFlexible(r, ['Hora estimada de salida','Hora de salida']);
  const huespedes  = huValueFlexible(r, ['# Huéspedes']);
  const propiedad  = huValueFlexible(r, ['Propiedad']);
  const departamento = huValueFlexible(r, ['# Departamento']);
  const medio      = huValueFlexible(r, ['Medio de reservación','Medio de reservacion']);
  const formaPago  = huValueFlexible(r, ['Forma de pago']);
  const montoPag   = huValueFlexible(r, ['($) Monto Total pagado','$ Monto Total pagado','Monto Total pagado']);
  const montoFact  = huValueFlexible(r, ['$ Monto facturado Total','Monto facturado Total']);
  const montoAirbnb= huValueFlexible(r, ['$ Monto total Airbnb','Monto total Airbnb','Monto Airbnb']);
  const reqFactura = huValueFlexible(r, ['¿Requiere factura?']);
  const razon      = huValueFlexible(r, ['Razón social']);
  const regimen    = huValueFlexible(r, ['Régimen fiscal','Regimen fiscal']);
  const cel        = huValueFlexible(r, ['Cel/Whatsapp (principal)']);
  const folio      = huValueFlexible(r, ['Folio facturapi','Folio Facturapi','Folio']);
  const ticketUrl  = huExtractTicketUrl(r);
  const esAirbnb   = String(medio||'').toLowerCase().includes('airbnb');

  // Paleta semafórica (basada en el screenshot)
  const palette = status === 'pendiente'
      ? { border:'#fecaca', bg:'#fef2f2', leftAcc:'#dc2626' }
      : status === 'emitida'
      ? { border:'#bbf7d0', bg:'#f0fdf4', leftAcc:'#16a34a' }
      : { border:'#cbd5e1', bg:'#f8fafc', leftAcc:'#94a3b8' };

  // Header chips: medio + factura + huéspedes
  const medioBadge = huMedioBadge(medio);
  const huespedesChip = huespedes
    ? `<span data-hu-hdr-huespedes style="display:inline-flex;align-items:center;gap:5px;padding:4px 11px;border-radius:999px;background:#fff;color:#1f2937;font-weight:800;font-size:11px;border:1px solid #e2e8f0;letter-spacing:.02em;box-shadow:0 1px 2px rgba(15,23,42,.05)">👥 ${esc(huespedes)} huésped${String(huespedes)==='1'?'':'es'}</span>`
    : '<span data-hu-hdr-huespedes></span>';
  let facBadge   = status === 'emitida'
    ? (ticketUrl
        ? `<a href="${esc(ticketUrl)}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="text-decoration:none">
             <span style="display:inline-block;padding:5px 12px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:11px;border:1px solid #86efac">🧾 Ticket emitido${folio?' - Folio #'+esc(folio):''}</span>
           </a>`
        : `<span style="display:inline-block;padding:5px 12px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:11px;border:1px solid #86efac">🧾 Ticket emitido${folio?' - Folio #'+esc(folio):''}</span>`)
    : status === 'pendiente'
    ? `<span style="display:inline-block;padding:5px 12px;border-radius:999px;background:#fff7ed;color:#c2410c;font-weight:700;font-size:11px;border:1.5px solid #fdba74">🧾 Ticket pendiente</span>`
    : '';
  if (status === 'emitida') {
    const medioEm = String(huValueFlexible(r, ['Medio de emisión','Medio de emision']) || '').trim();
    if (medioEm) {
      const isAuto = /auto/i.test(medioEm);
      const bg = isAuto ? '#ede9fe' : '#e0f2fe';
      const fg = isAuto ? '#5b21b6' : '#0369a1';
      const bd = isAuto ? '#c4b5fd' : '#7dd3fc';
      const emoji = isAuto ? '👤' : '🖥️';
      facBadge += ` <span title="Origen del ticket" style="display:inline-block;padding:5px 12px;border-radius:999px;background:${bg};color:${fg};border:1px solid ${bd};font-size:11px;font-weight:800;letter-spacing:.02em">${emoji} ${esc(medioEm)}</span>`;
    }
  }

  // KPIs del huésped (sumando su historial completo de reservaciones)
  const stats = huComputeGuestStats(r, HU_STATE.rows);
  const score = huComputeLoyaltyScore(stats);
  const tier  = huGuestTier(score, stats);
  const tierBadge = tier ? `
    <div title="${esc(tier.tooltip)}"
         style="display:flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;background:${tier.bg};color:${tier.fg};font-weight:800;font-size:11px;letter-spacing:.04em;text-transform:uppercase;border:1.5px solid ${tier.border};box-shadow:0 2px 8px ${tier.shadow};animation:hu-badge-glow 2.6s ease-in-out infinite">
      <span style="font-size:14px">${tier.icon}</span>
      <span>${tier.label}</span>
      <span style="display:inline-flex;align-items:center;justify-content:center;min-width:28px;height:18px;padding:0 6px;border-radius:9px;background:rgba(255,255,255,.7);color:${tier.fg};font-size:10px;font-weight:800;letter-spacing:0">${tier.score}</span>
    </div>` : '';
  const kpisHtml = `
    <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
      <div style="background:rgba(255,255,255,.75);border:1.5px solid ${palette.border};border-radius:10px;padding:6px 12px;min-width:84px;text-align:center;backdrop-filter:blur(4px)" title="Suma global de noches en todas las reservaciones del huésped">
        <div style="font-size:9px;color:#64748b;font-weight:800;letter-spacing:.05em;text-transform:uppercase">🌙 Noches globales</div>
        <div style="font-size:18px;font-weight:800;color:#0f172a;line-height:1.1">${stats.totalNoches}</div>
      </div>
      <div style="background:rgba(255,255,255,.75);border:1.5px solid ${palette.border};border-radius:10px;padding:6px 12px;min-width:84px;text-align:center;backdrop-filter:blur(4px)" title="Visitas globales distintas (reservaciones consecutivas cuentan como una sola visita)">
        <div style="font-size:9px;color:#64748b;font-weight:800;letter-spacing:.05em;text-transform:uppercase">🧳 Visitas globales</div>
        <div style="font-size:18px;font-weight:800;color:#0f172a;line-height:1.1">${stats.visitas}</div>
      </div>
      <div style="background:rgba(255,255,255,.75);border:1.5px solid ${palette.border};border-radius:10px;padding:6px 12px;min-width:104px;text-align:center;backdrop-filter:blur(4px)" title="Suma de $ Monto facturado Total de todas las reservaciones del huésped">
        <div style="font-size:9px;color:#64748b;font-weight:800;letter-spacing:.05em;text-transform:uppercase">💰 Monto global</div>
        <div style="font-size:16px;font-weight:800;color:#0f172a;line-height:1.1">${stats.montoGlobal > 0 ? huFmtMonto(stats.montoGlobal) : '—'}</div>
      </div>
      ${tierBadge}
    </div>`;

  // Chips Aseo + Asignaciones (Breezeway) por Lodgify Id del registro
  const lodIdForAseo = String(r['Lodgify Id'] || '').trim();
  const { aseoChip, asignacionesChip, fechaTermStr } = huBuildAseoBadgesForLodId(lodIdForAseo);
  const fechaTermChip = fechaTermStr
    ? `<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;border-radius:999px;background:#f1f5f9;color:#475569;font-weight:700;font-size:10px;border:1px solid #cbd5e1;letter-spacing:.02em">🕓 ${esc(fechaTermStr)}</span>`
    : '';
  // Calificación PROMEDIADA del huésped a lo largo de todas sus reservas.
  // Se muestra inline con el nombre en el header.
  const _avgRating = huAvgGuestRatingForRecord(r);
  const guestAvgStarsInline = _avgRating ? (() => {
    const filled = Math.round(_avgRating.avg);
    const stars = Array.from({ length: 5 }, (_, i) =>
      `<span style="color:${i < filled ? '#f59e0b' : '#e5e7eb'};font-size:15px;line-height:1">★</span>`).join('');
    const label = _avgRating.count > 1
      ? `promedio de ${_avgRating.count} reservas`
      : 'calificación del huésped';
    return `<span title="Calificación del huésped — ${label}: ${_avgRating.avg.toFixed(1)}/5" style="display:inline-flex;align-items:center;gap:3px;padding:3px 9px;border-radius:999px;background:#fffbeb;border:1.5px solid #fcd34d;vertical-align:middle;margin-left:8px">${stars}<span style="font-size:10px;color:#92400e;font-weight:800;margin-left:3px">${_avgRating.avg.toFixed(1)}</span></span>`;
  })() : '';

  // Header SUMMARY — clic abre/cierra (sin marker nativo)
  const summary = `
    <summary style="cursor:pointer;list-style:none;padding:16px 18px;background:${palette.bg};display:grid;grid-template-columns:1fr auto auto auto;gap:14px;align-items:center">
      <div>
        <div style="display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-bottom:10px">${medioBadge}${huespedesChip}${aseoChip}${asignacionesChip}${fechaTermChip}</div>
        <div style="font-size:18px;font-weight:800;color:#111827;line-height:1.25;margin-bottom:6px;display:flex;align-items:center;flex-wrap:wrap">${esc(nombre || '—')}${guestAvgStarsInline}</div>
        <div style="font-size:13px;color:#64748b;font-weight:500">${esc(propiedad || '—')}${departamento ? ' · # ' + esc(departamento) : ''}</div>
        <div style="font-size:13px;color:#64748b;font-weight:500;margin-top:2px">${huFmtFecha(ingreso)} → ${huFmtFecha(salida)}</div>
        <div style="font-size:12px;color:#475569;font-weight:600;margin-top:3px">🌙 <span data-hu-hdr-noches>${esc(noches && Number(noches)>0 ? noches : '—')}</span> noche${String(noches)==='1'?'':'s'}</div>
        <div style="display:flex;flex-wrap:wrap;gap:14px;margin-top:6px;font-size:11px;color:#64748b">
          <span><span style="color:#94a3b8;font-weight:600">Llegada estimada:</span> <b data-hu-hdr-horaing style="color:#1f2937">${esc(horaIng ? huFmtHoraSimple(horaIng) : '—')}</b></span>
          <span><span style="color:#94a3b8;font-weight:600">Salida estimada:</span> <b data-hu-hdr-horasal style="color:#1f2937">${esc(horaSal ? huFmtHoraSimple(horaSal) : '—')}</b></span>
        </div>
      </div>
      ${kpisHtml}
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:8px;min-width:160px">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:700">Monto facturado</div>
        <div data-hu-header-amount="1" style="font-size:22px;font-weight:800;color:#111827">${montoFact ? huFmtMonto(montoFact) : '—'}</div>
        <div>${facBadge}</div>
      </div>
      <div style="display:flex;align-items:center;justify-content:center;width:38px;height:38px;border-radius:50%;border:1.5px solid ${palette.border};background:#fff;color:#475569;font-size:14px;flex-shrink:0" class="hu-record-chev">▾</div>
    </summary>`;

  // Cuerpo expandido — grid de tarjetas-campo
  const fieldCard = (label, valueHtml) => `
    <div style="border:1.5px solid #e2e8f0;border-radius:12px;padding:11px 14px;background:#fff">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:700;margin-bottom:6px">${esc(label)}</div>
      <div style="font-size:13.5px;color:#1f2937">${valueHtml || '—'}</div>
    </div>`;

  // Pre-cálculo Airbnb cuando aplique (para que el primer render ya muestre los valores)
  const airbnbVal = esAirbnb ? huParseMontoAirbnb(montoAirbnb) : 0;
  const comisionPre  = esAirbnb && airbnbVal ? huCalcComisionAirbnb(airbnbVal).toFixed(2)        : '';
  const facturadoPre = esAirbnb && airbnbVal ? huCalcMontoFacturadoAirbnb(airbnbVal).toFixed(2) : montoFact;
  // El auto-save ahora se dispara desde el ontoggle del <details> cuando se
  // abre la card. Esto es más confiable que un setTimeout dependiente del DOM.

  // Botones cuando el ticket está emitido
  const mensajeConsulta = ticketUrl ? huBuildTicketConsultaMsg(ticketUrl) : '';
  const btnVerTicket = (status === 'emitida' && ticketUrl) ? `
    <a href="${esc(ticketUrl)}" target="_blank" rel="noopener" onclick="event.stopPropagation()"
       style="display:inline-block;padding:7px 14px;border:none;background:#16a34a;color:#fff;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer;text-decoration:none;margin-right:6px;box-shadow:0 2px 4px rgba(22,163,74,.3)">
      🧾 Ver ticket${folio ? ' - Folio #' + esc(folio) : ''}
    </a>` : '';
  const btnCopiarMsg = (status === 'emitida' && mensajeConsulta) ? `
    <button type="button" onclick="event.stopPropagation();huespedesCopiarMsgConsulta(this,'${encodeURIComponent(mensajeConsulta)}')"
            style="padding:7px 14px;border:none;background:#475569;color:#fff;border-radius:8px;font-weight:700;font-size:12px;cursor:pointer;box-shadow:0 2px 4px rgba(71,85,105,.3)">
      📋 Copiar mensaje para consultar ticket emitido
    </button>` : '';
  const btnGenerar = (status === 'pendiente') ? `
    <button onclick="event.stopPropagation();huespedesGenerarTicket('${esc(recId)}')"
            style="padding:8px 22px;border:none;background:linear-gradient(180deg,#ef4444 0%,#b91c1c 100%);color:#fff;border-radius:8px;font-weight:700;font-size:13px;cursor:pointer;box-shadow:0 2px 6px rgba(185,28,28,.4)">
      Generar Ticket
    </button>` : '';

  // Bloque Airbnb auto-facturación
  const airbnbBox = `
    <div data-hu-airbnb-box="1" style="border:1.5px solid #e2e8f0;border-radius:12px;padding:11px 14px;background:#fff">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:700;margin-bottom:10px">Ticket para auto-facturación</div>
      ${esAirbnb ? `
        <!-- (=) Monto total Airbnb — editable -->
        <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:10px;margin-bottom:8px">
          <div style="font-size:11px;color:#1e40af;font-weight:700;margin-bottom:6px">(=) $ Monto total Airbnb</div>
          <input type="number" step="0.01" min="0" value="${esc(montoAirbnb)}" placeholder="0.00"
                 onclick="event.stopPropagation()"
                 oninput="huRecalcAirbnb(this)"
                 onblur="huMaybePersistCardMonto(this.closest('.hu-record'))"
                 onkeydown="if(event.key==='Enter'){event.preventDefault();this.blur()}"
                 style="width:100%;padding:7px 10px;border:1px solid #bfdbfe;border-radius:6px;background:#fff;font-size:13px;color:#1e40af;font-weight:700;outline:none">
          <div style="font-size:10px;color:#3b82f6;margin-top:4px">Base editable para calcular comisión y monto facturado.</div>
        </div>
        <!-- (-) Comisión Airbnb — calculado, fondo más sombreado -->
        <div style="background:#fde68a;border:1px solid #f59e0b;border-radius:8px;padding:10px;margin-bottom:8px">
          <div style="font-size:11px;color:#78350f;font-weight:700;margin-bottom:6px">(-) $ Comisión Airbnb</div>
          <input type="number" step="0.01" data-hu-airbnb-comision="1" value="${esc(comisionPre)}" readonly aria-readonly="true"
                 onclick="event.stopPropagation()"
                 style="width:100%;padding:7px 10px;border:1px solid #f59e0b;border-radius:6px;background:#fef3c7;font-size:13px;color:#78350f;font-weight:700;cursor:not-allowed;outline:none">
          <div style="font-size:10px;color:#92400e;margin-top:4px;font-weight:600">🔒 Calculado automáticamente: Airbnb × 15.5%</div>
        </div>` : ''}
      <!-- (+) Monto facturado Total — calculado/editable según medio -->
      <div style="background:${esAirbnb?'#ddd6fe':'#ede9fe'};border:1px solid #a78bfa;border-radius:8px;padding:10px;margin-bottom:10px">
        <div style="font-size:11px;color:#4c1d95;font-weight:700;margin-bottom:6px">(+) $ Monto facturado Total</div>
        <input type="number" step="0.01" data-hu-airbnb-facturado="1" value="${esc(facturadoPre)}" ${esAirbnb?'readonly aria-readonly="true"':''} onclick="event.stopPropagation()"
               style="width:100%;padding:7px 10px;border:1px solid #a78bfa;border-radius:6px;background:${esAirbnb?'#c4b5fd':'#fff'};font-size:13px;color:#4c1d95;font-weight:700;${esAirbnb?'cursor:not-allowed;':''}outline:none">
        ${esAirbnb?'<div style="font-size:10px;color:#6d28d9;margin-top:4px;font-weight:600">🔒 Calculado automáticamente: $ Monto total Airbnb − $ Comisión Airbnb</div>':''}
      </div>
      <!-- Botones: Ver ticket + Copiar mensaje (cuando emitida) o Generar Ticket (cuando pendiente) -->
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:4px">${btnVerTicket}${btnCopiarMsg}${btnGenerar}</div>
    </div>`;

  // Cel con link
  const wa = huBuildWhatsAppUrl(cel);
  const phoneHtml = wa
    ? `<a href="${esc(wa)}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="color:#0d9488;text-decoration:none;font-weight:800;font-size:15px">${esc(cel)}</a>`
    : `<span style="font-weight:700;color:#1f2937">${esc(cel || '—')}</span>`;

  return `
    <details class="hu-record" data-record-id="${esc(recId)}" ontoggle="huOnDetailsToggle(this)" style="position:relative;border:1.5px solid ${palette.border};border-radius:14px;background:#fff;overflow:hidden;box-shadow:0 1px 3px rgba(15,23,42,.04)">
      <button class="btn-x" title="Eliminar reservación"
              onclick="event.stopPropagation(); event.preventDefault(); deleteHuespedRecord('${esc(recId)}', '${esc(nombre || '').replace(/'/g, "\\'")}')"
              style="position:absolute;top:10px;left:10px;z-index:5">×</button>
      ${summary}
      <div class="hu-record-body" style="padding:16px;background:linear-gradient(180deg,#f8fafc,#fff);display:grid;grid-template-columns:minmax(260px,1fr) minmax(220px,1fr) minmax(320px,1.4fr);gap:14px;align-items:start">
        <div class="hu-col-profile">${huBuildIdCard(r)}</div>
        <div class="hu-col-history">${huBuildHistoryList(r, HU_STATE.rows, recId, recId)}</div>
        <div class="hu-col-detail">${huBuildReservationDetail(r)}</div>
      </div>
    </details>`;
}

// ─── Integración Facturapi ──────────────────────────────────────────────────
// URL base del facturapi del check-in (Cloud Run us-central1).
// Se puede sobreescribir guardando otra en localStorage.HU_FACTURAPI_URL.
const HU_FACTURAPI_DEFAULT = 'https://checkin-app-957627511957.us-central1.run.app/facturapi';
function huGetFacturapiUrl() {
  try {
    const override = localStorage.getItem('HU_FACTURAPI_URL');
    if (override && override.trim()) return override.trim();
  } catch(_) {}
  return HU_FACTURAPI_DEFAULT;
}

// Toggle de organización Facturapi: el frontend sólo envía ?org=1|2 al
// Cloud Run; el backend escoge qué Live Secret Key usar
// (FACTURAPI_SECRET_KEY_ORG1 vs FACTURAPI_SECRET_KEY_ORG2). Las llaves NUNCA
// viven en el frontend. Default = '2' (la organización más reciente).
function huGetFacturapiOrg() {
  try {
    const v = String(localStorage.getItem('HU_FACTURAPI_ORG') || '').trim();
    if (v === '1' || v === '2') return v;
  } catch(_) {}
  return '2';
}
function huFacturapiSetOrg(org) {
  org = (org === '1') ? '1' : '2';
  try { localStorage.setItem('HU_FACTURAPI_ORG', org); } catch(_) {}
  huFacturapiPaintOrgToggle();
  const ifr = document.getElementById('hu-facturapi-frame');
  const ext = document.getElementById('hu-facturapi-external');
  if (ifr && ifr.src && ifr.src !== 'about:blank') {
    const next = huFacturapiReplaceOrgInUrl(ifr.src, org);
    ifr.src = next;
    if (ext) ext.href = next;
  }
}
function huFacturapiReplaceOrgInUrl(url, org) {
  try {
    const u = new URL(url);
    u.searchParams.set('org', org);
    return u.toString();
  } catch(_) {
    if (/[?&]org=/.test(url)) return url.replace(/([?&]org=)[^&]*/, '$1' + org);
    return url + (url.includes('?') ? '&' : '?') + 'org=' + org;
  }
}
function huFacturapiPaintOrgToggle() {
  const cur = huGetFacturapiOrg();
  document.querySelectorAll('#hu-facturapi-org-toggle button[data-org]').forEach(btn => {
    const active = btn.getAttribute('data-org') === cur;
    btn.style.background = active ? '#fff' : 'transparent';
    btn.style.color      = active ? '#0f172a' : '#fff';
  });
}
document.addEventListener('DOMContentLoaded', huFacturapiPaintOrgToggle);
// Cache warming: los reportes (Incidencias + Objetos) son consultados por
// el modal WhatsApp desde Chats bot. Precargarlos al arrancar la app
// evita que el user vea delay de ~2-5s al primer 'Ver WA' esperando el
// fetch a Apps Script. Fire-and-forget, no bloquea nada.
document.addEventListener('DOMContentLoaded', () => {
  setTimeout(() => {
    try { if (typeof incLoadIncidencias === 'function') incLoadIncidencias().catch(()=>{}); } catch(_){}
    try { if (typeof objLoadObjetos === 'function') objLoadObjetos().catch(()=>{}); } catch(_){}
  }, 1500); // pequeño delay para no competir con el fetch inicial de conversations/tickets
});

const HU_CHECKIN_WEBAPP_URL = 'https://script.google.com/macros/s/AKfycbwqMfC6tITLXlhEwYzQ5mKzw-KD6-nV7XVKIuekj6pK4Po50oRfVKClZeHcr-si3ppB/exec';

function huNormalizeCurrencyFromSheet(v) {
  const raw = String(v||'').trim().toUpperCase();
  if (!raw) return 'MXN';
  if (raw.includes('USD') || raw.includes('DÓLAR') || raw.includes('DOLAR')) return 'USD';
  if (raw.includes('EUR') || raw.includes('EURO')) return 'EUR';
  if (raw.includes('GBP') || raw.includes('LIBRA')) return 'GBP';
  if (raw.includes('BRL') || raw.includes('REAL')) return 'BRL';
  return 'MXN';
}

function huResolveConceptoPorRegimen(regimenFiscal) {
  // Regla del negocio: CUALQUIER régimen de Persona Moral → concepto 1.
  // Todo lo demás (persona física, RESICO física, etc.) → concepto 2.
  // Aplica también a 603 (Personas Morales con Fines no Lucrativos) y a
  // 626 Régimen Simplificado si es de Persona Moral — todos son PM.
  const norm = String(regimenFiscal || '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/^\s*\d{2,4}\s*[·\-|\/:.\s]*/, '') // quita "601·", "612 -", etc.
    .replace(/\s+/g, ' ')
    .trim().toLowerCase();
  const esPersonaMoral = /personas?\s+morales?/.test(norm);
  if (esPersonaMoral) return '1. Arrendamiento en Saltillo, Coah.';
  return '2. Arrendamiento en Saltillo, Coah.';
}

function huNormalizePhoneWA(phone) {
  let clean = String(phone || '').replace(/\D/g, '');
  if (!clean) return '';
  if (clean.length === 10) clean = '52' + clean;
  return clean;
}

function huFmtMontoEditable(v) {
  const raw = String(v||'').trim();
  if (!raw) return '';
  const limpio = raw.replace(/[^0-9.,-]/g, '').replace(/,/g, '');
  return limpio;
}

/** Construye la URL completa de facturapi con todos los params (igual al original).
 *  cantidadOverride: si se pasa, sobrescribe el valor de "quantity" (típicamente
 *  proveniente del input calculado del card). */
function huBuildFacturapiUrlFromRow(row, baseUrl, cantidadOverride) {
  const p = new URLSearchParams();
  p.set('source', 'control_huespedes');
  const cantidad = (cantidadOverride != null && String(cantidadOverride).trim() !== '')
    ? huFmtMontoEditable(cantidadOverride)
    : huFmtMontoEditable(huValueFlexible(row, ['$ Monto facturado Total','Monto facturado Total']));
  p.set('quantity', cantidad || '1');
  p.set('currency', huNormalizeCurrencyFromSheet(huValueFlexible(row, ['Divisa monto pagado','Moneda','Currency'])));
  const email     = huValueFlexible(row, ['Correo electrónico','Correo electronico','Email']);
  const whatsapp  = huNormalizePhoneWA(huValueFlexible(row, ['Cel/Whatsapp (principal)','Celular principal','Whatsapp principal']));
  const taxRegime = huValueFlexible(row, ['Régimen fiscal','Regimen fiscal','Tax regime']);
  const concepto  = huResolveConceptoPorRegimen(taxRegime);
  const recordId  = String(row['ID'] || row['row_number'] || '').trim();
  const rowNumber = String(row['row_number'] || '').trim();
  if (email) p.set('email', email);
  if (concepto) { p.set('concepto', concepto); p.set('descripcion', concepto); }
  if (whatsapp) p.set('whatsapp', whatsapp);
  if (taxRegime) p.set('taxRegime', taxRegime);
  if (recordId) {
    p.set('externalId', 'CHECKIN-' + recordId);
    p.set('recordId', recordId);
    p.set('rowNumber', rowNumber);
  }
  p.set('checkinWebAppUrl', HU_CHECKIN_WEBAPP_URL);
  p.set('org', huGetFacturapiOrg());
  // Marca que el ticket fue emitido DESDE EL SISTEMA (admin en Gestión de
  // reservas / Chats-bot). El popup lo forwardea al backend y Apps Script
  // lo escribe en la columna "Medio de emisión" de Reservaciones.
  // Guest desde /registro o /guia NO pasa este param → default backend =
  // "auto-facturación".
  p.set('medio_emision', 'facturación sistema');
  // Fechas + propiedad de la reserva (para el popup "Enviar correo y WA" que
  // programa el envío basándose en la salida). Normalizamos a YYYY-MM-DD.
  const _dateIso = (v) => {
    const s = String(v || '').trim();
    if (!s) return '';
    if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0,10);
    // Fallback: intentar parsear (MM/DD/YYYY o similar)
    const d = new Date(s);
    if (!isNaN(d.getTime())) return d.toISOString().slice(0,10);
    return '';
  };
  const fechaSalida = _dateIso(huValueFlexible(row, ['Fecha de salida','fecha_salida','DateDeparture']));
  const fechaIngreso = _dateIso(huValueFlexible(row, ['Fecha de ingreso','fecha_ingreso','DateArrival']));
  const propiedad = String(huValueFlexible(row, ['Propiedad','propiedad']) || '').trim();
  const depto = String(huValueFlexible(row, ['# Departamento','depto','departamento']) || '').trim();
  const nombre = String(huValueFlexible(row, ['Nombre','nombre','GuestName']) || '').trim();
  if (fechaSalida) p.set('fechaSalida', fechaSalida);
  if (fechaIngreso) p.set('fechaIngreso', fechaIngreso);
  if (propiedad) p.set('propiedad', propiedad);
  if (depto) p.set('depto', depto);
  if (nombre) p.set('nombre', nombre);
  // Cache-buster: fuerza recarga del iframe HTML aunque Fastly tenga versión
  // vieja cacheada. Cada apertura genera un nonce único.
  p.set('_ts', String(Date.now()));
  return `${baseUrl}?${p.toString()}`;
}

/** Genera ticket facturapi para un registro. */
async function huespedesGenerarTicket(recordId) {
  if (!recordId) { alert('No se pudo identificar el registro.'); return; }

  // CRÍTICO: si hay un debounce de persist pendiente, dispararlo YA y
  // esperar. Después, awaitar TODOS los POSTs de persist en vuelo. Sin esto,
  // el popup de Facturapi se abre con recordId y lee del sheet ANTES de que
  // el monto recién importado se haya guardado → quantity queda en "1".
  if (typeof HU_RECALC_TIMER !== 'undefined' && HU_RECALC_TIMER) {
    clearTimeout(HU_RECALC_TIMER);
    HU_RECALC_TIMER = null;
    // Disparar persist inmediato del card actual antes de awaitar
    const cardNow = document.querySelector(`.hu-record[data-record-id="${recordId}"]`)
                 || document.querySelector(`.hu-resv-cobros[data-hu-resv-id="${recordId}"]`)
                 || document.querySelector(`.hu-resv-detail[data-hu-resv-id="${recordId}"]`);
    if (cardNow) {
      try { __huTrackPersist(huPersistCardMonto(cardNow)); } catch (_) {}
    }
  }
  if (window.__huPendingPersists && window.__huPendingPersists.size) {
    // Race contra timeout de 4s. Si un persist previo se colgó (hipo de
    // Apps Script, timeout intermedio, etc.), no bloqueamos el flujo
    // indefinidamente — mejor abrir Facturapi con datos posiblemente
    // ligeramente desactualizados que dejar el botón sin efecto.
    const _timeout = new Promise(resolve => setTimeout(resolve, 4000));
    const _all = Promise.all([...window.__huPendingPersists]).catch(() => {});
    await Promise.race([_all, _timeout]);
  }

  // Buscar row en cache local
  let row = (HU_STATE.rows || []).find(r => String(r['ID']||r['row_number']||'') === String(recordId));
  if (!row) { alert('No se encontró la información del registro seleccionado.'); return; }

  // Si falta régimen fiscal, lo traemos del detalle (igual que el original)
  const missingRegime = !huValueFlexible(row, ['Régimen fiscal','Regimen fiscal','Tax regime']);
  if (missingRegime) {
    try {
      const res = await fetch(`${BACKEND}/huespedes-detail?record_id=${encodeURIComponent(recordId)}`);
      const json = await res.json();
      if (json?.ok && json.record) row = { ...row, ...json.record };
    } catch (_) {}
  }

  // Leer el monto facturado actual del input calculado del card (el valor
  // ya considera el cálculo Airbnb − comisión cuando aplica). El card puede
  // estar en cualquiera de las 3 vistas: .hu-record (huéspedes legacy),
  // .hu-resv-detail (Detalles fusionada legacy), .hu-resv-cobros (Detalles
  // dividida actual). Buscamos por data-hu-resv-id o data-record-id; si nada
  // matchea por recordId, caemos al primer input airbnb visible en pantalla
  // (porque en vista Detalles solo hay 1 caja visible a la vez).
  let cantidad = '';
  const card = document.querySelector(`.hu-record[data-record-id="${recordId}"]`)
            || document.querySelector(`.hu-resv-cobros[data-hu-resv-id="${recordId}"]`)
            || document.querySelector(`.hu-resv-detail[data-hu-resv-id="${recordId}"]`);
  const facInput = card?.querySelector('[data-hu-airbnb-facturado="1"]')
                || document.querySelector('[data-hu-airbnb-facturado="1"]');
  if (facInput && String(facInput.value).trim() !== '') cantidad = facInput.value;

  // URL base de facturapi (hardcoded al Cloud Run del check-in, override
  // posible vía localStorage.HU_FACTURAPI_URL)
  const base = huGetFacturapiUrl();
  const url = huBuildFacturapiUrlFromRow(row, base, cantidad);
  if (!url) { alert('No se pudo construir la URL de Facturapi.'); return; }

  // Abrir en modal con iframe embebido (en lugar de pestaña independiente)
  huespedesOpenFacturapi(url);
}

/** Re-emitir ticket: archiva el folio actual (lo mueve a la columna "Folio
 *  facturapi antiguo" del sheet de Reservaciones), limpia los campos del
 *  ticket actual, y abre Facturapi con los mismos montos para que el usuario
 *  emita uno nuevo. El nuevo folio reemplazará al archivado.
 *  Pide confirmación porque NO se puede deshacer desde la UI. */
window.huespedesReemitirTicket = async function(recordId) {
  if (!recordId) { alert('No se pudo identificar el registro.'); return; }
  const row = (HU_STATE.rows || []).find(r => String(r['ID']||r['row_number']||'') === String(recordId));
  if (!row) { alert('No se encontró la información del registro.'); return; }
  const folioActual = huValueFlexible(row, ['Folio facturapi','Folio Facturapi','Folio']);
  const ok = await (typeof showConfirm === 'function' ? showConfirm({
    icon: '🔄',
    title: '¿Re-emitir ticket?',
    msg: `El folio actual ${folioActual ? '#' + folioActual + ' ' : ''}se moverá a la columna "Folio facturapi antiguo" y se abrirá Facturapi para emitir uno nuevo. No se puede deshacer.`,
    okLabel: 'Sí, re-emitir',
  }) : Promise.resolve(window.confirm(`¿Re-emitir ticket? El folio ${folioActual||''} se archivará y se generará uno nuevo.`)));
  if (!ok) return;
  // 1) Archivar el folio actual en el sheet
  try {
    if (typeof showLoading === 'function') showLoading('Archivando folio actual…', 'Sheets');
    const res = await fetch(HU_CHECKIN_WEBAPP_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify({
        action: 'archive_folio_for_reemit',
        record_id: recordId,
      }),
      redirect: 'follow',
    });
    const json = await res.json().catch(() => ({}));
    if (!json.ok) {
      throw new Error(json.error || json.message || 'Falló el archivado');
    }
    // Reflejar limpieza local (para que el render siguiente no muestre el folio viejo)
    row['Folio facturapi'] = '';
    row['Folio CFDI'] = '';
    row['Ticket facturapi url'] = '';
    row['Estatus'] = '';
    row['Fecha de emisión'] = '';
    if (json.previous_folio) {
      const prev = String(row['Folio facturapi antiguo'] || '').trim();
      row['Folio facturapi antiguo'] = prev ? `${prev}, ${json.previous_folio}` : json.previous_folio;
    }
  } catch (e) {
    console.error('[HU] archive error:', e);
    alert('No se pudo archivar el folio actual: ' + (e.message || e));
    return;
  } finally {
    if (typeof hideLoading === 'function') hideLoading();
  }
  // 2) Abrir Facturapi con los mismos montos — mismo flujo que Generar Ticket
  await huespedesGenerarTicket(recordId);
};

/** Abre el modal de Facturapi con el iframe apuntando a la URL dada. */
// Marca como "atendido" cualquier solicitud pendiente de ticket_autofacturacion
// que corresponda a la reserva emitida — cierra el bucle bot→admin.
window._huCerrarSolicitudTicketAutofact_ = async function(row) {
  try {
    const reservaId = String(row['Lodgify Id'] || row['LodgifyId'] || row['ReservaId'] || '').trim();
    if (!reservaId) return;
    const r = await fetch('https://api.check-inn.mx/solicitudes?estado=pendiente', { cache:'no-store' });
    const j = await r.json();
    const rows = (j && j.ok && Array.isArray(j.rows)) ? j.rows : [];
    const matches = rows.filter(s =>
      String(s.Tipo||'').toLowerCase() === 'ticket_autofacturacion' &&
      String(s.ReservaId||'') === reservaId
    );
    if (!matches.length) return;
    const admin = (typeof getCurrentUserName === 'function' ? getCurrentUserName() : '') ||
                  localStorage.getItem('user_nombre') || 'Admin';
    for (const m of matches) {
      try {
        await fetch(`https://api.check-inn.mx/solicitudes/${encodeURIComponent(m.ID)}/estado`, {
          method:'POST', headers:{'Content-Type':'application/json'},
          body: JSON.stringify({ estado:'atendido', AtendidoPor: admin, Notas: 'Auto-cerrada al emitir ticket en FacturAPI' }),
        });
      } catch(_){}
    }
    console.info('[HU-ticket] solicitudes ticket_autofacturacion cerradas:', matches.length);
    try { if (typeof window._botcNotifRefreshBadge_ === 'function') window._botcNotifRefreshBadge_(); } catch(_){}
    // Si el panel Notificaciones sigue abierto, re-renderiza para que las
    // cards muestren estado actualizado (atendida + quién + timestamp).
    try {
      if (document.getElementById('botc-notifs-modal') && typeof window._botcOpenNotifsGlobal_ === 'function') {
        window._botcOpenNotifsGlobal_(null, null, true);
      }
    } catch(_){}
  } catch(e) { console.warn('[HU-ticket] cerrar solicitud fallo:', e.message); }
};

// Listener global para postMessage del iframe Facturapi. Cuando el popup
// "Enviar correo y WhatsApp" envía el WA, avisa aquí para que el auto-schedule
// (que corre al cerrar el iframe) NO cree un segundo envío duplicado.
if (!window.__waManualSentListenerInstalled) {
  window.__waManualSentListenerInstalled = true;
  window.__waManualSentUrls = window.__waManualSentUrls || new Set();
  window.addEventListener('message', function(ev) {
    const d = ev && ev.data;
    if (d && d.type === 'wa-manual-sent' && d.ticketUrl) {
      window.__waManualSentUrls.add(String(d.ticketUrl));
      window.__waManualSentThisSession = true;
      console.info('[HU-ticket] marcada como enviada manual:', d.ticketUrl);
      // Al confirmar envío por correo/WhatsApp, cerrar TAMBIÉN el modal
      // FacturAPI de fondo — no dejar dos overlays abiertos.
      try { if (typeof huespedesCloseFacturapi === 'function') huespedesCloseFacturapi(); } catch(_){}
    }
  });
}

function huespedesOpenFacturapi(url) {
  // Reset del flag "popup ya envió WA en esta sesión" — se prende cuando el
  // iframe FacturAPI emite postMessage 'wa-manual-sent'. Si termina prendido
  // al cerrar, saltamos el auto-schedule para evitar mensaje duplicado.
  window.__waManualSentThisSession = false;
  // Snapshot de URLs de tickets ANTES de abrir Facturapi. Al cerrarse, el
  // hook comparará y disparará auto-schedule del WA para cada URL nueva.
  try {
    window.__huTicketUrlSnapshot = new Map();
    for (const r of (HU_STATE.rows || [])) {
      const id = String(r['ID'] || r['row_number'] || '');
      if (id) window.__huTicketUrlSnapshot.set(id, String(r['Ticket facturapi url'] || '').trim());
    }
    console.info('[HU-ticket] snapshot capturado con', window.__huTicketUrlSnapshot.size, 'rows');
  } catch(e) { console.warn('[HU-ticket] snapshot falló:', e.message); }
  const ov   = document.getElementById('hu-facturapi-overlay');
  const ifr  = document.getElementById('hu-facturapi-frame');
  const ext  = document.getElementById('hu-facturapi-external');
  if (!ov || !ifr) { window.open(url, '_blank', 'noopener'); return; }
  if (ext) ext.href = url;
  ifr.src = url;
  ov.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
  huFacturapiPaintOrgToggle();
}

/** Cierra el modal de Facturapi. */
function huespedesCloseFacturapi() {
  const ov  = document.getElementById('hu-facturapi-overlay');
  const ifr = document.getElementById('hu-facturapi-frame');
  if (ifr) ifr.src = 'about:blank';
  if (ov) ov.classList.add('hidden');
  document.body.style.overflow = '';
  // Refresca para reflejar folio + monto facturado guardados por Facturapi.
  // Pequeño delay para que el Apps Script termine de escribir/flush
  // antes de re-leer (evita race condition entre cierre del modal y refresh).
  if (HU_STATE.loaded) {
    const lbl = document.getElementById('hu-status-label');
    if (lbl) lbl.textContent = 'Actualizando…';
    setTimeout(async () => {
      // Detecta cambios de URL comparando snapshot pre vs HU_STATE.rows actual.
      const _detectChanges = () => {
        const snap = window.__huTicketUrlSnapshot;
        if (!snap || !snap.size) return [];
        const out = [];
        for (const r of (HU_STATE.rows || [])) {
          const id = String(r['ID'] || r['row_number'] || '');
          if (!id) continue;
          const newUrl = String(r['Ticket facturapi url'] || '').trim();
          const oldUrl = snap.get(id) || '';
          if (newUrl && newUrl !== oldUrl) out.push({ row: r, id, newUrl, oldUrl });
        }
        return out;
      };
      // Reload con polling: hasta 4 intentos, 2.5s de espera si sheet aún no
      // reflejó la URL nueva (FacturAPI escribe async y a veces tarda unos s).
      let changed = [];
      for (let attempt = 1; attempt <= 4; attempt++) {
        try { await huespedesLoad(true); } catch(_) {}
        changed = _detectChanges();
        console.info(`[HU-ticket] intento ${attempt}: ${changed.length} cambios detectados`);
        if (changed.length) break;
        if (attempt < 4) await new Promise(rs => setTimeout(rs, 2500));
      }
      try {
        const snap = window.__huTicketUrlSnapshot;
        if (snap && snap.size) {
          console.info('[HU-ticket] post-refresh: comparando snapshot vs rows nuevas');
          console.info('[HU-ticket] cambios:', changed.length);
          window.__huTicketUrlSnapshot = null; // consumido
          // Skip TODO el auto-schedule si en esta sesión de FacturAPI el popup
          // ya envió el mensaje manual — evita duplicados (popup y auto-schedule
          // usan URLs distintas para el mismo PDF: dedup por URL fallaba).
          const popupAlreadySent = !!window.__waManualSentThisSession;
          window.__waManualSentUrls = window.__waManualSentUrls || new Set();
          for (const c of changed) {
            if (popupAlreadySent || window.__waManualSentUrls.has(c.newUrl)) {
              console.info('[HU-ticket] skip auto-schedule (popup ya envió) para', c.newUrl);
              // Aún cerrar la solicitud pendiente aunque saltemos el WA.
              try { await window._huCerrarSolicitudTicketAutofact_(c.row); } catch(_){}
              continue;
            }
            if (typeof window._huAutoScheduleTicketWa === 'function') {
              await window._huAutoScheduleTicketWa(c.row, c.newUrl);
            } else if (typeof window.huScheduleTicketWaNow === 'function') {
              await window.huScheduleTicketWaNow(c.id);
            }
            // Cerrar solicitud pendiente de ticket_autofacturacion (si existe)
            // matcheando por Lodgify Id de la reserva. Aparece atendida en Notif.
            try { await window._huCerrarSolicitudTicketAutofact_(c.row); } catch(_){}
          }
          // Refrescar el modal WhatsApp abierto (si aplica) para que las
          // cards nuevas aparezcan sin cerrar+reabrir.
          if (changed.length) {
            const st = window.__waModalState;
            if (st && st.bookingId) {
              try {
                const r2 = await fetch('https://api.check-inn.mx/wa/scheduled-list', {
                  method: 'POST', headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ bookingId: st.bookingId }),
                });
                const j2 = await r2.json();
                st.scheduledItems = (j2 && j2.items) || [];
                if (typeof _waRepaint === 'function') _waRepaint();
                console.info('[HU-ticket] modal WA refrescado');
              } catch(_) {}
            }
          }
        }
      } catch (e) { console.warn('[HU-ticket] auto-schedule falló:', e); }
      // También re-renderizar Gestión de reservas: las cards toman el color
      // de huGetFacturaStatus(huesped), que cambió de 'pendiente' a
      // 'emitida'. Sin esto, la card permanece roja hasta navegar.
      try {
        // Invalidar caches y recomputar matches
        LG_STATE.__syntheticCache = null;
        LG_STATE.__syntheticCacheKey = null;
        LG_STATE.__huIdxPhoneDates = null;
        LG_STATE.__huIdxPropDates  = null;
        LG_STATE.__huIdxRowsCount  = null;
        window.__huGuestIndex = null;
        window.__huGuestStatsCache = null;
        if (typeof lgComputeMatches === 'function') lgComputeMatches();
        window.LG_USER_INTERACTED = false;
        if (typeof lodgifyRender === 'function' && LG_STATE.loaded) {
          lodgifyRender({ force: true });
        }
        // Re-render explícito de la lista Huéspedes (por si la vista está en
        // Reservas manuales / Huéspedes) para que las cards muestren el nuevo
        // estado "ticket emitido" sin esperar a otra navegación.
        if (typeof huespedesRender === 'function') huespedesRender();
      } catch (e) { console.warn('[HU] re-render lodgify tras facturapi:', e); }
      // Refresh incondicional del panel Notificaciones si está abierto — así
      // toda acción disparada desde ahí queda reflejada al cerrar FacturAPI
      // (incluso si el usuario canceló sin emitir).
      try {
        if (document.getElementById('botc-notifs-modal') && typeof window._botcOpenNotifsGlobal_ === 'function') {
          window._botcOpenNotifsGlobal_(null, null, true);
        }
        if (typeof window._botcNotifRefreshBadge_ === 'function') window._botcNotifRefreshBadge_();
      } catch(_){}
    }, 600);
  }
}

// Esc cierra el modal de Facturapi
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    const ov = document.getElementById('hu-facturapi-overlay');
    if (ov && !ov.classList.contains('hidden')) huespedesCloseFacturapi();
  }
});

/** Permite resetear la URL base si quedó mal configurada. */
window.huespedesResetFacturapiUrl = function() {
  try { localStorage.removeItem('HU_FACTURAPI_URL'); } catch(_) {}
  alert('URL de Facturapi reseteada. La próxima vez que generes un ticket te pedirá la URL nueva.');
};

/** Cambia entre vista Lista y Calendario. */
function huespedesSetView(v) {
  HU_STATE.view = v;
  document.getElementById('hu-view-lista').style.background       = v === 'lista'      ? '#334155' : '#fff';
  document.getElementById('hu-view-lista').style.color            = v === 'lista'      ? '#fff'    : '#475569';
  document.getElementById('hu-view-calendario').style.background  = v === 'calendario' ? '#334155' : '#fff';
  document.getElementById('hu-view-calendario').style.color       = v === 'calendario' ? '#fff'    : '#475569';
  huespedesRender();
}

/** Vista Calendario simplificada: agrupa por propiedad → lista días ocupados. */
function huRenderCalendar(rows) {
  if (!rows.length) return `<div class="empty-state" style="padding:30px;text-align:center;color:#94a3b8;font-size:13px">Sin reservaciones para el período seleccionado.</div>`;
  // Agrupar por propiedad
  const byProp = {};
  for (const r of rows) {
    const p = huValueFlexible(r, ['Propiedad']) || '(Sin propiedad)';
    if (!byProp[p]) byProp[p] = [];
    byProp[p].push(r);
  }
  const propsHtml = Object.entries(byProp).sort((a, b) => a[0].localeCompare(b[0])).map(([prop, recs]) => {
    const rowsHtml = recs.map(r => {
      const ingreso = huValueFlexible(r, ['Fecha de ingreso']);
      const salida  = huValueFlexible(r, ['Fecha de salida']);
      const noches  = huValueFlexible(r, ['# Noches']);
      const nombre  = huValueFlexible(r, ['Nombre de la persona que hizo la reservación']);
      const status  = huGetFacturaStatus(r);
      const color   = status === 'pendiente' ? '#dc2626' : status === 'emitida' ? '#16a34a' : '#64748b';
      return `<div style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-bottom:1px solid #f3f4f6">
        <span style="width:8px;height:8px;border-radius:50%;background:${color};flex-shrink:0"></span>
        <div style="flex:1;font-size:12px;color:#1f2937"><b>${esc(nombre)}</b> · ${esc(ingreso)} → ${esc(salida)} (${esc(noches)} noche${noches==='1'?'':'s'})</div>
      </div>`;
    }).join('');
    return `<div style="margin-bottom:14px">
      <div style="background:#f1f5f9;padding:8px 12px;border-radius:8px 8px 0 0;font-weight:800;color:#334155;font-size:13px">🏠 ${esc(prop)} <span style="color:#64748b;font-weight:600">(${recs.length})</span></div>
      <div style="border:1px solid #e2e8f0;border-radius:0 0 8px 8px">${rowsHtml}</div>
    </div>`;
  }).join('');
  return propsHtml;
}

/** Abre el modal de detalle de una reservación. */
async function huespedesOpenDetail(recordId) {
  const ov = document.getElementById('hu-detail-overlay');
  const body = document.getElementById('hu-detail-body');
  const title = document.getElementById('hu-detail-title');
  if (!ov || !body) return;
  ov.classList.remove('hidden');
  body.innerHTML = '<div style="padding:30px;text-align:center;color:#94a3b8">Cargando detalle…</div>';
  if (title) title.textContent = 'Detalle de reservación';
  try {
    const res = await fetch(`${BACKEND}/huespedes-detail?record_id=${encodeURIComponent(recordId)}`);
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'Error al obtener detalle');
    const r = data.record || {};
    if (title) title.textContent = `${r['Nombre de la persona que hizo la reservación'] || 'Reservación'} · ${r['Fecha de ingreso'] || ''}`;
    const rows = Object.entries(r)
      .filter(([k, v]) => k !== '__row_number' && v != null && String(v).trim() !== '')
      .map(([k, v]) => `<tr style="border-bottom:1px solid #f3f4f6">
        <td style="padding:6px 10px;font-weight:700;color:#475569;font-size:11px;text-transform:uppercase;letter-spacing:.04em;background:#f8fafc;width:38%">${esc(k)}</td>
        <td style="padding:6px 10px;color:#1f2937;font-size:12px;word-break:break-word">${esc(String(v))}</td>
      </tr>`).join('');
    body.innerHTML = `<table style="width:100%;border-collapse:collapse">${rows}</table>`;
  } catch (e) {
    body.innerHTML = `<div style="padding:20px;color:#dc2626">⚠ ${esc(e.message)}</div>`;
  }
}

/** Exporta los registros filtrados a CSV. */
function huespedesExportCsv() {
  if (!HU_STATE.filteredRows.length) {
    alert('No hay registros para exportar.');
    return;
  }
  const headers = [
    '¿Requiere factura?','$ Monto facturado Total','Fecha de ingreso','Fecha de salida',
    'Nombre de la persona que hizo la reservación','Medio de reservación',
    'Cel/Whatsapp (principal)','Razón social','Forma de pago','Correo electrónico',
    'Propiedad','# Departamento','# Huéspedes'
  ];
  const esc2 = s => `"${String(s ?? '').replace(/"/g, '""')}"`;
  const lines = [headers.join(','), ...HU_STATE.filteredRows.map(r => headers.map(h => esc2(r[h])).join(','))];
  const blob = new Blob(['﻿' + lines.join('\n')], { type: 'text/csv;charset=utf-8;' });
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement('a');
  a.href     = url;
  a.download = `huespedes_${new Date().toISOString().slice(0,10)}.csv`;
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
}

// ═══════════════════════════════════════════════════════════════════════════
// ─── MÓDULO: Reservas Lodgify ──────────────────────────────────────────────
// Consume el backend de Lodgify (mismo que usa el archivo "otc_FIXED_…html")
// que ya está deployado en Cloud Run. Aggrega los rows por booking Id porque
// la API devuelve un row por LineItem (RoomRate + Fee + …).
// ═══════════════════════════════════════════════════════════════════════════

const LG_API_BASE = "https://checkinnreservas-1044570371371.northamerica-south1.run.app";
const LG_STATE = {
  raw: [],          // rows tal cual del backend (uno por line item)
  bookings: [],     // agregados por Id
  checkOuts: [],    // filas de la hoja "check_out" (piggyback en lodgify-list)
  checkOutIdx: null, // Map key=propNorm|deptoStr|salidaISO → row de check_out
  loaded: false,
  loading: false,
  from: '',
  to: '',
  viewMode: 'cards', // 'cards' | 'kanban' | 'table' | 'detail' | 'list' (default: cards)
  sortKey: '',      // columna activa para sort (vista tabla)
  sortDir: '',      // 'asc' | 'desc' | ''
  lastAutoSyncMs: 0,
  // multi-select state: id → Set de valores seleccionados
  multiSel: {
    programacion: null,
    source: null,
    status: null,
    propiedad: null,
    factura: null,
    meses: null,
    calificacion: null,
    incidencias: null,
    objetos: null,
  },
  // Map booking.Id (string) → row de Información de huéspedes
  matches: new Map(),
};

/** Normaliza un teléfono a solo dígitos. Útil para comparar números
 *  internacionales o locales con formatos distintos. */
function lgNormalizePhone(phone) {
  return String(phone || '').replace(/\D/g, '');
}

/** Convierte MM/DD/YYYY → YYYY-MM-DD para comparar contra fechas de
 *  Información de huéspedes (que vienen del Sheets ISO). */
/** Normaliza cualquier formato de fecha a ISO YYYY-MM-DD. Tolerante a:
 *   - MM/DD/YYYY (Lodgify nativo)
 *   - YYYY-MM-DD (huespedes / manual)
 *   - "YYYY-MM-DDT..." (ISO con tiempo)
 *   - Date object
 *  Devuelve '' si el input no matchea ningún patrón conocido.
 *  Antes solo aceptaba MM/DD/YYYY, lo que rompía filtros (mes, estado) para
 *  bookings sintéticos de reservas manuales que traen fecha ISO. Ahora el
 *  filtro es formato-agnóstico. */
function lgMMDDtoIsoDate(v) {
  if (v == null) return '';
  if (v instanceof Date && !isNaN(v.getTime())) {
    return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;
  }
  const s = String(v).trim();
  if (!s) return '';
  // ISO YYYY-MM-DD (con o sin tiempo)
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  // MM/DD/YYYY (Lodgify nativo)
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${m[3]}-${String(m[1]).padStart(2,'0')}-${String(m[2]).padStart(2,'0')}`;
  return '';
}

/** Normaliza CUALQUIER formato de fecha a "YYYY-MM-DD".
 *  Acepta:
 *    - "2026-06-13T06:00:00.000Z" (ISO con timezone — usa solo la parte de fecha)
 *    - "2026-06-13"               (ya en formato canónico)
 *    - "06/13/2026"               (MM/DD/YYYY Lodgify)
 *    - "13/06/2026"               (DD/MM/YYYY no usado pero por seguridad)
 *    - Date object
 *  Devuelve string vacío si no es parseable. */
function lgFmtDateUI(v) {
  if (v == null) return '';
  if (v instanceof Date && !isNaN(v.getTime())) {
    return `${v.getFullYear()}-${String(v.getMonth()+1).padStart(2,'0')}-${String(v.getDate()).padStart(2,'0')}`;
  }
  const s = String(v).trim();
  if (!s) return '';
  // ISO: "2026-06-13" o "2026-06-13T06:00:00.000Z" → tomar solo los primeros 10 chars
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  // MM/DD/YYYY (Lodgify nativo)
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${m[3]}-${String(m[1]).padStart(2,'0')}-${String(m[2]).padStart(2,'0')}`;
  // Última opción: dejar tal cual
  return s;
}

/** Normaliza texto para comparación tolerante: minúsculas + sin acentos +
 *  sin caracteres especiales. Útil para comparar nombres y propiedades. */
function lgNormalizeText(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // quita tildes
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/** Similitud trigramaria entre dos strings (0..1). Tolerante a diferencias
 *  pequeñas como espacios, orden de palabras, abreviaciones. */
function lgSimilarity(a, b) {
  const na = lgNormalizeText(a);
  const nb = lgNormalizeText(b);
  if (!na || !nb) return 0;
  if (na === nb) return 1;
  if (na.includes(nb) || nb.includes(na)) return 0.9;
  // Por palabras: cuántas palabras de la más corta están en la más larga
  const wa = new Set(na.split(' ').filter(w => w.length > 1));
  const wb = new Set(nb.split(' ').filter(w => w.length > 1));
  if (!wa.size || !wb.size) return 0;
  let common = 0;
  for (const w of wa) if (wb.has(w)) common++;
  return common / Math.min(wa.size, wb.size);
}

/** Diferencia en días entre dos fechas ISO (YYYY-MM-DD). Devuelve Infinity
 *  si alguna no es válida. */
function lgDaysDiff(isoA, isoB) {
  if (!isoA || !isoB) return Infinity;
  const a = new Date(isoA.slice(0,10));
  const b = new Date(isoB.slice(0,10));
  if (isNaN(a.getTime()) || isNaN(b.getTime())) return Infinity;
  return Math.abs(Math.round((a - b) / 86400000));
}

/** Devuelve los últimos 10 dígitos del PRIMER campo del row que parezca un
 *  teléfono (clave contiene "cel", "whats", "tel" o "phone"). Esto es más
 *  robusto que buscar nombres exactos de campos. */
function lgExtractHuespedPhoneTail(h) {
  if (!h || typeof h !== 'object') return '';
  for (const k of Object.keys(h)) {
    const norm = String(k).toLowerCase();
    if (!/cel|whats|tel[eé]?fono|phone/.test(norm)) continue;
    if (/emergencia|emergency/.test(norm)) continue; // ignorar el de emergencia
    const digits = lgNormalizePhone(h[k]);
    if (digits.length >= 10) return digits.slice(-10);
  }
  return '';
}

/** Busca una coincidencia en HU_STATE.rows para un booking de Lodgify.
 *  CRITERIOS ESTRICTOS (los 2 deben cumplirse):
 *    1) Últimos 10 dígitos del teléfono (omitiendo espacios) coinciden.
 *    2) Fechas de entrada y salida coinciden exactamente. */
/** Normaliza nombre de propiedad para comparación (lowercase, sin acentos ni
 *  espacios extras ni símbolos). Usado por el matching "probable". */
function lgNormPropName(s) {
  return String(s || '')
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

/** Normaliza # Departamento (deja solo dígitos/letras significativas). */
function lgNormDeptNum(s) {
  return String(s == null ? '' : s).replace(/[^0-9a-z]/gi, '').toLowerCase();
}

/** Construye la clave canónica "propiedad+departamento" para agrupar
 *  reservaciones. SIEMPRE incluye el departamento — sin él, "Calle X · #1"
 *  y "Calle X · #10" se confundirían como la misma propiedad.
 *
 *  Si `deptRaw` viene vacío, intenta extraer el `#N` del final de `propRaw`
 *  (ej. "Calle Cumbres - #8" → prop="calle cumbres", dept="8"). Esto es
 *  necesario porque las filas propagadas desde Lodgify a Reservaciones
 *  llegan con el nombre concatenado y el # Departamento en blanco. */
function lgPropDeptKey(propRaw, deptRaw) {
  let p = String(propRaw == null ? '' : propRaw);
  let d = lgNormDeptNum(deptRaw);
  if (!d) {
    // Buscar "...# N", "...#N", "...- #N", "...#  10", "...· # 8" al final
    const m = p.match(/[#]\s*([0-9]+[a-z]?)\s*$/i);
    if (m) {
      d = lgNormDeptNum(m[1]);
      // Quitar el "[separadores] #N" del final para dejar solo el nombre
      p = p.replace(/[\s\-·•|,]*[#]\s*[0-9]+[a-z]?\s*$/i, '').trim();
    }
  }
  const pNorm = lgNormPropName(p);
  if (!pNorm) return '';
  return d ? `${pNorm}|d${d}` : pNorm;
}

/** Normaliza una "Fecha y hora" del check_out a ISO YYYY-MM-DD.
 *  Acepta Date (serializado a "2026-07-16T10:00:00.000Z"), "2026-07-16T10:00",
 *  "16/07/2026", "07/16/2026", etc. */
function lgNormCheckoutDate_(v) {
  if (!v) return '';
  const s = String(v).trim();
  if (!s) return '';
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`;
  const dmy = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (dmy) {
    // Ambiguo entre DD/MM/YYYY y MM/DD/YYYY. Si el primer número > 12, es día.
    let a = +dmy[1], b = +dmy[2], y = +dmy[3];
    let d, m;
    if (a > 12) { d = a; m = b; } else if (b > 12) { m = a; d = b; } else { d = a; m = b; }
    return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
  }
  return '';
}

/** Construye un índice Map key="propKey|YYYY-MM-DD" → row de check_out. */
function lgBuildCheckOutIndex_(rows) {
  const idx = new Map();
  for (const r of (rows || [])) {
    const pk = lgPropDeptKey(r['Propiedad'] || '', r['# Departamento'] || '');
    const iso = lgNormCheckoutDate_(r['Fecha y hora']);
    if (!pk || !iso) continue;
    idx.set(`${pk}|${iso}`, r);
  }
  return idx;
}

/** Devuelve el registro de check_out que coincide con esta reserva, o null. */
function lgFindCheckoutFor_(prop, depto, salidaAny) {
  if (!LG_STATE.checkOutIdx) return null;
  const pk = lgPropDeptKey(prop, depto);
  if (!pk) return null;
  let iso = '';
  const s = String(salidaAny || '');
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) iso = s.slice(0,10);
  else if (typeof lgFmtDateUI === 'function') iso = String(lgFmtDateUI(s) || '').slice(0,10);
  if (!iso) return null;
  return LG_STATE.checkOutIdx.get(`${pk}|${iso}`) || null;
}

/** Extrae la clave prop+depto de cualquier objeto (huesped row o booking). */
function lgPropDeptKeyFromAny(o) {
  if (!o) return '';
  const prop = o['Propiedad'] || o.PropiedadRaw || o.HouseName || (o.__reservacion && o.__reservacion['Propiedad']) || '';
  const dept = o['# Departamento'] || o.DepartamentoRaw || (o.__reservacion && o.__reservacion['# Departamento']) || '';
  return lgPropDeptKey(prop, dept);
}

/** Construye índices de HU_STATE.rows para que lgMatchHuesped sea O(1).
 *  Se llama una vez por sesión / recarga de huéspedes. */
function lgBuildHuespedIndexes_() {
  const rows = HU_STATE.rows || [];
  const byPhoneDates = new Map();   // tail|arrIso|depIso → h
  const byPropDates  = new Map();   // propDeptKey|arrIso|depIso → h[]
  for (const h of rows) {
    const tail = lgExtractHuespedPhoneTail(h);
    const arr  = String(huValueFlexible(h, ['Fecha de ingreso','Fecha de entrada']) || '').slice(0,10);
    const dep  = String(huValueFlexible(h, ['Fecha de salida']) || '').slice(0,10);
    if (!arr || !dep) continue;
    if (tail && tail.length === 10) {
      const k = `${tail}|${arr}|${dep}`;
      if (!byPhoneDates.has(k)) byPhoneDates.set(k, h);
    }
    const propKey = lgPropDeptKey(huValueFlexible(h, ['Propiedad','Alojamiento','Casa']),
                                   huValueFlexible(h, ['# Departamento','Departamento']));
    if (propKey) {
      const k = `${propKey}|${arr}|${dep}`;
      if (!byPropDates.has(k)) byPropDates.set(k, []);
      byPropDates.get(k).push(h);
    }
  }
  LG_STATE.__huIdxPhoneDates = byPhoneDates;
  LG_STATE.__huIdxPropDates  = byPropDates;
  LG_STATE.__huIdxRowsCount  = rows.length;
}

/** Devuelve { h, kind } donde kind = 'exact' (phone + fechas exactos) o
 *  'probable' (propiedad + fechas exactos, pero phone NO matchea o falta).
 *  Devuelve null si ningún criterio matchea. */
function lgMatchHuesped(booking) {
  const rows = HU_STATE.rows || [];
  if (!rows.length) return null;
  // (Re)construir índices si HU_STATE cambió
  if (!LG_STATE.__huIdxPhoneDates || LG_STATE.__huIdxRowsCount !== rows.length) {
    lgBuildHuespedIndexes_();
  }
  const bPhoneAll = lgNormalizePhone(booking.GuestPhone);
  const bPhone10 = bPhoneAll.slice(-10);
  const bArrIso = lgMMDDtoIsoDate(booking.DateArrival);
  const bDepIso = lgMMDDtoIsoDate(booking.DateDeparture);
  if (!bArrIso || !bDepIso) return null;

  // 1) Exact: phone + fechas — lookup directo
  if (bPhone10.length === 10) {
    const hit = LG_STATE.__huIdxPhoneDates.get(`${bPhone10}|${bArrIso}|${bDepIso}`);
    if (hit) return { h: hit, kind: 'exact' };
  }

  // 2) Probable: propiedad+departamento + fechas exactas (sin includes)
  const bPropKey = lgPropDeptKeyFromAny(booking);
  if (!bPropKey) return null;
  const direct = LG_STATE.__huIdxPropDates.get(`${bPropKey}|${bArrIso}|${bDepIso}`);
  if (direct && direct.length) return { h: direct[0], kind: 'probable' };
  return null;
}

/** Fallback: si NO hay match exacto (phone + fechas), busca CUALQUIER fila
 *  de huéspedes con el mismo phone (últimos 10 dígitos). Sirve para mostrar
 *  Perfil + Historial cuando el booking de Lodgify aún no tiene un check-in
 *  manual asociado (mismas fechas), pero la persona sí existe en el sistema.
 *  Devuelve la reservación con Fecha de ingreso MÁS RECIENTE como "representante"
 *  para que huBuildIdCard tenga los datos más actualizados del perfil. */
function lgFindHuespedRepresentativeByPhone(booking) {
  const rows = HU_STATE.rows || [];
  if (!rows.length) return null;
  const bPhone10 = lgNormalizePhone(booking.GuestPhone).slice(-10);
  if (bPhone10.length < 10) return null;
  let best = null;
  let bestArr = '';
  for (const h of rows) {
    if (lgExtractHuespedPhoneTail(h) !== bPhone10) continue;
    const hArr = String(huValueFlexible(h, ['Fecha de ingreso','Fecha de entrada']) || '').slice(0,10);
    if (!best || hArr > bestArr) { best = h; bestArr = hArr; }
  }
  return best;
}

/** Recalcula LG_STATE.matches para todos los bookings cacheados. */
function lgComputeMatches() {
  const map = new Map();
  const kindMap = new Map();
  const bookings = LG_STATE.bookings || [];
  const huRows = HU_STATE.rows || [];
  for (const b of bookings) {
    const res = lgMatchHuesped(b);
    if (res && res.h) {
      map.set(String(b.Id), res.h);
      kindMap.set(String(b.Id), res.kind || 'exact');
    }
  }
  LG_STATE.matches = map;
  LG_STATE.matchKinds = kindMap;
  console.info(`[LG] matches: ${map.size} de ${bookings.length} bookings (huéspedes: ${huRows.length} rows)`);
  // Diagnóstico: muestra info de huéspedes para verificar campos
  if (huRows.length) {
    const phoneKeys = new Set();
    huRows.forEach(h => Object.keys(h).forEach(k => {
      const nk = String(k).toLowerCase();
      if (/cel|whats|tel|phone/.test(nk)) phoneKeys.add(k);
    }));
    console.info('[LG] keys-teléfono detectadas en huéspedes:', [...phoneKeys]);
  }
}

/** Garantiza que HU_STATE.rows esté disponible (carga si no lo está)
 *  y dispara el cómputo de matches + re-render del módulo Lodgify. */
async function lgEnsureHuespedesAndMatch() {
  try {
    if (!HU_STATE.loaded && !HU_STATE.loading) {
      // PERF: usar cache 5min de huespedesLoad (false = no force). Antes
      // se pasaba true en cada entrada al módulo → re-fetch de 25s cada vez.
      // Ahora respeta el cache localStorage; solo hace fetch si está expirado.
      await huespedesLoad(false);
    }
    // Si las dos colecciones ya están listas, cruzar.
    if (LG_STATE.loaded && HU_STATE.loaded) {
      lgComputeMatches();
      // Si el usuario ya seleccionó una card, NO re-renderizamos — perdería
      // su selección. Solo cruzamos matches en memoria.
      if (window.LG_USER_INTERACTED) {
        console.info('[LG] skip re-render tras match huéspedes: user interacted');
      } else {
        lodgifyRender();
      }
    }
  } catch (e) {
    console.warn('[LG] cruce con huéspedes falló:', e.message);
  }
}

/** Normaliza cualquier formato de fecha (MM/DD/YYYY, ISO 2026-08-05T…,
 *  YYYY-MM-DD, Date object) a "MM/DD/YYYY" — el formato canónico que usa
 *  el módulo en toda la UI. Devuelve "" si no es parseable. */
function lgNormalizeDate(v) {
  if (v == null) return '';
  const s = String(v).trim();
  if (!s) return '';
  // Caso 1: ya viene como MM/DD/YYYY o M/D/YYYY (string nativo)
  let m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${String(m[1]).padStart(2,'0')}/${String(m[2]).padStart(2,'0')}/${m[3]}`;
  // Caso 2: ISO completa con T "2026-08-05T06:00:00.000Z"
  // Esto solo ocurre cuando la celda del sheet quedó como Date object,
  // lo que en locale es-MX significa que Sheets parseó como DD/MM antes.
  // → Por eso swappeamos: el "MM" en ISO es realmente el día original,
  // y el "DD" en ISO es realmente el mes original.
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})T/);
  if (m) return `${m[3]}/${m[2]}/${m[1]}`; // swap: ISO-DD → MM, ISO-MM → DD
  // Caso 3: ISO solo fecha "2026-08-05" (string sin T, no parseado por Sheets)
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (m) return `${m[2]}/${m[3]}/${m[1]}`;
  return s; // último recurso: tal cual
}

/** MM/DD/YYYY → Date (UTC). */
function lgParseMMDD(s) {
  if (!s) return null;
  const m = String(s).match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (!m) return null;
  return new Date(Date.UTC(+m[3], +m[1]-1, +m[2]));
}

/** Devuelve "DD de mes" en es-MX a partir de MM/DD/YYYY. */
function lgFmtFecha(mmdd) {
  const d = lgParseMMDD(mmdd);
  if (!d) return '—';
  const mes = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'][d.getUTCMonth()];
  return `${d.getUTCDate()} de ${mes}`;
}

/** Trunca un texto largo de HouseName a algo legible como "Baja California #4". */
// ─── Catálogo de alojamientos (homologa nombres entre Lodgify ↔ Reservaciones) ──
// Estado global con índices por HouseId, HouseName, Propiedad, # Departamento.
// Se carga UNA VEZ al inicio vía /alojamientos-list.
const ALOJ_STATE = {
  rows: [],
  byHouseId: new Map(),       // "602128" → row
  byHouseName: new Map(),     // lowercase normalized → row
  byPropDepto: new Map(),     // "propiedad|depto" → row
  byDeviceName: new Map(),    // device_name normalizado → row (módulo Tuya)
  loaded: false,
  loading: false,
};

function alojNorm(s) { return String(s || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }

// ── Catálogo "Dispositivos" (Propiedad / # Departamento / Tipo / Device_name) ──
// Reemplaza a alojamientos como fuente de verdad en el módulo Tuya.
const DISP_STATE = {
  rows: [],
  byDeviceName: new Map(),
  loaded: false,
  loading: false,
};
async function dispLoadDispositivos() {
  if (DISP_STATE.loaded || DISP_STATE.loading) return;
  DISP_STATE.loading = true;
  try {
    const res = await fetch(`${BACKEND}/dispositivos-list`, { cache: 'no-store' });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'fetch failed');
    DISP_STATE.rows = data.rows || [];
    DISP_STATE.byDeviceName.clear();
    // Detectar columna Device_name de forma tolerante
    const firstRow = DISP_STATE.rows[0] || {};
    let devColKey = null;
    for (const k of Object.keys(firstRow)) {
      const nk = String(k).toLowerCase().replace(/[^a-z0-9]/g, '');
      if (nk === 'devicename' || nk === 'device' || nk === 'tuyaname' || nk === 'tuya') { devColKey = k; break; }
    }
    for (const r of DISP_STATE.rows) {
      if (devColKey) {
        const dev = alojNorm(r[devColKey]);
        if (dev) DISP_STATE.byDeviceName.set(dev, r);
      }
    }
    DISP_STATE.loaded = true;
    // Forzar re-init de chips Tuya: si Tuya renderizó antes con tipos vacíos
    // (porque DISP aún no había cargado), reset para que tipos se repueblen.
    if (typeof TUYA_STATE !== 'undefined') TUYA_STATE.tipos = null;
    console.info(`[DISP] catálogo: ${DISP_STATE.rows.length} dispositivos · col Device: ${devColKey || 'NO ENCONTRADA'}`);
  } catch (e) {
    console.warn('[DISP] no cargó:', e.message);
  } finally {
    DISP_STATE.loading = false;
  }
}

// El catálogo (64 filas) se guarda en localStorage: al abrir cualquier módulo
// queda disponible al instante y se refresca en segundo plano una vez por
// carga de página. Llamadas simultáneas comparten la misma descarga (antes
// regresaban de inmediato sin datos y el Dashboard pintaba "No hay catálogo").
const ALOJ_LOCAL_KEY = 'aloj_cache_v1';
async function lgLoadAlojamientos() {
  if (ALOJ_STATE._promise) return ALOJ_STATE._promise;
  if (ALOJ_STATE.loaded && ALOJ_STATE._refreshedThisPage) return;
  let servedLocal = false;
  if (!ALOJ_STATE.loaded) {
    try {
      const c = JSON.parse(localStorage.getItem(ALOJ_LOCAL_KEY) || 'null');
      if (c && Array.isArray(c.rows) && c.rows.length) { _alojIndexRows(c.rows); servedLocal = true; }
    } catch (_) {}
  }
  ALOJ_STATE.loading = true;
  ALOJ_STATE._promise = _alojFetchAndIndex().finally(() => {
    ALOJ_STATE.loading = false;
    ALOJ_STATE._promise = null;
    ALOJ_STATE._refreshedThisPage = true;
  });
  if (servedLocal) return;           // datos ya usables; el refresco sigue solo
  return ALOJ_STATE._promise;
}

async function _alojFetchAndIndex() {
  try {
    const res = await fetch(`${BACKEND}/alojamientos-list`, { cache: 'no-store' });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'fetch failed');
    _alojIndexRows(data.rows || []);
    try { localStorage.setItem(ALOJ_LOCAL_KEY, JSON.stringify({ ts: Date.now(), rows: ALOJ_STATE.rows })); } catch (_) {}
    // Rebuild filter options now that Propiedad can be homologated to
    // "José Cárdenas - #3" via the catalog.
    try {
      if (typeof lgRebuildFilterOptions === 'function') lgRebuildFilterOptions();
      if (typeof lodgifyRender === 'function' && LG_STATE.loaded) lodgifyRender();
      if (!document.getElementById('module-ocupacion')?.classList.contains('hidden') && typeof ocupRender === 'function') ocupRender();
    } catch (e) { /* silent */ }
  } catch (e) {
    console.warn('[ALOJ] no cargó:', e.message);
  }
}

function _alojIndexRows(rows) {
  {
    ALOJ_STATE.rows = rows || [];
    ALOJ_STATE.byHouseId.clear();
    ALOJ_STATE.byHouseName.clear();
    ALOJ_STATE.byPropDepto.clear();
    ALOJ_STATE.byDeviceName.clear();
    // Detectar la columna Device_name de forma case/whitespace-insensitive:
    // acepta "Device_name", "Device name", "device_name", "DEVICE NAME", etc.
    const firstRow = ALOJ_STATE.rows[0] || {};
    let devColKey = null;
    for (const k of Object.keys(firstRow)) {
      const nk = String(k).toLowerCase().replace(/[^a-z0-9]/g, '');
      if (nk === 'devicename' || nk === 'device' || nk === 'tuyaname' || nk === 'tuya') { devColKey = k; break; }
    }
    for (const r of ALOJ_STATE.rows) {
      // El id de Lodgify puede venir en varias columnas (por historia):
      //   'HouseId' (nueva), 'id_lodgify' (canónico en la hoja alojamientos),
      //   o 'HouseName' cuando la fila legacy lo guardaba ahí.
      const hid = String(r['HouseId'] || r['id_lodgify'] || r['HouseName'] || '').replace(/[^\d]/g, '').trim();
      if (hid) ALOJ_STATE.byHouseId.set(hid, r);
      const hname = alojNorm(r['HouseName']);
      if (hname) ALOJ_STATE.byHouseName.set(hname, r);
      const prop = alojNorm(r['Propiedad']);
      const dpt  = alojNorm(r['# Departamento']);
      if (prop || dpt) ALOJ_STATE.byPropDepto.set(`${prop}|${dpt}`, r);
      if (devColKey) {
        const dev = alojNorm(r[devColKey]);
        if (dev) ALOJ_STATE.byDeviceName.set(dev, r);
      }
    }
    ALOJ_STATE.loaded = true;
  }
}

/** Obtiene la fila del catálogo "alojamientos" para una reserva (de Lodgify
 *  vía HouseId/HouseName, o de Reservaciones vía Propiedad/# Departamento). */
function lgFindAlojamiento(opts) {
  if (!ALOJ_STATE.loaded) return null;
  const { houseId, houseName, propiedad, departamento } = opts || {};
  if (houseId) {
    const r = ALOJ_STATE.byHouseId.get(String(houseId).trim());
    if (r) return r;
  }
  if (houseName) {
    const r = ALOJ_STATE.byHouseName.get(alojNorm(houseName));
    if (r) return r;
  }
  if (propiedad || departamento) {
    const r = ALOJ_STATE.byPropDepto.get(`${alojNorm(propiedad)}|${alojNorm(departamento)}`);
    if (r) return r;
    // Fallback solo por Propiedad si no hay match exacto
    for (const row of ALOJ_STATE.rows) {
      if (alojNorm(row['Propiedad']) === alojNorm(propiedad)) return row;
    }
  }
  return null;
}

/** Formatea el label canónico "Propiedad - #Departamento" (ej. "José
 *  Cárdenas - #4"). Acepta opts con datos del booking Lodgify y/o del
 *  registro Reservaciones; prefiere el catálogo "alojamientos" cuando
 *  matchea, cae a los datos directos si no. */
function lgFmtPropiedad(arg, opts) {
  // Compat: si se llama con solo un string (legacy), lo trata como houseName.
  if (typeof arg === 'string' && opts === undefined) {
    const aloj = lgFindAlojamiento({ houseName: arg });
    if (aloj) return formatPropDeptoFromAloj_(aloj);
    // Fallback al comportamiento viejo: corta antes del "("
    const s = String(arg || '').trim();
    if (!s) return '—';
    const m = s.match(/^([^(]+)/);
    return (m ? m[1] : s).trim();
  }
  const o = (typeof arg === 'object' && arg) ? arg : (opts || {});
  const aloj = lgFindAlojamiento(o);
  if (aloj) return formatPropDeptoFromAloj_(aloj);
  // Fallback: combina los valores crudos
  const prop = String(o.propiedad || '').trim();
  const dpt  = String(o.departamento || '').trim();
  if (prop && dpt) return `${prop} - #${dpt.replace(/^#\s*/, '')}`;
  if (prop) return prop;
  // Último recurso: limpiar el houseName
  const s = String(o.houseName || '').trim();
  if (!s) return '—';
  const m = s.match(/^([^(]+)/);
  return (m ? m[1] : s).trim();
}

/** Extrae los campos de propiedad de un booking (real o synthetic) y los
 *  pasa a lgFmtPropiedad para obtener el label canónico
 *  "Propiedad - #Departamento". Se llama desde TODO lugar que muestra la
 *  propiedad — card sidebar, header, detalle, filtros, tabla. */
function lgPropOf(b) {
  if (!b) return '—';
  return lgFmtPropiedad({
    houseId:      b.HouseId || '',
    houseName:    b.HouseName || '',
    propiedad:    b.PropiedadRaw    || (b.__reservacion ? b.__reservacion['Propiedad']      : ''),
    departamento: b.DepartamentoRaw || (b.__reservacion ? b.__reservacion['# Departamento'] : ''),
  });
}

function formatPropDeptoFromAloj_(aloj) {
  const prop = String(aloj['Propiedad'] || '').trim();
  const dpt  = String(aloj['# Departamento'] || '').trim().replace(/^#\s*/, '');
  if (prop && dpt) return `${prop} - #${dpt}`;
  if (prop) return prop;
  return String(aloj['HouseName'] || '—').trim();
}

/** Badge del Source — colores por canal. */
function lgSourceBadge(src) {
  const s = String(src || '').trim();
  if (!s) return '<span style="display:inline-block;padding:4px 10px;border-radius:999px;background:#f1f5f9;color:#475569;font-weight:700;font-size:11px;border:1px solid #cbd5e1">Sin canal</span>';
  const lc = s.toLowerCase();
  let bg='#f1f5f9', fg='#475569', bd='#cbd5e1', ico='🌐';
  if (lc.includes('airbnb'))       { bg='#fef2f2'; fg='#dc2626'; bd='#fecaca'; ico='🅰'; }
  else if (lc.includes('booking')) { bg='#dbeafe'; fg='#1e40af'; bd='#93c5fd'; ico='🅱'; }
  else if (lc.includes('expedia')) { bg='#fef3c7'; fg='#92400e'; bd='#fcd34d'; ico='Ⓔ'; }
  else if (lc.includes('vrbo'))    { bg='#dcfce7'; fg='#166534'; bd='#86efac'; ico='Ⓥ'; }
  else if (lc.includes('manual'))  { bg='#ede9fe'; fg='#5b21b6'; bd='#c4b5fd'; ico='✋'; }
  return `<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 7px;border-radius:999px;background:${bg};color:${fg};font-weight:800;font-size:9px;border:1px solid ${bd};letter-spacing:.02em">${ico} ${esc(s)}</span>`;
}

/** Badge del Status (Open/Booked/Tentative/Declined). */
function lgStatusBadge(st) {
  const s = String(st || '').trim();
  if (!s) return '';
  const lc = s.toLowerCase();
  let bg='#f1f5f9', fg='#475569', bd='#cbd5e1';
  if (lc === 'booked')        { bg='#dcfce7'; fg='#166534'; bd='#86efac'; }
  else if (lc === 'open')     { bg='#dbeafe'; fg='#1e40af'; bd='#93c5fd'; }
  else if (lc === 'tentative'){ bg='#fef3c7'; fg='#92400e'; bd='#fcd34d'; }
  else if (lc === 'declined' || lc === 'cancelled') { bg='#fee2e2'; fg='#991b1b'; bd='#fca5a5'; }
  return `<span style="display:inline-block;padding:2px 8px;border-radius:999px;background:${bg};color:${fg};font-weight:700;font-size:8px;border:1px solid ${bd};text-transform:uppercase;letter-spacing:.04em">${esc(s)}</span>`;
}

/** Formato monetario tolerante (igual que huFmtMonto pero sin recuperación ISO). */
function lgFmtMoney(n, currency) {
  const v = Number(n) || 0;
  const cur = (currency || 'MXN').toUpperCase();
  return v.toLocaleString('es-MX', { style:'currency', currency: cur, minimumFractionDigits: v % 1 === 0 ? 0 : 2, maximumFractionDigits: 2 });
}

/** Construye el rango desde/hasta a partir del select de días. */
function lgGetRange() {
  const days = Number(document.getElementById('lg-filtro-rango')?.value) || 30;
  const today = new Date();
  const to = today.toISOString().slice(0,10);
  const fromDate = new Date(today.getTime() - days * 86400000);
  const from = fromDate.toISOString().slice(0,10);
  return { from, to, days };
}

/** Agrega los rows (uno por line item) en un objeto por booking Id. */
function lgAggregateBookings(rows) {
  const byId = new Map();
  for (const r of rows || []) {
    const id = r.Id;
    if (!id) continue;
    let agg = byId.get(id);
    if (!agg) {
      agg = {
        Id: id,
        Source: r.Source || '',
        SourceTextRaw: r.SourceText || '',
        Status: r.Status || '',
        DateArrival: r.DateArrival || '',
        DateDeparture: r.DateDeparture || '',
        DateCancelled: r.DateCancelled || '',
        Nights: Number(r.Nights) || 0,
        HouseName: r.HouseName || '',
        HouseId: r.HouseId || '',
        RoomTypeNames: r.RoomTypeNames || '',
        GuestName: r.GuestName || '',
        GuestEmail: r.GuestEmail || '',
        GuestPhone: r.GuestPhone || '',
        GuestCountryCode: r.GuestCountryCode || '',
        NumberOfGuests: Number(r.NumberOfGuests) || 0,
        Adults: Number(r.Adults) || 0,
        Children: Number(r.Children) || 0,
        Infants: Number(r.Infants) || 0,
        Pets: Number(r.Pets) || 0,
        Currency: r.Currency || 'MXN',
        ChannelBooking: r.ChannelBooking || '',
        Gross: 0,
        Net: 0,
        Vat: 0,
        LineItems: [],
      };
      byId.set(id, agg);
    }
    agg.Gross += Number(r.GrossAmount) || 0;
    agg.Net   += Number(r.NetAmount)   || 0;
    agg.Vat   += Number(r.VatAmount)   || 0;
    agg.LineItems.push({
      kind: r.LineItem || '',
      desc: r.LineItemDescription || '',
      gross: Number(r.GrossAmount) || 0,
      net:   Number(r.NetAmount)   || 0,
      vat:   Number(r.VatAmount)   || 0,
    });
  }
  // Parseo del SourceText (JSON) para extraer confirmationCode etc.
  for (const b of byId.values()) {
    try {
      const meta = JSON.parse(b.SourceTextRaw || '{}');
      b.ConfirmationCode = meta.confirmationCode || '';
      b.ListingId = meta.listingId || '';
      b.ThreadId  = meta.threadId  || '';
    } catch(_) { b.ConfirmationCode=''; b.ListingId=''; b.ThreadId=''; }
  }
  // Ordenar por DateArrival descendente (más reciente primero).
  return Array.from(byId.values()).sort((a,b) => {
    const da = lgParseMMDD(a.DateArrival)?.getTime() || 0;
    const db = lgParseMMDD(b.DateArrival)?.getTime() || 0;
    return db - da;
  });
}

/** HTML del loader animado de Check-inn (mismo del proyecto check-in). */
const LG_LOADER_BASE = 'https://checkinnsaltillo-byte.github.io/checkin-app/public/registro';
function lgLoaderHtml(msg) {
  // Estructura HTML idéntica a la de checkin-app/public/registro:
  // - <div class="ci-face"> para front/back
  // - <img class="ci-spacer"> DIRECTO (sin wrap en span) — esto da ancho
  //   real al .ci-pin para que rote sobre su eje central, no sobre el
  //   margen izquierdo.
  return `
    <div class="lg-loading-state">
      <div class="checkinn-loader size-lg" role="img" aria-label="Cargando">
        <div class="ci-pin-scene">
          <div class="ci-pin">
            <div class="ci-face front"><img src="${LG_LOADER_BASE}/loader_pin.png" alt=""></div>
            <div class="ci-face back"><img src="${LG_LOADER_BASE}/loader_pin.png" alt=""></div>
            <img class="ci-spacer" src="${LG_LOADER_BASE}/loader_pin.png" alt="">
          </div>
        </div>
        <img class="ci-text" src="${LG_LOADER_BASE}/loader_text.png" alt="Check-inn">
      </div>
      <div class="lg-loading-msg">${esc(msg || 'Cargando…')}</div>
    </div>`;
}

/** Normaliza una fila de Reservas_Lodgify (fechas, montos, LineItems). */
function lgNormalizeBookingRow_(b) {
  // TotalAmount es la cifra AUTORITATIVA de Lodgify (post-descuento y
  // lo que el huésped efectivamente paga). GrossTotal es la SUMA cruda
  // de LineItems y tiene un bug del sync: Promotion (descuento) se
  // suma como positivo en vez de restarse. Ejemplo: booking 23232434
  // → LineItems suman 4889.40 pero TotalAmount = 4119.40 (real).
  // Prioridad: TotalAmount > GrossTotal > Gross.
  const ta = Number(b.TotalAmount);
  const gt = Number(b.GrossTotal);
  const g  = Number(b.Gross);
  const totalReal = (Number.isFinite(ta) && ta > 0) ? ta
                 : (Number.isFinite(gt) && gt > 0) ? gt
                 : (Number.isFinite(g)  && g  > 0) ? g  : 0;
  return {
    ...b,
    DateArrival:   lgNormalizeDate(b.DateArrival),
    DateDeparture: lgNormalizeDate(b.DateDeparture),
    DateCancelled: lgNormalizeDate(b.DateCancelled),
    Gross: totalReal,
    Net:   Number(b.NetTotal   != null ? b.NetTotal   : b.Net)   || 0,
    Vat:   Number(b.VatTotal   != null ? b.VatTotal   : b.Vat)   || 0,
    LineItems: Array.isArray(b.LineItems) ? b.LineItems : [],
  };
}

/** Carga bajo demanda: si el usuario elige en "📅 Meses" un mes anterior a
 *  la ventana inicial (2 meses atrás → futuro), descarga las reservas desde
 *  ese mes hasta el inicio de la ventana, las agrega a LG_STATE.bookings y
 *  re-pinta. El servidor responde de su snapshot (~25 meses) al instante;
 *  más antiguo pasa por Apps Script (35-60 s). */
let _lgExtendInflight = null;
function lgEnsureMesesCargados_() {
  const sel = LG_STATE.multiSel && LG_STATE.multiSel['meses'];
  const rng = LG_STATE.__monthRange;
  if (_lgExtendInflight) return true;
  if (!(sel instanceof Set) || !sel.size || !rng || !rng.from) return false;
  const minYm = Array.from(sel).filter(v => /^\d{4}-\d{2}$/.test(v)).sort()[0];
  if (!minYm) return false;
  const fromIso = `${minYm}-01`;
  if (fromIso >= rng.from) return false;
  LG_STATE.__extFailed = LG_STATE.__extFailed || new Set();
  if (LG_STATE.__extFailed.has(fromIso)) return false; // ya falló: no reintentar en bucle
  const prevFrom = rng.from;
  const toD = new Date(prevFrom + 'T00:00:00'); toD.setDate(toD.getDate() - 1);
  const toIso = `${toD.getFullYear()}-${String(toD.getMonth()+1).padStart(2,'0')}-${String(toD.getDate()).padStart(2,'0')}`;
  const lbl = document.getElementById('lg-status-label');
  const cont = document.getElementById('lg-cards');
  const mesTxt = (() => { const M = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre']; const [y, m] = minYm.split('-'); return `${M[+m - 1]} ${y}`; })();
  if (lbl) lbl.textContent = `Cargando reservas desde ${mesTxt}…`;
  if (cont && typeof lgLoaderHtml === 'function') cont.innerHTML = lgLoaderHtml(`Trayendo reservas desde ${mesTxt}…`);
  const t0 = performance.now();
  _lgExtendInflight = (async () => {
    try {
      const res = await fetch(`${BACKEND}/lodgify-list?from=${fromIso}&to=${toIso}`, { cache: 'no-store' });
      const data = await res.json();
      if (!data.ok) throw new Error(data.error || `HTTP ${res.status}`);
      if (!LG_STATE.__rawStatusById) LG_STATE.__rawStatusById = new Map();
      const byId = new Map((LG_STATE.bookings || []).map(b => [String(b.Id || ''), b]));
      let nuevas = 0;
      (data.bookings || []).forEach(b => {
        const id = String(b && b.Id || '').trim();
        if (!id) return;
        LG_STATE.__rawStatusById.set(id, String(b.Status || ''));
        const st = String(b.Status || '').toLowerCase();
        if (st !== 'booked' && st !== 'tentative') return;
        if (byId.has(id)) return;
        byId.set(id, lgNormalizeBookingRow_(b));
        nuevas++;
      });
      LG_STATE.bookings = Array.from(byId.values());
      // Solo amplía la ventana si sigue vigente (otra carga base no la cambió).
      if (LG_STATE.__monthRange && LG_STATE.__monthRange.from === prevFrom) LG_STATE.__monthRange.from = fromIso;
      LG_STATE.__syntheticCache = null;
      try { if (typeof lgComputeMatches === 'function' && HU_STATE.loaded) lgComputeMatches(); } catch (_) {}
      console.info(`[LG] meses anteriores: +${nuevas} reservas desde ${fromIso} en ${Math.round(performance.now() - t0)} ms`);
      if (lbl) lbl.textContent = `${LG_STATE.bookings.length} reservaciones`;
    } catch (e) {
      console.warn('[LG] carga de meses anteriores:', e.message);
      LG_STATE.__extFailed.add(fromIso);
      if (lbl) lbl.textContent = 'Error al traer meses anteriores: ' + e.message;
    } finally {
      _lgExtendInflight = null;
      lodgifyRender({ force: true });
    }
  })();
  return true;
}

/** Lee desde el sheet (vía Cloud Run → Apps Script → hoja "Reservas_Lodgify").
 *  Es la lectura rápida (default). No consulta Lodgify directamente. */
async function lodgifyLoad(force, opts) {
  setSystemBusy(true, 'Cargando reservas…');
  try { return await __lodgifyLoadInner(force, opts); } finally { setSystemBusy(false); }
}
async function __lodgifyLoadInner(force, opts) {
  opts = opts || {};
  const silent = !!opts.silent; // si true, no limpia el contenedor ni muestra spinner
  const lbl = document.getElementById('lg-status-label');
  const lastSyncLbl = document.getElementById('lg-last-sync');
  const empty = document.getElementById('lg-empty');
  const cont = document.getElementById('lg-cards');
  if (LG_STATE.loading) return;
  LG_STATE.loading = true;
  if (!silent) {
    if (lbl) lbl.textContent = 'Cargando…';
    if (empty) empty.classList.add('hidden');
    if (cont) cont.innerHTML = lgLoaderHtml('Cargando reservaciones…');
  }
  // ── SWR client-side con localStorage ──────────────────────────────
  // Mostrar cache viejo INMEDIATAMENTE mientras refrescamos en background.
  // El usuario NUNCA ve el overlay/spinner si hay cache local disponible.
  // Incluso con force=true (ej. click "Refrescar") hidratamos primero desde
  // cache y luego seguimos con el fetch fresco al backend.
  const LG_CACHE_KEY = 'lg_cache_v2';
  const _t = { start: performance.now() };
  const _mark = (k) => { _t[k] = Math.round(performance.now() - _t.start); };
  const LG_CACHE_STALE_MS = 30 * 24 * 60 * 60 * 1000; // 30 días
  let _servedFromLocal = false;
  try {
    const raw = localStorage.getItem(LG_CACHE_KEY);
    if (raw) {
      const c = JSON.parse(raw);
      const age = Date.now() - (c.ts || 0);
      if (c && Array.isArray(c.bookings) && age < LG_CACHE_STALE_MS) {
        LG_STATE.bookings = c.bookings;
        LG_STATE.checkOuts = Array.isArray(c.checkOuts) ? c.checkOuts : [];
        LG_STATE.checkOutIdx = typeof lgBuildCheckOutIndex_ === 'function' ? lgBuildCheckOutIndex_(LG_STATE.checkOuts) : new Map();
        LG_STATE.__rawStatusById = new Map();
        LG_STATE.loaded = true;
        LG_STATE.lastSync = c.lastSync || '';
        _servedFromLocal = true;
        // Rendereo inmediato para que el usuario NO vea el overlay.
        try { if (typeof lgComputeMatches === 'function') lgComputeMatches(); } catch(_){}
        try { if (typeof lodgifyRender === 'function') lodgifyRender(); } catch(_){}
        // Quita el spinner porque ya hay data visible.
        if (cont && cont.querySelector('.lg-loading-msg')) {
          try { lodgifyRender(); } catch(_){}
        }
      }
    }
  } catch(_) {}
  try {
    // Ventana: reservas cuya estancia toca los últimos 2 meses + todas las
    // próximas. El backend la responde desde un snapshot en memoria. El
    // historial completo por huésped se carga on-demand al expandir la card.
    const d0 = new Date();
    d0.setMonth(d0.getMonth() - 2);
    const fromIso = `${d0.getFullYear()}-${String(d0.getMonth()+1).padStart(2,'0')}-${String(d0.getDate()).padStart(2,'0')}`;
    const toIso = '2099-12-31';
    const url = `${BACKEND}/lodgify-list?from=${fromIso}&to=${toIso}`;
    LG_STATE.__monthRange = { from: fromIso, to: toIso };
    // Fase 2c: precarga KPIs pre-computados en paralelo con lodgify-list.
    // No bloqueamos si falla (el render tiene fallback).
    if (typeof huEnsurePerfilKpis_ === 'function') huEnsurePerfilKpis_().catch(()=>{});
    _mark('cache_local');
    const res = await fetch(url, { cache:'no-store' });
    _mark('respuesta');
    const data = await res.json();
    _mark('json');
    if (!data.ok) throw new Error(data.error || `HTTP ${res.status}`);
    // Guarda un índice CRUDO (sin filtrar) de Lodgify Id → Status ANTES
    // de aplicar el filtro Booked/Tentative. Los sintéticos construidos
    // desde Reservaciones consultan este mapa para saber si su booking
    // real está Declined/Cancelled y no aparecer como "BOOKED" falso.
    LG_STATE.__rawStatusById = new Map();
    if (Array.isArray(data.bookings)) {
      data.bookings.forEach(b => {
        const id = String(b?.Id || '').trim();
        if (id) LG_STATE.__rawStatusById.set(id, String(b?.Status || ''));
      });
    }
    // Filtro adicional: solo Booked / Tentative
    if (Array.isArray(data.bookings)) {
      data.bookings = data.bookings.filter(b => {
        const st = String((b && b.Status) || '').toLowerCase();
        return st === 'booked' || st === 'tentative';
      });
    }
    // Normaliza nombres de campos del sheet (GrossTotal → Gross, etc.)
    // y normaliza fechas al formato MM/DD/YYYY (algunas celdas del sheet
    // están formateadas como fecha y Apps Script las devuelve como ISO
    // "2026-08-05T06:00:00.000Z" en vez de "08/05/2026").
    // Defensa contra filas duplicadas en el sheet: si el mismo Id aparece
    // más de una vez, conservamos:
    //   1) el de last_synced_at MÁS RECIENTE,
    //   2) si empatan, el de mayor GrossTotal (probable dato real vs blanco),
    //   3) si vuelven a empatar, el primero encontrado.
    const rawById = new Map();
    (data.bookings || []).forEach(b => {
      const id = String(b.Id || '');
      if (!id) return;
      const prev = rawById.get(id);
      if (!prev) { rawById.set(id, b); return; }
      const lsaNew = String(b.last_synced_at || '');
      const lsaOld = String(prev.last_synced_at || '');
      if (lsaNew > lsaOld) { rawById.set(id, b); return; }
      if (lsaNew === lsaOld) {
        const gNew = Number(b.GrossTotal || b.Gross) || 0;
        const gOld = Number(prev.GrossTotal || prev.Gross) || 0;
        if (gNew > gOld) rawById.set(id, b);
      }
    });
    const dedupedBookings = Array.from(rawById.values());
    const dupsHere = (data.bookings || []).length - dedupedBookings.length;
    if (dupsHere > 0) {
      console.warn(`[LG] ${dupsHere} fila(s) duplicada(s) ignoradas en frontend. Recomendado: redesplegar Apps Script + Sincronizar.`);
    }
    LG_STATE.bookings = dedupedBookings.map(lgNormalizeBookingRow_);
    _mark('normalizar');
    LG_STATE.loaded = true;
    LG_STATE.lastSync = data.last_synced_at || '';
    // Piggyback: registros de la hoja "check_out" indexados por prop|depto|salida
    LG_STATE.checkOuts = Array.isArray(data.check_outs) ? data.check_outs : [];
    LG_STATE.checkOutIdx = lgBuildCheckOutIndex_(LG_STATE.checkOuts);
    // Persistir en localStorage para SWR client-side en siguientes entradas.
    // Ignora errores si el quota se llena (7MB+ puede fallar en algunos navegadores).
    try {
      localStorage.setItem(LG_CACHE_KEY, JSON.stringify({
        ts: Date.now(),
        bookings: LG_STATE.bookings,
        checkOuts: LG_STATE.checkOuts,
        lastSync: LG_STATE.lastSync,
      }));
    } catch(_) {}
    if (lbl) lbl.textContent = `${LG_STATE.bookings.length} reservaciones`;
    if (lastSyncLbl) {
      lastSyncLbl.textContent = LG_STATE.lastSync
        ? '· última sync: ' + lgFmtRelativeTime(LG_STATE.lastSync)
        : '· sin sincronizar';
    }
    if (!LG_STATE.bookings.length && empty) {
      empty.textContent = 'La hoja "Reservas_Lodgify" está vacía. Click en "🔄 Sincronizar" para popular.';
      empty.classList.remove('hidden');
    }
    lgRebuildFilterOptions();
    // Si huéspedes ya está cargado, computar matches antes de renderizar
    if (HU_STATE.loaded) lgComputeMatches();
    // Si el usuario ya seleccionó una card (ej. lodgifyLoad fue silencioso
    // detrás de un módulo ya visible), NO re-renderizamos — perdería su
    // selección. La data ya está en memoria; lo verá al cambiar de card.
    _mark('guardar_local');
    if (window.LG_USER_INTERACTED) {
      console.info('[LG] skip re-render tras load: user interacted');
    } else {
      lodgifyRender();
    }
    _mark('render');
    LG_STATE.__extFailed = new Set(); // la carga base reinicia la ventana
    window.LG_LAST_TIMING = { ..._t, desde_cache_local: _servedFromLocal, reservas: LG_STATE.bookings.length, snapshot: !!data.snapshot };
    console.info('[LG timing ms]', window.LG_LAST_TIMING);
  } catch (e) {
    if (lbl) lbl.textContent = 'Error: ' + e.message;
    if (empty) { empty.textContent = '⚠ ' + e.message; empty.classList.remove('hidden'); }
  } finally {
    LG_STATE.loading = false;
  }
}

/** Dispara sincronización contra Lodgify (rolling o full). */
/** Backfill del Código de confirmación en Reservas_Lodgify. Corre el sync
 *  completo (full=true) en un loop con reintentos: Apps Script tiene tope de
 *  6 min por invocación, así que si timeoutea, la siguiente corrida termina
 *  las filas que faltaban. Máx 3 pases; en la práctica 1-2 alcanzan. */
window.lodgifyBackfillCodes = async function() {
  if (!confirm('Va a correr una Sync completa de Lodgify (jala 2 años atrás y adelante) para rellenar Código de confirmación en TODAS las reservas antiguas.\n\nTarda 2-6 min por pase, hasta 3 pases si Apps Script timeoutea. ¿Continuar?')) return;
  const lbl = document.getElementById('lg-status-label');
  const setLbl = t => { if (lbl) lbl.textContent = t; };
  const maxPasses = 3;
  let totalUpdated = 0;
  for (let pass = 1; pass <= maxPasses; pass++) {
    setLbl(`🔄 Backfill pase ${pass}/${maxPasses}…`);
    try {
      const res = await fetch(`${BACKEND}/lodgify-sync`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ full: true }),
      });
      const data = await res.json();
      if (!data.ok) {
        // Si timeouteó Apps Script, backend suele devolver ok:false con hint.
        // Reintentamos el siguiente pase para completar lo que faltó.
        console.warn(`[LG backfill] pase ${pass} error:`, data.error || data.raw);
        if (pass === maxPasses) throw new Error(data.error || `HTTP ${res.status}`);
        continue;
      }
      totalUpdated += Number(data.updated || 0);
      console.info(`[LG backfill] pase ${pass}: updated=${data.updated} inserted=${data.inserted} elapsed=${(data.elapsed_ms/1000).toFixed(1)}s`);
      // Si en este pase no actualizó nada nuevo, ya no hay pendientes → salimos.
      if (Number(data.updated || 0) === 0 && Number(data.inserted || 0) === 0 && pass > 1) break;
    } catch (e) {
      console.warn(`[LG backfill] pase ${pass} fetch falló:`, e);
      if (pass === maxPasses) { alert('Error en backfill: ' + e.message); setLbl('Error backfill'); return; }
    }
  }
  setLbl(`✓ Backfill terminado · ${totalUpdated} filas actualizadas en total`);
  alert(`✓ Backfill Lodgify completado.\n\nTotal de filas actualizadas: ${totalUpdated}.\n\nAhora los códigos de confirmación (HMxxx / #Bxxxx) están disponibles para el lookup en el check-in.`);
  try { await lodgifyLoad(true); } catch(_){}
};

async function lodgifySync(full) {
  const lbl = document.getElementById('lg-status-label');
  const empty = document.getElementById('lg-empty');
  const msg = full ? 'Sync completa (puede tardar 2-5 min)…' : 'Sincronizando…';
  if (!confirm(`${msg}\n\n¿Continuar?`)) return;
  try {
    if (lbl) lbl.textContent = msg;
    if (empty) { empty.textContent = msg; empty.classList.remove('hidden'); }
    // Sync MANUAL ROLLING usa ventana 60/60 (60d atrás, 60d adelante).
    // Razón: balance entre cobertura y rapidez. Captura bookings recientes
    // y los próximos 2 meses (incluye stays largos como Brayan si su
    // arrival está dentro de los próximos 60 días).
    // Para stays muy lejanos en el futuro: usar Sync Completa (730/730).
    const body = full ? { full: true } : { days_back: 60, days_fwd: 60 };
    const res = await fetch(`${BACKEND}/lodgify-sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || data.raw || `HTTP ${res.status}`);
    const dupsLine = data.duplicates_removed > 0 ? `\nDuplicadas eliminadas: ${data.duplicates_removed}` : '';
    alert(`✓ Sync OK\n\nRango: ${data.from} → ${data.to}\nBookings: ${data.bookings}\nInsertadas: ${data.inserted}\nActualizadas: ${data.updated}${dupsLine}\nTotal en sheet: ${data.total_in_sheet}\nTiempo: ${(data.elapsed_ms/1000).toFixed(1)}s`);
    await lodgifyLoad(true);
  } catch (e) {
    if (lbl) lbl.textContent = 'Error: ' + e.message;
    alert('Error en sync: ' + e.message);
  }
}

/** Sync silencioso al entrar al módulo. Throttle: máx 1 vez cada 10 min.
 *  Ventana: 7 días atrás a HOY únicamente (sin forward window).
 *  Esto evita el bug donde windows grandes (con días_fwd=730) hacían que
 *  el backend OTC devolviera aggregates inflados/inconsistentes por
 *  paginación, revirtiendo el sync manual del usuario.
 *  Las reservaciones futuras NO se tocan en auto-sync — solo manual.
 *  CLAVE: NO debe limpiar la pantalla ni mostrar spinner — el usuario ya
 *  está viendo las cards. Si la hoja no cambió (insertadas==0 + updated==0),
 *  ni siquiera se recarga. */
async function lodgifyMaybeAutoSync() {
  // Throttle 2 horas via localStorage: el auto-sync tarda ~60-90s (jala
  // desde Lodgify API todo el rango 60/60 días) y bloquea el re-render de
  // cards. Al usar throttle largo, la mayoría de entradas al módulo son
  // instant. Si necesita frescura absoluta, hay botón manual "Sincronizar"
  // en el header del módulo.
  const THROTTLE_MS = 2 * 60 * 60 * 1000; // 2 horas
  const KEY = 'lg-last-auto-sync-ms';
  let lastMs = Number(LG_STATE.lastAutoSyncMs || 0);
  if (!lastMs) {
    try { lastMs = Number(localStorage.getItem(KEY) || 0); } catch(_) {}
  }
  if (lastMs && (Date.now() - lastMs) < THROTTLE_MS) {
    const minsAgo = Math.round((Date.now() - lastMs) / 60000);
    console.info(`[LG] auto-sync skipped: ${minsAgo} min ago (throttle 2h)`);
    return;
  }
  LG_STATE.lastAutoSyncMs = Date.now();
  try { localStorage.setItem(KEY, String(Date.now())); } catch(_) {}
  const lbl = document.getElementById('lg-status-label');
  const prev = lbl ? lbl.textContent : '';
  try {
    if (lbl) lbl.textContent = (prev ? prev + ' · ' : '') + '🔄 Auto-sync…';
    const res = await fetch(`${BACKEND}/lodgify-sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      // Ventana 60/60 — la misma que el sync manual rolling. Balance
      // entre cobertura (incluye próximos 2 meses) y rapidez del sync.
      body: JSON.stringify({ days_back: 60, days_fwd: 60 }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || data.raw || 'sync failed');
    console.info('[LG] auto-sync OK:', data);
    if (lbl) lbl.textContent = prev;
    // Si NO hubo cambios, evitamos la recarga: la UI sigue intacta.
    const changes = (Number(data.inserted)||0) + (Number(data.updated)||0);
    if (changes === 0) {
      console.info('[LG] auto-sync: sin cambios, no se recarga');
      return;
    }
    // Hubo cambios: recargamos SILENCIOSAMENTE — sin limpiar el contenedor
    // ni mostrar spinner. Las cards se actualizan in-place al final.
    await lodgifyLoad(true, { silent: true });
  } catch (e) {
    console.warn('[LG] auto-sync error:', e.message);
    if (lbl) lbl.textContent = prev + ' · ⚠ sync falló';
  }
}

/** Formato tipo "hace 2h" / "ayer" / fecha ISO corta. */
function lgFmtRelativeTime(iso) {
  if (!iso) return '—';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso;
  const diff = (Date.now() - d.getTime()) / 1000;
  if (diff < 60) return 'hace segundos';
  if (diff < 3600) return `hace ${Math.floor(diff/60)} min`;
  if (diff < 86400) return `hace ${Math.floor(diff/3600)} h`;
  if (diff < 86400*7) return `hace ${Math.floor(diff/86400)} d`;
  return d.toISOString().slice(0,16).replace('T',' ');
}

// ─── Multi-select widget ────────────────────────────────────────────────────
// Cada filtro categórico (Programación, Fuente, Estado, Propiedad) usa este
// widget custom porque <select multiple> es feo y no soporta "Todas/Ninguna".
//
// Estado: LG_STATE.multiSel[id] = Set de valores seleccionados (null = first
// init, en cuyo caso se aplica el default).
// ────────────────────────────────────────────────────────────────────────────

function lgMultiInitIfNeeded(id, allValues, defaultSelected) {
  // Init tanto si es null (seed) como undefined (nunca declarada). Antes solo
  // veía null → undefined caía a "ya inicializada" y sel.size en el render
  // reventaba con "Cannot read properties of undefined ('size')".
  if (LG_STATE.multiSel[id] != null) return;
  // Si todavía NO hay opciones (datos no cargados) NO inicializamos: dejamos
  // multiSel[id] en null para reintentar al próximo rebuild. lgMultiGetSet
  // tratará null como "sin filtro" (no esconde nada).
  if (!Array.isArray(allValues) || allValues.length === 0) return;
  // Si hay default explícito, lo respetamos filtrando contra valores existentes.
  // Si no, todos seleccionados (= sin filtro).
  if (Array.isArray(defaultSelected)) {
    const lcAll = new Set(allValues.map(v => v.toLowerCase()));
    const sel = new Set(defaultSelected.filter(v => lcAll.has(String(v).toLowerCase())));
    LG_STATE.multiSel[id] = sel;
  } else {
    LG_STATE.multiSel[id] = new Set(allValues);
  }
}

/** Devuelve los valores seleccionados como Set en minúsculas, o null si
 *  no hay filtro activo (todos los valores están seleccionados). */
function lgMultiGetSet(id, allValues) {
  const sel = LG_STATE.multiSel[id];
  // null = sin inicializar (datos pendientes) → no filtra (muestra todo).
  if (sel === null || sel === undefined) return null;
  if (sel.size === 0) return new Set(); // ninguno seleccionado → oculta todo
  // Si está marcado todo → no filtra
  if (sel.size === allValues.length) return null;
  return new Set([...sel].map(v => String(v).toLowerCase()));
}

/** Genera el HTML del widget en su contenedor. */
function lgMultiRender(id, label, allValues, opts) {
  opts = opts || {};
  const containerId = 'lg-multi-' + id;
  const c = document.getElementById(containerId);
  if (!c) return;
  lgMultiInitIfNeeded(id, allValues, opts.defaultSelected);
  // lgMultiInitIfNeeded deja multiSel[id] en null cuando allValues está
  // vacío (datos aún no cargados). En ese caso NO renderizamos — el
  // próximo rebuild con datos reales lo pintará. Antes esto reventaba con
  // "Cannot read properties of null (reading 'size')" y abortaba lodgifyLoad.
  const sel = LG_STATE.multiSel[id];
  if (!sel) { if (c) c.innerHTML = ''; return; }
  const total = allValues.length;
  const selCount = sel.size;
  const labelTxt = selCount === total
      ? `Todas (${total})`
      : selCount === 0
      ? 'Ninguna'
      : selCount === 1
      ? [...sel][0]
      : `${selCount} de ${total}`;
  const renderOption = (v) => {
    const checked = sel.has(v) ? 'checked' : '';
    const disp = opts.optionRenderer ? opts.optionRenderer(v) : esc(v);
    return `
      <label class="lg-multi-opt">
        <input type="checkbox" class="lg-multi-cb" value="${esc(v)}" ${checked} onchange="lgMultiToggle('${id}','${esc(v)}')">
        <span class="lg-multi-opt-txt">${disp}</span>
      </label>`;
  };
  // Conserva si el panel estaba abierto entre re-renders.
  LG_STATE.multiOpen = LG_STATE.multiOpen || {};
  const isOpen = !!LG_STATE.multiOpen[id];
  c.innerHTML = `
    <label style="display:block;font-size:11px;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:.04em;margin-bottom:4px">${esc(label)}</label>
    <div class="lg-multi-wrap">
      <button type="button" onclick="lgMultiTogglePanel('${id}',event)" id="lg-multi-btn-${id}" class="lg-multi-btn">
        <span class="lg-multi-btn-lbl" id="lg-multi-lbl-${id}">${esc(labelTxt)}</span>
        <span class="lg-multi-btn-caret">▾</span>
      </button>
      <div id="lg-multi-panel-${id}" class="lg-multi-panel ${isOpen?'':'hidden'}" onclick="event.stopPropagation()">
        <div class="lg-multi-actions">
          <button type="button" onclick="event.stopPropagation();lgMultiSetAll('${id}')" class="lg-multi-action">✓ Todas</button>
          <button type="button" onclick="event.stopPropagation();lgMultiSetNone('${id}')" class="lg-multi-action">✕ Ninguna</button>
        </div>
        <div class="lg-multi-options">
          ${allValues.map(renderOption).join('')}
        </div>
      </div>
    </div>`;
}

window.lgMultiTogglePanel = function(id, ev) {
  if (ev) ev.stopPropagation();
  LG_STATE.multiOpen = LG_STATE.multiOpen || {};
  // Cierra otros paneles (y resetea su estado persistido)
  Object.keys(LG_STATE.multiOpen).forEach(k => {
    if (k !== id) {
      LG_STATE.multiOpen[k] = false;
      const op = document.getElementById(`lg-multi-panel-${k}`);
      if (op) op.classList.add('hidden');
    }
  });
  const p = document.getElementById(`lg-multi-panel-${id}`);
  const willOpen = p ? p.classList.contains('hidden') : !LG_STATE.multiOpen[id];
  LG_STATE.multiOpen[id] = willOpen;
  if (p) p.classList.toggle('hidden', !willOpen);
};

// Listener global: cerrar dropdowns abiertos al hacer click fuera de cualquier .lg-multi-wrap
if (!window.__lgMultiOutsideClickBound) {
  window.__lgMultiOutsideClickBound = true;
  document.addEventListener('click', function(e) {
    if (!LG_STATE || !LG_STATE.multiOpen) return;
    if (!e.target.closest('.lg-multi-wrap')) {
      let changed = false;
      Object.keys(LG_STATE.multiOpen).forEach(k => {
        if (LG_STATE.multiOpen[k]) { LG_STATE.multiOpen[k] = false; changed = true; }
      });
      if (changed) {
        document.querySelectorAll('.lg-multi-panel').forEach(p => p.classList.add('hidden'));
      }
    }
  });
}
window.lgMultiToggle = function(id, value) {
  const set = LG_STATE.multiSel[id];
  if (!set) return;
  if (set.has(value)) set.delete(value);
  else set.add(value);
  lgMultiUpdateLabel(id);
  lodgifyRenderForce();
};
window.lgMultiSetAll = function(id) {
  const opts = LG_FILTER_OPTIONS[id] || [];
  LG_STATE.multiSel[id] = new Set(opts);
  lgRebuildFilterOptions();
  lodgifyRenderForce();
};
window.lgMultiSetNone = function(id) {
  LG_STATE.multiSel[id] = new Set();
  lgRebuildFilterOptions();
  lodgifyRenderForce();
};
function lgMultiUpdateLabel(id) {
  const opts = LG_FILTER_OPTIONS[id] || [];
  const sel = LG_STATE.multiSel[id];
  const lbl = document.getElementById(`lg-multi-lbl-${id}`);
  if (!lbl || !sel) return;
  const txt = sel.size === opts.length ? `Todas (${opts.length})`
            : sel.size === 0 ? 'Ninguna'
            : sel.size === 1 ? [...sel][0]
            : `${sel.size} de ${opts.length}`;
  lbl.textContent = txt;
}

// Cerrar paneles al hacer click fuera
document.addEventListener('click', (e) => {
  if (!e.target.closest('[id^="lg-multi-"]')) {
    document.querySelectorAll('[id^="lg-multi-panel-"]').forEach(p => p.classList.add('hidden'));
  }
});

// Cache global de las opciones disponibles para cada filtro categórico.
const LG_FILTER_OPTIONS = { programacion: [], source: [], status: [], propiedad: [], factura: [], calificacion: ['Con calificación','Sin calificación'], incidencias: ['Con incidencia','Sin incidencia'], objetos: ['Con objeto olvidado','Sin objeto olvidado'] };

/** Devuelve si un booking REQUIERE FACTURA según el match con huéspedes.
 *  Si el huésped declaró "Sí" → "Con factura". Cualquier otro caso → "Sin factura". */
/** Obtiene la fila de Reservaciones (huésped) asociada a un booking:
 *  - Si el booking es sintético (sidebar Detalles desde Reservaciones),
 *    ya trae la referencia en b.__reservacion.
 *  - Si es un booking real de Lodgify, busca en LG_STATE.matches (que
 *    está keyed por Lodgify booking Id). */
function lgGetHuespedForBooking(b) {
  if (!b) return null;
  return b.__reservacion || LG_STATE.matches?.get(String(b.Id)) || null;
}

/** Devuelve 'exact' | 'probable' | null para un booking dado. */
function lgGetMatchKind(b) {
  if (!b) return null;
  if (b.__reservacionMatchKind) return b.__reservacionMatchKind;
  return LG_STATE.matchKinds?.get(String(b.Id)) || null;
}

/** HTML del chip "Probable match" (solo cuando kind === 'probable'). */
function lgProbableMatchChip() {
  return `<span title="Match por propiedad + fechas (el celular del booking no coincide con el del registro manual)" style="display:inline-block;padding:1px 7px;border-radius:999px;background:#fef3c7;color:#92400e;font-weight:800;font-size:9px;border:1px solid #fcd34d;letter-spacing:.04em">⚠ PROBABLE MATCH</span>`;
}

/** Decide si una fila de Reservaciones representa un REGISTRO MANUAL real
 *  (el huésped llenó el formulario de check-in) vs. una fila básica
 *  auto-creada por la propagación de Lodgify (que NO completa los campos
 *  del formulario).
 *
 *  La propagación llena solo: ID, Cel, Marca temporal, Medio, Propiedad,
 *  # Departamento, Fechas, # Noches, # Huéspedes, Nombre, Correo, Lodgify Id.
 *  Cualquier valor en los campos "manuales" abajo es señal inequívoca de
 *  que el huésped completó el formulario. */
function huHasManualRegistration(r) {
  if (!r) return false;
  // Criterio: la columna "Nombres de TODOS los huéspedes (separados por
  // comas)" tiene un valor no vacío. Lodgify no la propaga; solo se llena
  // cuando el huésped completa el formulario de check-in donde ese campo
  // es obligatorio.
  const v = r['Nombres de TODOS los huéspedes (separados por comas)'];
  return v != null && String(v).trim() !== '';
}

function lgBookingFacturaState(b) {
  const h = lgGetHuespedForBooking(b);
  if (!h) return 'Sin factura';
  const req = String(huValueFlexible(h, ['¿Requiere factura?']) || '').trim();
  return /^s[ií]?$/i.test(req) ? 'Con factura' : 'Sin factura';
}

/** Llena las opciones de los 5 filtros multi-select. */
function lgRebuildFilterOptions() {
  // Programación: estática
  LG_FILTER_OPTIONS.programacion = ['salida_hoy','activa','entrada_hoy','proxima','concluida'];
  // Source / Status / Propiedad: combinamos valores de Lodgify (LG_STATE)
  // Y Reservaciones (HU_STATE), porque el sidebar de Detalles ahora muestra
  // Reservaciones y sus "Medio de reservación" / "Propiedad" pueden tener
  // valores que NO existen en Lodgify (ej. "Manual local", "Walk-in", etc.).
  const lgSources = LG_STATE.bookings.map(b => b.Source).filter(Boolean);
  const huSources = (HU_STATE.rows || []).map(r => r['Medio de reservación']).filter(Boolean);
  LG_FILTER_OPTIONS.source = [...new Set([...lgSources, ...huSources])].sort();
  LG_FILTER_OPTIONS.status = [...new Set([...LG_STATE.bookings.map(b => b.Status), 'Booked', 'Tentative'].filter(Boolean))].sort();
  // Propiedad: SIEMPRE desde el catálogo "alojamientos" (homologado).
  // Si el catálogo aún no carga, fallback a los valores derivados de bookings/
  // huéspedes (homologados por lgPropOf cuando ALOJ_STATE ya cargó).
  if (ALOJ_STATE.loaded && ALOJ_STATE.rows.length) {
    const alojProps = ALOJ_STATE.rows
      .map(r => formatPropDeptoFromAloj_(r))
      .filter(v => v && v !== '—');
    LG_FILTER_OPTIONS.propiedad = [...new Set(alojProps)].sort((a,b) => a.localeCompare(b,'es'));
  } else {
    const lgProps = LG_STATE.bookings.map(b => lgPropOf(b));
    const huProps = (HU_STATE.rows || []).map(r => lgFmtPropiedad({ propiedad: r['Propiedad'] || '', departamento: r['# Departamento'] || '' }));
    LG_FILTER_OPTIONS.propiedad = [...new Set([...lgProps, ...huProps].filter(v => v && v !== '—'))].sort((a,b) => a.localeCompare(b,'es'));
  }
  // Factura: 2 valores estáticos
  LG_FILTER_OPTIONS.factura   = ['Con factura', 'Sin factura'];
  // Meses presentes en bookings + reservaciones (formato "YYYY-MM"). Ordenados
  // descendente (más recientes primero).
  const mesesSet = new Set();
  const addMes = (dateRaw) => {
    const s = String(dateRaw || '').trim();
    let m = s.match(/^(\d{4})-(\d{2})/);
    if (m) { mesesSet.add(`${m[1]}-${m[2]}`); return; }
    m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    if (m) mesesSet.add(`${m[3]}-${String(m[1]).padStart(2,'0')}`);
  };
  LG_STATE.bookings.forEach(b => addMes(b.DateArrival));
  (HU_STATE.rows || []).forEach(r => addMes(r['Fecha de ingreso']));
  // Siempre ofrece los últimos 36 meses aunque aún no estén cargados: al
  // elegir uno anterior a la ventana inicial se descargan bajo demanda.
  { const d = new Date(); d.setDate(1);
    for (let i = 0; i < 36; i++) { mesesSet.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`); d.setMonth(d.getMonth() - 1); } }
  LG_FILTER_OPTIONS.meses = Array.from(mesesSet).sort().reverse();

  lgMultiRender('programacion', '🗓️ Programación', LG_FILTER_OPTIONS.programacion, {
    optionRenderer: (v) => { const m = LG_STATE_META[v]; return m ? `${m.emoji} ${esc(m.label)}` : esc(v); },
  });
  // Cualquier valor de "Fuente" nuevo (aparece tras un sync) se selecciona
  // automáticamente — el filtro siempre arranca con TODAS las fuentes activas.
  if (LG_STATE.multiSel.source instanceof Set) {
    (LG_FILTER_OPTIONS.source || []).forEach(v => LG_STATE.multiSel.source.add(v));
  }
  lgMultiRender('source',    '🔌 Fuente',     LG_FILTER_OPTIONS.source, {
    defaultSelected: LG_FILTER_OPTIONS.source,
  });
  lgMultiRender('status',    '📊 Estado',     LG_FILTER_OPTIONS.status, { defaultSelected: ['Booked','Tentative'] });
  lgMultiRender('propiedad', '🏠 Propiedad',  LG_FILTER_OPTIONS.propiedad);
  lgMultiRender('factura',   '📄 Factura',    LG_FILTER_OPTIONS.factura, {
    optionRenderer: (v) => v === 'Con factura' ? '✅ Requiere factura' : '❌ No requiere factura',
  });
  // Filtros derivados de Breezeway / Incidencias / Objetos: cada uno con 2 opciones
  // (Con / Sin). Por default ambas seleccionadas — no filtra hasta que el usuario
  // deseleccione una explícitamente.
  lgMultiRender('calificacion', '⭐ Calificación', LG_FILTER_OPTIONS.calificacion, {
    defaultSelected: LG_FILTER_OPTIONS.calificacion,
    optionRenderer: (v) => v === 'Con calificación' ? '⭐ Con calificación' : '☆ Sin calificación',
  });
  lgMultiRender('incidencias', '🚨 Incidencias', LG_FILTER_OPTIONS.incidencias, {
    defaultSelected: LG_FILTER_OPTIONS.incidencias,
    optionRenderer: (v) => v === 'Con incidencia' ? '🚨 Con incidencia' : '· Sin incidencia',
  });
  lgMultiRender('objetos', '🧳 Objetos olvidados', LG_FILTER_OPTIONS.objetos, {
    defaultSelected: LG_FILTER_OPTIONS.objetos,
    optionRenderer: (v) => v === 'Con objeto olvidado' ? '🧳 Con objeto olvidado' : '· Sin objeto olvidado',
  });
  // Meses: default = mes en curso. Formatea como "Enero 2026".
  const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  const fmtMes = (ym) => {
    const m = String(ym).match(/^(\d{4})-(\d{2})/);
    return m ? `${meses[+m[2]-1]} ${m[1]}` : ym;
  };
  // Default = mes EN CURSO (si está en la lista de meses con datos).
  // Si la lista está vacía (datos no cargan aún) NO inicializamos → se
  // reintenta en el próximo rebuild cuando ya haya opciones.
  const now = new Date();
  const defaultMes = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  lgMultiRender('meses', '📅 Meses', LG_FILTER_OPTIONS.meses, {
    defaultSelected: LG_FILTER_OPTIONS.meses.includes(defaultMes) ? [defaultMes] : [],
    optionRenderer: (v) => esc(fmtMes(v)),
  });
}

/** Aplica filtros locales y devuelve los bookings a mostrar. */
/** Convierte una fila de Reservaciones a "booking sintético" con la misma
 *  forma que un Lodgify booking (Source, Status, DateArrival, etc.) para
 *  reutilizar todo el render del sidebar/detail SIN duplicar código.
 *  Si la fila tiene "Lodgify Id" y existe el booking real en LG_STATE.bookings,
 *  hidrata con sus campos (LineItems, Gross real, etc.). */
// Índice teléfono(10)|llegada|salida → reserva Lodgify. Se reconstruye cuando
// cambia LG_STATE.bookings. Si dos reservas comparten la clave se descarta
// (ambigua) para no ligar la equivocada.
let _LG_PHONE_DATES_IDX = { src: null, map: null };
function lgFindBookingByPhoneDates_(phone, arrival, departure) {
  const tail = (v) => { const s = String(v || '').replace(/\D/g, ''); return s.length >= 10 ? s.slice(-10) : ''; };
  const iso = (v) => {
    const s = String(v || '').trim();
    let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) return `${m[1]}-${m[2]}-${m[3]}`;
    m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); if (m) return `${m[3]}-${m[1].padStart(2,'0')}-${m[2].padStart(2,'0')}`;
    return '';
  };
  const t = tail(phone), a = iso(arrival), d = iso(departure);
  if (!t || !a || !d) return null;
  const src = LG_STATE.bookings || [];
  if (_LG_PHONE_DATES_IDX.src !== src) {
    const map = new Map();
    for (const b of src) {
      const k = `${tail(b.GuestPhone)}|${iso(b.DateArrival)}|${iso(b.DateDeparture)}`;
      if (k.startsWith('|')) continue;
      map.set(k, map.has(k) ? 'AMBIGUA' : b);
    }
    _LG_PHONE_DATES_IDX = { src, map };
  }
  const hit = _LG_PHONE_DATES_IDX.map.get(`${t}|${a}|${d}`);
  return hit && hit !== 'AMBIGUA' ? hit : null;
}

function huRowToSyntheticBooking(r, opts) {
  if (!r) return null;
  const phone = String(r['Cel/Whatsapp (principal)'] || '');
  const arrivalRaw = String(r['Fecha de ingreso'] || '');
  const departureRaw = String(r['Fecha de salida'] || '');
  // Las fechas en Reservaciones vienen como ISO YYYY-MM-DD; Lodgify formato
  // MM/DD/YYYY. El render espera MM/DD/YYYY (lgGetStayState, mmddToIso).
  const toMMDD = (iso) => {
    const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (m) return `${m[2]}/${m[3]}/${m[1]}`;
    return String(iso || '');
  };
  const lodId = String(r['Lodgify Id'] || '').trim();
  // Si la fila tiene Lodgify Id y el status REAL (del sheet Reservas_Lodgify,
  // capturado en __rawStatusById antes del filtro) es un estado no-visible,
  // NO generamos sintético → la reserva desaparece de Gestión de reservas.
  // Status Lodgify oculto (cancelada/borrada/etc.): por defecto NO generamos
  // sintético → la reserva desaparece de Gestión de reservas (filtrado).
  // Pero en modo display (opts.allowHidden, p.ej. al SELECCIONAR la card en el
  // historial) sí lo generamos, a partir de los datos PROPIOS de la fila e
  // ignorando el booking Lodgify oculto (que puede traer fechas/montos viejos).
  let _lgHidden = false;
  if (lodId && LG_STATE.__rawStatusById) {
    const rawSt = String(LG_STATE.__rawStatusById.get(lodId) || '').toLowerCase();
    const HIDDEN = new Set(['declined','cancelled','canceled','expired','deleted']);
    if (rawSt && HIDDEN.has(rawSt)) {
      if (!(opts && opts.allowHidden)) return null;
      _lgHidden = true;
    }
  }
  // realLg: primero busca en LG_STATE.bookings (mes en curso, filtrado
  // Booked/Tentative). Si no está — porque la reserva es de otro mes —
  // consulta el índice histórico completo LG_STATE.__allBookingsById.
  // Si el booking está oculto (_lgHidden) lo ignoramos: manda la fila.
  let realLg = (lodId && !_lgHidden) ? (LG_STATE.bookings || []).find(b => String(b.Id) === lodId) : null;
  if (!realLg && lodId && !_lgHidden && LG_STATE.__allBookingsById) {
    const raw = LG_STATE.__allBookingsById.get(lodId);
    if (raw) realLg = raw;
  }
  // Fila sin Lodgify Id (p. ej. check-in hecho sin la liga de la guía):
  // se liga con la reserva de Lodgify con mismo teléfono (10 dígitos) y
  // exactamente las mismas fechas de llegada y salida.
  if (!realLg && !lodId) realLg = lgFindBookingByPhoneDates_(phone, arrivalRaw, departureRaw);
  const arrival   = realLg?.DateArrival   || toMMDD(arrivalRaw);
  const departure = realLg?.DateDeparture || toMMDD(departureRaw);
  // Noches: si hay Lodgify, usarlo; si no, calcular de las fechas
  let nights = Number(r['# Noches']) || Number(realLg?.Nights) || 0;
  if (!nights && arrival && departure) {
    const da = arrival.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    const dd = departure.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    if (da && dd) {
      const t1 = new Date(+da[3], +da[1]-1, +da[2]).getTime();
      const t2 = new Date(+dd[3], +dd[1]-1, +dd[2]).getTime();
      nights = Math.max(0, Math.round((t2 - t1) / 86400000));
    }
  }
  // Rechaza placeholders literales que Apps Script deja al no poder
  // propagar el nombre desde Lodgify — se tratan como vacío para que la
  // cascada del render de la card llegue al fallback de Perfiles/BOTC.
  const _isPlaceholderName_ = (s) => {
    const v = String(s||'').trim().toLowerCase();
    return !v || v === 'falta el nombre del huésped' || v === 'falta el nombre del huesped'
        || v === 'sin nombre' || v === 'sin nombre del huésped' || v === 'sin nombre del huesped'
        || v === 'n/a' || v === 'na' || v === '-' || v === '—';
  };
  const _pickName_ = (...cands) => {
    for (const c of cands) { const v = String(c||'').trim(); if (v && !_isPlaceholderName_(v)) return v; }
    return '';
  };
  return {
    Id: String(r['ID'] || r['row_number'] || ''),
    GuestName: _pickName_(
      realLg?.GuestName,
      r['Nombre de la persona que hizo la reservación'],
      r['Nombre del huésped'],
      String(r['Nombres de TODOS los huéspedes (separados por comas)']||'').split(',')[0]
    ),
    GuestPhone: realLg?.GuestPhone || phone,
    GuestEmail: realLg?.GuestEmail || r['Correo electrónico'] || '',
    DateArrival: arrival,
    DateDeparture: departure,
    Nights: nights,
    NumberOfGuests: Number(realLg?.NumberOfGuests || r['# Huéspedes']) || 0,
    Adults: Number(realLg?.Adults || r['# Huéspedes']) || 0,
    Children: Number(realLg?.Children) || 0,
    Source: realLg?.Source || r['Medio de reservación'] || 'Manual',
    Status: realLg?.Status || 'Booked',
    HouseName: realLg?.HouseName || r['Propiedad'] || '',
    HouseId: realLg?.HouseId || '',
    // Campos crudos para el resolver de propiedad:
    PropiedadRaw: r['Propiedad'] || '',
    DepartamentoRaw: r['# Departamento'] || '',
    // Gross robusto: usa Gross de Lodgify si existe, sino delega a
    // huComputeRowTotal que suma tarifas ($ Noches + $ Cuota limpieza) o
    // usa múltiples fallbacks ($ MONTO TOTAL Airbnb, Monto facturado, etc).
    Gross: realLg && Number(realLg.Gross) > 0
      ? Number(realLg.Gross)
      : (typeof huComputeRowTotal === 'function' ? huComputeRowTotal(r) : (Number(r['$ Monto facturado Total']) || Number(r['($) Monto Total pagado']) || 0)),
    Currency: realLg?.Currency || 'MXN',
    LineItems: realLg?.LineItems || [],
    ConfirmationCode: realLg?.ConfirmationCode || '',
    LodgifyId: lodId || (realLg ? String(realLg.Id || '') : ''),
    // Referencias inversas para el render del detail:
    __reservacion: r,
    __lodgify: realLg,
  };
}

/** Resuelve prop+depto normalizados de un booking (real o synthetic) usando
 *  el catálogo alojamientos cuando es posible. Fallback a los campos crudos. */
function lgBookingPropDepNorm_(b) {
  // 1) Intenta mediante el catálogo (más robusto — normaliza HouseName)
  try {
    if (typeof lgFindAlojamiento === 'function') {
      const aloj = lgFindAlojamiento({
        houseId:      b.HouseId || '',
        houseName:    b.HouseName || '',
        propiedad:    b.PropiedadRaw    || (b.__reservacion ? b.__reservacion['Propiedad']      : ''),
        departamento: b.DepartamentoRaw || (b.__reservacion ? b.__reservacion['# Departamento'] : ''),
      });
      if (aloj) {
        return {
          propN: alojNorm(aloj['Propiedad'] || ''),
          deptN: alojNorm(String(aloj['# Departamento'] || '').replace(/^#\s*/, '')),
        };
      }
    }
  } catch(_) {}
  // 2) Fallback a campos crudos
  const propRaw = b.PropiedadRaw || (b.__reservacion && b.__reservacion['Propiedad']) || b.HouseName || '';
  const deptRaw = b.DepartamentoRaw || (b.__reservacion && b.__reservacion['# Departamento']) || '';
  return { propN: alojNorm(propRaw), deptN: alojNorm(String(deptRaw).replace(/^#\s*/,'')) };
}

/** Fechas ISO de estancia (arrival, departure) del booking, tolerante a shapes. */
function lgBookingArrDepIso_(b) {
  const arrIso = lgFmtDateUI(b.DateArrival)   || String((b.__reservacion && b.__reservacion['Fecha de ingreso']) || '').slice(0,10);
  const depIso = lgFmtDateUI(b.DateDeparture) || String((b.__reservacion && b.__reservacion['Fecha de salida']) || '').slice(0,10);
  return { arrIso, depIso };
}

/** ¿La reserva tiene calificación del huésped (Breezeway rating)? */
function lgBookingHasCalificacion(b) {
  if (typeof bzwGetRatingForLodId !== 'function') return false;
  // Real Lodgify: b.Id. Sintético (huRow): b.LodgifyId. Probar ambos.
  const ids = [String(b.LodgifyId||'').trim(), String(b.Id||'').trim()].filter(Boolean);
  for (const id of ids) {
    const r = bzwGetRatingForLodId(id);
    if (r != null && Number.isFinite(r)) return true;
  }
  return false;
}
/** ¿La reserva tiene reporte de incidencia (INC_STATE.list matches por prop+depto+rango)? */
function lgBookingHasIncidencia(b) {
  if (typeof INC_STATE === 'undefined' || !Array.isArray(INC_STATE.list) || !INC_STATE.list.length) return false;
  const { arrIso, depIso } = lgBookingArrDepIso_(b);
  if (!arrIso || !depIso) return false;
  const { propN, deptN } = lgBookingPropDepNorm_(b);
  if (!propN || !deptN) return false;
  for (const r of INC_STATE.list) {
    if (alojNorm(r['Propiedad']) !== propN) continue;
    if (alojNorm(String(r['# Departamento']||'').replace(/^#\s*/,'')) !== deptN) continue;
    const f = String(r['Fecha'] || r['Timestamp'] || '').slice(0,10);
    if (f && f >= arrIso && f <= depIso) return true;
  }
  return false;
}
/** ¿La reserva tiene reporte de objeto olvidado? */
function lgBookingHasObjeto(b) {
  if (typeof OBJ_STATE === 'undefined' || !Array.isArray(OBJ_STATE.list) || !OBJ_STATE.list.length) return false;
  const { arrIso, depIso } = lgBookingArrDepIso_(b);
  if (!arrIso || !depIso) return false;
  const { propN, deptN } = lgBookingPropDepNorm_(b);
  if (!propN || !deptN) return false;
  for (const r of OBJ_STATE.list) {
    if (alojNorm(r['Propiedad']) !== propN) continue;
    if (alojNorm(String(r['# Departamento']||'').replace(/^#\s*/,'')) !== deptN) continue;
    // Objetos usan "Fecha encontrado" o similar; probamos varios campos
    const f = String(r['Fecha encontrado'] || r['Fecha'] || r['Timestamp'] || '').slice(0,10);
    if (f && f >= arrIso && f <= depIso) return true;
  }
  return false;
}

function lgGetFiltered(sourceList) {
  // Sets de valores activos para cada filtro multi-select (null = no filtra)
  const pgSet = lgMultiGetSet('programacion', LG_FILTER_OPTIONS.programacion || []);
  const srcSet = lgMultiGetSet('source',     LG_FILTER_OPTIONS.source     || []);
  const stSet  = lgMultiGetSet('status',     LG_FILTER_OPTIONS.status     || []);
  const prSet  = lgMultiGetSet('propiedad',  LG_FILTER_OPTIONS.propiedad  || []);
  const facSet = lgMultiGetSet('factura',    LG_FILTER_OPTIONS.factura    || []);
  const calSet = lgMultiGetSet('calificacion', LG_FILTER_OPTIONS.calificacion || []);
  const incSet = lgMultiGetSet('incidencias',  LG_FILTER_OPTIONS.incidencias  || []);
  const objSet = lgMultiGetSet('objetos',      LG_FILTER_OPTIONS.objetos      || []);
  const nb  = (document.getElementById('lg-filtro-nombre')?.value || '').toLowerCase().trim();
  // Rango del slider (YYYY-MM-DD). Booking pasa si toca cualquier fecha:
  // DateArrival <= rangeEnd  AND  DateDeparture >= rangeStart
  // Filtro de meses: set de "YYYY-MM" seleccionados.
  const mesSet = lgMultiGetSet('meses', LG_FILTER_OPTIONS.meses || []);
  // Normalización de fechas format-agnóstica (soporta MM/DD/YYYY, YYYY-MM-DD
  // y Date). Antes solo aceptaba MM/DD/YYYY, lo que rompía el filtro de mes
  // para reservas manuales (formato ISO). Ahora usa el helper canónico.
  const mmddToIso = lgMMDDtoIsoDate;
  // NOTA: antes había una "ventana visible default" silenciosa que escondía
  // toda reserva con salida < hoy-7d. Eso ocultaba reservas históricas que
  // sí tenían registros en Reservaciones, sin que el usuario lo supiera y
  // dejando inútil la opción "Concluida" del filtro Programación. Ahora se
  // muestra todo por default; usa Programación / fechas para filtrar.
  const bookingsSrc = sourceList || LG_STATE.bookings;
  const filtered = bookingsSrc.filter(b => {
    if (srcSet) {
      if (!srcSet.has(String(b.Source||'').toLowerCase())) return false;
    }
    if (stSet) {
      if (!stSet.has(String(b.Status||'').toLowerCase())) return false;
    }
    if (prSet) {
      if (!prSet.has(String(lgPropOf(b)||'').toLowerCase())) return false;
    }
    if (pgSet) {
      const state = lgGetStayState(b.DateArrival, b.DateDeparture);
      if (!pgSet.has(state)) return false;
    }
    if (facSet) {
      if (!facSet.has(lgBookingFacturaState(b).toLowerCase())) return false;
    }
    if (calSet) {
      const has = lgBookingHasCalificacion(b);
      const key = has ? 'con calificación' : 'sin calificación';
      if (!calSet.has(key)) return false;
    }
    if (incSet) {
      const has = lgBookingHasIncidencia(b);
      const key = has ? 'con incidencia' : 'sin incidencia';
      if (!incSet.has(key)) return false;
    }
    if (objSet) {
      const has = lgBookingHasObjeto(b);
      const key = has ? 'con objeto olvidado' : 'sin objeto olvidado';
      if (!objSet.has(key)) return false;
    }
    if (nb) {
      // Búsqueda libre en TODOS los campos del booking + del huesped
      // vinculado + del booking Lodgify real (si existe). Aplana cualquier
      // valor primitivo a string; ignora objetos anidados gigantes (LineItems,
      // __reservacion, __lodgify) excepto sus claves seleccionadas.
      const acc = [];
      const push = (v) => {
        if (v == null) return;
        const t = typeof v;
        if (t === 'string' || t === 'number' || t === 'boolean') acc.push(String(v));
      };
      for (const k of Object.keys(b)) {
        if (k.startsWith('__')) continue;
        if (k === 'LineItems') continue;
        push(b[k]);
      }
      const huR = b.__reservacion;
      if (huR && typeof huR === 'object') {
        for (const k of Object.keys(huR)) push(huR[k]);
      }
      const lgR = b.__lodgify;
      if (lgR && typeof lgR === 'object') {
        for (const k of Object.keys(lgR)) {
          if (k === 'LineItems' || k === 'LineItemsJSON') continue;
          push(lgR[k]);
        }
      }
      const hay = acc.join(' ').toLowerCase();
      if (!hay.includes(nb)) return false;
    }
    // Filtro por MESES: booking pasa si la fecha de llegada cae en alguno
    // de los meses seleccionados (formato YYYY-MM). null = no filtra.
    if (mesSet) {
      const arrIso = mmddToIso(b.DateArrival);
      const mesArr = arrIso ? arrIso.slice(0,7) : '';
      if (!mesArr || !mesSet.has(mesArr)) return false;
    }
    return true;
  });
  // Si el usuario eligió una columna para ordenar (vista Tabla), aplica
  // ese orden a TODOS los registros filtrados.
  if (LG_STATE.sortKey) {
    const key = LG_STATE.sortKey;
    const dir = LG_STATE.sortDir === 'desc' ? -1 : 1;
    const accessor = (b) => {
      switch (key) {
        case 'Programacion': return ({ salida_hoy:1, activa:2, entrada_hoy:3, proxima:4, concluida:5 }[lgGetStayState(b.DateArrival, b.DateDeparture)] || 99);
        case 'Propiedad':    return lgPropOf(b).toLowerCase();
        case 'GuestName':    return String(b.GuestName||'').toLowerCase();
        case 'DateArrival':  return lgParseMMDD(b.DateArrival)?.getTime() || 0;
        case 'DateDeparture':return lgParseMMDD(b.DateDeparture)?.getTime() || 0;
        case 'Nights':       return Number(b.Nights)||0;
        case 'Source':       return String(b.Source||'').toLowerCase();
        case 'Status':       return String(b.Status||'').toLowerCase();
        case 'NumberOfGuests':return Number(b.NumberOfGuests)||0;
        case 'Adults':       return Number(b.Adults)||0;
        case 'Children':     return Number(b.Children)||0;
        case 'Gross':        return Number(b.Gross)||0;
        case 'Net':          return Number(b.Net)||0;
        case 'Vat':          return Number(b.Vat)||0;
        case 'Currency':     return String(b.Currency||'').toLowerCase();
        case 'GuestEmail':   return String(b.GuestEmail||'').toLowerCase();
        case 'GuestPhone':   return String(b.GuestPhone||'').toLowerCase();
        case 'ConfirmationCode': return String(b.ConfirmationCode||'').toLowerCase();
        case 'DateCancelled': return lgParseMMDD(b.DateCancelled)?.getTime() || 0;
        case 'RoomTypeNames':return String(b.RoomTypeNames||'').toLowerCase();
        case 'ChannelBooking': return String(b.ChannelBooking||'').toLowerCase();
        case 'Id':           return String(b.Id||'');
        default:             return String(b[key]||'');
      }
    };
    filtered.sort((a, b) => {
      const va = accessor(a), vb = accessor(b);
      if (va < vb) return -1 * dir;
      if (va > vb) return  1 * dir;
      return 0;
    });
    return filtered; // saltar el orden por Programación cuando hay sort explícito
  }
  // Ordenamiento global:
  //   1) Con factura + Pendiente  (factRank=0)
  //   2) Con factura + Emitida    (factRank=1)
  //   3) Resto                    (factRank=2)
  // Dentro del grupo factura, sub-orden por Programación (Próxima → Activa →
  // Salida hoy → Concluida) y luego fecha de llegada.
  const factRankOf = (b) => {
    const h = lgGetHuespedForBooking(b);
    if (!h) return 2;
    const st = (typeof huGetFacturaStatus === 'function') ? huGetFacturaStatus(h) : '';
    const req = huValueFlexible(h, ['¿Requiere factura?']);
    const conFact = /s[ií]/i.test(String(req||'')) || st === 'emitida' || st === 'pendiente';
    if (!conFact) return 2;
    if (st === 'pendiente') return 0;
    if (st === 'emitida')   return 1;
    return 2;
  };
  const rank = { salida_hoy: 1, activa: 2, entrada_hoy: 3, proxima: 4, concluida: 5 };
  const tsArrival = (b) => {
    const m = String(b.DateArrival||'').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    return m ? new Date(+m[3], +m[1]-1, +m[2]).getTime() : 0;
  };
  // Claves calculadas una vez por reserva (no en cada comparación del sort).
  const keyed = filtered.map(b => ({
    b,
    f: factRankOf(b),
    s: rank[lgGetStayState(b.DateArrival, b.DateDeparture)] || 99,
    t: tsArrival(b),
  }));
  keyed.sort((x, y) => {
    if (x.f !== y.f) return x.f - y.f;
    if (x.s !== y.s) return x.s - y.s;
    // Próximas / Entrada hoy / Activa / Salida hoy: ascendente por fecha.
    // Concluidas: las más recientes primero.
    if (x.s === 5) return y.t - x.t;
    return x.t - y.t;
  });
  return keyed.map(k => k.b);
}

/** Renderiza KPIs + lista de cards. */
// Re-render explícito disparado por usuario (filtros, paginación, etc.).
// Resetea la selección actual (ese es el comportamiento esperado para filtros).
window.lodgifyRenderForce = function() {
  window.LG_USER_INTERACTED = false;
  lodgifyRender({ force: true });
};
function lodgifyRender(opts) {
  // BAIL EARLY: una vez el usuario selecciona una card (lgHistorySelect),
  // CUALQUIER re-render programático destruye la selección y vuelve al
  // booking #1 — eso es exactamente lo que el usuario reporta.
  // Filtros y acciones explícitas pasan {force:true} para forzar el render.
  if (!(opts && opts.force) && window.LG_USER_INTERACTED) {
    console.info('[LG] lodgifyRender BLOQUEADO: usuario interactuó. force:true para forzar.');
    return;
  }
  // Meses seleccionados anteriores a lo ya descargado → traerlos (async) y
  // volver a pintar al llegar.
  try {
    if (lgEnsureMesesCargados_()) return; // descargando: el loader queda visible y se re-pinta al llegar
  } catch (_) {}
  const mode = LG_STATE.viewMode || 'list';
  // En modo "detail" el sidebar muestra Reservaciones. Si HU_STATE aún no
  // está cargado (las páginas están en curso), evitamos renderizar con datos
  // parciales — sería el flicker que ve el usuario. Mostramos placeholder
  // y volvemos a llamar a lodgifyRender desde huespedesLoad al finalizar.
  if ((mode === 'detail' || mode === 'cards') && !HU_STATE.loaded) {
    const cont = document.getElementById('lg-cards');
    if (cont && !cont.querySelector('.lg-detail-loading-placeholder')) {
      cont.innerHTML = `
        <div class="lg-detail-loading-placeholder" style="padding:60px 20px;text-align:center;color:#64748b;font-size:13px">
          <div style="font-size:28px;margin-bottom:10px">⏳</div>
          <div style="font-weight:700;margin-bottom:4px">Cargando reservaciones…</div>
          <div style="font-size:11px;color:#94a3b8">Trayendo todas las páginas de Reservaciones. Tarda 1–3s.</div>
        </div>`;
    }
    return;
  }
  // En modo "detail" el sidebar muestra Reservaciones (no Lodgify), respetando
  // el mismo diseño de cards (synthetic bookings con mismos campos).
  // Cache de la lista de synthetic bookings: invalidate solo cuando cambie
  // el tamaño de HU_STATE.rows o LG_STATE.bookings. Construir 785 sintéticos
  // por cada filter/click es prohibitivo (≈300ms por re-render).
  let detailSource = null;
  if (mode === 'detail' || mode === 'cards') {
    // Solo reservaciones cuya estancia toca la ventana del módulo (2 meses
    // atrás → futuro). Antes se convertía TODO el historial (≈6,000 filas,
    // ~3 s por render).
    const winFrom = huParseDate((LG_STATE.__monthRange && LG_STATE.__monthRange.from) || '');
    const huAll = HU_STATE.rows || [];
    const hu = winFrom ? huAll.filter(r => {
      const d = huParseDate(r['Fecha de salida']) || huParseDate(r['Fecha de ingreso']);
      return !d || d >= winFrom;
    }) : huAll;
    const lg = LG_STATE.bookings || [];
    const cacheKey = `${huAll.length}|${hu.length}|${lg.length}`;
    if (!LG_STATE.__syntheticCache || LG_STATE.__syntheticCacheKey !== cacheKey) {
      // SIDEBAR = HUÉSPEDES: 1 card por persona (dedupe por últimos 10
      // dígitos del teléfono); el card refleja la reservación MÁS RECIENTE
      // (mayor Fecha de ingreso) de esa persona.
      const phoneTail = (v) => {
        const s = String(v || '').replace(/\D/g, '');
        return s.length >= 10 ? s.slice(-10) : '';
      };
      // PASE 1 — dedupe por teléfono (1 card por persona).
      const latestByTail = new Map();
      const noPhone = [];
      for (const r of hu) {
        const tail = phoneTail(r['Cel/Whatsapp (principal)']);
        if (!tail) { noPhone.push(r); continue; }
        const cur = latestByTail.get(tail);
        const dThis = String(r['Fecha de ingreso'] || '');
        if (!cur || dThis > String(cur['Fecha de ingreso'] || '')) {
          latestByTail.set(tail, r);
        }
      }
      const afterPhone = Array.from(latestByTail.values()).concat(noPhone);
      // PASE 2 — merge por (propiedad + fechas). Cuando dos filas comparten
      // ese trío pero tienen teléfono distinto, las colapsamos en UNA sola
      // (preferimos la que tenga registro manual; en empate, la más reciente).
      // Las "perdedoras" desaparecen del sidebar pero siguen vivas en
      // HU_STATE.rows para que aparezcan en "Reservas totales" con chip
      // ⚠ PROBABLE.
      const groupKeyOf = (r) => {
        const pk = lgPropDeptKey(r['Propiedad'], r['# Departamento']);
        const ar = String(r['Fecha de ingreso'] || '').slice(0,10);
        const dp = String(r['Fecha de salida'] || '').slice(0,10);
        return (pk && ar && dp) ? `${pk}|${ar}|${dp}` : '';
      };
      const groups = new Map();
      const ungrouped = [];
      for (const r of afterPhone) {
        const k = groupKeyOf(r);
        if (!k) { ungrouped.push(r); continue; }
        if (!groups.has(k)) groups.set(k, []);
        groups.get(k).push(r);
      }
      const winners = [];
      const probableWinnerIds = new Set();
      for (const [k, rows] of groups) {
        rows.sort((a, b) => {
          const ma = huHasManualRegistration(a) ? 1 : 0;
          const mb = huHasManualRegistration(b) ? 1 : 0;
          if (ma !== mb) return mb - ma;
          return String(b['Fecha de ingreso']||'').localeCompare(String(a['Fecha de ingreso']||''));
        });
        const winner = rows[0];
        winners.push(winner);
        if (rows.length > 1) {
          const wTail = phoneTail(winner['Cel/Whatsapp (principal)']);
          const diffPhone = rows.slice(1).some(l => {
            const lt = phoneTail(l['Cel/Whatsapp (principal)']);
            return lt && lt !== wTail;
          });
          if (diffPhone) {
            probableWinnerIds.add(String(winner['ID'] || winner['row_number'] || ''));
          }
        }
      }
      const finalRows = [...winners, ...ungrouped];
      LG_STATE.__syntheticCache = finalRows.map(huRowToSyntheticBooking).filter(Boolean);
      LG_STATE.__syntheticCache.forEach(b => {
        if (probableWinnerIds.has(String(b.Id))) b.__reservacionMatchKind = 'probable';
      });
      LG_STATE.__syntheticCacheKey = cacheKey;
    }
    detailSource = LG_STATE.__syntheticCache;
  }
  const list = lgGetFiltered(detailSource);
  // Memoriza la lista filtrada actual para que el Historial use exactamente
  // los mismos registros (mismas reglas de filtro = misma cuenta).
  LG_STATE.lastFilteredList = list;
  // KPIs
  const nights = list.reduce((a,b) => a + (b.Nights || 0), 0);
  const gross  = list.reduce((a,b) => a + (b.Gross  || 0), 0);
  const cur    = list[0]?.Currency || 'MXN';
  const setT = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  setT('lg-kpi-count', String(list.length));
  setT('lg-kpi-nights', String(nights));
  setT('lg-kpi-gross', gross > 0 ? lgFmtMoney(gross, cur) : '—');
  setT('lg-kpi-avg',   nights > 0 ? lgFmtMoney(gross/nights, cur) : '—');
  // Cards
  const cont = document.getElementById('lg-cards');
  const empty = document.getElementById('lg-empty');

  // En modo "detail" SIEMPRE renderizamos el sidebar (con leyendas de filtros)
  // aunque la lista filtrada esté vacía — así el usuario puede re-activar
  // chips desde Ninguna sin perder el control.
  if (mode === 'detail') {
    lgBuildDetailView(list, cont);
    if (empty) empty.classList.add('hidden');
    return;
  }
  if (mode === 'cards') {
    lgBuildCardsView(list, cont);
    if (empty) empty.classList.add('hidden');
    return;
  }

  if (!list.length) {
    cont.innerHTML = '';
    if (empty) { empty.textContent = 'Sin reservaciones según los filtros.'; empty.classList.remove('hidden'); }
    return;
  }
  if (empty) empty.classList.add('hidden');

  if (mode === 'kanban') {
    cont.innerHTML = lgBuildKanban(list);
  } else if (mode === 'table') {
    cont.innerHTML = lgBuildTable(list);
  } else {
    cont.innerHTML = list.map(lgBuildCard).join('');
    if (typeof lgSetupCardEnrichObserver === 'function') lgSetupCardEnrichObserver();
  }
}

// IntersectionObserver: cuando una card entra en viewport y su huésped tiene
// registro manual pero aún no se cargan los URLs de INE/vehículo, fetch
// /huespedes-detail una sola vez y re-render esa card.
const _LG_CARD_ENRICHED = new Set();
let _lgCardObserver = null;
function lgSetupCardEnrichObserver() {
  if (typeof IntersectionObserver === 'undefined') return;
  if (_lgCardObserver) _lgCardObserver.disconnect();
  _lgCardObserver = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      const el = entry.target;
      const bid = el.getAttribute('data-lg-id');
      _lgCardObserver.unobserve(el);
      if (!bid || _LG_CARD_ENRICHED.has(bid)) return;
      _LG_CARD_ENRICHED.add(bid);
      lgEnrichCardPhotos(bid, el);
    });
  }, { rootMargin: '300px' });
  document.querySelectorAll('.lg-card[data-lg-id]').forEach(el => {
    const bid = el.getAttribute('data-lg-id');
    if (!bid) return;
    const h = LG_STATE.matches?.get(bid);
    if (!h || !huHasManualRegistration(h)) return;
    if (h.__lgCardEnriched) return;
    const hasUrls = h['Link INE frontal'] || h['INE frontal'] || h['Link INE trasero'] || h['INE trasero'] || h['Link foto vehículo'] || h['Foto vehículo'];
    if (hasUrls) { h.__lgCardEnriched = true; return; }
    _lgCardObserver.observe(el);
  });
}
async function lgEnrichCardPhotos(bookingId, cardEl) {
  const h = LG_STATE.matches?.get(String(bookingId));
  if (!h) return;
  const recId = String(h.ID || h.row_number || '');
  if (!recId) return;
  try {
    const j = await fetch(`${BACKEND}/huespedes-detail?record_id=${encodeURIComponent(recId)}`).then(r => r.json());
    if (!j?.ok || !j.record) return;
    const merged = { ...h, ...j.record, __lgCardEnriched: true };
    const idx = (HU_STATE.rows || []).findIndex(x => String(x['ID']||x['row_number']||'') === recId);
    if (idx >= 0) HU_STATE.rows[idx] = merged;
    LG_STATE.matches.set(String(bookingId), merged);
    const b = (LG_STATE.bookings || []).find(x => String(x.Id) === String(bookingId));
    if (!b || !cardEl.isConnected) return;
    const tpl = document.createElement('template');
    tpl.innerHTML = lgBuildCard(b).trim();
    const fresh = tpl.content.firstElementChild;
    if (fresh) cardEl.replaceWith(fresh);
  } catch (e) { console.warn('[LG cards] enrich:', e.message); }
}

/** Versión compacta del chip de fuente para los items del sidebar de la
 *  vista Detalles. Pequeño, padding mínimo. */
function lgSourceChipMini(src) {
  const s = String(src || '').trim();
  if (!s) return '<span style="display:inline-block;padding:1px 7px;border-radius:999px;background:#f1f5f9;color:#475569;font-weight:700;font-size:9px;border:1px solid #cbd5e1">—</span>';
  const lc = s.toLowerCase();
  let bg='#f1f5f9', fg='#475569', bd='#cbd5e1', ico='🌐';
  if (lc.includes('airbnb'))       { bg='#fef2f2'; fg='#dc2626'; bd='#fecaca'; ico='Ⓐ'; }
  else if (lc.includes('booking')) { bg='#dbeafe'; fg='#1e40af'; bd='#93c5fd'; ico='Ⓑ'; }
  else if (lc.includes('expedia')) { bg='#fef3c7'; fg='#92400e'; bd='#fcd34d'; ico='Ⓔ'; }
  else if (lc.includes('vrbo'))    { bg='#dcfce7'; fg='#166534'; bd='#86efac'; ico='Ⓥ'; }
  else if (lc.includes('manual'))  { bg='#ede9fe'; fg='#5b21b6'; bd='#c4b5fd'; ico='✋'; }
  return `<span style="display:inline-flex;align-items:center;gap:3px;padding:1px 7px;border-radius:999px;background:${bg};color:${fg};font-weight:800;font-size:9px;border:1px solid ${bd};letter-spacing:.02em">${ico} ${esc(s)}</span>`;
}

/** Construye un item del sidebar de la vista "Detalles" con:
 *  - Top: chip Fuente + chip Ticket emitido / pendiente / Requiere factura
 *  - Centro: thumb, nombre, fechas, status badge, monto
 *  - Bottom: cajas Noches globales y Tier del huésped (si hay match)
 *  - Fondo: color del estado de programación (tenue). */
function lgBuildDetailSidebarItem(b, selectedId, huespedOverride) {
  const isSel = String(b.Id) === String(selectedId);
  const statusUi = rdMapStatus(b);
  const ing = rdFmtFechaCortaNoYear(b.DateArrival);
  const sal = rdFmtFechaCortaNoYear(b.DateDeparture);
  // huespedOverride permite inyectar un huésped sintético (ej. bot-chats
  // arma uno mínimo con solo el phone para resolver KPIs desde el cache
  // pre-computado cuando la persona no está en Reservaciones).
  const huesped = huespedOverride || lgGetHuespedForBooking(b);
  // hasMatch = registro manual REAL (huésped llenó formulario), no sólo una
  // fila básica importada de Lodgify.
  const hasMatch = huHasManualRegistration(huesped);
  const initials = String(b.GuestName||'?').split(/\s+/).map(w => w[0]||'').slice(0,2).join('').toUpperCase();

  const stayState = lgGetStayState(b.DateArrival, b.DateDeparture) || '';
  const stMeta = LG_STATE_META[stayState] || LG_STATE_META.concluida;
  // BG según factura (NO programación). Programación se mueve al borde
  // izquierdo más grueso para distinguir cards visualmente sin perder el
  // canal "factura".
  //   Con factura + Emitida #X → verde claro
  //   Con factura + Pendiente  → rojo claro
  //   Sin factura              → blanco
  const facStatus = huesped ? ((typeof huGetFacturaStatus === 'function') ? huGetFacturaStatus(huesped) : '') : '';
  const reqFac = huesped ? huValueFlexible(huesped, ['¿Requiere factura?']) : '';
  const conFactura = /s[ií]/i.test(String(reqFac||'')) || facStatus === 'emitida' || facStatus === 'pendiente';
  let itemBg = '#fff';
  let itemBgSel = '#f1f5f9'; // resaltado neutro para "sin factura"
  if (conFactura && facStatus === 'emitida')  { itemBg = '#dcfce7'; itemBgSel = '#86efac'; }      // verde claro → verde más intenso
  else if (conFactura && facStatus === 'pendiente') { itemBg = '#fee2e2'; itemBgSel = '#fca5a5'; } // rojo claro  → rojo más intenso
  // (sin factura → blanco; default ya; resaltado = gris claro)
  const accentColor = stMeta.border;
  const finalBg = isSel ? itemBgSel : itemBg;
  const activeShadow = isSel
    ? `box-shadow:0 6px 18px ${stMeta.shadowAccent}, 0 2px 6px rgba(15,23,42,.18);transform:translateX(2px);`
    : '';

  // ─── Top: source + ticket / requiere factura ───
  const sourceChip = lgSourceChipMini(b.Source);
  let tktChip = '';
  if (huesped) {
    const status = (typeof huGetFacturaStatus === 'function') ? huGetFacturaStatus(huesped) : '';
    const folio = huValueFlexible(huesped, ['Folio facturapi','Folio Facturapi','Folio']);
    const reqFac = huValueFlexible(huesped, ['¿Requiere factura?']);
    if (status === 'emitida') {
      tktChip = `<span style="display:inline-block;padding:1px 7px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:9px;border:1px solid #86efac">🧾 Emitida${folio?' #'+esc(folio):''}</span>`;
    } else if (status === 'pendiente') {
      tktChip = `<span style="display:inline-block;padding:1px 7px;border-radius:999px;background:#fff7ed;color:#c2410c;font-weight:700;font-size:9px;border:1px solid #fdba74">🧾 Pendiente</span>`;
    } else if (/s[ií]/i.test(reqFac)) {
      tktChip = `<span style="display:inline-block;padding:1px 7px;border-radius:999px;background:#fef3c7;color:#92400e;font-weight:700;font-size:9px;border:1px solid #fde68a">📄 Req. factura</span>`;
    }
    if (status === 'emitida') {
      const medio = String(huValueFlexible(huesped, ['Medio de emisión','Medio de emision']) || '').trim();
      if (medio) {
        const isAuto = /auto/i.test(medio);
        const bg = isAuto ? '#ede9fe' : '#e0f2fe';
        const fg = isAuto ? '#5b21b6' : '#0369a1';
        const bd = isAuto ? '#c4b5fd' : '#7dd3fc';
        const emoji = isAuto ? '👤' : '🖥️';
        tktChip += ` <span title="Origen del ticket" style="display:inline-block;padding:1px 7px;border-radius:999px;background:${bg};color:${fg};border:1px solid ${bd};font-size:9px;font-weight:800;letter-spacing:.02em">${emoji} ${esc(medio)}</span>`;
      }
    }
  }
  // Chip Late checkout — leído de la columna LateCheckout de Reservaciones
  // (formato "HH:MM · pendiente|confirmado|rechazado · timestamp").
  let lateChip = '';
  const lateRaw = huesped ? String(huValueFlexible(huesped, ['LateCheckout']) || '').trim() : '';
  if (lateRaw) {
    const partes = lateRaw.split('·').map(s => s.trim());
    const hora = partes[0] || '';
    const est = (partes[1] || 'pendiente').toLowerCase();
    let bg = '#fef3c7', fg = '#92400e', bd = '#fde68a';       // pendiente
    if (est === 'confirmado') { bg = '#dcfce7'; fg = '#166534'; bd = '#86efac'; }
    else if (est === 'rechazado') { bg = '#fee2e2'; fg = '#991b1b'; bd = '#fca5a5'; }
    lateChip = `<span title="${esc('Late checkout · ' + est + (partes[2]?' · '+partes[2]:''))}" style="display:inline-block;padding:1px 7px;border-radius:999px;background:${bg};color:${fg};font-weight:800;font-size:9px;border:1px solid ${bd};letter-spacing:.04em">🕐 Late ${esc(hora)}</span>`;
  }

  // ─── Bottom: 3 cajas Noches + Visitas + Monto + tier inline (sólo si hay match) ───
  let bottomBoxesHtml = '';
  let tierInlineHtml = '';
  if (huesped && typeof huComputeGuestStats === 'function') {
    try {
      const stats = huComputeGuestStats(huesped, HU_STATE.rows);
      const score = (typeof huComputeLoyaltyScore === 'function') ? huComputeLoyaltyScore(stats) : 0;
      const tier  = (typeof huGuestTier === 'function') ? huGuestTier(score, stats) : null;
      const boxHtml = (icon, label, value, flex) => `
        <div style="flex:${flex};background:#fff;border:1px solid #e2e8f0;border-radius:6px;padding:3px 7px;text-align:center;min-width:0">
          <div style="font-size:7px;color:#64748b;font-weight:800;letter-spacing:.04em;text-transform:uppercase">${icon} ${esc(label)}</div>
          <div style="font-size:11px;font-weight:800;color:#0f172a;line-height:1.1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${value}</div>
        </div>`;
      const fmt$ = (n) => (typeof huFmtMonto === 'function') ? huFmtMonto(n) : ('$ '+Number(n||0).toFixed(0));
      // Fallback: si stats.montoTotal es 0 (huésped sin match/registro),
      // usa Gross del booking Lodgify — el mismo campo que suma la card
      // de "Gestión de reservas" (ver huComputeLodgifyGrossForStay).
      const bkTotal = Number(b.Gross || b.Amount || b.Total || 0);
      const montoShow = stats.montoTotal > 0 ? stats.montoTotal : bkTotal;
      bottomBoxesHtml = `
        <div style="display:flex;gap:5px;margin-top:7px">
          ${boxHtml('🌙', 'Noches', String(stats.totalNoches), '1')}
          ${boxHtml('🧳', 'Visitas', String(stats.visitas), '1')}
          ${boxHtml('💰', 'Monto', montoShow > 0 ? fmt$(montoShow) : '—', '1.4')}
        </div>`;
      // Tier+score inline para colocarlo junto al nombre
      tierInlineHtml = tier ? `
        <span title="${esc(tier.tooltip)}" style="display:inline-flex;align-items:center;gap:3px;font-size:9px;font-weight:800;color:${tier.fg};background:${tier.bg};border:1px solid ${tier.border};padding:1px 6px;border-radius:999px;letter-spacing:.04em;text-transform:uppercase;line-height:1.2;white-space:nowrap">
          <span style="font-size:11px">${tier.icon}</span>${esc(tier.label)}
          <span style="background:rgba(255,255,255,.7);color:${tier.fg};padding:0 4px;border-radius:6px;font-weight:800">${tier.score}</span>
        </span>` : '';
    } catch (e) { /* silent */ }
  } else {
    // Fallback: SIN match manual (huésped no registrado). Mostramos KPIs
    // básicos derivados sólo del booking Lodgify — así todas las cards
    // muestran monto/noches y no aparecen sin datos.
    try {
      const fmt$ = (n) => (typeof huFmtMonto === 'function') ? huFmtMonto(n) : ('$ '+Number(n||0).toFixed(0));
      const boxHtml = (icon, label, value, flex) => `
        <div style="flex:${flex};background:#fff;border:1px solid #e2e8f0;border-radius:6px;padding:3px 7px;text-align:center;min-width:0">
          <div style="font-size:7px;color:#64748b;font-weight:800;letter-spacing:.04em;text-transform:uppercase">${icon} ${esc(label)}</div>
          <div style="font-size:11px;font-weight:800;color:#0f172a;line-height:1.1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${value}</div>
        </div>`;
      // Noches directo del rango del booking (MMDD → Date).
      const parseD = (v) => {
        const m = String(v || '').match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/) || String(v || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
        if (!m) return null;
        return m[3] && m[3].length === 4 ? new Date(+m[3], +m[1]-1, +m[2]) : new Date(+m[1], +m[2]-1, +m[3]);
      };
      const dA = parseD(b.DateArrival), dD = parseD(b.DateDeparture);
      const nochesN = (dA && dD) ? Math.max(1, Math.round((dD - dA) / 86_400_000)) : 0;
      const bkTotal = Number(b.Gross || b.Amount || b.Total || 0);
      bottomBoxesHtml = `
        <div style="display:flex;gap:5px;margin-top:7px">
          ${boxHtml('🌙', 'Noches',  nochesN > 0 ? String(nochesN) : '—', '1')}
          ${boxHtml('🧳', 'Visitas', '1', '1')}
          ${boxHtml('💰', 'Monto',   bkTotal > 0 ? fmt$(bkTotal) : '—', '1.4')}
        </div>`;
    } catch(_) {}
  }

  // Programación: punto animado (mismo patrón que historial de Reservas
  // totales) + label texto (Activa, Concluida, Próxima, etc.).
  const dotColor = stMeta.border;
  const dotPulse = stayState === 'activa'      ? 'animation:hu-dot-pulse 1.4s ease-in-out infinite;'
                 : stayState === 'salida_hoy'  ? 'animation:hu-dot-pulse-strong 1s ease-in-out infinite;'
                 : stayState === 'entrada_hoy' ? 'animation:hu-dot-pulse 1.4s ease-in-out infinite;'
                 : stayState === 'proxima'     ? 'animation:hu-dot-pulse 2s ease-in-out infinite;'
                 : '';
  const progDot = stayState ? `
    <span style="display:inline-flex;align-items:center;gap:4px">
      <span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:${dotColor};box-shadow:0 0 0 2px rgba(255,255,255,.7);${dotPulse}"></span>
      <span style="color:${stMeta.accentFg};font-weight:800">${esc(stMeta.label)}</span>
    </span>` : '';

  // ─── Calificación del huésped: promedio de guest_rating a lo largo de sus reservas ───
  // Preferimos usar el huésped registrado (para tener acceso al historial vía phone tail);
  // si no hay huésped, cae al Lodgify Id del booking actual.
  let guestAvgStarsInline = '';
  try {
    let _avg = null;
    if (huesped && typeof huAvgGuestRatingForRecord === 'function') {
      _avg = huAvgGuestRatingForRecord(huesped);
    }
    if (!_avg && typeof bzwGetRatingForLodId === 'function') {
      const _r = bzwGetRatingForLodId(String(b.Id||''));
      if (_r != null) _avg = { avg: _r, count: 1, values: [_r] };
    }
    if (_avg) {
      const filled = Math.round(_avg.avg);
      const stars = Array.from({ length: 5 }, (_, i) =>
        `<span style="color:${i < filled ? '#f59e0b' : '#e5e7eb'};font-size:12px;line-height:1">★</span>`).join('');
      const lbl = _avg.count > 1
        ? `promedio de ${_avg.count} reservas`
        : 'calificación del huésped';
      guestAvgStarsInline = `<span title="Calificación del huésped — ${lbl}: ${_avg.avg.toFixed(1)}/5" style="display:inline-flex;align-items:center;gap:2px;padding:2px 7px;border-radius:999px;background:#fffbeb;border:1.5px solid #fcd34d;line-height:1.2">${stars}<span style="font-size:9px;color:#92400e;font-weight:800;margin-left:2px">${_avg.avg.toFixed(1)}</span></span>`;
    }
  } catch(_) {}

  return `
    <div class="rd-item ${isSel?'rd-active':''}" onclick="lgDetailSelect('${esc(b.Id)}')"
         data-lg-booking-id="${esc(b.Id)}"
         data-lodgify-id="${esc(b.LodgifyId || b.Id || '')}"
         data-lg-state="${stayState||'concluida'}"
         data-lg-bg="${finalBg}"
         data-lg-bg-sel="${itemBgSel}"
         data-lg-bg-norm="${itemBg}"
         style="position:relative;background:${finalBg};border-left:7px solid ${accentColor};padding-left:9px;display:block;${activeShadow}">
      <button onclick="event.stopPropagation();lgHideCard('${esc(b.LodgifyId || '')}','${esc(b.Id || '')}')"
              title="Ocultar esta reserva del frontend"
              style="position:absolute;top:4px;left:4px;z-index:5;width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;border:1px solid #fecaca;background:#fff;color:#dc2626;font-size:11px;font-weight:900;line-height:1;cursor:pointer;box-shadow:0 1px 2px rgba(15,23,42,.08)">×</button>
      <!-- Top: chips Fuente + Registrado/Ticket (izquierda)  + Programación (derecha) -->
      <div style="display:flex;gap:5px;align-items:center;flex-wrap:wrap;margin-bottom:6px;min-width:0;justify-content:space-between;padding-left:22px">
        <div style="display:flex;gap:5px;align-items:center;flex-wrap:wrap;min-width:0">
          ${sourceChip}
          ${hasMatch?'<span style="display:inline-block;padding:1px 7px;border-radius:999px;background:linear-gradient(135deg,#475569,#334155);color:#fff;font-weight:800;font-size:9px;border:1px solid #1e293b;letter-spacing:.04em">REGISTRADO</span>':''}
          ${lgGetMatchKind(b) === 'probable' ? lgProbableMatchChip() : ''}
          ${tktChip}
          ${lateChip}
        </div>
        ${(() => {
          const coHead = (typeof lgFindCheckoutFor_ === 'function') ? lgFindCheckoutFor_(lgPropOf(b), '', b.DateDeparture) : null;
          const coChip = coHead
            ? `<span title="${esc('Check-out registrado' + (coHead['Comentarios'] ? ' · ' + String(coHead['Comentarios']) : ''))}" style="display:inline-block;padding:1px 7px;border-radius:999px;background:#dc2626;color:#fff;font-weight:800;font-size:9px;letter-spacing:.04em">🚪 Check-out</span>`
            : '';
          // Chip de status de pago (Pagada/Sin pago/Parcial/etc.) — se
          // muestra debajo del chip de programación. Al click abre el
          // drawer con desglose (mismo que módulo Pagos).
          let payChip = '';
          try {
            if (typeof _botcPaymentChip === 'function') {
              const ph = String(b.GuestPhone || '');
              const chip = _botcPaymentChip(b);
              if (chip) payChip = `<span onclick="event.stopPropagation();_botcOpenPaymentDrawer('${esc(ph)}')" title="Ver desglose de pago" style="cursor:pointer">${chip}</span>`;
            }
          } catch(_){}
          if (!progDot && !coChip && !payChip) return '';
          return `<span style="margin-left:auto;display:inline-flex;flex-direction:column;align-items:flex-end;gap:3px;font-size:9px;letter-spacing:.04em;text-transform:uppercase">${progDot}${coChip}${payChip}</span>`;
        })()}
      </div>
      <!-- Chips Aseo + Asignaciones se inyectan por bzwInjectSidebarChips
           (DOM) para sobrevivir al timing entre el render del sidebar y la
           carga async de BZW_ALL_TASKS. NO renderizar aquí — duplicaría. -->
      <!-- Centro: nombre, propiedad, fechas, status, monto. -->
      <div style="min-width:0">
        <div class="rd-item-row1">
          <span class="rd-status-badge rd-status-${statusUi}">${esc(statusUi)}</span>
        </div>
        <div class="rd-item-name" style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">
          ${(() => {
            // Prioriza el nombre del Perfil. Busca en cascada:
            //  1) huesped (match del booking en Reservaciones).
            //  2) HU_STATE.rows por celular (si el match falló pero el huésped
            //     tiene otro row en Reservaciones con ese phone).
            //  3) BOTC_STATE.conversations por celular (Perfiles vía Chats bot).
            const bookingName = String(b.GuestName || '').trim();
            const p10 = String(b.GuestPhone || '').replace(/\D/g,'').slice(-10);
            // Toma el primer nombre de una lista "Nombres de TODOS los
            // huéspedes (separados por comas)" — para reservas Airbnb
            // suele ser la única fuente con el nombre real.
            const _primerHuesped = (raw) => String(raw||'').split(',')[0].trim();
            // Placeholders literales que Apps Script deja en la hoja cuando no
            // logra propagar el nombre desde Lodgify — hay que tratarlos como
            // vacíos para que la cascada siga buscando el nombre real.
            const _PLACEHOLDERS = new Set([
              'falta el nombre del huésped',
              'falta el nombre del huesped',
              'sin nombre',
              'sin nombre del huésped',
              'sin nombre del huesped',
              'n/a', 'na', '-', '—',
            ]);
            const _validName = (s) => {
              const v = String(s||'').trim();
              if (!v) return '';
              return _PLACEHOLDERS.has(v.toLowerCase()) ? '' : v;
            };
            let perfilName = '';
            // 1) PRIORIDAD 1 — Perfiles vía BOTC_STATE (nombre canónico de la hoja Perfiles).
            if (p10 && typeof BOTC_STATE === 'object' && BOTC_STATE !== null && Array.isArray(BOTC_STATE.conversations)) {
              try {
                const c = BOTC_STATE.conversations.find(x => x && String(x.phone) === p10);
                if (c && c.name) perfilName = _validName(c.name);
              } catch(_){}
            }
            // 2) Match en Reservaciones (huesped): "Nombre del huésped" y luego "Nombres de TODOS los huéspedes".
            if (!perfilName && huesped) perfilName = _validName(huesped['Nombre del huésped']);
            if (!perfilName && huesped) perfilName = _validName(_primerHuesped(huesped['Nombres de TODOS los huéspedes (separados por comas)']));
            // 3) Buscar en HU_STATE.rows por celular (otro row del mismo huésped).
            if (!perfilName && p10 && typeof HU_STATE !== 'undefined' && Array.isArray(HU_STATE.rows)) {
              try {
                const m = HU_STATE.rows.find(r => String(r['Cel/Whatsapp (principal)']||'').replace(/\D/g,'').slice(-10) === p10);
                if (m) {
                  perfilName = _validName(m['Nombre del huésped'])
                            || _validName(_primerHuesped(m['Nombres de TODOS los huéspedes (separados por comas)']));
                }
              } catch(_){}
            }
            // Regla: la card SIEMPRE muestra el nombre del Perfil (mismo que
            // aparece en el editor). Nunca muestra el nombre con el que se
            // registró la reserva en Lodgify (fallback solo si no hay perfil).
            // También filtra el bookingName por placeholder para no mostrar
            // "Falta el nombre del huésped" cuando Perfiles tampoco tiene dato.
            const main = perfilName || _validName(bookingName) || 'Sin nombre';
            return `<span>${esc(main)}</span>`;
          })()}
          ${(() => {
            const ph = String(b.GuestPhone || '').replace(/\D/g,'').slice(-10);
            if (!ph) return '';
            return `<button type="button" onclick="event.stopPropagation();_botcOpenPerfilEditor_('${esc(ph)}')" title="Editar perfil del huésped" style="background:#dbeafe;border:1px solid #93c5fd;cursor:pointer;padding:2px 6px;border-radius:5px;color:#1e40af;font-size:10px;font-weight:800;line-height:1;display:inline-flex;align-items:center;gap:3px" onmouseover="this.style.background='#bfdbfe'" onmouseout="this.style.background='#dbeafe'">✏️ Editar</button>`;
          })()}
          ${guestAvgStarsInline}
          ${tierInlineHtml}
        </div>
        <div style="font-size:11px;color:#475569;font-weight:600;margin-top:2px">${esc(lgPropOf(b) || '—')}</div>
        <div class="rd-item-meta"><span>🌙 ${esc(ing)} - ${esc(sal)}</span><span>· 👥 ${b.NumberOfGuests||0}</span></div>
        <div class="rd-item-amount">${b.Gross>0 ? lgFmtMoney(b.Gross, b.Currency) : '<span style="color:#94a3b8;font-weight:700;font-size:11px">N/A</span>'}</div>
      </div>
      <!-- Bottom: cajas Noches + Tier (última línea) -->
      ${bottomBoxesHtml}
    </div>`;
}

/** Leyenda de Factura (Con factura / Sin factura + Todas / Ninguna). */
function lgBuildFacturaLegendHtml() {
  const allValues = LG_FILTER_OPTIONS.factura || ['Con factura','Sin factura'];
  lgMultiInitIfNeeded('factura', allValues);
  const sel = LG_STATE.multiSel['factura'] || new Set();
  const styles = {
    'Con factura': { bgIntense:'#dcfce7', border:'#86efac', accentFg:'#166534', shadow:'rgba(22,163,74,.22)', icon:'✅', label:'Requiere factura' },
    'Sin factura': { bgIntense:'#fee2e2', border:'#fca5a5', accentFg:'#991b1b', shadow:'rgba(220,38,38,.22)', icon:'❌', label:'No requiere factura' },
  };
  const chip = (v) => {
    const s = styles[v]; if (!s) return '';
    const active = sel.has(v);
    return `
      <button type="button" onclick="event.stopPropagation();lgMultiToggle('factura','${esc(v)}');lodgifyRender()"
              title="${esc(s.label)}"
              style="display:inline-flex;align-items:center;gap:4px;padding:4px 9px;border-radius:999px;
                     border:1.5px solid ${s.border};
                     background:${active ? s.bgIntense : '#fff'};
                     color:${active ? s.accentFg : '#cbd5e1'};
                     font-weight:800;font-size:10px;letter-spacing:.02em;cursor:pointer;
                     transition:transform 120ms ease, box-shadow 120ms ease;
                     ${active ? `box-shadow:0 2px 6px ${s.shadow};` : 'opacity:.55;'}
                     white-space:nowrap">
        <span style="font-size:11px;line-height:1">${s.icon}</span>${esc(s.label)}
      </button>`;
  };
  const todasBtn = `
    <button type="button" onclick="event.stopPropagation();lgMultiSetAll('factura');lodgifyRender()"
            style="padding:4px 9px;border-radius:999px;border:1.5px solid #cbd5e1;background:#f8fafc;color:#475569;font-weight:800;font-size:10px;cursor:pointer">✓ Todas</button>`;
  const ningunaBtn = `
    <button type="button" onclick="event.stopPropagation();lgMultiSetNone('factura');lodgifyRender()"
            style="padding:4px 9px;border-radius:999px;border:1.5px solid #cbd5e1;background:#f8fafc;color:#475569;font-weight:800;font-size:10px;cursor:pointer">✕ Ninguna</button>`;
  return `
    <div style="padding:8px 12px;border-bottom:1px solid #e2e8f0;background:#fafbfc">
      <div style="font-size:9px;letter-spacing:.16em;color:#94a3b8;font-weight:800;margin-bottom:6px;text-transform:uppercase">📄 Factura · filtro</div>
      <div style="display:flex;flex-wrap:wrap;gap:5px;align-items:center">
        ${allValues.map(chip).join('')}
        <span style="width:1px;height:18px;background:#e2e8f0;margin:0 2px"></span>
        ${todasBtn}${ningunaBtn}
      </div>
    </div>`;
}

/** Construye la leyenda de Programación (5 chips de color + Todas + Ninguna)
 *  arriba del sidebar "Reservas". Comparte el estado del filtro
 *  `programacion` con el dropdown global → un click aquí filtra la lista del
 *  sidebar Y la lista general. */
function lgBuildProgLegendHtml() {
  const allValues = LG_FILTER_OPTIONS.programacion || ['salida_hoy','activa','entrada_hoy','proxima','concluida'];
  lgMultiInitIfNeeded('programacion', allValues);
  const sel = LG_STATE.multiSel['programacion'] || new Set();
  const chip = (state) => {
    const m = LG_STATE_META[state]; if (!m) return '';
    const active = sel.has(state);
    // Fondo blanco siempre. La identidad de cada chip se refleja en una
    // LÍNEA gruesa a la izquierda (5px) — mismo color que el borde izquierdo
    // de las cards del sidebar (que también marca Programación).
    return `
      <button type="button" onclick="event.stopPropagation();lgMultiToggle('programacion','${state}');lodgifyRender()"
              title="${esc(m.label)}${active?' (activo)':' (desactivado — click para activar)'}"
              style="display:inline-flex;align-items:center;gap:6px;padding:4px 9px 4px 0;border-radius:6px;
                     border:1px solid ${active ? '#94a3b8' : '#e2e8f0'};
                     background:#fff;
                     color:${active ? '#0f172a' : '#cbd5e1'};
                     font-weight:800;font-size:10px;letter-spacing:.02em;cursor:pointer;
                     transition:opacity 120ms ease, border-color 120ms ease;
                     ${active ? '' : 'opacity:.55;'}
                     white-space:nowrap;overflow:hidden">
        <span style="display:inline-block;width:5px;align-self:stretch;background:${m.border};border-radius:6px 0 0 6px"></span>
        <span>${esc(m.label)}</span>
      </button>`;
  };
  const todasBtn = `
    <button type="button" onclick="event.stopPropagation();lgMultiSetAll('programacion');lodgifyRender()"
            style="padding:4px 9px;border-radius:999px;border:1.5px solid #cbd5e1;background:#f8fafc;color:#475569;font-weight:800;font-size:10px;cursor:pointer">✓ Todas</button>`;
  const ningunaBtn = `
    <button type="button" onclick="event.stopPropagation();lgMultiSetNone('programacion');lodgifyRender()"
            style="padding:4px 9px;border-radius:999px;border:1.5px solid #cbd5e1;background:#f8fafc;color:#475569;font-weight:800;font-size:10px;cursor:pointer">✕ Ninguna</button>`;
  return `
    <div style="padding:8px 12px;border-bottom:1px solid #e2e8f0;background:#fafbfc">
      <div style="font-size:9px;letter-spacing:.16em;color:#94a3b8;font-weight:800;margin-bottom:6px;text-transform:uppercase">🗓️ Programación · filtro</div>
      <div style="display:flex;flex-wrap:wrap;gap:5px;align-items:center">
        ${['salida_hoy','activa','entrada_hoy','proxima','concluida'].map(chip).join('')}
        <span style="width:1px;height:18px;background:#e2e8f0;margin:0 2px"></span>
        ${todasBtn}${ningunaBtn}
      </div>
    </div>`;
}

/** Vista "Detalles": sidebar izquierdo con lista de reservas + área amplia
 *  a la derecha con el MISMO contenido del modal pop-up (header Lodgify +
 *  detalle + bloque huéspedes 3-columnas). Cuando se selecciona un item del
 *  sidebar, solo se re-renderiza el área de detalle. */
/** Barra de progreso de Facturación — emitidas vs pendientes — solo dentro
 *  del universo "requiere factura". Mismo estilo que la barra "Por clasificar"
 *  de Registros contables. */
function lgBuildFacturaProgressHtml(list) {
  let requeridas = 0, emitidas = 0, pendientes = 0;
  (list || []).forEach(b => {
    const h = (typeof lgGetHuespedForBooking === 'function') ? lgGetHuespedForBooking(b) : null;
    if (!h) return;
    const req = String(huValueFlexible(h, ['¿Requiere factura?']) || '').trim();
    const st  = (typeof huGetFacturaStatus === 'function') ? huGetFacturaStatus(h) : '';
    const conFact = /^s[ií]?$/i.test(req) || st === 'emitida' || st === 'pendiente';
    if (!conFact) return;
    requeridas++;
    if (st === 'emitida') emitidas++;
    else pendientes++;
  });
  const total = requeridas;
  const pctE  = total > 0 ? (emitidas   / total * 100) : 0;
  const pctP  = total > 0 ? (pendientes / total * 100) : 0;
  return `
    <div style="padding:8px 12px;background:#f8fafc;border:1px solid #cbd5e1;border-radius:10px;margin-bottom:10px">
      <div style="font-size:10px;letter-spacing:.14em;color:#64748b;font-weight:800;text-transform:uppercase;margin-bottom:6px">🧾 Reservas con ticket de auto-facturación</div>
      <div style="display:flex;align-items:center;gap:10px">
        <div style="display:flex;align-items:center;gap:6px;font-size:12px;font-weight:700;color:#14532d;white-space:nowrap">
          <span style="width:9px;height:9px;border-radius:50%;background:#16a34a;display:inline-block"></span>
          ${emitidas} (${pctE.toFixed(0)}%) Emitidas
        </div>
        <div style="flex:1;display:flex;height:12px;border-radius:999px;overflow:hidden;background:#e5e7eb">
          <div title="Emitidas: ${emitidas}"   style="width:${pctE.toFixed(2)}%;background:linear-gradient(90deg,#16a34a,#86efac);transition:width .3s"></div>
          <div title="Pendientes: ${pendientes}" style="width:${pctP.toFixed(2)}%;background:linear-gradient(90deg,#fca5a5,#dc2626);transition:width .3s"></div>
        </div>
        <div style="display:flex;align-items:center;gap:6px;font-size:12px;font-weight:700;color:#7f1d1d;white-space:nowrap">
          Pendientes ${pendientes} (${pctP.toFixed(0)}%)
          <span style="width:9px;height:9px;border-radius:50%;background:#dc2626;display:inline-block"></span>
        </div>
      </div>
    </div>`;
}

function lgBuildDetailView(list, cont) {
  // Determina el booking seleccionado: prioridad LG_STATE.detailSelectedId,
  // si no, el primero de la lista filtrada.
  let selectedId = LG_STATE.detailSelectedId;
  if (!selectedId || !list.find(b => String(b.Id) === String(selectedId))) {
    selectedId = list.length ? String(list[0].Id) : null;
    LG_STATE.detailSelectedId = selectedId;
  }
  const selected = list.find(b => String(b.Id) === String(selectedId));

  // Sidebar HTML
  const sidebarItems = list.slice(0, 200).map(b => lgBuildDetailSidebarItem(b, selectedId)).join('');
  const facturaLegendHtml = lgBuildFacturaLegendHtml();
  const legendHtml = lgBuildProgLegendHtml();
  const facturaProgressHtml = lgBuildFacturaProgressHtml(list);

  // Hamburguesa de filtros: predeterminadamente desplegada (LG_STATE.filtersOpen).
  if (LG_STATE.filtersOpen === undefined) LG_STATE.filtersOpen = true;
  const filtersExpanded = !!LG_STATE.filtersOpen;
  // Sidebar de Huéspedes: colapsable. Mobile colapsado por default, desktop expandido.
  const _isMobile = window.matchMedia && window.matchMedia('(max-width: 768px)').matches;
  if (LG_STATE.sidebarOpen === undefined) LG_STATE.sidebarOpen = !_isMobile;
  const sidebarOpen = !!LG_STATE.sidebarOpen;
  cont.innerHTML = `
    <div class="lg-detail-shell">
      <aside class="rd-sidebar">
        <!-- Filtros y barra de progreso ARRIBA — siempre visibles aunque la
             lista de huéspedes esté colapsada. -->
        ${facturaProgressHtml}
        <div id="lg-sidebar-filters" style="${filtersExpanded ? '' : 'display:none'}">
          ${facturaLegendHtml}
          ${legendHtml}
        </div>
        <!-- Header colapsable: solo controla la visibilidad de la lista. -->
        <div class="rd-sidebar-header" style="display:flex;align-items:center;gap:10px;cursor:pointer;user-select:none;margin-top:6px" onclick="lgToggleSidebarOpen()">
          <span style="font-size:16px;color:#475569;width:18px;text-align:center">${sidebarOpen ? '▾' : '▸'}</span>
          <button type="button" onclick="event.stopPropagation();lgToggleSidebarFilters(this)"
                  title="Mostrar/ocultar filtros"
                  style="border:1px solid #cbd5e1;background:#fff;color:#475569;border-radius:8px;width:34px;height:34px;cursor:pointer;font-size:16px;flex-shrink:0;display:flex;align-items:center;justify-content:center">☰</button>
          <div>
            <div class="rd-sidebar-title">Huéspedes</div>
            <div class="rd-sidebar-count">${list.length} huésped${list.length===1?'':'es'}</div>
          </div>
        </div>
        ${sidebarOpen ? `<div class="rd-list">${sidebarItems || '<div style="padding:20px;text-align:center;color:#94a3b8;font-size:12px;font-style:italic">Sin reservaciones</div>'}</div>` : ''}
      </aside>
      <div class="lg-detail-panel">
        <div id="lg-detail-main" class="lg-detail-panel-body"></div>
      </div>
    </div>`;

  if (selected) lgDetailRenderMain(selected);
}

/** Vista "Cards" — full width:
 *    [barra de progreso] [filtros Factura | Programación] [hamburguesa ☰]
 *    [lista de cards a todo el ancho]
 *  Cada card es el mismo header que el sidebar de Detalles; al hacer click
 *  se EXPANDE hacia abajo con el panel completo (perfil + 3 columnas). */
function lgBuildCardsView(list, cont) {
  if (LG_STATE.filtersOpen === undefined) LG_STATE.filtersOpen = true;
  const filtersExpanded = !!LG_STATE.filtersOpen;
  if (!window.__lgCardsExpanded) window.__lgCardsExpanded = new Set();
  const expandedSet = window.__lgCardsExpanded;
  const facturaProgressHtml = lgBuildFacturaProgressHtml(list);
  const facturaLegendHtml = lgBuildFacturaLegendHtml();
  const legendHtml = lgBuildProgLegendHtml();

  // Lista vacía (ej. "Ninguna" en Factura/Programación): se renderiza el
  // mismo shell de filtros + un placeholder en lugar de las cards. Antes
  // se reemplazaba todo el contenedor → los filtros desaparecían y el
  // usuario quedaba sin forma de re-seleccionar.
  // Se pintan de 60 en 60 ("Ver más"): 200 tarjetas costaban ~750 ms.
  const shown = Math.min(list.length, LG_STATE.cardsLimit || 60);
  const itemsHtml = !list.length
    ? '<div style="padding:60px 20px;text-align:center;color:#94a3b8;font-size:13px;font-style:italic">Sin reservaciones según los filtros.</div>'
    : list.slice(0, shown).map(b => {
    const idStr = esc(b.Id);
    let sidebarHeader = lgBuildDetailSidebarItem(b, ''); // sin selected → estilo base
    sidebarHeader = sidebarHeader.replace(
      /onclick="lgDetailSelect\('[^']*'\)"/g,
      `onclick="lgCardsToggle('${idStr}')"`
    );
    const isOpen = expandedSet.has(String(b.Id));
    return `
      <div class="lg-cards-item" data-lg-cards-id="${idStr}" style="margin-bottom:8px;border:1px solid #e2e8f0;border-radius:10px;overflow:hidden;background:#fff">
        ${sidebarHeader}
        <div class="lg-cards-body" data-lg-cards-body style="${isOpen ? '' : 'display:none;'}background:#f8fafc;padding:14px;border-top:1px solid #e2e8f0">
          ${isOpen ? lgCardsExpandedHtml(b) : ''}
        </div>
      </div>`;
  }).join('');

  cont.innerHTML = `
    <div class="lg-cards-shell" style="display:block;width:100%">
      <!-- Línea 1: hamburguesa + barra de progreso de facturación, a lo ancho. -->
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px">
        <button type="button" onclick="lgToggleSidebarFilters(this)"
                title="Mostrar/ocultar filtros"
                style="border:1px solid #cbd5e1;background:#fff;color:#475569;border-radius:8px;width:34px;height:34px;cursor:pointer;font-size:16px;flex-shrink:0;display:flex;align-items:center;justify-content:center">☰</button>
        <div style="flex:1;min-width:0">${facturaProgressHtml}</div>
      </div>
      <!-- Línea 2: filtros (toggleables con el botón ☰) -->
      <div id="lg-sidebar-filters" style="display:${filtersExpanded ? 'grid' : 'none'};grid-template-columns:1fr 1fr;gap:10px;align-items:start;margin-bottom:10px">
        <div>${facturaLegendHtml}</div>
        <div>${legendHtml}</div>
      </div>
      <div class="lg-cards-list" style="display:block">
        ${itemsHtml}
      </div>
      ${list.length > shown ? `<button type="button" onclick="lgCardsShowMore()" style="display:block;width:100%;margin:14px 0 8px;padding:10px 12px;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;font-size:12px;font-weight:800;color:#334155;cursor:pointer">Ver ${Math.min(60, list.length - shown)} más · mostrando ${shown} de ${list.length}</button>` : ''}
    </div>`;
}

window.lgCardsShowMore = function () {
  LG_STATE.cardsLimit = (LG_STATE.cardsLimit || 60) + 60;
  const y = window.scrollY;
  lodgifyRender({ force: true });
  window.scrollTo(0, y);
};

/** Contenido expandido de una card en vista Cards.
 *  Como el header colapsable ya muestra nombre + tier + KPIs (Noches/Visitas/
 *  Monto), aquí solo renderizamos:
 *  - Datos del perfil (INE / Contacto / Fiscales / Vehículo) en fondo BLANCO
 *  - 3 columnas (history / detail / cobros) vía lgBuildHuespedSectionHtml */
function lgCardsExpandedHtml(b) {
  let huesped = null;
  try {
    huesped = (typeof lgGetHuespedForBooking === 'function') ? lgGetHuespedForBooking(b) : null;
    if (!huesped && typeof lgFindHuespedRepresentativeByPhone === 'function') {
      huesped = lgFindHuespedRepresentativeByPhone(b);
    }
  } catch (_) {}
  // Datos del perfil en fondo BLANCO (palette neutro).
  const _whitePalette = { border: '#e2e8f0', bg: '#ffffff' };
  let profileHtml = '';
  try {
    if (huesped && typeof lgBuildProfileHeaderHtml === 'function') {
      const inner = lgBuildProfileHeaderHtml(huesped, _whitePalette);
      if (inner) {
        profileHtml = `<div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:12px 14px;margin-bottom:14px">${inner}</div>`;
      }
    }
  } catch (e) { console.error('[lgCardsExpandedHtml] profile error:', e); }
  let body = '';
  try {
    if (huesped && typeof lgBuildHuespedSectionHtml === 'function') {
      body = lgBuildHuespedSectionHtml(huesped, b, null);
    } else if (typeof lgBuildEmpty3ColLayout === 'function') {
      body = lgBuildEmpty3ColLayout(b);
    }
  } catch (e) {
    console.error('[lgCardsExpandedHtml] body error:', e);
    body = `<div style="padding:14px;color:#dc2626;font-size:12px">Error al cargar detalles: ${esc(e.message||String(e))}</div>`;
  }
  return profileHtml + body;
}

/** Toggle expand/collapse de una card en vista Cards. */
window.lgCardsToggle = function(bookingId) {
  if (!window.__lgCardsExpanded) window.__lgCardsExpanded = new Set();
  const set = window.__lgCardsExpanded;
  const id = String(bookingId);
  const item = document.querySelector(`.lg-cards-item[data-lg-cards-id="${CSS.escape(id)}"]`);
  if (!item) { console.warn('[lgCardsToggle] item no encontrado:', id); return; }
  const body = item.querySelector('[data-lg-cards-body]');
  if (!body) { console.warn('[lgCardsToggle] body no encontrado:', id); return; }
  const wasOpen = set.has(id);
  if (wasOpen) {
    set.delete(id);
    body.style.display = 'none';
    body.innerHTML = '';
    return;
  }
  // Buscar el booking. Si no se encuentra, NO mutamos el set (evita
  // estados inconsistentes UI ↔ estado).
  let b = (LG_STATE.bookings || []).find(x => String(x.Id) === id)
       || (LG_STATE.__syntheticCache || []).find(x => String(x.Id) === id);
  if (!b && typeof huRowToSyntheticBooking === 'function') {
    const r = (HU_STATE.rows || []).find(x => String(x['ID']||x['row_number']||'') === id);
    if (r) b = huRowToSyntheticBooking(r);
  }
  if (!b) { console.warn('[lgCardsToggle] booking no encontrado:', id); return; }
  try {
    body.innerHTML = lgCardsExpandedHtml(b);
  } catch (e) {
    console.error('[lgCardsToggle] error renderizando expanded:', e);
    body.innerHTML = `<div style="padding:20px;color:#dc2626;font-size:12px">Error al cargar detalles: ${esc(e.message||String(e))}</div>`;
  }
  body.style.display = 'block';
  set.add(id);
  window.LG_USER_INTERACTED = true;
  // Enrich fotos INE/vehículo si no están en cache (URLs solo vienen de /huespedes-detail)
  try {
    const h = lgGetHuespedForBooking(b) || (typeof lgFindHuespedRepresentativeByPhone==='function' ? lgFindHuespedRepresentativeByPhone(b) : null);
    if (h && huHasManualRegistration(h) && !h.__lgCardEnriched) {
      const hasUrls = h['Link INE frontal']||h['INE frontal']||h['Link INE trasero']||h['INE trasero']||h['Link foto vehículo']||h['Foto vehículo'];
      if (hasUrls) { h.__lgCardEnriched = true; }
      else {
        const recId = String(h.ID||h.row_number||'');
        if (recId) {
          fetch(`${BACKEND}/huespedes-detail?record_id=${encodeURIComponent(recId)}`)
            .then(r => r.json())
            .then(j => {
              if (!j?.ok || !j.record) return;
              const merged = { ...h, ...j.record, __lgCardEnriched: true };
              const idx = (HU_STATE.rows || []).findIndex(x => String(x['ID']||x['row_number']||'') === recId);
              if (idx >= 0) HU_STATE.rows[idx] = merged;
              if (LG_STATE.matches) LG_STATE.matches.set(String(b.Id), merged);
              // Sincronizar también __reservacion del booking sintético y caché
              if (b.__reservacion) b.__reservacion = merged;
              (LG_STATE.__syntheticCache || []).forEach(s => { if (s.__reservacion && String(s.__reservacion.ID||s.__reservacion.row_number) === recId) s.__reservacion = merged; });
              if (!set.has(id)) return;
              const stillBody = document.querySelector(`.lg-cards-item[data-lg-cards-id="${CSS.escape(id)}"] [data-lg-cards-body]`);
              if (!stillBody) return;
              try { stillBody.innerHTML = lgCardsExpandedHtml(b); } catch(_) {}
            })
            .catch(e => console.warn('[lgCardsToggle] enrich foto:', e.message));
        }
      }
    }
  } catch (_) {}
};


/** Click en una card del sidebar de Detalles. */
window.lgToggleSidebarFilters = function(btn) {
  LG_STATE.filtersOpen = !LG_STATE.filtersOpen;
  const box = document.getElementById('lg-sidebar-filters');
  if (box) box.style.display = LG_STATE.filtersOpen ? '' : 'none';
};
window.lgToggleSidebarOpen = function() {
  LG_STATE.sidebarOpen = !LG_STATE.sidebarOpen;
  window.LG_USER_INTERACTED = false;
  if (typeof lodgifyRender === 'function') lodgifyRender({ force: true });
};

window.lgDetailSelect = function(id) {
  LG_STATE.detailSelectedId = String(id);
  // Re-skin: la card seleccionada usa bg INTENSO (data-lg-bg-sel) y sombra.
  // Las demás vuelven al bg normal (data-lg-bg-norm).
  document.querySelectorAll('.lg-detail-shell .rd-item').forEach(el => {
    const bid = el.getAttribute('data-lg-booking-id');
    const state = el.getAttribute('data-lg-state') || 'concluida';
    const meta = LG_STATE_META[state] || LG_STATE_META.concluida;
    const bgNorm = el.getAttribute('data-lg-bg-norm') || '#fff';
    const bgSel  = el.getAttribute('data-lg-bg-sel')  || '#f1f5f9';
    const isThis = String(bid) === String(id);
    if (isThis) {
      el.classList.add('rd-active');
      el.style.background = bgSel;
      el.style.boxShadow  = `0 6px 18px ${meta.shadowAccent}, 0 2px 6px rgba(15,23,42,.18)`;
      el.style.transform  = 'translateX(2px)';
    } else {
      el.classList.remove('rd-active');
      el.style.background = bgNorm;
      el.style.boxShadow  = '';
      el.style.transform  = '';
    }
  });
  // En vista Detalles el sidebar muestra Reservaciones (sintéticas). Buscamos
  // primero en HU_STATE.rows (id = ID de Reservaciones), si no, fallback a
  // LG_STATE.bookings (id = Lodgify Id) para compat con otras vistas.
  const r = (HU_STATE.rows || []).find(x => String(x['ID']||x['row_number']||'') === String(id));
  if (r) {
    const b = huRowToSyntheticBooking(r);
    if (b) { lgDetailRenderMain(b); return; }
  }
  const b = (LG_STATE.bookings || []).find(x => String(x.Id) === String(id));
  if (b) lgDetailRenderMain(b);
};

// Token de generación para abortar callbacks asíncronos obsoletos. Cada vez
// que el usuario clickea otro card, este contador sube; cualquier fetch /
// requestAnimationFrame en vuelo cuyo token no coincida con el actual debe
// descartar su resultado (no pisar el DOM con datos del card anterior).
let LG_RENDER_GEN = 0;

/** Renderiza el contenido principal de la vista Detalles con el mismo
 *  contenido del modal pop-up. */
function lgDetailRenderMain(b) {
  const main = document.getElementById('lg-detail-main');
  if (!main) return;
  // Generación de este render — invalida cualquier render anterior en vuelo.
  const myGen = ++LG_RENDER_GEN;
  main.dataset.lgGen = String(myGen);
  // Subtítulo en el header del panel: nombre + #ID
  const subtitle = document.getElementById('lg-detail-subtitle');
  if (subtitle) subtitle.textContent = `${b.GuestName || 'Sin nombre'} · #${b.Id}`;
  // Si el booking es "sintético" (originado en Reservaciones), ya trae la
  // referencia a la fila como __reservacion → match directo. Para el Detalle
  // fusionado, si la fila tiene Lodgify Id, también traemos el booking real
  // (b.__lodgify) y lo usamos para Línea de cobro, etc.
  let huesped = b.__reservacion || LG_STATE.matches?.get(String(b.Id)) || null;
  const phoneHuesped = huesped ? null : lgFindHuespedRepresentativeByPhone(b);
  const effectiveHuesped = huesped || phoneHuesped;
  // Paso 1: shell rápido.
  try {
    main.innerHTML = lgBuildDetailShellHtml(b, huHasManualRegistration(effectiveHuesped));
    main.dataset.lgGen = String(myGen); // tras setear innerHTML re-aplicamos el gen
  } catch (err) {
    console.error('[LG] detail shell error:', err);
    main.innerHTML = `<div style="padding:20px;color:#dc2626">Error: ${esc(err.message||err)}</div>`;
    return;
  }
  if (!effectiveHuesped) return; // ya tiene los placeholders + col 3 con Lodgify

  // Helper: verifica si este render sigue siendo el activo. Si el usuario
  // ya cambió a otro card, abortamos cualquier escritura al DOM.
  const isStaleGen = () => Number(main.dataset.lgGen) !== myGen;

  // Paso 2: inyecta el bloque 3-col con datos completos del huésped
  requestAnimationFrame(() => {
    if (isStaleGen()) return;
    const slot = document.getElementById('lg-huesped-slot');
    if (!slot) return;
    try {
      const bookingArg = huesped ? b : null;
      slot.innerHTML = lgBuildHuespedSectionHtml(effectiveHuesped, bookingArg, !huesped ? b : null);
    }
    catch (err) {
      console.error('[LG] detail huesped section error:', err);
      slot.innerHTML = `<div style="padding:12px;color:#dc2626;font-size:12px">Error al cargar datos del huésped.</div>`;
    }
  });
  // Paso 3: enrich UNA SOLA VEZ por record. Re-renderiza TODO el main panel
  // (header + slot) — así el HEADER recibe las URLs de fotos INE/vehículo
  // que vienen en /huespedes-detail. Gateado por token.
  if (!effectiveHuesped['__huEnriched']) {
    const recId = String(effectiveHuesped['ID'] || effectiveHuesped['row_number'] || '');
    if (recId) {
      fetch(`${BACKEND}/huespedes-detail?record_id=${encodeURIComponent(recId)}`)
        .then(r => r.json())
        .then(j => {
          if (!j?.ok || !j.record) return;
          const merged = { ...effectiveHuesped, ...j.record, __huEnriched: true };
          const idx = (HU_STATE.rows || []).findIndex(x => String(x['ID']||x['row_number']||'') === recId);
          if (idx >= 0) HU_STATE.rows[idx] = merged;
          LG_STATE.__syntheticCache = null;
          LG_STATE.__syntheticCacheKey = null;
          if (isStaleGen()) return;
          // Re-render del MAIN COMPLETO → el header (perfil con fotos) Y el
          // slot (3 columnas) reciben los datos enriquecidos.
          try {
            let finalB = b;
            if (b.__reservacion && typeof huRowToSyntheticBooking === 'function') {
              const reb = huRowToSyntheticBooking(merged);
              if (reb) {
                finalB = reb;
                finalB.__reservacion = merged;
              }
            }
            main.innerHTML = lgBuildDetailShellHtml(finalB, huHasManualRegistration(merged));
            main.dataset.lgGen = String(myGen);
            requestAnimationFrame(() => {
              if (isStaleGen()) return;
              const slot = document.getElementById('lg-huesped-slot');
              if (!slot) return;
              try {
                const bookingArg = huesped ? finalB : null;
                slot.innerHTML = lgBuildHuespedSectionHtml(merged, bookingArg, !huesped ? finalB : null);
              } catch (err) { console.error('[LG] enrich slot re-render error:', err); }
            });
          } catch (err) { console.error('[LG] enrich shell re-render error:', err); }
        })
        .catch(e => console.warn('[LG] detail enrich fail:', e.message));
    }
  }
}

/** Construye las 4 columnas: Salida hoy · Activa · Entrada hoy · Próxima.
 *  (Concluida queda fuera del kanban porque no requiere acción.) */
function lgBuildKanban(list) {
  const groups = { salida_hoy: [], activa: [], entrada_hoy: [], proxima: [], concluida: [] };
  const sinFecha = [];
  list.forEach(b => {
    const state = lgGetStayState(b.DateArrival, b.DateDeparture);
    if (!state) { sinFecha.push(b); return; }
    if (groups[state]) groups[state].push(b);
  });
  const col = (title, icon, accent, bookings) => `
    <div style="flex:1;min-width:220px;background:#fff;border-radius:11px;border:1.5px solid ${accent.border};box-shadow:0 2px 8px rgba(15,23,42,.06);overflow:hidden;display:flex;flex-direction:column">
      <div style="padding:8px 10px;background:${accent.bg};border-bottom:1.5px solid ${accent.border};display:flex;align-items:center;justify-content:space-between;gap:8px">
        <div style="display:flex;align-items:center;gap:5px;font-weight:800;color:${accent.fg};font-size:11px;letter-spacing:.02em">
          <span style="font-size:13px">${icon}</span>${esc(title)}
        </div>
        <span style="display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:18px;padding:0 6px;border-radius:9px;background:#fff;color:${accent.fg};font-weight:800;font-size:10px;border:1px solid ${accent.border}">${bookings.length}</span>
      </div>
      <div style="padding:6px;background:#f8fafc;flex:1;display:block;max-height:78vh;overflow-y:auto">
        ${bookings.length ? bookings.map(b => `<div style="margin-bottom:5px">${lgBuildCard(b)}</div>`).join('') : `<div style="padding:14px 10px;text-align:center;color:#94a3b8;font-size:11px;font-style:italic">Sin reservaciones</div>`}
      </div>
    </div>`;
  // Pie informativo: la vista de 4 columnas NO muestra las "Concluidas"
  // ni las reservaciones sin fechas válidas, pero el KPI total sí las
  // cuenta. Aquí informamos al usuario para que el delta se entienda.
  const ocultas = groups.concluida.length + sinFecha.length;
  const footer = ocultas > 0 ? `
    <div style="margin-top:12px;padding:10px 14px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;font-size:11px;color:#64748b;display:flex;flex-wrap:wrap;gap:14px;align-items:center;justify-content:space-between">
      <div>
        ℹ️ <b>${ocultas}</b> reservación${ocultas===1?'':'es'} no se muestran en las 4 columnas:
        ${groups.concluida.length ? `<span style="display:inline-flex;align-items:center;gap:3px;padding:1px 8px;border-radius:999px;background:#f1f5f9;color:#475569;font-weight:700;font-size:10px;margin-left:4px">⚪ ${groups.concluida.length} concluida${groups.concluida.length===1?'':'s'}</span>` : ''}
        ${sinFecha.length ? `<span style="display:inline-flex;align-items:center;gap:3px;padding:1px 8px;border-radius:999px;background:#fef2f2;color:#991b1b;font-weight:700;font-size:10px;margin-left:4px">⚠ ${sinFecha.length} sin fecha</span>` : ''}
      </div>
      <span style="color:#94a3b8;font-style:italic">Cambia a vista 📋 Lista o usa el filtro Programación para verlas.</span>
    </div>` : '';
  return `
    <div style="display:flex;flex-wrap:wrap;gap:8px;align-items:stretch">
      ${col(LG_STATE_META.salida_hoy.label,  LG_STATE_META.salida_hoy.emoji,  { bg:LG_STATE_META.salida_hoy.bg,  border:LG_STATE_META.salida_hoy.border,  fg:LG_STATE_META.salida_hoy.accentFg  }, groups.salida_hoy)}
      ${col(LG_STATE_META.activa.label,      LG_STATE_META.activa.emoji,      { bg:LG_STATE_META.activa.bg,      border:LG_STATE_META.activa.border,      fg:LG_STATE_META.activa.accentFg      }, groups.activa)}
      ${col(LG_STATE_META.entrada_hoy.label, LG_STATE_META.entrada_hoy.emoji, { bg:LG_STATE_META.entrada_hoy.bg, border:LG_STATE_META.entrada_hoy.border, fg:LG_STATE_META.entrada_hoy.accentFg }, groups.entrada_hoy)}
      ${col(LG_STATE_META.proxima.label,     LG_STATE_META.proxima.emoji,     { bg:LG_STATE_META.proxima.bg,     border:LG_STATE_META.proxima.border,     fg:LG_STATE_META.proxima.accentFg     }, groups.proxima)}
    </div>
    ${footer}`;
}

/** Borra todos los filtros y vuelve al estado por defecto. */
/** Refresca AMBOS caches (Lodgify + Reservaciones) y recalcula matches.
 *  Útil cuando agregas/editas filas manualmente en el sheet sin reabrir la
 *  app. (Antes el botón Refrescar solo recargaba Lodgify, dejando
 *  HU_STATE.rows con datos viejos del Reservaciones.) */
window.lgRefreshAll = async function() {
  try {
    await Promise.all([
      lodgifyLoad(true),
      huespedesLoad(true),
    ]);
    if (LG_STATE.loaded && HU_STATE.loaded) {
      lgComputeMatches();
      lodgifyRenderForce();
    }
  } catch (e) {
    console.warn('[LG] refresh-all error:', e?.message || e);
  }
};

window.lgClearFilters = function() {
  // Multi-select: todo seleccionado = sin filtro (excepto meses, que mantiene
  // el mes en curso para no traer históricos infinitos)
  ['programacion','source','status','propiedad','factura','calificacion','incidencias','objetos'].forEach(id => {
    LG_STATE.multiSel[id] = new Set(LG_FILTER_OPTIONS[id] || []);
  });
  const now = new Date();
  const defMes = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  LG_STATE.multiSel['meses'] = (LG_FILTER_OPTIONS.meses || []).includes(defMes) ? new Set([defMes]) : new Set();
  // Inputs
  const nb = document.getElementById('lg-filtro-nombre'); if (nb) nb.value = '';
  LG_STATE.sortKey = '';
  LG_STATE.sortDir = '';
  lgRebuildFilterOptions();
  lodgifyRenderForce();
};

// ─── Rango de fechas (dos inputs date) ─────────────────────────────────────
// Default = día 1 → último día del mes en curso. Filtro de "toca el rango"
// se aplica en lgGetFiltered (intersección de estancia con [inicio, fin]).

const LG_DATE_PICKER = { built: false };

function lgDateSliderResetToCurrentMonth() {
  const now = new Date();
  const y = now.getFullYear(), mo = now.getMonth();
  const first = new Date(y, mo, 1);
  const last  = new Date(y, mo+1, 0);
  const fmt = (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
  const hidIni = document.getElementById('lg-filtro-fecha-inicio');
  const hidFin = document.getElementById('lg-filtro-fecha-fin');
  if (hidIni) hidIni.value = fmt(first);
  if (hidFin) hidFin.value = fmt(last);
}

function lgDateSliderBuild() {
  if (LG_DATE_PICKER.built) return;
  LG_DATE_PICKER.built = true;
  lgDateSliderResetToCurrentMonth();
}

/** Cambia el modo de vista (lista / kanban / table / detail) y re-renderiza. */
window.lgSetViewMode = function(mode) {
  LG_STATE.viewMode = mode;
  const btnList = document.getElementById('lg-view-list');
  const btnKb   = document.getElementById('lg-view-kanban');
  const btnTb   = document.getElementById('lg-view-table');
  const btnDt   = document.getElementById('lg-view-detail');
  const btnCd   = document.getElementById('lg-view-cards');
  const active   = 'background:#0d9488;color:#fff;border-color:#0d9488';
  const inactive = 'background:#fff;color:#475569;border-color:#cbd5e1';
  const style = (act) => `padding:6px 12px;border:1.5px solid;border-radius:6px;font-weight:700;font-size:12px;cursor:pointer;${act ? active : inactive}`;
  if (btnList) btnList.setAttribute('style', style(mode==='list'));
  if (btnKb)   btnKb.setAttribute('style',   style(mode==='kanban'));
  if (btnTb)   btnTb.setAttribute('style',   style(mode==='table'));
  if (btnDt)   btnDt.setAttribute('style',   style(mode==='detail'));
  if (btnCd)   btnCd.setAttribute('style',   style(mode==='cards'));
  lodgifyRenderForce();
};

/** Cambia la columna de orden de la tabla. Si ya está en ese key,
 *  alterna asc → desc → off. */
window.lgSetSort = function(key) {
  if (LG_STATE.sortKey === key) {
    if (LG_STATE.sortDir === 'asc') LG_STATE.sortDir = 'desc';
    else if (LG_STATE.sortDir === 'desc') { LG_STATE.sortKey = ''; LG_STATE.sortDir = ''; }
    else LG_STATE.sortDir = 'asc';
  } else {
    LG_STATE.sortKey = key;
    LG_STATE.sortDir = 'asc';
  }
  lodgifyRenderForce();
};

/** Vista en tabla. Aplica a TODOS los registros filtrados (no solo a
 *  los visibles), respetando el orden establecido con lgSetSort. */
function lgBuildTable(list) {
  // Helper: obtiene un valor del row de huéspedes (match) si existe.
  const huV = (b, cands) => {
    const h = LG_STATE.matches?.get(String(b.Id));
    if (!h) return '';
    return huValueFlexible(h, Array.isArray(cands) ? cands : [cands]);
  };
  // Formato fecha YYYY-MM-DD o ISO → "8 de junio"
  const fmtFechaIso = (raw) => {
    if (!raw) return '—';
    const s = String(raw).trim();
    const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
    const iso = m ? `${m[1]}-${m[2]}-${m[3]}` : s;
    return (typeof huFmtFecha === 'function') ? huFmtFecha(iso) : esc(iso);
  };
  const fmtHora = (raw) => {
    if (!raw) return '—';
    const s = String(raw).trim();
    const m = s.match(/T(\d{2}):(\d{2})/);
    if (m) return `${m[1]}:${m[2]}`;
    return (typeof huFmtHoraSimple === 'function') ? huFmtHoraSimple(s) : esc(s);
  };
  const fmtMonto = (v) => {
    if (v == null || String(v).trim() === '') return '—';
    return (typeof huFmtMonto === 'function') ? huFmtMonto(v) : esc(v);
  };

  // Columnas: primero los campos clave de Lodgify, luego los campos
  // importados de "Información de huéspedes" cuando hay match.
  const cols = [
    // ─── Datos primarios (Lodgify) ───
    { key:'Programacion',   label:'Programación', formatter: (b) => {
        const s = lgGetStayState(b.DateArrival, b.DateDeparture);
        const m = LG_STATE_META[s];
        if (!m) return '<span style="color:#94a3b8">—</span>';
        return `<span style="display:inline-block;padding:3px 9px;border-radius:999px;background:${m.bg};color:${m.accentFg};font-weight:700;font-size:11px;border:1px solid ${m.border}">${m.emoji} ${esc(m.label)}</span>`;
      }},
    { key:'Registrado',     label:'Registrado', formatter: (b) => LG_STATE.matches?.has(String(b.Id))
        ? `<span style="display:inline-block;padding:2px 8px;border-radius:999px;background:linear-gradient(135deg,#475569,#334155);color:#fff;font-weight:800;font-size:10px;border:1px solid #1e293b;letter-spacing:.04em">📋</span>`
        : '<span style="color:#cbd5e1">—</span>' },
    { key:'Propiedad',      label:'Propiedad', formatter: (b) => esc(lgPropOf(b)) },
    { key:'GuestName',      label:'Nombre del huésped', formatter: (b) => esc(b.GuestName||'—') },
    { key:'DateArrival',    label:'Fecha de entrada', formatter: (b) => esc(b.DateArrival||'—') },
    { key:'DateDeparture',  label:'Fecha de salida', formatter: (b) => esc(b.DateDeparture||'—') },
    { key:'Nights',         label:'# Noches', formatter: (b) => `<b>${Number(b.Nights)||0}</b>` },
    { key:'Source',         label:'Fuente', formatter: (b) => esc(b.Source||'—') },
    { key:'Status',         label:'Estado', formatter: (b) => esc(b.Status||'—') },
    { key:'NumberOfGuests', label:'# Huéspedes', formatter: (b) => String(b.NumberOfGuests||0) },
    { key:'Adults',         label:'Adultos', formatter: (b) => String(b.Adults||0) },
    { key:'Children',       label:'Niños', formatter: (b) => String(b.Children||0) },
    { key:'GuestEmail',     label:'Correo', formatter: (b) => b.GuestEmail ? `<a href="mailto:${esc(b.GuestEmail)}" style="color:#0d9488">${esc(b.GuestEmail)}</a>` : '—' },
    { key:'GuestPhone',     label:'Teléfono', formatter: (b) => b.GuestPhone ? `<a href="https://wa.me/${esc(String(b.GuestPhone).replace(/\D/g,''))}" target="_blank" rel="noopener" style="color:#0d9488">${esc(b.GuestPhone)}</a>` : '—' },
    { key:'Currency',       label:'Moneda', formatter: (b) => esc(b.Currency||'MXN') },
    { key:'Gross',          label:'Gross', formatter: (b) => Number(b.Gross)>0 ? lgFmtMoney(b.Gross, b.Currency) : '—' },
    { key:'Net',            label:'Net', formatter: (b) => Number(b.Net)>0 ? lgFmtMoney(b.Net, b.Currency) : '—' },
    { key:'Vat',            label:'VAT', formatter: (b) => Number(b.Vat)>0 ? lgFmtMoney(b.Vat, b.Currency) : '—' },

    // ─── Campos importados de "Información de huéspedes" (solo si hay match) ───
    { key:'hu_HoraLlegada', label:'Llegada estimada', huesped:true, formatter: (b) => {
        const v = huV(b, ['Hora estimada de llegada','Hora de llegada']);
        return v ? esc(fmtHora(v)) : '<span style="color:#cbd5e1">—</span>';
      }},
    { key:'hu_HoraSalida',  label:'Salida estimada', huesped:true, formatter: (b) => {
        const v = huV(b, ['Hora estimada de salida','Hora de salida']);
        return v ? esc(fmtHora(v)) : '<span style="color:#cbd5e1">—</span>';
      }},
    { key:'hu_FormaPago',   label:'Forma de pago', huesped:true, formatter: (b) => esc(huV(b, ['Forma de pago']) || '—') },
    { key:'hu_MontoFact',   label:'Monto facturado', huesped:true, formatter: (b) => {
        const v = huV(b, ['$ Monto facturado Total','Monto facturado Total']);
        return v ? esc(fmtMonto(v)) : '<span style="color:#cbd5e1">—</span>';
      }},
    { key:'hu_StatusFact',  label:'Factura', huesped:true, formatter: (b) => {
        const h = LG_STATE.matches?.get(String(b.Id));
        if (!h) return '<span style="color:#cbd5e1">—</span>';
        const status = (typeof huGetFacturaStatus === 'function') ? huGetFacturaStatus(h) : '';
        const folio = huValueFlexible(h, ['Folio facturapi','Folio']);
        if (status === 'emitida') return `<span style="display:inline-block;padding:2px 8px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:10px;border:1px solid #86efac">🧾 Emitida${folio?' #'+esc(folio):''}</span>`;
        if (status === 'pendiente') return `<span style="display:inline-block;padding:2px 8px;border-radius:999px;background:#fff7ed;color:#c2410c;font-weight:700;font-size:10px;border:1px solid #fdba74">🧾 Pendiente</span>`;
        return '<span style="color:#cbd5e1">—</span>';
      }},
    { key:'hu_Folio',       label:'Folio facturapi', huesped:true, formatter: (b) => {
        const v = huV(b, ['Folio facturapi','Folio Facturapi','Folio']);
        return v ? `<code style="font-size:11px;background:#f1f5f9;padding:1px 6px;border-radius:4px">${esc(v)}</code>` : '<span style="color:#cbd5e1">—</span>';
      }},
    { key:'hu_ReqFactura',  label:'¿Req. factura?', huesped:true, formatter: (b) => {
        const v = huV(b, ['¿Requiere factura?']);
        if (!v) return '<span style="color:#cbd5e1">—</span>';
        const yes = /s[ií]/i.test(v);
        return `<span style="font-weight:700;color:${yes?'#166534':'#475569'}">${esc(v)}</span>`;
      }},
    { key:'hu_Razon',       label:'Razón social', huesped:true, formatter: (b) => esc(huV(b, ['Razón social']) || '—') },
    { key:'hu_RFC',         label:'RFC', huesped:true, formatter: (b) => {
        const v = huV(b, ['RFC']);
        return v ? `<code style="font-size:11px;background:#f1f5f9;padding:1px 6px;border-radius:4px">${esc(v)}</code>` : '<span style="color:#cbd5e1">—</span>';
      }},
    { key:'hu_Regimen',     label:'Régimen fiscal', huesped:true, formatter: (b) => esc(huV(b, ['Régimen fiscal']) || '—') },
    { key:'hu_CP',          label:'Código Postal', huesped:true, formatter: (b) => esc(huV(b, ['Código Postal']) || '—') },
    { key:'hu_Motivo',      label:'Motivo', huesped:true, formatter: (b) => esc(huV(b, ['Motivo de tu hospedaje','Motivo']) || '—') },
    { key:'hu_CelEmer',     label:'Cel emergencia', huesped:true, formatter: (b) => esc(huV(b, ['Cel/Whatsapp (contacto de emergencia)']) || '—') },
    { key:'hu_Comentarios', label:'Comentarios', huesped:true, formatter: (b) => {
        const v = huV(b, ['Notas','Comentarios','Envía tus comentarios']);
        return v ? `<span title="${esc(v)}">${esc(v.length>40?v.slice(0,40)+'…':v)}</span>` : '<span style="color:#cbd5e1">—</span>';
      }},

    // ─── Campos secundarios de Lodgify ───
    { key:'ConfirmationCode', label:'Confirmation', formatter: (b) => b.ConfirmationCode ? `<code style="font-size:11px;background:#f1f5f9;padding:1px 6px;border-radius:4px">${esc(b.ConfirmationCode)}</code>` : '—' },
    { key:'DateCancelled',  label:'Cancelada', formatter: (b) => esc(b.DateCancelled||'—') },
    { key:'RoomTypeNames',  label:'Habitación', formatter: (b) => esc(b.RoomTypeNames||'—') },
    { key:'ChannelBooking', label:'Channel ID', formatter: (b) => esc(b.ChannelBooking||'—') },
    { key:'Id',             label:'Booking ID', formatter: (b) => `<code style="font-size:11px;background:#f1f5f9;padding:1px 6px;border-radius:4px">${esc(b.Id)}</code>` },
  ];

  const sortIcon = (key) => {
    if (LG_STATE.sortKey !== key) return '<span style="opacity:.3;font-size:10px">↕</span>';
    return LG_STATE.sortDir === 'asc' ? '<span style="color:#0d9488;font-size:11px">▲</span>' : '<span style="color:#0d9488;font-size:11px">▼</span>';
  };

  const head = cols.map(c => {
    const isHu = !!c.huesped;
    const bg   = isHu ? '#f8fafc' : '#ffffff';
    const fg   = isHu ? '#475569' : '#64748b';
    const icon = isHu ? '<span style="font-size:9px;margin-right:3px" title="Importado de Información de huéspedes">📋</span>' : '';
    return `
      <th onclick="lgSetSort('${c.key}')"
          style="cursor:pointer;user-select:none;padding:10px 12px;background:${bg};border-bottom:1px solid #e5e7eb;border-right:1px solid #f1f5f9;font-size:10px;text-transform:uppercase;letter-spacing:.04em;color:${fg};font-weight:800;text-align:left;white-space:nowrap;position:sticky;top:0;z-index:2"
          title="Click para ordenar por ${esc(c.label)}${isHu?' (importado de Información de huéspedes)':''}">
        <span style="display:inline-flex;align-items:center;gap:5px">${icon}${esc(c.label)} ${sortIcon(c.key)}</span>
      </th>`;
  }).join('');

  // Filas con fondo blanco. Líneas grises claras horizontales y verticales.
  // Hover: aplica una clase CSS que oscurece ligeramente toda la fila.
  const rows = list.map((b) => {
    const tds = cols.map(c => {
      const isHu = !!c.huesped;
      // Solo los headers de columnas-huésped tienen fondo gris claro; las
      // celdas de datos siempre van en blanco.
      return `<td style="padding:9px 12px;border-bottom:1px solid #f1f5f9;border-right:1px solid #f1f5f9;background:#fff;font-size:12.5px;color:#1f2937;white-space:nowrap;max-width:280px;overflow:hidden;text-overflow:ellipsis">${c.formatter(b)}</td>`;
    }).join('');
    return `<tr class="lg-tbl-row">${tds}</tr>`;
  }).join('');

  return `
    <div style="background:#fff;border-radius:12px;border:1px solid #e5e7eb;box-shadow:0 1px 3px rgba(15,23,42,.04);overflow:auto;max-height:78vh">
      <table style="width:100%;border-collapse:collapse;font-family:inherit;background:#fff">
        <thead><tr>${head}</tr></thead>
        <tbody>${rows || `<tr><td colspan="${cols.length}" style="padding:30px;text-align:center;color:#94a3b8;font-style:italic;background:#fff">Sin registros</td></tr>`}</tbody>
      </table>
    </div>`;
}


/** Card de una reservación de Lodgify — diseño idéntico al de huéspedes.
 *  Wrapper clickeable que abre el modal. El contenido del header (mismo que
 *  el header del panel "Detalles") se construye con lgBuildCardSummary. */
function lgBuildCard(b) {
  const stayState = lgGetStayState(b.DateArrival, b.DateDeparture);
  const meta = LG_STATE_META[stayState] || LG_STATE_META.concluida;
  const bookingId = String(b.Id || '');
  return `
    <div class="lg-card hu-record" data-lg-id="${esc(b.Id)}"
         onclick="lgOpenDetailModal('${esc(b.Id)}')"
         style="position:relative;border:1.5px solid ${meta.border};border-radius:10px;background:#fff;overflow:hidden;box-shadow:0 1px 3px rgba(15,23,42,.04);transition:transform 120ms ease-out, box-shadow 120ms ease-out"
         onmouseover="this.style.transform='translateY(-1px)';this.style.boxShadow='0 4px 12px rgba(15,23,42,.10)'"
         onmouseout="this.style.transform='';this.style.boxShadow='0 1px 3px rgba(15,23,42,.04)'">
      <button onclick="event.stopPropagation();lgHideBooking('${esc(bookingId)}')"
              title="Ocultar esta reserva del frontend"
              style="position:absolute;top:6px;left:6px;z-index:5;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;border:1px solid #fecaca;background:#fff;color:#dc2626;font-size:13px;font-weight:900;line-height:1;cursor:pointer;box-shadow:0 1px 3px rgba(15,23,42,.08)">×</button>
      ${lgBuildCardSummary(b)}
    </div>`;
}

/** Unifica dos filas de Reservaciones del mismo grupo (probable match):
 *  copia campos faltantes del registro manual desde el registro loser
 *  (propagado por Lodgify), y oculta el loser del frontend. */
async function lgUnifyReservaciones(winnerId, loserId) {
  if (!winnerId || !loserId) return;
  if (winnerId === loserId) { alert('IDs iguales, no se puede unificar.'); return; }
  if (!confirm('¿Unificar estas reservaciones?\n\nSe llenarán los datos faltantes del registro manual con los datos del registro de Lodgify. La reserva de Lodgify quedará oculta.')) return;
  const rows = HU_STATE.rows || [];
  const winner = rows.find(r => String(r['ID']||r['row_number']||'') === String(winnerId));
  const loser  = rows.find(r => String(r['ID']||r['row_number']||'') === String(loserId));
  if (!winner || !loser) { alert('No se encontraron las filas en memoria.'); return; }
  // Calcular campos faltantes: para cada header presente en loser, si el
  // winner está vacío y el loser tiene valor, lo copiamos.
  const fields = {};
  // El "Lodgify Id" SÍ se transfiere — es la llave que el frontend usa para
  // jalar Cobros (de Reservas_Lodgify) y Aseo (de Breezeway tasks) hacia
  // la card del winner. Sin él, esos bloques quedan vacíos.
  const skip = new Set(['ID','row_number','__row_number','Marca temporal']);
  const isBlank = (v) => v == null || String(v).trim() === '';
  Object.keys(loser).forEach(k => {
    if (skip.has(k)) return;
    if (!isBlank(loser[k]) && isBlank(winner[k])) {
      fields[k] = loser[k];
    }
  });
  try {
    const resp = await fetch(`${BACKEND}/lg-unify-records`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        winner_id: winnerId,
        loser_id: loserId,
        fields,
        hidden_by: (typeof currentUser !== 'undefined' ? currentUser : ''),
      }),
    });
    const j = await resp.json();
    if (!j.ok) throw new Error(j.error || 'unify_failed');
    // Actualizar winner localmente y eliminar loser
    Object.keys(fields).forEach(k => { winner[k] = fields[k]; });
    HU_STATE.rows = rows.filter(r => String(r['ID']||r['row_number']||'') !== String(loserId));
    // Invalidar caches y re-render
    LG_STATE.__syntheticCache = null;
    LG_STATE.__syntheticCacheKey = null;
    LG_STATE.__huIdxPhoneDates = null;
    LG_STATE.__huIdxPropDates  = null;
    LG_STATE.__huIdxRowsCount  = null;
    if (typeof lgComputeMatches === 'function') lgComputeMatches();
    window.LG_USER_INTERACTED = false;
    if (typeof lodgifyRender === 'function') lodgifyRender({ force: true });
  } catch (e) {
    alert('Error al unificar: ' + (e.message || e));
  }
}

/** Oculta UNA reserva del frontend.
 *  - lodgifyId: si se pasa, oculta el booking de Reservas_Lodgify.
 *  - reservacionId: si se pasa, oculta la fila de Reservaciones.
 *  Pueden venir ambos (cuando la card está respaldada por ambos) o solo uno.
 *  La acción es por reserva, no por huésped: el resto de las reservaciones
 *  del mismo huésped no se tocan. */
async function lgHideCard(lodgifyId, reservacionId) {
  const lod = String(lodgifyId || '').trim();
  const rsv = String(reservacionId || '').trim();
  if (!lod && !rsv) { alert('No hay IDs para ocultar.'); return; }
  if (!confirm('¿Deseas eliminar esta reserva?')) return;
  const tasks = [];
  if (lod) {
    tasks.push(fetch(`${BACKEND}/lg-hide-booking`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: lod, hidden_by: (typeof currentUser !== 'undefined' ? currentUser : '') }),
    }).then(r=>r.json()));
  }
  if (rsv) {
    tasks.push(fetch(`${BACKEND}/lg-hide-reservacion`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: rsv, hidden_by: (typeof currentUser !== 'undefined' ? currentUser : '') }),
    }).then(r=>r.json()));
  }
  // Memorizar la identidad del huésped seleccionado en el sidebar ANTES del
  // re-render. Usamos teléfono (últimos 10 dígitos) + propiedad+fechas — más
  // robusto que el ID, porque tras un dedupe puede sobrevivir una fila
  // distinta del mismo huésped.
  const prevSelId = String(LG_STATE.detailSelectedId || '');
  let prevTail = '', prevPropKey = '', prevArr = '', prevDep = '';
  if (prevSelId) {
    const prevRow = (HU_STATE.rows || []).find(r => String(r['ID']||r['row_number']||'') === prevSelId);
    if (prevRow) {
      const cel = huValueFlexible(prevRow, ['Cel/Whatsapp (principal)','Celular principal']);
      const s = String(cel || '').replace(/\D/g,''); prevTail = s.length >= 10 ? s.slice(-10) : '';
      prevPropKey = lgPropDeptKey(prevRow['Propiedad'], prevRow['# Departamento']);
      prevArr = String(prevRow['Fecha de ingreso']||'').slice(0,10);
      prevDep = String(prevRow['Fecha de salida']||'').slice(0,10);
    }
  }
  try {
    const results = await Promise.all(tasks);
    const failed = results.find(j => !j || j.ok === false);
    if (failed) throw new Error(failed.error || 'hide_failed');
    // Limpiar caches locales
    if (lod && Array.isArray(LG_STATE.bookings)) {
      LG_STATE.bookings = LG_STATE.bookings.filter(bk => String(bk.Id) !== lod);
    }
    if (rsv && Array.isArray(HU_STATE.rows)) {
      HU_STATE.rows = HU_STATE.rows.filter(r => String(r['ID']||r['row_number']||'') !== rsv);
    }
    LG_STATE.__syntheticCache = null;
    LG_STATE.__syntheticCacheKey = null;
    LG_STATE.__huIdxPhoneDates = null;
    LG_STATE.__huIdxPropDates  = null;
    LG_STATE.__huIdxRowsCount  = null;
    window.__huGuestIndex = null;
    window.__huGuestStatsCache = null;
    if (typeof lgComputeMatches === 'function') lgComputeMatches();
    // Re-seleccionar el huésped previo: buscar en HU_STATE.rows una fila que
    // matchee por (1) mismo ID, (2) mismo teléfono, o (3) misma prop+fechas.
    // Asignar antes del render para que lgBuildDetailView lo respete.
    if (prevSelId) {
      const rows = HU_STATE.rows || [];
      let cand = rows.find(r => String(r['ID']||r['row_number']||'') === prevSelId);
      if (!cand && prevTail) {
        cand = rows.find(r => {
          const s = String(huValueFlexible(r, ['Cel/Whatsapp (principal)','Celular principal']) || '').replace(/\D/g,'');
          return s.length >= 10 && s.slice(-10) === prevTail;
        });
      }
      if (!cand && prevPropKey && prevArr && prevDep) {
        cand = rows.find(r => {
          const pk = lgPropDeptKey(r['Propiedad'], r['# Departamento']);
          return pk === prevPropKey
              && String(r['Fecha de ingreso']||'').slice(0,10) === prevArr
              && String(r['Fecha de salida']||'').slice(0,10) === prevDep;
        });
      }
      if (cand) LG_STATE.detailSelectedId = String(cand['ID']||cand['row_number']||'');
    }
    window.LG_USER_INTERACTED = false;
    if (typeof lodgifyRender === 'function') lodgifyRender({ force: true });
  } catch (e) {
    alert('Error al ocultar la reserva: ' + (e.message || e));
  }
}

// Compat: el viejo callsite del list mode pasaba solo el bookingId Lodgify.
async function lgHideBooking(id) { return lgHideCard(id, ''); }

/** Construye SOLO el contenido del header de una card de reservación
 *  (sin el wrapper clickeable). Reusable en el panel de la vista Detalles. */
/** Versión COMPACTA-HORIZONTAL del perfil del huésped para vivir en el
 *  header de "Detalles de la Reserva" (arriba, antes de la barra de KPIs).
 *  4 bloques en grid: Identificación · Contacto · Datos fiscales · Vehículo.
 *  Solo dibuja los bloques que tengan datos. */
function lgBuildProfileHeaderHtml(r, palette) {
  if (!r) return '';
  const recId    = String(r['ID'] || r['row_number'] || '');
  const nombreP  = huValueFlexible(r, ['Nombre del huésped','Nombre de la persona que hizo la reservación']);
  const tipoId   = huValueFlexible(r, ['Tipo de identificación']);
  const ineFront = huValueFlexible(r, ['Link INE frontal','INE frontal','Link foto INE frontal']);
  const ineBack  = huValueFlexible(r, ['Link INE trasero','INE trasero','Link foto INE trasero']);
  const idUnica  = huValueFlexible(r, ['Link identificación única','Identificación única']);
  const cel      = huValueFlexible(r, ['Cel/Whatsapp (principal)']);
  const celEmer  = huValueFlexible(r, ['Cel/Whatsapp (contacto de emergencia)']);
  const correoP  = huValueFlexible(r, ['Correo electrónico para el envío de la factura','Correo electrónico']);
  const razon    = huValueFlexible(r, ['Razón social']);
  const rfc      = huValueFlexible(r, ['RFC']);
  const regimen  = huValueFlexible(r, ['Régimen fiscal']);
  const cp       = huValueFlexible(r, ['Código Postal']);
  const reqFact  = huValueFlexible(r, ['¿Requiere factura?']);
  const tieneVeh = huValueFlexible(r, ['¿Cuenta con vehículo?']);
  const marca    = huValueFlexible(r, ['Marca vehículo']);
  const marcaOtr = huValueFlexible(r, ['Marca vehículo otro']);
  const modelo   = huValueFlexible(r, ['Modelo vehículo']);
  const modeloOtr= huValueFlexible(r, ['Modelo vehículo otro']);
  const colorV   = huValueFlexible(r, ['Color vehículo']);
  const placas   = huValueFlexible(r, ['Placas']);
  const fotoVeh  = huValueFlexible(r, ['Link foto vehículo','Foto vehículo']);
  const marcaTxt = (marca && marca.toLowerCase() === 'otro') ? (marcaOtr || marca) : marca;
  const modeloTxt= (modelo && modelo.toLowerCase() === 'otro') ? (modeloOtr || modelo) : modelo;

  // Mini foto cuadrada (thumbnail pequeño + blur; click → zoom carga full)
  const photo = (url, label, icon) => {
    if (!url) return `
      <div style="height:80px;border:1px dashed #e2e8f0;border-radius:8px;background:#f8fafc;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#cbd5e1;font-size:9px;letter-spacing:.04em">
        <div style="font-size:18px;opacity:.5">${icon}</div>
        <div style="font-weight:700;text-transform:uppercase">${esc(label)}</div>
        <div style="font-size:8px;font-style:italic">No disponible</div>
      </div>`;
    let driveId = '';
    const sRaw = String(url).trim();
    let mm = sRaw.match(/\/file\/d\/([a-zA-Z0-9_-]+)/);  if (mm) driveId = mm[1];
    if (!driveId) { mm = sRaw.match(/\/d\/([a-zA-Z0-9_-]+)/);    if (mm) driveId = mm[1]; }
    if (!driveId) { mm = sRaw.match(/[?&]id=([a-zA-Z0-9_-]+)/);  if (mm) driveId = mm[1]; }
    // PRIMARY: lh3.googleusercontent (CDN, más confiable). FALLBACK: drive thumbnail.
    const thumb = driveId ? `https://lh3.googleusercontent.com/d/${driveId}=w160` : esc(url);
    const fb    = driveId ? `https://drive.google.com/thumbnail?id=${driveId}&sz=w160` : '';
    const full  = driveId ? `https://lh3.googleusercontent.com/d/${driveId}=w1600` : esc(url);
    const onerr = `(function(img){if(!img.dataset.t&&'${esc(fb)}'){img.dataset.t='1';img.src='${esc(fb)}';return;}img.style.display='none';img.nextElementSibling.style.display='flex';})(this)`;
    return `
      <div style="position:relative;height:80px;cursor:zoom-in;border-radius:8px;overflow:hidden;border:1.5px solid #e2e8f0;background:#f8fafc"
           onclick="event.stopPropagation();huImageZoom('${esc(full)}','${esc(label)}')">
        <img src="${esc(thumb)}" alt="${esc(label)}" loading="lazy" referrerpolicy="no-referrer"
             style="width:100%;height:100%;object-fit:cover;display:block;filter:blur(1.5px);transition:filter .2s ease"
             onmouseenter="this.style.filter='blur(0)'" onmouseleave="this.style.filter='blur(1.5px)'"
             onerror="${onerr}">
        <div style="display:none;position:absolute;inset:0;flex-direction:column;align-items:center;justify-content:center;color:#94a3b8;font-size:9px;background:#f8fafc">
          <div style="font-size:18px;opacity:.5">${icon}</div><div style="font-weight:700;text-transform:uppercase">${esc(label)}</div>
        </div>
        <div style="position:absolute;bottom:0;left:0;right:0;padding:2px 5px;background:linear-gradient(180deg,transparent,rgba(15,23,42,.7));color:#fff;font-size:8px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;pointer-events:none">${esc(label)} 🔍</div>
      </div>`;
  };

  // Bloque Identificación (fotos) — SOLO renderizamos las cajas que SÍ
  // tienen URL. Sin URLs, ni siquiera mostramos el bloque.
  const photoCells = [
    ineFront ? photo(ineFront, 'INE frontal', '🪪') : '',
    ineBack  ? photo(ineBack,  'INE trasero', '🪪') : '',
    idUnica  ? photo(idUnica,  'ID única',    '🆔') : '',
  ].filter(Boolean);
  const idBlock = photoCells.length ? `
    <div style="background:rgba(255,255,255,.85);border:1px solid ${palette.border};border-radius:10px;padding:8px 10px;min-width:0">
      <div style="font-size:8px;letter-spacing:.12em;color:#64748b;font-weight:800;margin-bottom:6px;text-transform:uppercase">📇 Identificación${tipoId ? ` · ${esc(tipoId)}`:''}</div>
      <div style="display:grid;grid-template-columns:repeat(${photoCells.length}, 1fr);gap:5px">
        ${photoCells.join('')}
      </div>
    </div>` : '';

  // Bloque Contacto
  const wa = cel ? `https://wa.me/${String(cel).replace(/\D/g,'')}` : '';
  const waEm = celEmer ? `https://wa.me/${String(celEmer).replace(/\D/g,'')}` : '';
  const tieneContacto = !!(cel || correoP || celEmer);
  const contactoBlock = tieneContacto ? `
    <div style="background:rgba(255,255,255,.85);border:1px solid ${palette.border};border-radius:10px;padding:8px 10px;min-width:0">
      <div style="font-size:8px;letter-spacing:.12em;color:#0f766e;font-weight:800;margin-bottom:6px;text-transform:uppercase">📞 Contacto</div>
      ${cel ? (function(){
        // Priorizar ID Lodgify — asegura misma llave que la card Lodgify (b.Id)
        // y que el modal (st.bookingId = waBookingId_(b) === b.Id). Sin esto,
        // el toggle Auto de la vista Huéspedes y el de la vista Lodgify se
        // referencian a IDs distintos y quedan desincronizados.
        const bookingId = String(r['ID Lodgify'] || r['ID'] || r['row_number'] || '').trim();
        const waPayload = {
          Id: bookingId,
          GuestName: huValueFlexible(r,["Nombre del huésped","Nombre de la persona que hizo la reservación","Nombre completo","Nombre reservación","Nombre"])||"",
          GuestPhone: cel,
          HouseId: huValueFlexible(r,["ID Lodgify","HouseId","Id Lodgify"])||"",
          PropertyName: huValueFlexible(r,["Propiedad"])||"",
          RoomTypeName: huValueFlexible(r,["# Departamento","Departamento"])||"",
          DateArrival: String(huValueFlexible(r,["Fecha de ingreso"])||"").slice(0,10),
          DateDeparture: String(huValueFlexible(r,["Fecha de salida"])||"").slice(0,10),
          hu_HoraLlegada: huValueFlexible(r,["Hora estimada de llegada","Hora de llegada"])||"",
          hu_HoraSalida: huValueFlexible(r,["Hora estimada de salida","Hora de salida"])||"",
        };
        const jsonSafe = JSON.stringify(waPayload).replace(/</g,"\\u003c").replace(/'/g,"&#39;");
        return `<div style="font-size:11px;color:#1f2937;margin-bottom:3px;display:flex;align-items:center;gap:6px;flex-wrap:wrap">
          <span style="font-size:10px">📱</span>
          <a href="${esc(wa)}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="color:#0d9488;font-weight:800;text-decoration:none">${esc(cel)}</a>
          <button type="button" title="Enviar plantilla/mensaje desde el sistema" onclick='event.stopPropagation(); waOpenModal(${jsonSafe})' style="padding:2px 8px;background:#25d366;color:#fff;border:0;border-radius:999px;font-size:10px;font-weight:800;cursor:pointer;letter-spacing:.02em">💬 Enviar</button>
          ${bookingId ? waAutoToggleHtml(bookingId) : ''}
        </div>`;
      })() : ''}
      ${correoP ? `<div style="font-size:10px;word-break:break-all;margin-bottom:3px"><a href="mailto:${esc(correoP)}" onclick="event.stopPropagation()" style="color:#0d9488;font-weight:700;text-decoration:none">📧 ${esc(correoP)}</a></div>` : ''}
      ${celEmer ? `<div style="font-size:10px;color:#7f1d1d;margin-top:4px;padding-top:4px;border-top:1px dashed #fecaca">🚨 <a href="${esc(waEm)}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="color:#b91c1c;font-weight:700;text-decoration:none">${esc(celEmer)}</a></div>` : ''}
    </div>` : '';

  // Bloque Datos fiscales
  const tieneFiscales = !!(razon || rfc || regimen || cp);
  const fiscalesBlock = tieneFiscales ? `
    <div style="background:rgba(255,255,255,.85);border:1px solid ${palette.border};border-radius:10px;padding:8px 10px;min-width:0">
      <div style="font-size:8px;letter-spacing:.12em;color:#1e40af;font-weight:800;margin-bottom:6px;text-transform:uppercase">🧾 Datos fiscales${huIsFacturaYes(reqFact)?' <span style="color:#15803d;background:#dcfce7;padding:0 5px;border-radius:999px;margin-left:3px;font-weight:700">Requiere</span>':''}</div>
      ${razon ? `<div style="font-size:11px;color:#0f172a;font-weight:700;margin-bottom:3px;word-break:break-word">${esc(razon)}</div>` : ''}
      ${rfc ? `<div style="font-size:10px;color:#1f2937;font-family:'SFMono-Regular',Consolas,monospace;letter-spacing:.04em;background:#dbeafe;padding:1px 5px;border-radius:3px;display:inline-block;margin-bottom:3px">RFC: <b>${esc(rfc)}</b></div>` : ''}
      ${regimen ? `<div style="font-size:9px;color:#475569;margin-top:2px">${esc(regimen)}</div>` : ''}
      ${cp ? `<div style="font-size:9px;color:#475569">📮 C.P. ${esc(cp)}</div>` : ''}
    </div>` : '';

  // Bloque Vehículo
  const tieneVehInfo = !!(huIsFacturaYes(tieneVeh) || marcaTxt || modeloTxt || colorV || placas || fotoVeh);
  const vehBlock = tieneVehInfo ? `
    <div style="background:rgba(255,255,255,.85);border:1px solid ${palette.border};border-radius:10px;padding:8px 10px;min-width:0">
      <div style="font-size:8px;letter-spacing:.12em;color:#6d28d9;font-weight:800;margin-bottom:6px;text-transform:uppercase">🚗 Vehículo</div>
      ${fotoVeh ? `<div style="margin-bottom:6px">${photo(fotoVeh, 'Vehículo', '🚗')}</div>` : ''}
      ${(marcaTxt||modeloTxt) ? `<div style="font-size:11px;color:#0f172a;font-weight:700;margin-bottom:3px">${esc(marcaTxt||'')} ${esc(modeloTxt||'')}</div>` : ''}
      <div style="display:flex;flex-wrap:wrap;gap:4px">
        ${colorV ? `<span style="font-size:9px;color:#475569;background:#f1f5f9;padding:1px 6px;border-radius:999px">🎨 ${esc(colorV)}</span>` : ''}
        ${placas ? `<span style="font-size:10px;color:#0f172a;font-family:'SFMono-Regular',Consolas,monospace;font-weight:800;background:#fef3c7;padding:2px 6px;border-radius:3px;border:1px solid #fcd34d;letter-spacing:.06em">${esc(placas)}</span>` : ''}
      </div>
    </div>` : '';

  if (!idBlock && !contactoBlock && !fiscalesBlock && !vehBlock) return '';
  return `
    <div style="margin-top:10px;display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px;align-items:start">
      ${idBlock}${contactoBlock}${fiscalesBlock}${vehBlock}
    </div>`;
}

function lgBuildCardSummary(b) {
  const nombre = b.GuestName || 'Sin nombre';
  const prop   = lgPropOf(b);
  const ingreso = lgFmtFecha(b.DateArrival);
  const salida  = lgFmtFecha(b.DateDeparture);
  const noches  = b.Nights || 0;
  const stayState = lgGetStayState(b.DateArrival, b.DateDeparture);
  const meta = LG_STATE_META[stayState] || LG_STATE_META.concluida;
  const palette = { border: meta.border, bg: meta.bg };

  const huespedesChip = b.NumberOfGuests
    ? `<span style="display:inline-flex;align-items:center;gap:3px;padding:2px 7px;border-radius:999px;background:#fff;color:#1f2937;font-weight:700;font-size:9px;border:1px solid #e2e8f0;letter-spacing:.02em">👥 ${b.NumberOfGuests}</span>`
    : '';

  // Chip "REGISTRADO" — solo si el huésped llenó EL FORMULARIO manual.
  // Una fila importada de Lodgify (sin datos del formulario) NO califica.
  const huespedMatch = lgGetHuespedForBooking(b);
  const matchBadge = huHasManualRegistration(huespedMatch)
    ? `<span title="Registro manual completado por el huésped" style="display:inline-flex;align-items:center;gap:3px;padding:3px 9px;border-radius:999px;background:linear-gradient(135deg,#475569,#334155);color:#fff;font-weight:800;font-size:9px;border:1px solid #1e293b;letter-spacing:.04em;box-shadow:0 1px 4px rgba(15,23,42,.35)">📋 REGISTRADO</span>`
    : '';
  const probableBadge = (lgGetMatchKind(b) === 'probable') ? lgProbableMatchChip() : '';

  // ─── Si hay match, calculamos los chips y KPIs del módulo huéspedes ───
  let kpisBarHtml = '';            // barra horizontal con KPIs
  let kpisBarHtml_tierInline = ''; // tier inline (sin caja) al lado del nombre
  let belowLineRowHtml = '';       // chips REGISTRADO / Ticket + Llegada/Salida est.
  let facBadge = '';               // chip "Ticket emitido/pendiente"
  let montoFacturadoHtml = '';     // bloque Monto Facturado (columna derecha)
  if (huespedMatch) {
    const status = (typeof huGetFacturaStatus === 'function') ? huGetFacturaStatus(huespedMatch) : '';
    const folio = huValueFlexible(huespedMatch, ['Folio facturapi','Folio Facturapi','Folio']);
    const ticketUrl = (typeof huExtractTicketUrl === 'function') ? huExtractTicketUrl(huespedMatch) : '';
    const montoFact = huValueFlexible(huespedMatch, ['$ Monto facturado Total','Monto facturado Total']);
    const horaIng = huValueFlexible(huespedMatch, ['Hora estimada de llegada','Hora de llegada']);
    const horaSal = huValueFlexible(huespedMatch, ['Hora estimada de salida','Hora de salida']);
    // Chip Ticket emitido / pendiente (mismo diseño que en módulo huéspedes)
    facBadge = status === 'emitida'
      ? (ticketUrl
          ? `<a href="${esc(ticketUrl)}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="text-decoration:none">
               <span style="display:inline-block;padding:4px 10px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:10px;border:1px solid #86efac">🧾 Ticket emitido${folio?' - Folio #'+esc(folio):''}</span>
             </a>`
          : `<span style="display:inline-block;padding:4px 10px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:10px;border:1px solid #86efac">🧾 Ticket emitido${folio?' - Folio #'+esc(folio):''}</span>`)
      : status === 'pendiente'
      ? `<span style="display:inline-block;padding:4px 10px;border-radius:999px;background:#fff7ed;color:#c2410c;font-weight:700;font-size:10px;border:1.5px solid #fdba74">🧾 Ticket pendiente</span>`
      : '';
    if (status === 'emitida') {
      const medio = String(huValueFlexible(huespedMatch, ['Medio de emisión','Medio de emision']) || '').trim();
      if (medio) {
        const isAuto = /auto/i.test(medio);
        const bg = isAuto ? '#ede9fe' : '#e0f2fe';
        const fg = isAuto ? '#5b21b6' : '#0369a1';
        const bd = isAuto ? '#c4b5fd' : '#7dd3fc';
        const emoji = isAuto ? '👤' : '🖥️';
        facBadge += ` <span title="Origen del ticket" style="display:inline-block;padding:4px 10px;border-radius:999px;background:${bg};color:${fg};border:1px solid ${bd};font-size:10px;font-weight:800;letter-spacing:.02em">${emoji} ${esc(medio)}</span>`;
      }
    }
    // KPIs globales del huésped + tier
    if (typeof huComputeGuestStats === 'function') {
      const stats = huComputeGuestStats(huespedMatch, HU_STATE.rows);
      const score = (typeof huComputeLoyaltyScore === 'function') ? huComputeLoyaltyScore(stats) : 0;
      const tier  = (typeof huGuestTier === 'function') ? huGuestTier(score, stats) : null;
      // Tier INLINE (sin caja/fondo) — se inyecta al lado del nombre.
      kpisBarHtml_tierInline = tier ? `
        <span title="${esc(tier.tooltip)}" style="display:inline-flex;align-items:center;gap:6px;font-size:13px;color:${tier.fg};font-weight:800;letter-spacing:.04em;text-transform:uppercase;line-height:1">
          <span style="font-size:18px">${tier.icon}</span>
          <span>${tier.label}</span>
          <span style="font-size:11px;color:#475569;text-transform:none;letter-spacing:0;font-weight:700">· Score final: <b style="color:#0f172a">${tier.score}</b></span>
        </span>` : '';
      // KPIs (sin tier — el tier va inline al lado del nombre)
      kpisBarHtml = `
        <div style="display:flex;gap:6px;align-items:stretch;justify-content:space-between;margin-top:6px">
          <div style="flex:1;background:rgba(255,255,255,.9);border:1px solid ${palette.border};border-radius:8px;padding:4px 8px;text-align:center;min-width:0" title="Suma global de noches del huésped">
            <div style="font-size:8px;color:#64748b;font-weight:800;letter-spacing:.04em;text-transform:uppercase">🌙 Noches</div>
            <div style="font-size:13px;font-weight:800;color:#0f172a;line-height:1.1">${stats.totalNoches}</div>
          </div>
          <div style="flex:1;background:rgba(255,255,255,.9);border:1px solid ${palette.border};border-radius:8px;padding:4px 8px;text-align:center;min-width:0" title="Visitas globales (consecutivas cuentan como una)">
            <div style="font-size:8px;color:#64748b;font-weight:800;letter-spacing:.04em;text-transform:uppercase">🧳 Visitas</div>
            <div style="font-size:13px;font-weight:800;color:#0f172a;line-height:1.1">${stats.visitas}</div>
          </div>
          <div style="flex:1.4;background:rgba(255,255,255,.9);border:1px solid ${palette.border};border-radius:8px;padding:4px 8px;text-align:center;min-width:0" title="Suma de los TOTAL de Cobros en todas las reservaciones">
            <div style="font-size:8px;color:#64748b;font-weight:800;letter-spacing:.04em;text-transform:uppercase">💰 Monto</div>
            <div style="font-size:12px;font-weight:800;color:#0f172a;line-height:1.1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${stats.montoTotal > 0 ? ((typeof huFmtMonto==='function')?huFmtMonto(stats.montoTotal):('$ '+stats.montoTotal)) : '—'}</div>
          </div>
        </div>`;
    }
    // Bloque "Monto Facturado" (columna derecha, debajo del Ingreso bruto)
    // Ya NO incluye el chip facBadge — ese se movió debajo de la línea.
    if (montoFact) {
      montoFacturadoHtml = `
        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:2px;margin-top:5px;padding-top:5px;border-top:1px dashed #cbd5e1">
          <div style="font-size:8px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:700">Monto facturado</div>
          <div style="font-size:13px;font-weight:800;color:#111827;line-height:1.1">${(typeof huFmtMonto==='function')?huFmtMonto(montoFact):('$ '+esc(montoFact))}</div>
        </div>`;
    }
    // Bloque DEBAJO de la línea divisoria: vacío por requerimiento del
    // usuario — REGISTRADO / Ticket pendiente / Llegada estimada / Salida
    // estimada se removieron del header. (Los chips siguen vivos en las
    // cards del sidebar; aquí no aparecen.)
    belowLineRowHtml = '';
  }

  // Helper para construir el link a WhatsApp con el número del huésped.
  const waPhone = b.GuestPhone ? String(b.GuestPhone).replace(/\D/g, '') : '';
  const waBookingJson = b.GuestPhone ? esc(JSON.stringify(b).replace(/'/g,'&#39;')) : '';
  const phoneHtml = b.GuestPhone
    ? `<span style="display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap">
        <a href="https://wa.me/${waPhone}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="color:#0d9488;font-weight:700;text-decoration:none">📱 ${esc(b.GuestPhone)}</a>
        <button type="button" title="Enviar plantilla o mensaje libre desde el sistema"
          onclick='event.stopPropagation(); waOpenModal(${JSON.stringify(b).replace(/</g,"\\u003c")})'
          style="padding:2px 8px;background:#25d366;color:#fff;border:0;border-radius:999px;font-size:10px;font-weight:800;cursor:pointer;letter-spacing:.02em">💬 Enviar</button>
        ${b.Id ? waAutoToggleHtml(b.Id) : ''}
      </span>`
    : '';

  // Header — bg + border-left HOMOLOGADOS con la card seleccionada del
  // sidebar:  bg según FACTURA (verde intenso si emitida, rojo intenso si
  // pendiente, gris claro si sin factura), border-left 7px con color de
  // PROGRAMACIÓN (meta.border).
  // Mismo bg que la card del sidebar SIN seleccionar (tonalidad clara).
  let headerBg = '#fff'; // sin factura → blanco
  if (huespedMatch) {
    const facStHeader = (typeof huGetFacturaStatus === 'function') ? huGetFacturaStatus(huespedMatch) : '';
    const reqFacHeader = huValueFlexible(huespedMatch, ['¿Requiere factura?']);
    const conFacHeader = /s[ií]/i.test(String(reqFacHeader||'')) || facStHeader === 'emitida' || facStHeader === 'pendiente';
    if (conFacHeader && facStHeader === 'emitida')  headerBg = '#dcfce7'; // verde claro
    else if (conFacHeader && facStHeader === 'pendiente') headerBg = '#fee2e2'; // rojo claro
  }
  const summary = `
    <div style="cursor:pointer;padding:12px 14px;background:${headerBg};border-left:7px solid ${meta.border}">
      <div style="display:flex;align-items:baseline;justify-content:flex-start;gap:14px;margin-bottom:10px;flex-wrap:wrap">
        <div style="font-size:22px;font-weight:900;color:#0f172a;line-height:1.15;letter-spacing:-.01em;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(nombre)}</div>
        ${probableBadge}
        ${kpisBarHtml_tierInline}
      </div>
      ${kpisBarHtml}
      ${huespedMatch ? lgBuildProfileHeaderHtml(huespedMatch, palette) : ''}
    </div>`;

  // Detalle expandido
  const fldRow = (label, value) => `
    <div style="display:grid;grid-template-columns:170px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid #f1f5f9">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:700;align-self:center">${esc(label)}</div>
      <div style="font-size:13px;color:#1f2937">${value || '—'}</div>
    </div>`;

  const lineItemsHtml = (b.LineItems || []).map(li => `
    <div style="display:grid;grid-template-columns:1fr auto;gap:10px;padding:6px 0;border-bottom:1px dashed #e2e8f0;font-size:12px">
      <div><b style="color:#0f172a">${esc(li.kind || '—')}</b>${li.desc ? `<span style="color:#64748b"> · ${esc(li.desc)}</span>` : ''}</div>
      <div style="font-weight:700;color:#0f766e">${lgFmtMoney(li.gross, b.Currency)}</div>
    </div>`).join('');

  const detalleBody = `
    <div style="padding:16px;background:linear-gradient(180deg,#f8fafc,#fff)">
      <div style="background:#fff;border-radius:14px;padding:14px 16px;box-shadow:0 4px 16px rgba(15,23,42,.06);border:1.5px solid #e2e8f0">
        <div style="font-size:11px;letter-spacing:.18em;color:#64748b;font-weight:800;margin-bottom:10px">📑 DETALLE DE RESERVACIÓN</div>
        ${fldRow('ID booking', `<code style="background:#f1f5f9;padding:2px 6px;border-radius:4px;font-size:11px">${esc(b.Id)}</code>`)}
        ${b.ConfirmationCode ? fldRow('Confirmation code', `<code style="background:#f1f5f9;padding:2px 6px;border-radius:4px;font-size:11px">${esc(b.ConfirmationCode)}</code>`) : ''}
        ${fldRow('Fuente', lgSourceBadge(b.Source))}
        ${fldRow('Estado', lgStatusBadge(b.Status))}
        ${fldRow('Propiedad', esc(lgPropOf(b)))}
        ${b.RoomTypeNames ? fldRow('Tipo de habitación', esc(b.RoomTypeNames)) : ''}
        ${fldRow('Llegada', esc(lgFmtDateUI(b.DateArrival)))}
        ${fldRow('Salida', esc(lgFmtDateUI(b.DateDeparture)))}
        ${fldRow('# Noches', `<b>${b.Nights}</b>`)}
        ${b.DateCancelled ? fldRow('Fecha cancelación', esc(b.DateCancelled)) : ''}
        ${fldRow('Nombre del huésped', esc(b.GuestName))}
        ${b.GuestEmail ? fldRow('Correo', `<a href="mailto:${esc(b.GuestEmail)}" style="color:#0d9488">${esc(b.GuestEmail)}</a>`) : ''}
        ${b.GuestPhone ? fldRow('Teléfono', `<a href="https://wa.me/${esc(String(b.GuestPhone).replace(/\D/g,''))}" target="_blank" rel="noopener" style="color:#0d9488">${esc(b.GuestPhone)}</a>`) : ''}
        ${b.GuestCountryCode ? fldRow('País', esc(b.GuestCountryCode)) : ''}
        ${fldRow('Personas', `👥 ${b.NumberOfGuests} (Adultos: ${b.Adults}, Niños: ${b.Children}${b.Infants?`, Infantes: ${b.Infants}`:''}${b.Pets?`, Mascotas: ${b.Pets}`:''})`)}
        ${fldRow('Currency', esc(b.Currency))}
        ${fldRow('Gross / Net / VAT', `${lgFmtMoney(b.Gross, b.Currency)} / ${lgFmtMoney(b.Net, b.Currency)} / ${lgFmtMoney(b.Vat, b.Currency)}`)}
        ${b.ChannelBooking ? fldRow('Channel booking', esc(b.ChannelBooking)) : ''}
        ${b.ListingId ? fldRow('Listing ID', esc(b.ListingId)) : ''}
      </div>
      ${lineItemsHtml ? `
      <div style="background:#fff;border-radius:14px;padding:14px 16px;box-shadow:0 4px 16px rgba(15,23,42,.06);border:1.5px solid #e2e8f0;margin-top:12px">
        <div style="font-size:11px;letter-spacing:.18em;color:#64748b;font-weight:800;margin-bottom:10px">💰 LÍNEAS DE COBRO</div>
        ${lineItemsHtml}
        <div style="display:grid;grid-template-columns:1fr auto;gap:10px;padding:10px 0 0;font-size:13px;border-top:2px solid #e2e8f0;margin-top:6px">
          <div style="font-weight:800;color:#0f172a">Total</div>
          <div style="font-weight:800;color:#0f766e">${lgFmtMoney(b.Gross, b.Currency)}</div>
        </div>
      </div>` : ''}
      ${huespedMatch ? lgBuildHuespedBlock(huespedMatch, fldRow) : ''}
    </div>`;

  return summary;
}

// ─── Modal de detalle de reservación Lodgify ────────────────────────────────

/** Abre el modal en 2 pasadas para que sea fluido:
 *    Paso 1: render INMEDIATO del header + bloque Lodgify (~liviano).
 *    Paso 2 (deferred con requestAnimationFrame): inyecta el bloque
 *      de huéspedes (3 columnas pesadas) DESPUÉS del primer paint.
 *    Paso 3 (opcional async): si el huésped no trae fotos enriquecidas,
 *      fetch a /huespedes-detail y se reemplaza solo el bloque de huésped. */
window.lgOpenDetailModal = function(bookingId) {
  const overlay = document.getElementById('lg-detail-overlay');
  const body    = document.getElementById('lg-detail-body');
  if (!overlay || !body) return;
  const b = (LG_STATE.bookings || []).find(x => String(x.Id) === String(bookingId));
  if (!b) return;
  const huesped = LG_STATE.matches?.get(String(b.Id)) || null;

  // ── Paso 1: render rápido (solo header + Lodgify) ──
  try {
    body.innerHTML = lgBuildModalShellHtml(b, huHasManualRegistration(huesped));
  } catch (err) {
    console.error('[LG] modal shell error:', err);
    body.innerHTML = `<div style="padding:20px;color:#dc2626">Error renderizando detalle.</div>`;
  }
  overlay.classList.remove('hidden');

  if (!huesped) return;

  // ── Paso 2: inyecta el bloque de huéspedes en el siguiente frame ──
  // Esto permite al browser pintar el modal antes de procesar el HTML
  // pesado del 3-columnas. Diferencia visual: el modal aparece instantáneo.
  requestAnimationFrame(() => {
    if (overlay.classList.contains('hidden')) return;
    const slot = document.getElementById('lg-huesped-slot');
    if (!slot) return;
    try { slot.innerHTML = lgBuildHuespedSectionHtml(huesped, b); }
    catch (err) {
      console.error('[LG] huesped section error:', err);
      slot.innerHTML = `<div style="padding:12px;color:#dc2626;font-size:12px">Error al cargar datos del huésped.</div>`;
    }
  });

  // ── Paso 3: enrich async si no tiene fotos ──
  const alreadyEnriched = !!(
    huesped['Link INE frontal'] || huesped['INE frontal'] ||
    huesped['Link INE trasero'] || huesped['INE trasero'] ||
    huesped['Link foto vehículo']
  );
  if (alreadyEnriched) return;
  const recId = String(huesped['ID'] || huesped['row_number'] || '');
  if (!recId) return;
  fetch(`${BACKEND}/huespedes-detail?record_id=${encodeURIComponent(recId)}`)
    .then(r => r.json())
    .then(j => {
      if (!j?.ok || !j.record) return;
      if (overlay.classList.contains('hidden')) return;
      const merged = { ...huesped, ...j.record };
      const idx = (HU_STATE.rows || []).findIndex(x => String(x['ID']||x['row_number']||'') === recId);
      if (idx >= 0) HU_STATE.rows[idx] = merged;
      LG_STATE.matches.set(String(b.Id), merged);
      const slot = document.getElementById('lg-huesped-slot');
      if (slot) {
        try { slot.innerHTML = lgBuildHuespedSectionHtml(merged, b); }
        catch (err) { console.error('[LG] huesped re-render error:', err); }
      }
    })
    .catch(e => console.warn('[LG] enrich huesped falló:', e.message));
};

window.lgCloseDetailModal = function() {
  const overlay = document.getElementById('lg-detail-overlay');
  if (overlay) overlay.classList.add('hidden');
};

// Escape cierra el modal
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    const ov = document.getElementById('lg-detail-overlay');
    if (ov && !ov.classList.contains('hidden')) lgCloseDetailModal();
  }
});

/** ─── Shell del modal (render rápido — header + Lodgify + slot vacío) ─── */
function lgBuildModalShellHtml(b, hasHuesped) {
  const main = lgBuildModalLodgifyHtml(b, hasHuesped);
  // El slot del huésped se llena en el siguiente animation frame. Usamos
  // content-visibility:auto para que el browser pueda saltar layout/paint
  // del bloque mientras esté fuera del viewport.
  const slot = hasHuesped
    ? `<div id="lg-huesped-slot" style="content-visibility:auto;contain-intrinsic-size:1px 500px"></div>`
    : '';
  return main + slot;
}

/** Shell de la vista "Detalles" — usa el MISMO header que las cards de la
 *  vista "Lista" (lgBuildCardSummary), seguido del bloque Lodgify y el slot
 *  del huésped (se llena async). */
function lgBuildDetailShellHtml(b, hasHuesped) {
  const stayState = lgGetStayState(b.DateArrival, b.DateDeparture);
  const meta = LG_STATE_META[stayState] || LG_STATE_META.concluida;
  const headerCard = `
    <div style="border:1.5px solid ${meta.border};border-radius:12px;background:#fff;overflow:hidden;box-shadow:0 1px 3px rgba(15,23,42,.04);margin-bottom:14px">
      ${lgBuildCardSummary(b)}
    </div>`;
  // SIEMPRE 3 columnas. Si no hay match, col 1 y 2 son placeholders vacíos.
  // Col 3 SIEMPRE tiene contenido (Lodgify + líneas de cobro, +
  // datos del huésped y caja auto-facturación si hay match).
  const slot = `<div id="lg-huesped-slot" style="content-visibility:auto;contain-intrinsic-size:1px 500px">${lgBuildEmpty3ColLayout(b)}</div>`;
  return headerCard + slot;
}

/** Layout 3 columnas con placeholders + col 3 con datos Lodgify.
 *  Se usa como render inmediato mientras llega el huésped completo (si hay
 *  match) o como render final (si no hay match). */
function lgBuildEmpty3ColLayout(b) {
  const emptyCol = (label, icon) => `
    <div style="background:#fff;border-radius:14px;padding:14px 16px;border:1.5px dashed #e2e8f0;box-shadow:0 1px 3px rgba(15,23,42,.03);min-height:200px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;color:#cbd5e1;text-align:center">
      <div style="font-size:24px;opacity:.5">${icon}</div>
      <div style="font-size:10px;letter-spacing:.16em;color:#94a3b8;font-weight:800;text-transform:uppercase">${esc(label)}</div>
      <div style="font-size:11px;color:#cbd5e1;font-style:italic">Sin datos del registro manual</div>
    </div>`;
  return `
    <div class="hu-record-body" style="padding:16px;background:linear-gradient(180deg,#f8fafc,#fff);border-radius:14px;border:1.5px solid #e2e8f0;display:grid;grid-template-columns:minmax(260px,1fr) minmax(220px,1fr) minmax(320px,1.4fr);gap:14px;align-items:start">
      <div class="hu-col-profile">${emptyCol('Perfil del huésped', '👤')}</div>
      <div class="hu-col-history">${emptyCol('Reservas totales', '📚')}</div>
      <div class="hu-col-detail">${lgBuildCombinedDetailColumn(b, null)}</div>
    </div>`;
}

/** Col 3 — Detalle de reservación fusionado: Lodgify + huésped + líneas de cobro.
 *  Si hay huesped, integra los datos del registro manual + la caja
 *  auto-facturación. Si no, muestra solo Lodgify. */
function lgBuildCombinedDetailColumn(b, huesped) {
  const fldRow = (label, value) => `
    <div style="display:grid;grid-template-columns:170px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid #f1f5f9">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:700;align-self:center">${esc(label)}</div>
      <div style="font-size:13px;color:#1f2937">${value === '' || value == null ? '—' : value}</div>
    </div>`;

  // Helper: lee del huésped manual (Reservaciones) cuando exista.
  const hv = (cands) => huesped ? huValueFlexible(huesped, Array.isArray(cands) ? cands : [cands]) : '';
  const fmtHora = (raw) => {
    if (!raw) return '';
    const s = String(raw).trim();
    const m = s.match(/T(\d{2}):(\d{2})/);
    if (m) return `${m[1]}:${m[2]}`;
    return (typeof huFmtHoraSimple === 'function') ? huFmtHoraSimple(s) : s;
  };

  // ─── Ids ───
  // Lodgify Id: si es synthetic, b.LodgifyId (del campo Reservaciones:Lodgify Id)
  // o b.__lodgify.Id (booking real). Si es booking real puro, b.Id.
  const lodgifyId = (b.__lodgify && b.__lodgify.Id) || b.LodgifyId || (b.__reservacion ? '' : (b.Id || ''));
  // Registro Id: ID de Reservaciones (solo aplica a synthetic bookings).
  const registroId = b.__reservacion ? (b.__reservacion['ID'] || b.__reservacion['row_number'] || '') : '';

  // ─── Datos combinados — Lodgify es source-of-truth para fechas, noches,
  // personas y propiedad porque Lodgify se actualiza cuando el huésped
  // extiende/modifica la reserva, mientras que la fila de Reservaciones
  // queda con los valores originales del check-in manual.
  const llegada   = b.DateArrival   || hv(['Fecha de ingreso']);
  const salida    = b.DateDeparture || hv(['Fecha de salida']);
  const horaIng   = hv(['Hora estimada de llegada','Hora de llegada']);
  const horaSal   = hv(['Hora estimada de salida','Hora de salida']);
  const noches    = b.Nights || hv(['# Noches']);
  const personas  = b.NumberOfGuests || hv(['# Huéspedes']);
  const nombresT  = hv(['Nombres de TODOS los huéspedes (separados por comas)']);
  const motivo    = hv(['Motivo de tu hospedaje','Motivo']);
  const reqFactRaw= String(hv(['¿Requiere factura?','Tipo de factura']) || '').trim();
  const comen     = hv(['Envía tus comentarios','Comentarios','Notas']);

  // Chip "¿Requiere factura?": verde si sí, rojo si no, gris si vacío
  let reqFactChip = '';
  if (reqFactRaw) {
    const isYes = /^s[ií]/i.test(reqFactRaw);
    const isNo  = /^no/i.test(reqFactRaw);
    if (isYes) reqFactChip = `<span style="display:inline-block;padding:2px 9px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:11px;border:1px solid #86efac">✅ Sí</span>`;
    else if (isNo) reqFactChip = `<span style="display:inline-block;padding:2px 9px;border-radius:999px;background:#fee2e2;color:#991b1b;font-weight:700;font-size:11px;border:1px solid #fca5a5">❌ No</span>`;
    else reqFactChip = `<span style="display:inline-block;padding:2px 9px;border-radius:999px;background:#f1f5f9;color:#475569;font-weight:700;font-size:11px;border:1px solid #cbd5e1">${esc(reqFactRaw)}</span>`;
  }

  // ─── Sección 1: campos generales ───
  const section1 = `
    ${lodgifyId  ? fldRow('Lodgify Id',  `<code style="background:#f1f5f9;padding:2px 6px;border-radius:4px;font-size:11px">${esc(lodgifyId)}</code>`) : ''}
    ${registroId ? fldRow('Registro Id', `<code style="background:#f1f5f9;padding:2px 6px;border-radius:4px;font-size:11px">${esc(registroId)}</code>`) : ''}
    ${fldRow('Fuente',   lgSourceBadge(b.Source))}
    ${fldRow('Estado',   lgStatusBadge(b.Status))}
    ${fldRow('Propiedad', esc(lgPropOf(b) || ''))}
    ${fldRow('Llegada', esc(lgFmtDateUI(llegada)))}
    ${fldRow('Hora llegada', horaIng ? esc(fmtHora(horaIng)) : '—')}
    ${fldRow('Salida', esc(lgFmtDateUI(salida)))}
    ${fldRow('Hora salida',  horaSal ? esc(fmtHora(horaSal)) : '—')}
    ${fldRow('# Noches', noches ? `🌙 <b>${esc(String(noches))}</b>` : '—')}
    ${fldRow('Personas', personas ? `👥 <b>${esc(String(personas))}</b>` : '—')}
    ${fldRow('Nombres de huéspedes', nombresT ? `<span style="font-size:12px;line-height:1.5">${esc(nombresT)}</span>` : '—')}
    ${fldRow('Motivo', motivo ? esc(motivo) : '—')}
    ${fldRow('¿Requiere factura?', reqFactChip || '—')}
    ${fldRow('Comentarios', comen ? `<div style="font-size:12px;line-height:1.5;background:#f8fafc;padding:8px 10px;border-radius:6px;border-left:3px solid #94a3b8;font-style:italic;color:#334155">${esc(comen)}</div>` : '—')}`;

  // ─── Sección 2: Líneas de cobro ───
  // Prioridad 1: Lodgify LineItemsJSON agrupado por kind (RoomRate / Fee /
  // Tax). Prioridad 2 (fallback): campos de la hoja Reservaciones
  // ($ Noches, $ Cuota de limpieza, ($) Monto Total pagado / $ Monto
  // facturado Total). Cuando ambos están vacíos → "—" / N/A.
  const lineItems = b.LineItems || [];
  const sumKind = (matcher) => lineItems
    .filter(li => matcher(String(li.kind || '').toLowerCase()))
    .reduce((acc, li) => acc + (Number(li.gross) || 0), 0);
  // LECTURA DIRECTA de campos $ (sin huValueFlexible). huValueFlexible
  // normaliza claves quitando $ # y caracteres especiales, lo que hace que
  // "$ Noches" (costo) y "# Noches" (cantidad) colisionen al normalizar
  // ambos a "noches" → devuelve un valor incorrecto. Acá leemos exact key.
  const numFromHuExact = (keys) => {
    if (!huesped) return 0;
    for (const k of keys) {
      const v = huesped[k];
      if (v == null || String(v).trim() === '') continue;
      const s = String(v).replace(/[^0-9.\-]/g, '');
      const n = Number(s);
      if (Number.isFinite(n) && n > 0) return n;
    }
    return 0;
  };
  const tarifaHosp = sumKind(k => k.includes('roomrate') || k.includes('room'))
                  || numFromHuExact(['$ Noches']);
  const tarifaLimp = sumKind(k => k.includes('fee') || k.includes('clean') || k.includes('limpieza'))
                  || numFromHuExact(['$ Cuota de limpieza']);
  const impuestos  = sumKind(k => k.includes('tax') || k.includes('vat') || k.includes('iva'));
  // Promoción (Airbnb "estancia mínima" / descuentos en general).
  // En Lodgify vienen como kind='Promotion' con gross positivo pero SUMAN
  // como negativo al total. Mostramos el monto con signo negativo para que
  // el desglose cuadre visualmente con Lodgify.
  const promocion = sumKind(k => k.includes('promotion') || k.includes('discount') || k.includes('promoci') || k.includes('descuento'));
  const totalLineItems = tarifaHosp + tarifaLimp + impuestos - promocion;
  // TotalAmount (post-descuento, autoritativo). Fallback a la resta manual.
  const totalCobros = Number(b.Gross)
                   || (totalLineItems > 0 ? totalLineItems : 0)
                   || numFromHuExact(['($) Monto Total pagado','$ MONTO TOTAL Airbnb','$ Monto facturado Total']);
  const cur = b.Currency || 'MXN';
  const moneyOrDash = (n) => n > 0 ? `<b style="color:#0f766e">${lgFmtMoney(n, cur)}</b>` : '—';
  const promocionRow = promocion > 0
    ? `${fldRow('Promoción estancia mínima Airbnb', `<b style="color:#b45309">−${lgFmtMoney(promocion, cur)}</b>`)}`
    : '';
  const section2 = `
    ${fldRow('Divisa', b.Currency ? `<b>${esc(b.Currency)}</b>` : '—')}
    ${fldRow('Tarifa hospedaje', moneyOrDash(tarifaHosp))}
    ${promocionRow}
    ${fldRow('Tarifa limpieza',  moneyOrDash(tarifaLimp))}
    ${fldRow('Impuestos',        moneyOrDash(impuestos))}
    <div style="display:grid;grid-template-columns:170px 1fr;gap:10px;padding:10px 0;border-top:2px solid #e2e8f0;margin-top:4px">
      <div style="font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:800;align-self:center">TOTAL</div>
      <div style="font-size:15px;font-weight:800;color:#0f766e">${totalCobros > 0 ? lgFmtMoney(totalCobros, cur) : '<span style="color:#94a3b8">N/A</span>'}</div>
    </div>`;

  // Línea divisoria visible entre sección 1 y sección 2
  const divider = `
    <div style="margin:14px 0;border-top:2px dashed #cbd5e1"></div>`;

  // Para mantener compat con código existente que esperaba estas vars:
  const lodgifyFields = section1;
  const huespedFields = '';
  const lineItemsBlock = divider + section2;

  // Caja de auto-facturación (editable) — solo cuando hay match en huéspedes.
  // YA NO auto-rellena al abrir; el usuario debe oprimir el botón
  // "Importar $Montos" entre Líneas de cobro y esta caja.
  let airbnbBoxHtml = '';
  if (huesped && typeof huBuildAirbnbBox === 'function') {
    try { airbnbBoxHtml = huBuildAirbnbBox(huesped, { source: b?.Source }); }
    catch (e) { console.error('[LG] airbnbBox error:', e); }
  }

  // Botón "Importar $Montos" — copia el Total de Líneas de cobro al campo
  // correspondiente: si la reserva es Airbnb → "(=) $ Monto total Airbnb"
  // (que cascadea a comisión y monto facturado), si no → "(+) $ Monto
  // facturado Total" directo. Solo se inserta cuando hay caja de
  // auto-facturación visible Y hay un Gross > 0 que importar.
  const medioHu = huesped ? String(huValueFlexible(huesped, ['Medio de reservación']) || '') : '';
  const esAirbnbBtn = medioHu.toLowerCase().includes('airbnb') || String(b.Source||'').toLowerCase().includes('airbnb');
  const grossNum = Number(b.Gross) || 0;
  const importBtnHtml = (airbnbBoxHtml && grossNum > 0) ? `
    <div style="margin:14px 0 0;display:flex;justify-content:center">
      <button type="button"
              onclick="event.stopPropagation();huImportLodgifyMontos(this)"
              data-lg-gross="${grossNum}"
              data-lg-esairbnb="${esAirbnbBtn ? '1' : '0'}"
              title="Copia el Total de Líneas de cobro al campo ${esAirbnbBtn ? '(=) $ Monto total Airbnb' : '(+) $ Monto facturado Total'}"
              style="display:inline-flex;align-items:center;gap:7px;padding:8px 16px;border:1.5px solid #7c3aed;background:linear-gradient(180deg,#ede9fe,#fff);color:#5b21b6;border-radius:10px;font-weight:800;font-size:12px;cursor:pointer;box-shadow:0 2px 6px rgba(124,58,237,.18);transition:transform 120ms ease, box-shadow 120ms ease"
              onmouseover="this.style.transform='translateY(-1px)';this.style.boxShadow='0 4px 10px rgba(124,58,237,.25)'"
              onmouseout="this.style.transform='';this.style.boxShadow='0 2px 6px rgba(124,58,237,.18)'">
        <span style="font-size:14px">⤓</span> Importar $Montos
      </button>
    </div>` : '';

  return `
    <div class="hu-resv-detail" data-hu-resv-id="${esc(huesped ? String(huesped['ID']||huesped['row_number']||'') : '')}" style="background:#fff;border-radius:14px;padding:14px 16px;box-shadow:0 4px 16px rgba(15,23,42,.06);border:1.5px solid #e2e8f0">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
        <div style="font-size:11px;letter-spacing:.18em;color:#64748b;font-weight:800">📑 DETALLE DE RESERVACIÓN</div>
        ${lgStatusBadge(b.Status)}
      </div>
      ${lodgifyFields}
      ${huespedFields}
      ${lineItemsBlock}
      ${importBtnHtml}
      ${airbnbBoxHtml}
    </div>`;
}

/** Solo Sección 1 (datos generales) en su propia tarjeta. */
function lgBuildSection1DetailHtml(b, huesped) {
  // Reutilizamos lgBuildCombinedDetailColumn pero recortamos solo la Sección 1
  // tomando los <fldRow> hasta el divider. Para evitar duplicar código,
  // reconstruimos los mismos cálculos aquí y devolvemos solo la mitad.
  const fldRow = (label, value) => `
    <div style="display:grid;grid-template-columns:170px 1fr;gap:10px;padding:8px 0;border-bottom:1px solid #f1f5f9">
      <div style="font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#a16207;font-weight:700;align-self:center">${esc(label)}</div>
      <div style="font-size:13px;color:#1f2937">${value === '' || value == null ? '—' : value}</div>
    </div>`;
  const hv = (cands) => huesped ? huValueFlexible(huesped, Array.isArray(cands) ? cands : [cands]) : '';
  const fmtHora = (raw) => {
    if (!raw) return '';
    const s = String(raw).trim();
    const m = s.match(/T(\d{2}):(\d{2})/);
    if (m) return `${m[1]}:${m[2]}`;
    return (typeof huFmtHoraSimple === 'function') ? huFmtHoraSimple(s) : s;
  };
  const lodgifyId = (b.__lodgify && b.__lodgify.Id) || b.LodgifyId || (b.__reservacion ? '' : (b.Id || ''));
  const registroId = b.__reservacion ? (b.__reservacion['ID'] || b.__reservacion['row_number'] || '') : '';
  // Lodgify es source-of-truth (ver nota en lgBuildSection1DetailHtml).
  const llegada   = b.DateArrival   || hv(['Fecha de ingreso']);
  const salida    = b.DateDeparture || hv(['Fecha de salida']);
  const horaIng   = hv(['Hora estimada de llegada','Hora de llegada']);
  const horaSal   = hv(['Hora estimada de salida','Hora de salida']);
  const noches    = b.Nights || hv(['# Noches']);
  const personas  = b.NumberOfGuests || hv(['# Huéspedes']);
  const nombresT  = hv(['Nombres de TODOS los huéspedes (separados por comas)']);
  const motivo    = hv(['Motivo de tu hospedaje','Motivo']);
  const reqFactRaw= String(hv(['¿Requiere factura?','Tipo de factura']) || '').trim();
  const comen     = hv(['Envía tus comentarios','Comentarios','Notas']);
  let reqFactChip = '';
  if (reqFactRaw) {
    const isYes = /^s[ií]/i.test(reqFactRaw);
    const isNo  = /^no/i.test(reqFactRaw);
    if (isYes) reqFactChip = `<span style="display:inline-block;padding:2px 9px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:700;font-size:11px;border:1px solid #86efac">✅ Sí</span>`;
    else if (isNo) reqFactChip = `<span style="display:inline-block;padding:2px 9px;border-radius:999px;background:#fee2e2;color:#991b1b;font-weight:700;font-size:11px;border:1px solid #fca5a5">❌ No</span>`;
    else reqFactChip = `<span style="display:inline-block;padding:2px 9px;border-radius:999px;background:#f1f5f9;color:#475569;font-weight:700;font-size:11px;border:1px solid #cbd5e1">${esc(reqFactRaw)}</span>`;
  }
  return `
    <div class="hu-resv-detail hu-col-card" data-hu-resv-id="${esc(huesped ? String(huesped['ID']||huesped['row_number']||'') : '')}" style="background:#fff;border-radius:16px;padding:0;box-shadow:0 4px 16px rgba(15,23,42,.08);border:1.5px solid #e2e8f0;overflow:hidden">
      <div style="height:4px;background:linear-gradient(90deg,#f59e0b,#ef4444,#ec4899)"></div>
      <div style="padding:14px 16px">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
        <div style="font-size:11px;letter-spacing:.18em;color:#64748b;font-weight:800">📑 DETALLE DE RESERVACIÓN</div>
        ${lgStatusBadge(b.Status)}
      </div>
      ${lodgifyId  ? fldRow('Lodgify Id',  `<code style="background:#f1f5f9;padding:2px 6px;border-radius:4px;font-size:11px">${esc(lodgifyId)}</code>`) : ''}
      ${registroId ? fldRow('Registro Id', `<code style="background:#f1f5f9;padding:2px 6px;border-radius:4px;font-size:11px">${esc(registroId)}</code>`) : ''}
      ${fldRow('Fuente',   lgSourceBadge(b.Source))}
      ${fldRow('Estado',   lgStatusBadge(b.Status))}
      ${fldRow('Propiedad', esc(lgPropOf(b) || ''))}
      ${fldRow('Llegada', esc(lgFmtDateUI(llegada)))}
      ${fldRow('Hora llegada', horaIng ? esc(fmtHora(horaIng)) : '—')}
      ${fldRow('Salida', esc(lgFmtDateUI(salida)))}
      ${fldRow('Hora salida',  horaSal ? esc(fmtHora(horaSal)) : '—')}
      ${fldRow('# Noches', noches ? `🌙 <b>${esc(String(noches))}</b>` : '—')}
      ${fldRow('Personas', personas ? `👥 <b>${esc(String(personas))}</b>` : '—')}
      ${fldRow('Nombres de huéspedes', nombresT ? `<span style="font-size:12px;line-height:1.5">${esc(nombresT)}</span>` : '—')}
      ${fldRow('Motivo', motivo ? esc(motivo) : '—')}
      ${fldRow('¿Requiere factura?', reqFactChip || '—')}
      ${fldRow('Comentarios', comen ? `<div style="font-size:12px;line-height:1.5;background:#f8fafc;padding:8px 10px;border-radius:6px;border-left:3px solid #94a3b8;font-style:italic;color:#334155">${esc(comen)}</div>` : '—')}
      </div>
    </div>`;
}

/** Construye la sección "🧹 Aseo" con los campos de Ejecución de Breezeway.
 *  Acepta:
 *    - un objeto booking de Lodgify (tomará b.Id)
 *    - un row de Reservaciones (tomará r['Lodgify Id'])
 *    - un string con el Lodgify Id directo
 *  La sección SIEMPRE se renderiza para que el usuario vea que está integrada,
 *  con placeholders claros cuando no hay datos. */
// ─── Re-injection de Incidencias/Objetos cuando llegan sus listas async ────
function lgReinjectRelatedSections(kind) {
  // kind: 'inc' | 'obj'
  const detailEls = document.querySelectorAll('.hu-col-detail, .hu-resv-detail');
  for (const el of detailEls) {
    if (el.dataset.aseoInjected !== '1') continue;
    const arg = (typeof lookupBookingForDetailEl_fromAseo !== 'undefined')
      ? null
      : (window.__lgBookingForDetail && window.__lgBookingForDetail.get(el));
    // Reconstruir arg desde data-attrs si está disponible
    let booking = arg;
    if (!booking) {
      // Fallback: parsea el ID de booking del DOM
      const idAttr = el.getAttribute('data-hu-resv-id') || el.getAttribute('data-lg-id') || '';
      if (idAttr) booking = idAttr;
    }
    if (!booking) continue;
    const builder = kind === 'inc' ? (window.lgBuildIncSectionForBooking) : (window.lgBuildObjSectionForBooking);
    const cls = kind === 'inc' ? 'lg-inc-card' : 'lg-obj-card';
    if (typeof builder !== 'function') continue;
    const newHtml = builder(booking);
    if (!newHtml) continue;
    // Remove existing same-kind card under this detail, then re-append.
    el.querySelectorAll(`:scope > div > .${cls}, :scope > .${cls}`).forEach(n => n.parentElement.remove());
    const w = document.createElement('div');
    w.innerHTML = newHtml;
    el.appendChild(w);
  }
}

// ─── Click delegation global (capture phase) para cards Inc/Obj relacionadas.
// Intercepta el click ANTES que cualquier handler descendiente o ancestral
// pueda interferir. Garantiza apertura del slide-in.
if (!window.__lgRelatedClickInstalled) {
  window.__lgRelatedClickInstalled = true;
  document.addEventListener('click', function(e) {
    // Los chips de estatus / prioridad y su menú viven dentro de la card
    // (data-lg-inc-id) pero NO deben abrir el detalle.
    if (e.target.closest('[data-wa-inc-est-chip], [data-wa-inc-nivel-chip], .wa-inc-menu, [data-wa-report-msg-btn], .wa-report-msg-panel')) return;
    const incEl = e.target.closest('[data-lg-inc-id]');
    if (incEl) {
      e.preventDefault();
      e.stopPropagation();
      try { console.info('[LG-INC] click ->', incEl.dataset.lgIncId); } catch(_) {}
      window.lgOpenIncDetailFromBooking(incEl.dataset.lgIncId);
      return;
    }
    const objEl = e.target.closest('[data-lg-obj-id]');
    if (objEl) {
      e.preventDefault();
      e.stopPropagation();
      try { console.info('[LG-OBJ] click ->', objEl.dataset.lgObjId); } catch(_) {}
      window.lgOpenObjDetailFromBooking(objEl.dataset.lgObjId);
      return;
    }
  }, true); // capture
}

// ─── Slide-in genérico para detalle de Incidencia / Objeto desde reserva ───
function lgOpenRelatedPanel(title, html, headerColor) {
  const panel = document.getElementById('lg-related-panel');
  const back  = document.getElementById('lg-related-backdrop');
  const host  = document.getElementById('lg-related-host');
  const t     = document.getElementById('lg-related-title');
  if (!panel || !host) { console.error('[LG-PANEL] elementos no encontrados', { panel: !!panel, back: !!back, host: !!host }); return; }
  // Mover panel + backdrop a document.body para evitar contextos de apilamiento
  // de padres (overflow:hidden, transform, etc.) que puedan ocultarlo.
  if (panel.parentNode !== document.body) document.body.appendChild(panel);
  if (back && back.parentNode !== document.body) document.body.appendChild(back);
  if (t) t.textContent = title || 'Detalle';
  const headerEl = panel.firstElementChild;
  if (headerEl && headerColor) headerEl.style.background = headerColor;
  host.innerHTML = html || '';
  // Mostrar SYNCHRONOUSLY — sin rAF/setTimeout. Si la animación de slide no
  // se ve, el panel igual aparece (mejor que invisible).
  back.classList.remove('hidden');
  panel.classList.remove('hidden');
  back.style.opacity = '1';
  panel.style.transform = 'translateX(0)';
  // z-index encima del wa-modal (99999) y del capture-panel (100002) para
  // que sea visible cuando se abre desde el modal Whatsapp.
  back.style.zIndex  = '100010';
  panel.style.zIndex = '100011';
  document.body.style.overflow = 'hidden';
  console.info('[LG-PANEL] abierto:', title);
}
function lgCloseRelatedPanel() {
  const panel = document.getElementById('lg-related-panel');
  const back  = document.getElementById('lg-related-backdrop');
  if (!panel) return;
  panel.style.transform = 'translateX(100%)';
  back.style.opacity = '0';
  setTimeout(() => { panel.classList.add('hidden'); back.classList.add('hidden'); }, 300);
  document.body.style.overflow = '';
}
window.lgCloseRelatedPanel = lgCloseRelatedPanel;
// ─── Wrappers scope-aware para edición dentro del slide-in panel ────────────
// Sin esto, los selectores `document.querySelector('.inc-card[data-inc-id=X]')`
// de incEnterEdit/Save/Cancel pueden devolver el card DUPLICADO del módulo
// Incidencias oculto, dejando el form editable invisible al usuario.
function lgPanelScopeQuery(sel) {
  const p = document.getElementById('lg-related-panel');
  return p ? p.querySelector(sel) : null;
}
function lgRewriteEditOnclicks(html, kind, id) {
  // Reescribe los onclicks de los buttons editables para usar las versiones
  // scoped al slide-in panel. Mantiene event.stopPropagation() prefix.
  const safeId = String(id).replace(/'/g, "\\'");
  return html
    .replace(/incEnterEdit\('([^']+)'\)/g,   `lgScopedEnterEdit('${kind}','$1')`)
    .replace(/incSaveEdit\('([^']+)'\)/g,    `lgScopedSaveEdit('${kind}','$1')`)
    .replace(/incCancelEdit\('([^']+)'\)/g,  `lgScopedCancelEdit('${kind}','$1')`)
    .replace(/incEditOnChange\('([^']+)'\)/g,`lgScopedEditOnChange('${kind}','$1')`)
    .replace(/objEnterEdit\('([^']+)'\)/g,   `lgScopedEnterEdit('obj','$1')`)
    .replace(/objSaveEdit\('([^']+)'\)/g,    `lgScopedSaveEdit('obj','$1')`)
    .replace(/objCancelEdit\('([^']+)'\)/g,  `lgScopedCancelEdit('obj','$1')`)
    .replace(/objEditOnChange\('([^']+)'\)/g,`lgScopedEditOnChange('obj','$1')`);
}
window.lgScopedEnterEdit = function(kind, id) {
  const STATE = kind === 'inc' ? INC_STATE : OBJ_STATE;
  const sel = kind === 'inc' ? `.inc-card[data-inc-id="${CSS.escape(id)}"]` : `.inc-card[data-obj-id="${CSS.escape(id)}"]`;
  const card = lgPanelScopeQuery(sel);
  const row = (STATE.list||[]).find(r => String(r['ID']||'') === id);
  if (!card || !row) { console.warn('[LG-EDIT] no card/row', kind, id); return; }
  STATE.editing.add(id);
  STATE.editDirty.delete(id);
  const toData = kind === 'inc' ? incRowToReportData : objRowToReportData;
  const snap = toData(row);
  snap._fotosUrls = String(row['Fotos_URLs']||'').split(',').map(s=>s.trim()).filter(Boolean);
  STATE.editOriginal[id] = JSON.stringify(snap);
  if (STATE.editPhotos) delete STATE.editPhotos[id];
  const body = card.querySelector('.inc-card-body');
  if (body) {
    const editableFn = kind === 'inc' ? incCardBodyHtmlEditable : objCardBodyHtmlEditable;
    body.innerHTML = lgRewriteEditOnclicks(editableFn(row, id), kind, id);
    body.classList.add('editing');
  }
};
window.lgScopedCancelEdit = function(kind, id) {
  const STATE = kind === 'inc' ? INC_STATE : OBJ_STATE;
  const sel = kind === 'inc' ? `.inc-card[data-inc-id="${CSS.escape(id)}"]` : `.inc-card[data-obj-id="${CSS.escape(id)}"]`;
  const card = lgPanelScopeQuery(sel);
  const row = (STATE.list||[]).find(r => String(r['ID']||'') === id);
  if (!card || !row) return;
  STATE.editing.delete(id);
  STATE.editDirty.delete(id);
  delete STATE.editOriginal[id];
  if (STATE.editPhotos) delete STATE.editPhotos[id];
  const body = card.querySelector('.inc-card-body');
  if (body) {
    const roFn = kind === 'inc' ? incCardBodyHtmlReadonly : objCardBodyHtmlReadonly;
    body.innerHTML = lgRewriteEditOnclicks(roFn(row, id), kind, id);
    body.classList.remove('editing');
  }
};
window.lgScopedEditOnChange = function(kind, id) {
  // Mirror de inc/objEditOnChange pero scoped al panel — sólo actualiza el
  // estado dirty y la visibilidad del botón Guardar.
  const sel = kind === 'inc' ? `.inc-card[data-inc-id="${CSS.escape(id)}"]` : `.inc-card[data-obj-id="${CSS.escape(id)}"]`;
  const card = lgPanelScopeQuery(sel);
  if (!card) return;
  const STATE = kind === 'inc' ? INC_STATE : OBJ_STATE;
  STATE.editDirty.add(id);
  const saveBtn = card.querySelector('[data-edit-save]');
  if (saveBtn) saveBtn.style.display = '';
};
window.lgScopedSaveEdit = async function(kind, id) {
  const sel = kind === 'inc' ? `.inc-card[data-inc-id="${CSS.escape(id)}"]` : `.inc-card[data-obj-id="${CSS.escape(id)}"]`;
  const card = lgPanelScopeQuery(sel);
  if (!card) return;
  const STATE = kind === 'inc' ? INC_STATE : OBJ_STATE;
  const collectFn = kind === 'inc' ? incCollectEditFields : objCollectEditFields;
  const fields = collectFn(card);
  const photoState = (STATE.editPhotos || {})[id] || { existingUrls: [], newOnes: [] };
  const newFotos = photoState.newOnes.map(f => ({ name: f.name, base64: f.base64, mimeType: f.mimeType }));
  const keepUrls = photoState.existingUrls.slice();
  const saveBtn = card.querySelector('[data-edit-save]');
  const cancelBtn = card.querySelector('.inc-edit-btn-cancel');
  if (saveBtn) { saveBtn.disabled = true; saveBtn.innerHTML = '⏳ Guardando…'; }
  if (cancelBtn) cancelBtn.disabled = true;
  try {
    const payload = { id, fields, keepUrls, fotos: newFotos };
    const res = await fetch(`https://api.check-inn.mx/${kind === 'inc' ? 'update-incidencia' : 'update-objeto'}`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'save failed');
    // Actualizar la fila en memoria
    const row = (STATE.list||[]).find(r => String(r['ID']||'') === id);
    if (row) {
      const fieldMap = kind === 'inc'
        ? { fecha:'Fecha', motivos:'Motivos', clasificaciones:'Clasificacion', propiedad:'Propiedad', depto:'# Departamento', alojamiento:'Alojamiento', reportante:'Reportante', personas:'Personas', nivel:'Nivel', estatus:'Estatus', descripcion:'Descripcion', acciones:'Acciones', seguimiento:'Seguimiento', comentarios:'Comentarios' }
        : { estado:'Estado', fecha_encontrado:'Fecha_encontrado', fecha_entregado:'Fecha_entregado', entregado_a:'Entregado_a', propiedad:'Propiedad', depto:'# Departamento', alojamiento:'Alojamiento', reportante:'Reportante', categoria:'Categoria', categoria_otro:'Categoria_otro', descripcion:'Descripcion', lugar_resguardo:'Lugar_resguardo', lugar_otro:'Lugar_otro', comentarios:'Comentarios' };
      for (const k of Object.keys(fields)) {
        const colName = fieldMap[k];
        if (colName) row[colName] = Array.isArray(fields[k]) ? fields[k].join(', ') : (fields[k] != null ? String(fields[k]) : '');
      }
      if (data.fotos_urls) row['Fotos_URLs'] = String(data.fotos_urls).trim();
    }
    STATE.editing.delete(id);
    STATE.editDirty.delete(id);
    delete STATE.editOriginal[id];
    if (STATE.editPhotos) delete STATE.editPhotos[id];
    // Salir del modo edición y mostrar el detalle actualizado
    const body = card.querySelector('.inc-card-body');
    if (body) {
      const roFn = kind === 'inc' ? incCardBodyHtmlReadonly : objCardBodyHtmlReadonly;
      body.innerHTML = lgRewriteEditOnclicks(roFn(row, id), kind, id);
      body.classList.remove('editing');
    }
    // Refresh de vistas relacionadas sin cambiar de tab:
    // - Timeline de la ventana lateral WA (todas las pestañas)
    // - Lista principal de Incidencias / Objetos (si está visible)
    try { if (typeof _waRepaint === 'function') _waRepaint(); } catch(_){}
    try {
      if (kind === 'inc' && typeof incRenderCards === 'function') {
        const cont = document.getElementById('inc-cards');
        if (cont) incRenderCards();
      } else if (kind === 'obj' && typeof objRenderCards === 'function') {
        const cont = document.getElementById('obj-cards');
        if (cont) objRenderCards();
      }
    } catch(_){}
  } catch (e) {
    alert('Error al guardar: ' + (e.message || e));
    if (saveBtn) { saveBtn.disabled = false; saveBtn.innerHTML = '💾 Guardar cambios y Salir'; }
    if (cancelBtn) cancelBtn.disabled = false;
  }
};

window.lgOpenIncDetailFromBooking = function(id) {
  const row = (typeof INC_STATE !== 'undefined' && Array.isArray(INC_STATE.list) ? INC_STATE.list : []).find(r => String(r['ID']||'') === id);
  if (!row) { lgOpenRelatedPanel('Incidencia', '<div style="padding:14px;color:#dc2626">No se encontró el registro.</div>'); return; }
  const titulo = [String(row['Motivos']||''), String(row['Clasificacion']||'')].filter(Boolean).join(' — ') || 'Reporte';
  const fecha = String(row['Fecha'] || '').slice(0,10);
  let inner = '';
  try { inner = (typeof incCardBodyHtmlReadonly === 'function') ? incCardBodyHtmlReadonly(row, id) : (typeof incCardBodyHtml === 'function' ? incCardBodyHtml(row) : ''); } catch (_) {}
  inner = lgRewriteEditOnclicks(inner, 'inc', id);
  const body = `<div class="inc-card expanded" data-inc-id="${esc(id)}">
    <div class="inc-card-body">${inner}</div>
  </div>`;
  lgOpenRelatedPanel(`📋 ${titulo}${fecha?' · '+fecha:''}`, body, 'linear-gradient(180deg,#fef3c7,#fff)');
};
window.lgOpenObjDetailFromBooking = function(id) {
  const row = (typeof OBJ_STATE !== 'undefined' && Array.isArray(OBJ_STATE.list) ? OBJ_STATE.list : []).find(r => String(r['ID']||'') === id);
  if (!row) { lgOpenRelatedPanel('Objeto olvidado', '<div style="padding:14px;color:#dc2626">No se encontró el registro.</div>'); return; }
  const cat = String(row['Categoria']||'').trim() || 'Objeto';
  const fecha = String(row['Fecha_encontrado']||'').slice(0,10);
  let inner = '';
  try {
    if (typeof objCardBodyHtmlReadonly === 'function') inner = objCardBodyHtmlReadonly(row, id);
    else if (typeof objBuildReporteHtml === 'function' && typeof objRowToReportData === 'function') inner = objBuildReporteHtml(objRowToReportData(row));
  } catch (_) {}
  inner = lgRewriteEditOnclicks(inner, 'obj', id);
  const body = `<div class="inc-card expanded" data-obj-id="${esc(id)}">
    <div class="inc-card-body">${inner}</div>
  </div>`;
  lgOpenRelatedPanel(`🧳 ${cat}${fecha?' · '+fecha:''}`, body, 'linear-gradient(180deg,#ecfdf5,#fff)');
};

// ─── Sección "Incidencias relacionadas" en detalle de reserva ───────────────
function lgBuildIncSectionForBooking(arg) {
  if (typeof arg === 'string') {
    if (!/^\d{6,12}$/.test(arg.trim())) return '';
    const b = (LG_STATE?.bookings || []).find(x => String(x.Id) === arg.trim());
    if (!b) return '';
    arg = b;
  }
  if (!arg || typeof arg !== 'object') return '';
  const arrIso = lgFmtDateUI(arg.DateArrival)   || String((arg.__reservacion && arg.__reservacion['Fecha de ingreso']) || '').slice(0,10);
  const depIso = lgFmtDateUI(arg.DateDeparture) || String((arg.__reservacion && arg.__reservacion['Fecha de salida']) || '').slice(0,10);
  const propRaw = arg.PropiedadRaw || (arg.__reservacion && arg.__reservacion['Propiedad']) || '';
  const deptRaw = arg.DepartamentoRaw || (arg.__reservacion && arg.__reservacion['# Departamento']) || '';
  const propN = alojNorm(propRaw);
  const deptN = alojNorm(deptRaw);
  const wrap = (inner) => `
    <div class="hu-col-card lg-inc-card" style="margin-top:14px;background:#fff;border-radius:16px;padding:0;box-shadow:0 4px 16px rgba(15,23,42,.08);border:1.5px solid #e2e8f0;overflow:hidden;box-sizing:border-box;width:100%">
      <div style="height:4px;background:linear-gradient(90deg,#f59e0b,#ef4444,#dc2626)"></div>
      <div style="padding:14px 16px;box-sizing:border-box">${inner}</div>
    </div>`;
  const header = `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
    <div style="font-size:11px;letter-spacing:.18em;color:#64748b;font-weight:800">🚨 INCIDENCIAS</div>
  </div>`;
  const placeholder = (msg) => wrap(header + `<div style="padding:12px;font-size:12px;color:#64748b;font-style:italic;background:#f8fafc;border-radius:6px">${esc(msg)}</div>`);
  if (!arrIso || !depIso) return placeholder('Sin fechas para cruzar.');
  if (!propN || !deptN) return placeholder('Sin propiedad/depto para cruzar.');
  if (typeof INC_STATE === 'undefined' || !Array.isArray(INC_STATE.list)) return placeholder('⏳ Cargando incidencias…');
  if (!INC_STATE.list.length) {
    if (typeof incLoadIncidencias === 'function') incLoadIncidencias();
    return placeholder('⏳ Cargando incidencias…');
  }
  const matches = INC_STATE.list.filter(r => {
    if (alojNorm(r['Propiedad']) !== propN) return false;
    if (alojNorm(r['# Departamento']) !== deptN) return false;
    const f = String(r['Fecha'] || r['Timestamp'] || '').slice(0,10);
    return f && f >= arrIso && f <= depIso;
  });
  if (!matches.length) {
    const reason = [];
    for (const r of INC_STATE.list) {
      const rp = alojNorm(r['Propiedad']);
      const rd = alojNorm(r['# Departamento']);
      const f = String(r['Fecha'] || r['Timestamp'] || '').slice(0,10);
      let why = '';
      if (rp !== propN) why = `propiedad: "${r['Propiedad']}"(${rp}) ≠ "${propRaw}"(${propN})`;
      else if (rd !== deptN) why = `depto: "${r['# Departamento']}"(${rd}) ≠ "${deptRaw}"(${deptN})`;
      else if (!f) why = 'sin Fecha/Timestamp';
      else if (f < arrIso) why = `fecha ${f} < entrada ${arrIso}`;
      else if (f > depIso) why = `fecha ${f} > salida ${depIso}`;
      if (why) reason.push({ id: r['ID'], why });
    }
    if (reason.length) console.warn('[LG-INC] sin match para reserva', { propRaw, deptRaw, arrIso, depIso }, 'descartados:', reason);
  }
  // Nota: el botón "+ Generar nuevo reporte" se movió al selector unificado
  // (lgBuildReportsSectionForBooking). Aquí solo mostramos incidencias.
  if (!matches.length) return ''; // sección se omite si no hay data para mostrar
  // Cards minimalistas desde cero (no reuso incRenderCardOne para evitar
  // que onclicks/elementos internos roben el evento). Click abre slide-in.
  const cards = matches.map(row => {
    const id = String(row['ID']||'');
    const titulo = [String(row['Motivos']||''), String(row['Clasificacion']||'')].filter(Boolean).join(' — ') || 'Reporte';
    const propiedad = String(row['Propiedad']||'').trim();
    const depto = String(row['# Departamento']||'').trim();
    const aloj = String(row['Alojamiento']||'').trim() || (propiedad && depto ? `${propiedad} - #${depto}` : propiedad);
    const fecha = String(row['Fecha']||row['Timestamp']||'').slice(0,10);
    const nivel = incNormalizeNivel(row['Nivel']);
    const estatus = incNormalizeEstatus(row['Estatus']);
    const motivoCls = (typeof incMotivoColorClass === 'function') ? incMotivoColorClass(row['Motivos']||'') : 'default';
    const BG = { Limpieza:'#06b6d4', Mantenimiento:'#f59e0b', Insumos:'#8b5cf6', default:'#64748b' };
    const headerBg = BG[motivoCls] || BG.default;
    const _estC = incEstatusColors(estatus);
    const estBg = _estC.bg, estCl = _estC.fg;
    const nivelDot = incNivelDot(nivel);
    return `<div data-lg-inc-id="${esc(id)}" role="button" tabindex="0"
              style="display:block;cursor:pointer;width:100%;box-sizing:border-box;background:#fff;border:1.5px solid #e2e8f0;border-radius:10px;overflow:hidden;transition:transform .12s,box-shadow .12s">
        <div style="background:${headerBg};color:#fff;padding:10px 14px;display:flex;justify-content:space-between;align-items:center;gap:10px;pointer-events:none">
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:800;display:flex;align-items:center;gap:8px">
              <span>${esc(titulo)}</span>
              <span title="Nivel ${esc(nivel)}" style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${nivelDot};flex-shrink:0"></span>
            </div>
            ${aloj ? `<div style="font-size:11px;opacity:.92;margin-top:2px">📍 ${esc(aloj)}</div>` : ''}
            ${fecha ? `<div style="font-size:11px;opacity:.85;margin-top:2px">📅 ${esc(fecha)}</div>` : ''}
          </div>
          <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px">
            <span style="padding:3px 10px;background:${estBg};color:${estCl};border-radius:999px;font-size:10px;font-weight:800">${esc(estatus)}</span>
            <span style="font-size:11px;opacity:.7">▸</span>
          </div>
        </div>
      </div>`;
  }).join('');
  return wrap(header + `<div style="display:flex;flex-direction:column;gap:8px">${cards}</div>`);
}

// ─── Sección "Objetos olvidados relacionados" en detalle de reserva ─────────
function lgBuildObjSectionForBooking(arg) {
  if (typeof arg === 'string') {
    if (!/^\d{6,12}$/.test(arg.trim())) return '';
    const b = (LG_STATE?.bookings || []).find(x => String(x.Id) === arg.trim());
    if (!b) return '';
    arg = b;
  }
  if (!arg || typeof arg !== 'object') return '';
  const arrIso = lgFmtDateUI(arg.DateArrival)   || String((arg.__reservacion && arg.__reservacion['Fecha de ingreso']) || '').slice(0,10);
  const depIso = lgFmtDateUI(arg.DateDeparture) || String((arg.__reservacion && arg.__reservacion['Fecha de salida']) || '').slice(0,10);
  const propRaw = arg.PropiedadRaw || (arg.__reservacion && arg.__reservacion['Propiedad']) || '';
  const deptRaw = arg.DepartamentoRaw || (arg.__reservacion && arg.__reservacion['# Departamento']) || '';
  const propN = alojNorm(propRaw);
  const deptN = alojNorm(deptRaw);
  const wrap = (inner) => `
    <div class="hu-col-card lg-obj-card" style="margin-top:14px;background:#fff;border-radius:16px;padding:0;box-shadow:0 4px 16px rgba(15,23,42,.08);border:1.5px solid #e2e8f0;overflow:hidden;box-sizing:border-box;width:100%">
      <div style="height:4px;background:linear-gradient(90deg,#10b981,#059669,#047857)"></div>
      <div style="padding:14px 16px;box-sizing:border-box">${inner}</div>
    </div>`;
  const header = `<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
    <div style="font-size:11px;letter-spacing:.18em;color:#64748b;font-weight:800">🧳 OBJETOS OLVIDADOS</div>
  </div>`;
  const placeholder = (msg) => wrap(header + `<div style="padding:12px;font-size:12px;color:#64748b;font-style:italic;background:#f8fafc;border-radius:6px">${esc(msg)}</div>`);
  if (!arrIso || !depIso) return placeholder('Sin fechas para cruzar.');
  if (!propN || !deptN) return placeholder('Sin propiedad/depto para cruzar.');
  if (typeof OBJ_STATE === 'undefined' || !Array.isArray(OBJ_STATE.list)) return placeholder('⏳ Cargando objetos olvidados…');
  if (!OBJ_STATE.list.length) {
    if (typeof objLoadObjetos === 'function') objLoadObjetos();
    return placeholder('⏳ Cargando objetos olvidados…');
  }
  const matches = OBJ_STATE.list.filter(r => {
    if (alojNorm(r['Propiedad']) !== propN) return false;
    if (alojNorm(r['# Departamento']) !== deptN) return false;
    const f = String(r['Fecha_encontrado'] || '').slice(0,10);
    return f && f >= arrIso && f <= depIso;
  });
  // Debug: si NO hubo matches pero la reservación tiene prop/depto, listar a consola
  // los registros descartados con el motivo. Útil para detectar normalizaciones rotas.
  if (!matches.length) {
    const reason = [];
    for (const r of OBJ_STATE.list) {
      const rp = alojNorm(r['Propiedad']);
      const rd = alojNorm(r['# Departamento']);
      const f = String(r['Fecha_encontrado'] || '').slice(0,10);
      let why = '';
      if (rp !== propN) why = `propiedad: "${r['Propiedad']}"(${rp}) ≠ "${propRaw}"(${propN})`;
      else if (rd !== deptN) why = `depto: "${r['# Departamento']}"(${rd}) ≠ "${deptRaw}"(${deptN})`;
      else if (!f) why = 'sin Fecha_encontrado';
      else if (f < arrIso) why = `fecha ${f} < entrada ${arrIso}`;
      else if (f > depIso) why = `fecha ${f} > salida ${depIso}`;
      if (why) reason.push({ id: r['ID'], why });
    }
    if (reason.length) console.warn('[LG-OBJ] sin match para reserva', { propRaw, deptRaw, arrIso, depIso }, 'descartados:', reason);
  }
  // Nota: el botón "+ Registrar nuevo objeto" se movió al selector unificado.
  if (!matches.length) return ''; // sección se omite si no hay data para mostrar
  // Cards minimalistas desde cero. Click abre slide-in.
  const cards = matches.map(row => {
    const id = String(row['ID']||'');
    const cat = String(row['Categoria']||'').trim();
    const catOtro = String(row['Categoria_otro']||'').trim();
    const catLabel = cat === 'Otro' ? `Otro: ${catOtro || '—'}` : (cat || 'Sin categoría');
    const propiedad = String(row['Propiedad']||'').trim();
    const depto = String(row['# Departamento']||'').trim();
    const aloj = String(row['Alojamiento']||'').trim() || (propiedad && depto ? `${propiedad} - #${depto}` : propiedad);
    const fechaEnc = String(row['Fecha_encontrado']||'').slice(0,10);
    const fechaEnt = String(row['Fecha_entregado']||'').slice(0,10);
    const entregado = !!fechaEnt;
    const headerBg = '#059669';
    const estBg = entregado ? '#dcfce7' : '#fef3c7';
    const estCl = entregado ? '#166534' : '#92400e';
    const estLbl = entregado ? '✓ Entregado' : '⏳ Pendiente';
    return `<div data-lg-obj-id="${esc(id)}" role="button" tabindex="0"
              style="display:block;cursor:pointer;width:100%;box-sizing:border-box;background:#fff;border:1.5px solid #e2e8f0;border-radius:10px;overflow:hidden;transition:transform .12s,box-shadow .12s">
        <div style="background:${headerBg};color:#fff;padding:10px 14px;display:flex;justify-content:space-between;align-items:center;gap:10px;pointer-events:none">
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:800">${esc(catLabel)}</div>
            ${aloj ? `<div style="font-size:11px;opacity:.92;margin-top:2px">📍 ${esc(aloj)}</div>` : ''}
            ${fechaEnc ? `<div style="font-size:11px;opacity:.85;margin-top:2px">📅 ${esc(fechaEnc)}</div>` : ''}
          </div>
          <div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px">
            <span style="padding:3px 10px;background:${estBg};color:${estCl};border-radius:999px;font-size:10px;font-weight:800">${esc(estLbl)}</span>
            <span style="font-size:11px;opacity:.7">▸</span>
          </div>
        </div>
      </div>`;
  }).join('');
  return wrap(header + `<div style="display:flex;flex-direction:column;gap:8px">${cards}</div>`);
}

/** Card unificada "+ Generar nuevo reporte" que abre selector de tipo:
 *  1) Incidencia · 2) Objeto perdido · 3) Reporte técnico (próximamente).
 *  Reemplaza los 2 botones sueltos que había en Inc/Obj sections. */
