/** Alterna la sidebar entre expandida (280px) y colapsada (0). Persiste
 *  la preferencia en localStorage para que se recuerde en próximas
 *  visitas — útil en móvil donde el usuario suele preferirla colapsada. */
window.guiasToggleSidebar = function () {
  const sb  = document.getElementById('guias-sidebar');
  const btn = document.getElementById('guias-sidebar-toggle');
  if (!sb) return;
  const willCollapse = !sb.classList.contains('is-collapsed');
  sb.classList.toggle('is-collapsed', willCollapse);
  if (willCollapse) {
    sb.style.width = '0'; sb.style.padding = '10px 0'; sb.style.opacity = '0'; sb.style.border = '0';
    if (btn) { btn.textContent = '☰'; btn.title = 'Mostrar lista de alojamientos'; }
  } else {
    sb.style.width = '280px'; sb.style.padding = '10px'; sb.style.opacity = '1'; sb.style.borderRight = '1px solid #e2e8f0';
    if (btn) { btn.textContent = '✕'; btn.title = 'Ocultar lista de alojamientos'; }
  }
  try { localStorage.setItem('guias-sidebar-collapsed', willCollapse ? '1' : '0'); } catch {}
};

// Al entrar por primera vez, respeta la preferencia guardada.
(function () {
  const apply = () => {
    let saved = null;
    try { saved = localStorage.getItem('guias-sidebar-collapsed'); } catch {}
    // Auto-colapsar en pantallas angostas si no hay preferencia guardada.
    if (saved == null && window.matchMedia && window.matchMedia('(max-width: 720px)').matches) saved = '1';
    if (saved === '1') {
      const sb = document.getElementById('guias-sidebar');
      const btn = document.getElementById('guias-sidebar-toggle');
      if (sb) {
        sb.classList.add('is-collapsed');
        sb.style.width = '0'; sb.style.padding = '10px 0'; sb.style.opacity = '0'; sb.style.border = '0';
      }
      if (btn) { btn.textContent = '☰'; btn.title = 'Mostrar lista de alojamientos'; }
    } else {
      const btn = document.getElementById('guias-sidebar-toggle');
      if (btn) { btn.textContent = '✕'; btn.title = 'Ocultar lista de alojamientos'; }
    }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply);
  else apply();
})();

/** Copia al portapapeles la URL pública del alojamiento y muestra un modal
 *  con el link + QR code para compartir. */
// Mensaje contextual que se copia al portapapeles cuando el usuario oprime
// "Copiar link" de una guía. Incluye el HouseName + URL.
function guiasBuildShareMessage_(nombre, url) {
  return `Te comparto la 'Guía de Bienvenida' del alojamiento '${nombre}', donde podrás consultar las instrucciones de acceso, la ubicación, el reglamento, etc. Aquí mismo podrás realizar el 'check-in' a tu entrada y el 'check-out' a tu salida: ${url}`;
}

// Handler global usado por el botón "Copiar link" — evita problemas de
// escapado en inline onclick (el mensaje contiene comillas y espacios).
window.guiasCopyShareMsg_ = function (btn, houseId, nombre) {
  const url = `https://www.check-inn.mx/public/guia/?id=${encodeURIComponent(houseId)}`;
  const msg = guiasBuildShareMessage_(nombre, url);
  try { navigator.clipboard?.writeText(msg); } catch (_) {}
  if (btn) {
    const orig = btn.textContent;
    btn.textContent = '✓ Copiado';
    setTimeout(() => { btn.textContent = orig; }, 1500);
  }
};

window.guiasShareLink_ = function (houseId, nombre) {
  const url = `https://www.check-inn.mx/public/guia/?id=${encodeURIComponent(houseId)}`;
  const shareMsg = guiasBuildShareMessage_(nombre, url);
  // Intenta copiar el mensaje contextual al portapapeles.
  try { navigator.clipboard?.writeText(shareMsg); } catch {}
  document.getElementById('guias-share-modal')?.remove();
  const el = document.createElement('div');
  el.id = 'guias-share-modal';
  el.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.75);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px';
  const qr = `https://api.qrserver.com/v1/create-qr-code/?size=280x280&margin=8&data=${encodeURIComponent(url)}`;
  el.innerHTML = `
    <div style="background:#fff;border-radius:16px;max-width:420px;width:100%;padding:24px;box-shadow:0 24px 60px rgba(0,0,0,.3);position:relative">
      <button type="button" onclick="document.getElementById('guias-share-modal')?.remove()"
              style="position:absolute;top:12px;right:12px;background:#f1f5f9;border:0;width:32px;height:32px;border-radius:50%;font-size:16px;cursor:pointer;color:#475569">✕</button>
      <div style="font-size:14px;font-weight:800;color:#0f172a;margin-bottom:4px">🔗 Link de guía</div>
      <div style="font-size:12px;color:#64748b;margin-bottom:16px">${esc(nombre)}</div>
      <div style="background:#f1f5f9;padding:12px;border-radius:10px;font-family:'SF Mono',Menlo,monospace;font-size:11px;color:#334155;word-break:break-all;margin-bottom:8px">${esc(url)}</div>
      <div style="background:#fef3c7;padding:10px 12px;border-radius:10px;font-size:11.5px;color:#78350f;margin-bottom:12px;line-height:1.4"><strong>Mensaje que se copia:</strong><br>${esc(shareMsg)}</div>
      <div style="display:flex;gap:8px;margin-bottom:16px">
        <button type="button" data-house-id="${esc(houseId)}" data-nombre="${esc(nombre)}" onclick="guiasCopyShareMsg_(this, this.dataset.houseId, this.dataset.nombre)"
                style="flex:1;padding:10px 12px;background:#0d9488;color:#fff;border:0;border-radius:8px;font-weight:700;font-size:12.5px;cursor:pointer">📋 Copiar link</button>
        <a href="${esc(url)}" target="_blank" rel="noopener"
           style="flex:1;padding:10px 12px;background:#f1f5f9;color:#0f172a;border-radius:8px;font-weight:700;font-size:12.5px;text-decoration:none;text-align:center;display:inline-block">↗ Abrir</a>
        <button type="button" onclick="guiasShareCard_('${esc(houseId)}','${esc(nombre).replace(/'/g,"\\'")}','${url}')"
                style="flex:1;padding:10px 12px;background:#1e293b;color:#fff;border:0;border-radius:8px;font-weight:700;font-size:12.5px;cursor:pointer">🎴 Card</button>
      </div>
      <div style="display:flex;justify-content:center;padding:12px;background:#f8fafc;border-radius:10px;border:1px solid #e2e8f0">
        <img src="${qr}" alt="QR" style="width:220px;height:220px;display:block">
      </div>
      <div style="font-size:11px;color:#94a3b8;text-align:center;margin-top:10px">El huésped puede escanear el QR o abrir el link — solo verá esta guía.</div>
    </div>`;
  el.addEventListener('click', ev => { if (ev.target === el) el.remove(); });
  document.body.appendChild(el);
};

/** Salta a una sección del quicknav: abre el <details> y hace scroll suave. */
window.guiasJumpTo_ = function (id) {
  const el = document.getElementById(id);
  if (!el) return false;
  if (el.tagName === 'DETAILS' && !el.open) el.open = true;
  el.scrollIntoView({ behavior: 'smooth', block: 'start' });
  return false;
};

// Definición de campos por tab usando las columnas REALES de la hoja
// "alojamientos". Formato: [labelUI, columnKey, inputType?='text'].
const GUIAS_TAB_FIELDS = {
  'wifi': [
    ['Red 1 (SSID)', 'wifi_name_1'],
    ['Red 2 (SSID)', 'wifi_name_2'],
    ['Instrucciones y contraseñas', 'wifi_txt', 'textarea'],
  ],
  'check-in': [
    ['Ubicación', 'ubicacion'],
    ['Detalles de ubicación', 'ubicacion_txt', 'textarea'],
    ['Hora de llegada', 'hr_llegada'],
    ['Hora de salida', 'hr_salida'],
    ['Método de check-in', 'check_in_method'],
    ['Instrucciones de check-in', 'checkin_txt', 'textarea'],
    ['Contactos', 'contactos_txt', 'textarea'],
  ],
  'acceso': [
    ['Clave de acceso', 'clave_acceso'],
    ['Método de check-in', 'check_in_method'],
    ['Estacionamiento', 'parking_txt', 'textarea'],
  ],
  'rules':    [['Reglas de la casa', 'rules_txt', 'textarea']],
  'waste':    [['Mantenimiento / Limpieza / Residuos', 'mantenimiento_txt', 'textarea']],
  'services': [
    ['Tipo', 'tipo'],
    ['Capacidad', 'capacidad'],
    ['Recámaras', 'recamaras'],
    ['Camas', 'camas'],
    ['Baños', 'banos'],
    ['Planta', 'planta'],
    ['Estacionamiento', 'parking_txt', 'textarea'],
  ],
  'guide': [],
};

function guiasBuildTabHtml(key, alojs) {
  if (key === 'check-in') return guiasTabCheckinSpecial(alojs);
  const fields = GUIAS_TAB_FIELDS[key] || [];
  if (!fields.length) return guiasCard(GUIAS_TABS.find(t => t.key === key)?.label || '', '',
    '<div style="font-size:12px;color:#94a3b8;font-style:italic">Sin campos definidos para esta sección.</div>');
  const tabMeta = GUIAS_TABS.find(t => t.key === key);
  const inner = fields.map(([lbl, col, type]) => guiasField(lbl, col, alojs, { type: type || 'text' })).join('');
  return guiasCard(tabMeta?.label || '', tabMeta?.icon || '', inner);
}

// ─── Guía de bienvenida — layout tipo "guía de llegada" (12 secciones) ───
// Lee columnas de la hoja "alojamientos". Cuando el usuario nombró una key
// que difiere de la existente, hacemos fallback a la variante conocida.

/** Lee el valor de una fila probando varios nombres de columna. */
function guiasVal_(aloj, ...keys) {
  for (const k of keys) {
    const v = aloj && aloj[k];
    if (v != null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}

/** Divide una lista escrita en el sheet: acepta saltos de línea, ;, |
 *  y opcionalmente coma. Los pasos NO se dividen por coma (respetan
 *  descripciones internas). */
function guiasList_(str, opts) {
  const sep = opts && opts.comma ? /\r?\n|;|\||,/ : /\r?\n|;|\|/;
  return String(str||'').split(sep)
    .map(s => s.trim())
    // Quita bullets de inicio: •, -, –, *, letra) o dígito) o dígito.
    .map(s => s.replace(/^\s*(?:[•\-\–\*]|[a-zA-Z]\)|\d+[\.\)])\s*/, '').trim())
    .filter(Boolean);
}

/** Emoji para un ítem de amenidad/insumo/salida según palabras clave. */
function guiIcon_(text) {
  const t = String(text||'').toLowerCase();
  const map = [
    // ── Instrucciones de salida (patrones específicos primero) ──
    [/check.?out.*(esta|misma).*p[aá]gina|realiza.*check.?out|check.?out.*app/, '💻'],
    [/lockbox|caja de seg|dep[oó]sit[oa].*llav|deja.*llav|entrega.*llav/, '🔐'],
    [/apaga.*(luz|luces|aire|clima|aparat)/, '💡'],
    [/cierra.*(ventana|puerta|con llave)|cerrar.*puerta/, '🚪'],
    [/trastes|lavavajillas|fregader|platos sucios/, '🍽️'],
    [/basura|contenedor|residuos/, '🗑️'],
    [/limpieza|limpiar|ordenad|dejar limpio/, '🧽'],
    [/revis|revisi[oó]n|check.?list/, '✅'],
    // ── Amenidades / insumos ──
    [/wi ?fi|internet/, '📶'],
    [/aire acond|a\/c|\bac\b|clima/, '❄️'],
    [/calefac|calent(ador|amiento)|calor/, '🔥'],
    [/smart\s?tv|\btv\b|televis/, '📺'],
    [/utensili|cubierto|cuchar|tenedor|olla|sart[eé]n/, '🥄'],
    [/cocin/, '🍳'],
    [/cafetera|caf[eé]/, '☕'],
    [/\bt[eé]\b/, '🍵'],
    [/refrig|nevera|frigo/, '🧊'],
    [/lavador|lavander/, '🧺'],
    [/secador/, '🌀'],
    [/estacion|parking|cochera|garage/, '🅿️'],
    [/agua caliente|regader|duch/, '🚿'],
    [/toalla/, '🛁'],
    [/shampoo|gel|amenidades? de bañ/, '🧴'],
    [/jab[oó]n/, '🧼'],
    [/papel higi[eé]n/, '🧻'],
    [/ropa de cama|s[aá]bana|almohada|cama|colch[oó]n/, '🛏️'],
    [/sal|aceite|b[aá]sicos|especias|az[uú]car/, '🧂'],
    [/limpieza|limpiador|productos de aseo/, '🧽'],
    [/basura|residuos/, '🗑️'],
    [/llave|acceso|puerta/, '🔑'],
    [/mascota|perro|gato/, '🐾'],
    [/fumar|tabaco|cigarr/, '🚭'],
    [/luz|luces|apaga/, '💡'],
    [/ventana|cerrar/, '🪟'],
    [/aire libre|terraza|patio|jard[ií]n/, '🌿'],
    [/piscina|alberca/, '🏊'],
    [/microondas/, '🍲'],
    [/plancha/, '👔'],
    [/tomacorriente|enchufe|carga/, '🔌'],
    [/agua purificad|agua embotellad|garraf[oó]n/, '💧'],
    [/mesa|comedor|silla/, '🪑'],
    [/aspiradora|escoba|trap/, '🧹'],
  ];
  for (const [rx, ic] of map) if (rx.test(t)) return ic;
  return '•';
}

/** Fila de dato Clave/Valor (K/V) — vacío ⇒ se omite. */
function guiKv_(k, v) {
  if (!v) return '';
  return `<div style="display:flex;gap:10px;padding:10px 0;border-bottom:1px dashed #e2e8f0"><div style="flex:none;width:120px;font-weight:600;font-size:13px;color:#0f172a">${esc(k)}</div><div style="flex:1;font-size:13.5px;color:#334155">${esc(v)}</div></div>`;
}

function guiCallout_(text, icon) {
  if (!text) return '';
  return `<div style="display:flex;gap:12px;background:#fffbeb;border:1px solid #fde68a;border-left:4px solid #f59e0b;border-radius:12px;padding:13px;margin-top:12px;font-size:13px;color:#334155"><span style="font-size:18px">${icon||'💡'}</span><div>${esc(text)}</div></div>`;
}

/** Tarjeta acordeón: `<details>` con header y body. Sin subtítulo. */
function guiSection_(id, iconEmoji, iconClass, title, _subtitle, inner, opts) {
  const open = opts && opts.open ? ' open' : '';
  return `<details id="${id}" class="guia-section"${open} style="background:#fff;border:1px solid #e2e8f0;border-radius:14px;margin-bottom:14px;overflow:hidden;box-shadow:0 2px 10px -4px rgba(15,23,42,.10);scroll-margin-top:70px">
    <summary style="display:flex;align-items:center;gap:14px;padding:16px;cursor:pointer;list-style:none;user-select:none">
      <div style="flex:none;width:44px;height:44px;border-radius:13px;display:grid;place-items:center;font-size:22px;background:${iconClass};color:#fff">${iconEmoji}</div>
      <div style="flex:1;min-width:0"><div style="font-size:15px;font-weight:700;color:#0f172a">${esc(title)}</div></div>
      <div style="color:#94a3b8;font-size:12px">▼</div>
    </summary>
    <div style="padding:2px 18px 18px">${inner}</div>
  </details>`;
}

/** Chips (para amenidades / insumos). Incluye ícono automático por keyword. */
function guiChips_(list) {
  if (!list.length) return '';
  return `<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:6px">${list.map(c => {
    const no = /^no\s|^sin\s|^prohib/i.test(c);
    const bg = no ? '#fef2f2' : '#f0fdfa';
    const col = no ? '#b91c1c' : '#0f766e';
    const bd = no ? '#fecaca' : '#99f6e4';
    const icon = guiIcon_(c);
    return `<span style="display:inline-flex;align-items:center;gap:6px;font-size:12.5px;font-weight:500;background:${bg};color:${col};border:1px solid ${bd};padding:7px 12px;border-radius:10px"><span style="font-size:14px">${icon}</span>${esc(c)}</span>`;
  }).join('')}</div>`;
}

/** Reglas (✓ / ✗ / !). Detecta la naturaleza por keywords iniciales pero
 *  respeta el texto original (no quita "No" ni "Sí"). */
function guiRules_(list) {
  if (!list.length) return '';
  return list.map(t => {
    let mark = '!', bg = '#f59e0b';
    if (/^\s*(no|prohibid|✗|✘)/i.test(t)) { mark='✗'; bg='#dc2626'; }
    else if (/^\s*(sí|si\b|✓|✔|permitid|se permit)/i.test(t)) { mark='✓'; bg='#16a34a'; }
    return `<div style="display:flex;gap:10px;align-items:flex-start;padding:9px 0;border-bottom:1px solid #f1f5f9"><div style="flex:none;width:24px;height:24px;border-radius:7px;display:grid;place-items:center;font-size:13px;font-weight:700;color:#fff;background:${bg}">${mark}</div><div style="font-size:13.5px;flex:1;color:#334155">${esc(t)}</div></div>`;
  }).join('');
}

/** Lista tipo "íconos" (para lavandería/salida): cada línea con ícono
 *  contextual del guiIcon_. Sin cajitas ✗/✓. */
function guiIconList_(list) {
  if (!list.length) return '';
  return list.map(t => {
    const ic = guiIcon_(t);
    return `<div style="display:flex;gap:10px;align-items:flex-start;padding:9px 0;border-bottom:1px solid #f1f5f9"><div style="flex:none;width:28px;height:28px;border-radius:8px;display:grid;place-items:center;font-size:15px;background:#f0fdfa">${ic}</div><div style="font-size:13.5px;flex:1;color:#334155">${esc(t)}</div></div>`;
  }).join('');
}

/** Pasos numerados: cada item con formato "Título (descripción)".
 *  Si NO hay paréntesis, todo va como título (peso normal). Los que sí
 *  tienen paréntesis se dividen en título negrita + descripción gris. */
function guiSteps_(list) {
  if (!list.length) return '';
  return `<div style="position:relative;margin-top:6px">${list.map((raw, i) => {
    // Parte fuera de paréntesis vs. dentro del PRIMER par ( ... ).
    const parenIdx = raw.indexOf('(');
    let title = raw.trim();
    let desc = '';
    if (parenIdx > 0) {
      // Extrae el primer contenido balanceado entre paréntesis.
      const closeIdx = raw.lastIndexOf(')');
      if (closeIdx > parenIdx) {
        title = raw.slice(0, parenIdx).trim().replace(/[:\-–]\s*$/, '');
        desc  = raw.slice(parenIdx + 1, closeIdx).trim();
      }
    }
    const last = i === list.length - 1;
    return `<div style="position:relative;padding:2px 0 18px 44px">
      <div style="position:absolute;left:0;top:0;width:30px;height:30px;border-radius:50%;background:linear-gradient(135deg,#f97316,#f59e0b);color:#fff;display:grid;place-items:center;font-weight:700;font-size:14px">${i+1}</div>
      ${!last ? '<div style="position:absolute;left:14px;top:32px;bottom:2px;width:2px;background:#e2e8f0"></div>' : ''}
      <div style="font-size:14px;font-weight:${/bienvenido/i.test(title) || desc ? '800' : '500'};color:#0f172a">${esc(title)}</div>
      ${desc ? `<div style="font-size:13px;color:#64748b;margin-top:2px">${esc(desc).replace(/(c[oó]digo[:\s]*)(\d+)/i, '$1<b style="font-weight:800;font-size:16px;color:#1d4ed8">$2</b>')}</div>` : ''}
    </div>`;
  }).join('')}</div>`;
}

function guiWifi_(red, pass, aviso) {
  if (!red && !pass && !aviso) return '<div style="font-size:12px;color:#94a3b8;font-style:italic">Datos de Wi-Fi no configurados.</div>';
  return `<div style="background:linear-gradient(135deg,#0f172a,#1e293b);border-radius:16px;padding:18px;color:#fff;margin-top:4px">
    ${red ? `<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.12)"><div><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;opacity:.7">Red</div><div style="font-size:16px;font-weight:700;font-family:'Courier New',monospace">${esc(red)}</div></div></div>` : ''}
    ${pass ? `<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0"><div><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;opacity:.7">Contraseña</div><div id="guia-wifi-pass" style="font-size:16px;font-weight:700;font-family:'Courier New',monospace">${esc(pass)}</div></div><button type="button" onclick="guiCopy_(this,'${esc(pass).replace(/'/g,"\\'")}')" style="background:#f59e0b;color:#3b2500;border:0;font-weight:700;font-size:12px;padding:8px 14px;border-radius:10px;cursor:pointer">Copiar</button></div>` : ''}
  </div>${guiCallout_(aviso, '📡')}`;
}

window.guiCopy_ = function (btn, txt) {
  navigator.clipboard?.writeText(txt).then(() => {
    const orig = btn.textContent; btn.textContent = '¡Copiado!'; btn.style.background = '#16a34a'; btn.style.color = '#fff';
    setTimeout(() => { btn.textContent = orig; btn.style.background = '#f59e0b'; btn.style.color = '#3b2500'; }, 1800);
  });
};

function guiEmerg_(nombre1, num1, nombre2, num2) {
  const card = (nombre, num, i) => {
    if (!nombre && !num) return '';
    const bg = i === 0 ? '#dc2626' : '#0891b2';
    return `<a href="${num ? `tel:${esc(String(num).replace(/[^0-9+]/g,''))}` : '#'}" style="display:flex;align-items:center;gap:12px;text-decoration:none;color:#334155;background:#fef2f2;border:1px solid #fecaca;border-radius:13px;padding:13px 14px">
      <div style="width:40px;height:40px;border-radius:11px;background:${bg};color:#fff;display:grid;place-items:center;font-size:19px;flex:none">👤</div>
      <div style="flex:1"><b style="font-size:14px;display:block">${esc(nombre || 'Contacto')}</b><span style="font-size:12px;color:#64748b">${esc(num || 'Sin número')}</span></div>
      ${num ? '<div style="font-size:12px;font-weight:700;color:#dc2626">Llamar</div>' : ''}
    </a>`;
  };
  return `<div style="display:flex;flex-direction:column;gap:10px;margin-top:4px">
    ${card(nombre1, num1, 0)}
    ${card(nombre2, num2, 1)}
  </div>`;
}

/** Construye la guía tipo "guía de llegada" para un solo alojamiento (o el
 *  primero si hay varios). Sigue el layout del prototipo con 12 secciones. */
function guiasBuildGuide(alojs) {
  if (!alojs.length) return '';
  const a = alojs[0]; // usamos el primero cuando hay varios
  const V = (...keys) => guiasVal_(a, ...keys);
  // # Departamento (se muestra dentro de "Método de llegada", antes del paso 1)
  const deptoNum = V('# Departamento','Departamento','departamento');
  const deptoNote = deptoNum
    ? `<div style="background:linear-gradient(135deg,#eff6ff,#dbeafe);border:1px solid #bfdbfe;border-radius:12px;padding:12px 14px;margin-bottom:12px;font-size:14px;color:#0f172a;text-align:center">Tu departamento es el <b style="font-weight:800;font-size:16px;color:#1d4ed8">#${esc(deptoNum)}</b></div>`
    : '';
  // I. Ubicación y cómo llegar
  const sec1 = (() => {
    const gmapUrl = V('url_google_maps');
    const dir     = V('direccion');
    const ref     = V('referencia');
    const aviso   = V('referencia_googlemaps');
    const inner = `
      ${gmapUrl ? `<a class="btn-map" href="${esc(gmapUrl)}" target="_blank" rel="noopener" style="display:block;text-align:center;text-decoration:none;margin-bottom:12px;background:linear-gradient(135deg,#f97316,#f59e0b);color:#fff;font-weight:700;font-size:14px;padding:13px;border-radius:12px;box-shadow:0 4px 12px -4px rgba(249,115,22,.5)">🧭 Abrir en Google Maps</a>` : ''}
      ${guiKv_('Dirección', dir)}
      ${guiKv_('Referencia', ref)}
      ${guiCallout_(aviso, '💡')}`;
    return guiSection_('gu-loc', '📍', 'linear-gradient(135deg,#0ea5e9,#38bdf8)', 'Ubicación y cómo llegar', 'Dirección, mapa y referencias', inner, { open: true });
  })();
  // II. Características del alojamiento
  const sec2 = (() => {
    const inner = `
      ${guiKv_('Tipo', V('tipo'))}
      ${guiKv_('Capacidad', (() => { const c = V('capacidad'); return c ? (/hu[eé]sped/i.test(c) ? c : `${c} huéspedes máx.`) : ''; })())}
      ${guiKv_('Recámaras', V('recamaras'))}
      ${guiKv_('Baños', V('banos','Banos','baños','Baños'))}
      ${guiKv_('Planta', String(V('planta','Planta')||'').replace(/\s*planta\s*$/i, '').trim())}`;
    return guiSection_('gu-house', '🏠', 'linear-gradient(135deg,#8b5cf6,#a78bfa)', 'Características del alojamiento', 'Espacios y capacidad', inner);
  })();
  // III. Amenidades
  const sec3 = (() => {
    const list = guiasList_(V('amenidades'), { comma: true });
    return guiSection_('gu-amen', '✨', 'linear-gradient(135deg,#0f766e,#14b8a6)', 'Amenidades', 'Lo que incluye el espacio', guiChips_(list) || '<div style="font-size:12px;color:#94a3b8;font-style:italic">Sin amenidades listadas.</div>');
  })();
  // IV. Reglamento de la casa
  const sec4 = (() => {
    const list = guiasList_(V('reglamento'));
    return guiSection_('gu-rules', '📋', 'linear-gradient(135deg,#dc2626,#f87171)', 'Reglamento de la casa', 'Para una convivencia armónica', guiRules_(list) || '<div style="font-size:12px;color:#94a3b8;font-style:italic">Sin reglamento listado.</div>', { open: true });
  })();
  // V. Horas de entrada y salida
  const sec5 = (() => {
    const entrada = V('hora_llegada','hr_llegada');
    const salida  = V('hora_salida','hr_salida');
    const inner = `<div style="display:flex;gap:12px;margin-top:6px">
      <div style="flex:1;text-align:center;padding:16px 8px;border-radius:14px;border:1px solid #a5f3fc;background:linear-gradient(135deg,#ecfeff,#f0fdfa)"><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:4px">Entrada</div><div style="font-size:24px;font-weight:800;color:#0f172a">${esc(entrada || '—')}</div></div>
      <div style="flex:1;text-align:center;padding:16px 8px;border-radius:14px;border:1px solid #fde68a;background:linear-gradient(135deg,#fff7ed,#fef9c3)"><div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#64748b;margin-bottom:4px">Salida</div><div style="font-size:24px;font-weight:800;color:#0f172a">${esc(salida || '—')}</div></div>
    </div>`;
    return guiSection_('gu-time', '🕐', 'linear-gradient(135deg,#f59e0b,#fbbf24)', 'Horas de entrada y salida', 'Check-in / Check-out', inner, { open: true });
  })();
  // VI. Método de llegada — incluye "Tu departamento es el #N" antes del paso 1
  const sec6 = (() => {
    const list = guiasList_(V('metodo_llegada')).map(s =>
      /¡?bienvenido[!¡]?/i.test(s) && !/🙂/.test(s) ? s.replace(/(¡?[Bb]ienvenido[!¡]?)/, '$1 🙂') : s
    );
    const steps = guiSteps_(list) || '<div style="font-size:12px;color:#94a3b8;font-style:italic">Sin instrucciones de llegada.</div>';
    return guiSection_('gu-arr', '🚪', 'linear-gradient(135deg,#2563eb,#60a5fa)', 'Método de llegada', 'Acceso al alojamiento', deptoNote + steps, { open: true });
  })();
  // VII. Conexión WiFi
  const sec7 = (() => {
    return guiSection_('gu-wifi', '📶', 'linear-gradient(135deg,#7c3aed,#c084fc)', 'Conexión WiFi', 'Red y contraseña',
      guiWifi_(V('wifi_red','wifi_name_1'), V('wifi_contrasena'), V('wifi_aviso')), { open: true });
  })();
  // VIII. Estacionamiento
  const sec8 = (() => {
    const inner = `
      ${guiKv_('Tipo', V('estacionamiento_tipo'))}
      ${guiKv_('Instrucciones', V('estacionamiento_instrucciones'))}
      ${guiKv_('En la calle', V('estacionamiento_calle'))}
      ${guiCallout_(V('estacionamiento_aviso'), '🚗')}`;
    return guiSection_('gu-park', '🅿️', 'linear-gradient(135deg,#475569,#94a3b8)', 'Estacionamiento', 'Dónde dejar tu auto', inner);
  })();
  // IX. Lavandería
  const sec9 = (() => {
    const regList = guiasList_(V('lavanderia_reglamento'));
    const regBlock = regList.length ? `<div style="padding:12px 0 4px"><div style="font-size:12.5px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px">Reglamento</div>${guiRules_(regList)}</div>` : '';
    const inner = `
      ${guiKv_('Ubicación', V('lavanderia_ubicacion'))}
      ${guiKv_('Acceso', V('lavanderia_acceso'))}
      ${regBlock}
      ${guiCallout_(V('lavanderia_aviso'), '👕')}`;
    return guiSection_('gu-wash', '🧺', 'linear-gradient(135deg,#0891b2,#22d3ee)', 'Lavandería', 'Lavadora y secado', inner);
  })();
  // X. Insumos disponibles
  const sec10 = (() => {
    const inner = `
      ${guiKv_('Ubicación', V('insumos_ubicacion'))}
      ${(() => { const list = guiasList_(V('insumos'), { comma: true }); return list.length ? `<div style="padding:7px 0"><div style="font-size:13px;font-weight:600;color:#0f172a;margin-bottom:6px">Algunos insumos disponibles</div>${guiChips_(list)}</div>` : ''; })()}
      ${guiCallout_(V('insumos_aviso'), '🛒')}`;
    return guiSection_('gu-supply', '🧴', 'linear-gradient(135deg,#16a34a,#4ade80)', 'Insumos disponibles', 'Lo que encontrarás listo', inner);
  })();
  // XI. Instrucciones de salida
  const sec11 = (() => {
    const list = guiasList_(V('salida_instrucciones')).filter(s => !/realiza.*check-?out.*(esta|misma)/i.test(s));
    const rules = list.length ? guiIconList_(list) : '<div style="font-size:12px;color:#94a3b8;font-style:italic">Sin instrucciones de salida.</div>';
    return guiSection_('gu-out', '👋', 'linear-gradient(135deg,#ea580c,#fb923c)', 'Instrucciones de salida', 'Antes de irte', rules + guiCallout_(V('salida_aviso'), '💚'));
  })();
  // XII. Contacto de emergencia
  const sec12 = (() => {
    return guiSection_('gu-emerg', '🚨', 'linear-gradient(135deg,#b91c1c,#ef4444)', 'Contacto de emergencia', 'Estamos para ayudarte',
      guiEmerg_(V('contacto_emergencia_1_nombre'), V('contacto_emergencia_1_numero'),
                V('contacto_emergencia_2_nombre'), V('contacto_emergencia_2_numero')));
  })();
  // XIII. Parrilla eléctrica — solo aparece si el alojamiento tiene contenido.
  const sec13 = (() => {
    const list = guiasList_(V('parrilla'));
    if (!list.length) return '';
    return guiSection_('gu-grill', '🔥', 'linear-gradient(135deg,#c2410c,#f97316)', 'Parrilla eléctrica', 'Cómo usarla', guiSteps_(list));
  })();
  // XIV. Información de vehículos — botón que abre popup dentro de la Guía.
  const sec14 = `<div onclick="guiasOpenVehiculos_()" role="button" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();guiasOpenVehiculos_()}" style="background:#fff;border:1px solid #e2e8f0;border-radius:14px;margin-bottom:14px;overflow:hidden;box-shadow:0 2px 10px -4px rgba(15,23,42,.10);cursor:pointer;transition:transform .12s,box-shadow .12s" onmouseover="this.style.transform='translateY(-1px)';this.style.boxShadow='0 6px 16px -6px rgba(15,23,42,.18)'" onmouseout="this.style.transform='';this.style.boxShadow='0 2px 10px -4px rgba(15,23,42,.10)'">
    <div style="display:flex;align-items:center;gap:14px;padding:16px">
      <div style="flex:none;width:44px;height:44px;border-radius:13px;display:grid;place-items:center;font-size:22px;background:linear-gradient(135deg,#1d4ed8,#3b82f6);color:#fff">🚗</div>
      <div style="flex:1;min-width:0"><div style="font-size:15px;font-weight:700;color:#0f172a">Información de vehículos</div><div style="font-size:12.5px;color:#64748b;margin-top:2px">Coordinación de estacionamiento con otros huéspedes</div></div>
      <div style="color:#94a3b8;font-size:16px">›</div>
    </div>
  </div>`;
  // XV. Recomendaciones — restaurantes/lugares cerca del alojamiento.
  // Columna "restaurantes" en la hoja: URLs de Google Maps separados por ";".
  // Cada card se hidrata con Microlink (título + imagen) al abrirse la guía.
  const sec15 = (() => {
    const raw = V('restaurantes','Restaurantes');
    if (!raw) return '';
    const urls = String(raw).split(';').map(s => s.trim()).filter(s => /^https?:\/\//i.test(s));
    if (!urls.length) return '';
    const cards = urls.map((u, i) => {
      const rid = 'gu-reco-' + Math.random().toString(36).slice(2,9) + '-' + i;
      return `<div id="${rid}" data-reco-url="${esc(u)}" style="display:flex;gap:12px;padding:12px;border:1px solid #e2e8f0;border-radius:12px;margin-bottom:10px;background:#fff;box-shadow:0 1px 4px -1px rgba(15,23,42,.06)">
        <div class="reco-img" style="flex:none;width:88px;height:88px;border-radius:10px;background:linear-gradient(135deg,#f1f5f9,#e2e8f0) center/cover;overflow:hidden;position:relative"><div style="position:absolute;inset:0;display:grid;place-items:center;font-size:24px;color:#94a3b8">🍽️</div></div>
        <div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:6px">
          <div class="reco-title" style="font-size:14px;font-weight:700;color:#0f172a;line-height:1.25;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical">Cargando…</div>
          <div class="reco-desc" style="font-size:11.5px;color:#64748b;line-height:1.35;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical"></div>
          <a href="${esc(u)}" target="_blank" rel="noopener" style="margin-top:auto;align-self:flex-start;display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:700;color:#fff;background:#0d9488;text-decoration:none;padding:6px 12px;border-radius:8px">🗺️ Google Maps</a>
        </div>
      </div>`;
    }).join('');
    return guiSection_('gu-reco', '🍽️', 'linear-gradient(135deg,#7c2d12,#ea580c)', 'Recomendaciones', 'Lugares cerca del alojamiento', cards);
  })();
  // Orden: Ubicación, Alojamiento, Llegada (con "# Departamento" antes del
  // paso 1), Reglamento, Horarios, WiFi, Vehículos, Estacionamiento,
  // Lavandería, Insumos, Amenidades, [Parrilla], Salida, [Recomendaciones],
  // Emergencias SIEMPRE al final.
  // Orden: Ubicación, Horarios, Llegada, Reglamento, WiFi (todos abiertos por
  // default), luego Alojamiento, Vehículos, Estacionamiento, Lavandería,
  // Insumos, Amenidades, [Parrilla], Salida, [Recomendaciones], Emergencias.
  return sec1 + sec5 + sec6 + sec4 + sec7 + sec2 + sec14 + sec8 + sec9 + sec10 + sec3 + sec13 + sec11 + sec15 + sec12;
}

/** Hidrata cards de "Recomendaciones" pidiendo a Microlink título/imagen
 *  a partir del URL de Google Maps de cada card. Idempotente. */
window.guiasHydrateRecos_ = function () {
  document.querySelectorAll('[data-reco-url]').forEach(card => {
    if (card.dataset.recoHydrated === '1') return;
    card.dataset.recoHydrated = '1';
    const url = card.getAttribute('data-reco-url');
    fetch(`https://api.microlink.io/?url=${encodeURIComponent(url)}`, { cache: 'no-store' })
      .then(r => r.json())
      .then(j => {
        if (!j || j.status !== 'success' || !j.data) return;
        const d = j.data;
        const title = card.querySelector('.reco-title');
        const desc  = card.querySelector('.reco-desc');
        const imgEl = card.querySelector('.reco-img');
        const cleanTitle = String(d.title || '').replace(/\s*-\s*Google Maps.*$/i, '').replace(/^Google Maps\s*[-·]\s*/i, '').trim();
        if (title) title.textContent = cleanTitle || 'Lugar recomendado';
        if (desc)  desc.textContent  = String(d.description || '').trim();
        const imgUrl = d.image?.url || d.logo?.url || '';
        if (imgEl && imgUrl) {
          imgEl.style.background = `url("${imgUrl}") center/cover, linear-gradient(135deg,#f1f5f9,#e2e8f0)`;
          const ph = imgEl.querySelector('div'); if (ph) ph.remove();
        }
      })
      .catch(() => { /* deja el placeholder + botón Maps */ });
  });
};

function guiasCard(title, icon, inner) {
  return `<div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;margin-bottom:12px;overflow:hidden">
    <div style="padding:12px 14px;background:#f8fafc;border-bottom:1px solid #e2e8f0;display:flex;align-items:center;gap:8px;font-weight:700;color:#0f172a;font-size:14px">
      ${icon ? `<span>${icon}</span>` : ''}<span>${esc(title)}</span>
    </div>
    <div style="padding:14px">${inner}</div>
  </div>`;
}

// Campo configurable: lectura o input según editMode + multi-select.
function guiasField(label, fieldKey, alojs, opts) {
  const { value, mixed } = guiasFieldValue(alojs, fieldKey);
  const placeholder = mixed ? '(varios — escribe para sobrescribir)' : '—';
  const inputType = (opts && opts.type) || 'text';
  if (GUIAS_STATE.editMode) {
    const input = inputType === 'textarea'
      ? `<textarea oninput="guiasOnFieldChange('${esc(fieldKey)}', this.value)" placeholder="${esc(placeholder)}" rows="3" style="width:100%;padding:7px 9px;border:1px solid #cbd5e1;border-radius:6px;font-size:13px;font-family:inherit;box-sizing:border-box">${esc(value)}</textarea>`
      : `<input type="${esc(inputType)}" oninput="guiasOnFieldChange('${esc(fieldKey)}', this.value)" value="${esc(value)}" placeholder="${esc(placeholder)}" style="width:100%;padding:7px 9px;border:1px solid #cbd5e1;border-radius:6px;font-size:13px;box-sizing:border-box">`;
    return `<div style="padding:6px 0">
      <div style="font-size:11px;color:#64748b;margin-bottom:4px;font-weight:700">${esc(label)}</div>
      ${input}
    </div>`;
  }
  return `<div style="display:grid;grid-template-columns:38% 1fr;gap:14px;align-items:start;padding:7px 0;border-bottom:1px solid #f1f5f9">
    <div style="font-size:12px;color:#64748b;font-weight:500;text-align:left">${esc(label)}</div>
    <div style="font-size:13.5px;color:${mixed?'#94a3b8':'#0f172a'};font-weight:400;text-align:left;font-style:${mixed?'italic':'normal'};white-space:pre-wrap;word-break:break-word;line-height:1.45">${esc(mixed ? '(varios)' : (value || '—'))}</div>
  </div>`;
}

// Render especial del Check-in: agrega botón "Navegar con Google Maps" y
// extrae teléfonos/emails del campo `contactos_txt` para mostrar botones
// rápidos cuando NO está en modo edición.
function guiasTabCheckinSpecial(alojs) {
  const fields = GUIAS_TAB_FIELDS['check-in'];
  const inner = fields.map(([lbl, col, type]) => guiasField(lbl, col, alojs, { type: type || 'text' })).join('');
  const ubicInfo = guiasFieldValue(alojs, 'ubicacion');
  const ubic = ubicInfo.mixed ? '' : ubicInfo.value;
  // Usa la columna url_google_maps si existe; si no, construye desde ubicacion.
  const gmInfo = guiasFieldValue(alojs, 'url_google_maps');
  const gmUrl = (gmInfo.mixed ? '' : gmInfo.value) || (ubic ? `https://maps.google.com/?q=${encodeURIComponent(ubic)}` : '');
  const mapsBtn = (!GUIAS_STATE.editMode && gmUrl)
    ? `<a href="${esc(gmUrl)}" target="_blank" rel="noopener" style="display:block;text-align:center;background:#1e293b;color:#fff;text-decoration:none;font-weight:700;font-size:12px;padding:9px;border-radius:8px;margin:8px 0">🗺️ Navegar con Google Maps</a>`
    : '';
  // Extrae teléfono / whatsapp / email de contactos_txt si existe.
  const cInfo = guiasFieldValue(alojs, 'contactos_txt');
  const ctxt = cInfo.mixed ? '' : cInfo.value;
  const phoneMatch = ctxt.match(/\+?\d[\d\s\-()]{6,}/);
  const emailMatch = ctxt.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
  const phone = phoneMatch ? phoneMatch[0].trim() : '';
  const email = emailMatch ? emailMatch[0].trim() : '';
  const quickBtns = (!GUIAS_STATE.editMode && (phone || email))
    ? `<div style="display:flex;flex-direction:column;gap:6px;margin-top:8px">
        ${phone ? `<a href="tel:${esc(phone)}" style="text-align:center;background:#3b82f6;color:#fff;text-decoration:none;font-weight:700;font-size:12px;padding:9px;border-radius:8px">📞 ${esc(phone)}</a>` : ''}
        ${phone ? `<a href="https://wa.me/${esc(String(phone).replace(/[^0-9]/g,''))}" target="_blank" rel="noopener" style="text-align:center;background:#25d366;color:#fff;text-decoration:none;font-weight:700;font-size:12px;padding:9px;border-radius:8px">💬 WhatsApp</a>` : ''}
        ${email ? `<a href="mailto:${esc(email)}" style="text-align:center;background:#475569;color:#fff;text-decoration:none;font-weight:700;font-size:12px;padding:9px;border-radius:8px">✉️ ${esc(email)}</a>` : ''}
       </div>`
    : '';
  return guiasCard('Check-in', '🔑', inner + mapsBtn + quickBtns);
}

// ═══════════════════════════════════════════════════════════════════════
// ║  RH · CONTROL DE ASISTENCIAS — captura con geolocalización            ║
// ║                                                                       ║
// ║  Sub-secciones: Nuevo registro (activa) / Tabla de control (v1).      ║
// ║  Nuevo registro: botón dispara geolocation.getCurrentPosition + set   ║
// ║  auto de fecha/hora. Empleado desde hoja Personal (INC_STATE.personas).║
// ║  Guardado vía rh_save_asistencia (Apps Script) con headers extendidos.║
// ═══════════════════════════════════════════════════════════════════════

const ASIST_STATE = {
  currentGeo: null,          // { lat, lng, accuracy, timestamp }
  currentDate: null,         // ISO
  currentTime: null,         // HH:MM:SS
  // ─── Tabla / Calendario ───
  vis: 'tabla',              // 'tabla' | 'calendario'
  seleccionar: false,        // modo selección múltiple (con checkboxes)
  selected: new Set(),       // IDs de filas seleccionadas
  editing: new Set(),        // IDs de filas en modo edición inline
  dirty: new Set(),          // IDs de filas con cambios sin guardar
  rows: [],                  // filas de RH_Asistencia
  headers: [],               // headers del sheet
  sortKey: 'Fecha',          // columna activa para sort (default: Fecha)
  sortDir: 'desc',           // 'asc' | 'desc' (default: más reciente primero)
  loading: false,
  loaded: false,
  calMonth: null,            // primer día del mes visible
};

// Columnas que se ocultan de la tabla (redundantes o metadatos)
const ASIST_HIDDEN_COLS = new Set(['Empleado_ID','Horas_extra','ID','Ubicacion_Lat','Ubicacion_Lng','Ubicacion_Salida_Lat','Ubicacion_Salida_Lng','Ubicacion_Entrada_Lat','Ubicacion_Entrada_Lng','GPS_Accuracy','Tipo','Hora']);
const ASIST_PRIMA_COLS = ['$ Salario base','$ Prima vacacional (25%)','$ Prima dominical (25%)','$ Prima día feriado (200%)'];
const ASIST_TOTAL_COL = '$ Salario total';
// Columnas derivadas — no vienen del sheet, se calculan on-the-fly
const ASIST_DERIVED_COLS = ['Entrada','Salida','Horas','$ Salario base','$ Prima vacacional (25%)','$ Prima dominical (25%)','$ Prima día feriado (200%)','$ Salario total'];

// Campos con lista cerrada (para dropdown en modo edición)
const ASIST_LISTAS = {
  Tipo: ['Entrada','Salida','Break_inicio','Break_fin','Vacaciones','Asueto','Otro'],
  Metodo: ['GPS','Manual'],
};

/** True si el puesto es administrativo (excluye del calendario). */
function asistEsAdministrativo(puesto) {
  const p = String(puesto || '').toLowerCase();
  return /administr/.test(p);
}

/** Devuelve la lista de personal para el calendario, EXCLUYE los puestos de
 *  Administración según la columna Puesto de la hoja Personal. */
/** ¿La persona tiene "No" en la columna salario de la hoja Personal? Acepta
 *  nombre completo o corto ("Andrés" → canonical) para registros viejos. */
function asistEsSinSalario_(nombre) {
  const rows = INC_STATE?.personalRows || [];
  if (!rows.length) return false;
  const sinSalario = new Set();
  rows.forEach(r => {
    if (String(r['salario'] ?? r['Salario'] ?? '').trim().toLowerCase() === 'no') {
      const n = String(r['Nombre'] || '').trim();
      if (n) sinSalario.add(_normNombre_(n));
    }
  });
  if (!sinSalario.size) return false;
  const t = String(nombre || '').trim();
  if (!t) return false;
  if (sinSalario.has(_normNombre_(t))) return true;
  const alias = _asistBuildAliasMap_(rows.map(r => ({ nombre: String(r['Nombre'] || '').trim() })).filter(x => x.nombre));
  const canon = alias.get(_normNombre_(t));
  return !!(canon && sinSalario.has(_normNombre_(canon)));
}

function asistPersonalOperativo() {
  const rows = (INC_STATE?.personalRows || []);
  if (rows.length) {
    return rows
      .map(r => ({
        nombre: _rhPersonalFullName_(r),
        puesto: String(r['Puesto'] || r['Rol'] || r['Cargo'] || '').trim(),
        estado: String(r['Estado'] || '').trim(),
        salario: String(r['salario'] ?? r['Salario'] ?? '').trim(),
      }))
      // Excluye — CRÍTICO — cualquier empleado cuyo Estado no sea 'Activo'
      // (Inactivo, Suspendido, Baja). Estado vacío se trata como activo por
      // retrocompatibilidad con filas viejas.
      // El puesto ya NO excluye: solo se oculta a quien tenga salario = "No"
      // (no lleva control de asistencia: dirección, auxiliar contable, etc.).
      .filter(x => {
        if (!x.nombre) return false;
        if (x.estado && x.estado.toLowerCase() !== 'activo') return false;
        if (x.salario.toLowerCase() === 'no') return false;
        return true;
      });
  }
  // Fallback: si aún no cargó la hoja Personal, usa INC_PERSONAL (hardcoded)
  // que sí trae puesto por persona, así el filtro de administrativos también
  // aplica en el modo fallback. INC_STATE.personas es solo la lista plana
  // y perdería la info del puesto.
  const fb = (typeof INC_PERSONAL !== 'undefined' && Array.isArray(INC_PERSONAL))
    ? INC_PERSONAL.map(p => ({ nombre: String(p.nombre || '').trim(), puesto: String(p.puesto || '').trim() }))
    : (INC_STATE?.personas || []).map(n => ({ nombre: String(n).trim(), puesto: '' }));
  return fb.filter(x => x.nombre && !asistEsAdministrativo(x.puesto));
}

/** Parsea "HH:MM[:SS]" a minutos totales. Devuelve null si inválido. */
function asistParseTimeToMinutes(s) {
  const m = String(s || '').match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (!m) return null;
  const h = Number(m[1]), mi = Number(m[2]);
  if (h < 0 || h > 23 || mi < 0 || mi > 59) return null;
  return h * 60 + mi;
}

/** Dado la lista de registros para un persona+día, devuelve:
 *   { entrada, salida, horasStr, estado, semaforo }
 *   estado: 'asistencia' | 'vacaciones' | 'asueto' | 'falta' | 'futuro' | 'finde'
 *   semaforo: '#16a34a' verde | '#f59e0b' amarillo | '#dc2626' rojo | '' sin marcar
 */
/** Deriva los conceptos activos de un día a partir de los registros de la
 *  hoja RH_Asistencia. Devuelve un Set<string> con las claves que usa el
 *  panel (Asistencia · Falta · Incapacidad · Vacaciones · Día feriado). */
function asistDeriveConceptos_(recs) {
  const out = new Set();
  // Incluye TANTO los legados ('Asistencia' / 'Día feriado') como las
  // sub-clasificaciones nuevas del panel (Regular / Vac laboradas /
  // Domingo). Sin las nuevas, un registro con Concepto='Vac laboradas'
  // se caía al fallback de Entrada/Salida y siempre etiquetaba como
  // 'Asistencia' → 'Regular' — perdiendo la sub-clasificación.
  const CONCEPTO_KEYS = ['Asistencia','Regular','Vac laboradas','Día feriado','Domingo','Sin beneficios','Falta','Incapacidad','Vacaciones','Feriado'];
  for (const r of (recs || [])) {
    // Campo Concepto (fuente preferida cuando existe la columna en el sheet).
    const conc = String(r.Concepto || '').trim();
    const foundC = conc && CONCEPTO_KEYS.find(k => k.toLowerCase() === conc.toLowerCase());
    if (foundC) { out.add(foundC); continue; }
    const t = String(r.Tipo || '').toLowerCase();
    if      (t === 'vacaciones')  out.add('Vacaciones');
    else if (t === 'asueto')      out.add('Día feriado');
    else if (t === 'falta')       out.add('Falta');
    else if (t === 'incapacidad') out.add('Incapacidad');
    else if (t === 'entrada' || t === 'salida') out.add('Asistencia');
    // Legacy: filas sin Tipo (formato antiguo Entrada/Salida/Horas). Se
    // infiere el concepto desde Observaciones (patrón "(Concepto)") o, si
    // hay Entrada/Salida con hora, se asume "Asistencia".
    if (!t) {
      const obs = String(r.Observaciones || '');
      const m = obs.match(/\(([^)]+)\)/);
      const found = m && CONCEPTO_KEYS.find(k => k.toLowerCase() === m[1].trim().toLowerCase());
      if (found) out.add(found);
      else if (String(r.Entrada || r.Salida || '').trim()) out.add('Asistencia');
    }
  }
  return out;
}

function asistDeriveDayInfo(recs, date, today) {
  const isWeekend = date.getDay() === 0 || date.getDay() === 6;
  const isFuture = date > today;
  // Estado dominante — priorizamos Concepto (fuente de verdad de la UI
  // administrativa) sobre Tipo (marca del bot WhatsApp). Esto sincroniza
  // el calendario con el Registro de asistencia lateral, que usa Concepto.
  //
  // Prioridad de estados si hay múltiples registros el mismo día:
  //   vacaciones > asueto > día feriado > falta > asistencia
  let hasVac = false, hasAsueto = false, hasFeriado = false, hasFalta = false;
  let entradaMin = null, salidaMin = null;
  let entradaStr = '', salidaStr = '';
  const _normConcepto = (typeof asistPanelNormalizarConceptoLegado_ === 'function')
    ? asistPanelNormalizarConceptoLegado_
    : (v => String(v || '').trim());
  for (const r of recs) {
    const tipo = String(r.Tipo || '').toLowerCase();
    const conceptoRaw = String(r.Concepto || '').trim();
    const conceptoNorm = _normConcepto(conceptoRaw);
    const conceptoLC = String(conceptoNorm || '').toLowerCase();
    // Vacaciones / asueto / feriado / falta — Concepto O Tipo dominan.
    if (tipo === 'vacaciones' || conceptoLC.includes('vacaciones') || conceptoLC.includes('vac laboradas')) hasVac = true;
    if (tipo === 'asueto' || conceptoLC === 'asueto') hasAsueto = true;
    if (conceptoLC.includes('feriado') || conceptoLC.includes('día feriado') || conceptoLC.includes('dia feriado')) hasFeriado = true;
    if (tipo === 'falta' || conceptoLC === 'falta') hasFalta = true;
    // Entrada/Salida — del bot (Tipo) o del registro manual completo
    // (columnas Entrada/Salida en el propio row).
    if (tipo === 'entrada') {
      const m = asistParseTimeToMinutes(r.Hora || r.Entrada);
      if (m != null && (entradaMin == null || m < entradaMin)) { entradaMin = m; entradaStr = (r.Hora || r.Entrada || '').slice(0,5); }
    } else if (tipo === 'salida') {
      const m = asistParseTimeToMinutes(r.Hora || r.Salida);
      if (m != null && (salidaMin == null || m > salidaMin)) { salidaMin = m; salidaStr = (r.Hora || r.Salida || '').slice(0,5); }
    } else {
      // Row sin Tipo (registro manual con Entrada/Salida completos).
      const eM = asistParseTimeToMinutes(r.Entrada);
      const sM = asistParseTimeToMinutes(r.Salida);
      if (eM != null && (entradaMin == null || eM < entradaMin)) { entradaMin = eM; entradaStr = String(r.Entrada || '').slice(0,5); }
      if (sM != null && (salidaMin  == null || sM > salidaMin))  { salidaMin  = sM; salidaStr  = String(r.Salida  || '').slice(0,5); }
    }
  }
  let horasStr = '';
  if (entradaMin != null && salidaMin != null && salidaMin > entradaMin) {
    const diff = salidaMin - entradaMin;
    horasStr = `${Math.floor(diff/60)}h${String(diff%60).padStart(2,'0')}`;
  }
  if (hasVac)     return { entrada:entradaStr, salida:salidaStr, horasStr, estado:'vacaciones',  semaforo:'#f59e0b' };
  if (hasAsueto)  return { entrada:entradaStr, salida:salidaStr, horasStr, estado:'asueto',      semaforo:'#f59e0b' };
  if (hasFeriado) return { entrada:entradaStr, salida:salidaStr, horasStr, estado:'dia_feriado', semaforo:'#0ea5e9' };
  if (hasFalta)   return { entrada:'', salida:'', horasStr:'', estado:'falta', semaforo:'#dc2626' };
  if (entradaMin != null) return { entrada:entradaStr, salida:salidaStr, horasStr, estado:'asistencia', semaforo:'#16a34a' };
  return { entrada:'', salida:'', horasStr:'', estado:'', semaforo:'' };
}

function asistInit() {
  // Default vis = 'calendario' (antes 'tabla'). Se respeta la elección
  // previa del usuario si ya cambió de vista en esta sesión.
  if (!ASIST_STATE.vis) ASIST_STATE.vis = 'calendario';
  // Precarga lista de Personal si aún no está en memoria.
  const afterPersonal = () => {
    asistPopulateEmpleadoSelect();
    // Re-render de AMBAS vistas cuando Personal llega — el primer render
    // seguramente corrió con el fallback (INC_PERSONAL sin admins), pero
    // recién ahora tenemos la lista real de la hoja con Estado='Activo'
    // y la reconciliación de nombres. Re-pintar ajusta las filas del
    // calendario (Adán aparece, admins salen) y refresca la tabla.
    ASIST_STATE._focusMode = 'preserve';
    if (ASIST_STATE.vis !== 'resumen') {
      asistRenderCalendar();
      asistRenderTabla();
    }
  };
  if (typeof incLoadPersonal === 'function' && (!INC_STATE?.personalRows?.length)) {
    incLoadPersonal().then(afterPersonal).catch(afterPersonal);
  } else {
    afterPersonal();
  }
  // Carga los registros al entrar; render de la vista actual (calendario
  // o tabla) se hace dentro de asistReloadList.
  if (!ASIST_STATE.loaded && !ASIST_STATE.loading) {
    asistReloadList();
  } else {
    // Ya cargados: aplica la vista actual (asistSetVis re-usa datos en memoria).
    asistSetVis(ASIST_STATE.vis);
  }
}
window.asistInit = asistInit;

// ── Visualización Tabla / Calendario / Resumen semanal ──
window.asistSetVis = function (vis) {
  // Modelo unificado: Calendario + Tabla se renderizan SIEMPRE en la
  // misma vista de Control de asistencias (una debajo de la otra), sin
  // pestañas. Solo Resumen semanal se mantiene como caso aparte porque
  // vive en Nómina, no aquí.
  ASIST_STATE.vis = vis;
  const wrapT = document.getElementById('asist-tabla-wrap');
  const wrapC = document.getElementById('asist-cal-wrap');
  const wrapR = document.getElementById('asist-resumen-wrap');
  const tbC   = document.getElementById('asist-cal-toolbar');
  const editWrap = document.getElementById('asist-editar-wrap');
  // Editar aplica solo cuando la tabla es la vista principal — en el
  // modelo unificado ambos están siempre visibles, así que dejamos el
  // botón como estaba antes (visible por default).
  if (editWrap) editWrap.style.display = '';
  if (vis === 'resumen') {
    // Modo Resumen: oculta calendario+tabla, muestra resumen.
    if (wrapT) wrapT.classList.add('hidden');
    if (wrapC) wrapC.classList.add('hidden');
    if (tbC)   tbC.classList.add('hidden');
    if (wrapR) wrapR.classList.remove('hidden');
    asistRenderResumen();
    return;
  }
  // Cualquier otra vis (calendario/tabla/undefined) = modo unificado:
  // Calendario arriba + Tabla abajo, ambas visibles simultáneamente.
  if (wrapC) wrapC.classList.remove('hidden');
  if (tbC)   tbC.classList.remove('hidden');
  if (wrapT) wrapT.classList.remove('hidden');
  if (wrapR) wrapR.classList.add('hidden');
  asistRenderCalendar();
  asistRenderTabla();
};

/** Vista "Resumen semanal": agrega (Empleado_Nombre × Semana Lun-Dom)
 *  sumando Horas y las 5 columnas monetarias derivadas por concepto. */
function asistRenderResumen(targetId) {
  const wrap = document.getElementById(targetId || 'asist-resumen-wrap');
  if (!wrap) return;
  wrap.classList.remove('hidden');
  // Filtros persistentes en memoria (no re-crear en cada render).
  if (typeof ASIST_RESUMEN_FILTERS === 'undefined') {
    window.ASIST_RESUMEN_FILTERS = { semana: '', empleado: '', altaImss: '' };
  }
  const F = window.ASIST_RESUMEN_FILTERS;
  // Barra superior con botón "+ Nuevo registro de asistencia" (mismo panel
  // lateral que el de Control de asistencias).
  const toolbarHtml = `
    <div class="rh-toolbar">
      <div>
        <div class="rh-toolbar-title">📊 Resumen semanal</div>
        <div class="rh-toolbar-count">Agregado por Empleado × Semana (Lun-Dom)</div>
      </div>
      <button type="button" onclick="asistNuevoRegistro()"
              style="all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:6px;padding:9px 14px;background:linear-gradient(135deg,#0ea5e9,#0369a1);color:#fff;font-size:12.5px;font-weight:900;letter-spacing:.02em;border-radius:9px;box-shadow:0 3px 10px rgba(14,165,233,.35);white-space:nowrap">
        <span style="font-size:14px">➕</span>
        <span>Nuevo registro de asistencia</span>
      </button>
    </div>`;
  const parseHoras = s => {
    const m = String(s||'').match(/^(\d+)h(\d{2})/);
    return m ? Number(m[1]) * 60 + Number(m[2]) : 0;
  };
  const fmtHoras = mins => mins ? `${Math.floor(mins/60)}h${String(mins%60).padStart(2,'0')}` : '';
  const parseMonto = s => {
    const n = Number(String(s||'').replace(/[$,\s]/g,''));
    return Number.isFinite(n) ? n : 0;
  };
  // Semana ISO: lunes como inicio. Devuelve `{value, label}` compatible con nomWeekOptions.
  const weekOf = (isoDate) => {
    const [y,m,d] = isoDate.split('-').map(Number);
    const dt = new Date(y, m-1, d);
    const dow = dt.getDay(); // 0=dom
    const lun = new Date(dt); lun.setDate(dt.getDate() - ((dow + 6) % 7));
    const dom = new Date(lun); dom.setDate(lun.getDate() + 6);
    const iso = x => `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`;
    const value = `S:${iso(lun)}_${iso(dom)}`;
    const M = (typeof NOM_MONTHS_ABR !== 'undefined') ? NOM_MONTHS_ABR : ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
    const label = `Lun ${lun.getDate()} ${M[lun.getMonth()]} – Dom ${dom.getDate()} ${M[dom.getMonth()]} ${dom.getFullYear()}`;
    return { value, label, lun };
  };
  // Agrega. Los valores mostrados deben coincidir EXACTAMENTE con las
  // 5 columnas de nómina semanal del calendario del panel:
  //   $ Salario base       = $315.04 × min(7, N + 2)  (N = días con Asistencia)
  //   $ Prima vacacional   = suma prima vac por concepto/día
  //   $ Prima dominical    = suma prima dom por concepto/día
  //   $ Prima día feriado  = suma prima DF por concepto/día
  //   $ Salario total      = suma de las 4 anteriores
  // Reconcilia nombres cortos ("Adán") con el nombre completo del Personal
  // ("Adán Ramos") — de otra forma se generan grupos duplicados por nombre.
  const _aliasToFull = new Map();
  (INC_STATE?.personalRows || []).forEach(pr => _rhRegisterPersonalAliases_(_aliasToFull, pr));
  const _canonRes = (raw) => {
    const t = String(raw || '').trim();
    if (!t) return t;
    return _aliasToFull.get(_normNombre_(t)) || t;
  };
  const grupos = new Map();
  // Quien tiene salario = "No" en Personal no se calcula ni en Control de
  // asistencias ni en Nómina (p. ej. Dirección que marca por WhatsApp).
  for (const r of ASIST_STATE.rows) {
    if (asistEsSinSalario_(r.Empleado_Nombre)) continue;
    const nombre = _canonRes(String(r.Empleado_Nombre||'').trim());
    const fecha  = String(r.Fecha||'').slice(0,10);
    if (!nombre || !fecha) continue;
    const w = weekOf(fecha);
    const k = `${nombre}||${w.value}`;
    let g = grupos.get(k);
    if (!g) { g = { nombre, semana: w, horas:0, workDays: new Set(), vac:0, dom:0, df:0, comp:0, compConceptos: [], ids:[] }; grupos.set(k, g); }
    g.horas += parseHoras(r.Horas);
    // Concepto: se toma tal cual; solo se asume 'Regular' cuando hay
    // evidencia de trabajo (Entrada/Salida). Registros solo con
    // compensación (sin concepto ni ent/sal) NO cuentan como día
    // trabajado ni generan prima.
    const _ent = String(r.Entrada||'').trim();
    const _sal = String(r.Salida||'').trim();
    let _conc = String(r.Concepto||'').trim();
    if (!_conc && (_ent || _sal)) _conc = 'Regular';
    const concepto = asistPanelNormalizarConceptoLegado_(_conc);
    // Cualquier concepto que pague salario base (Asistencia, Vacaciones,
    // Feriado no trabajado) aporta al Base laborado semanal. Solo Falta e
    // Incapacidad NO se pagan.
    if (concepto && asistPanelPagaSalarioBase_(concepto)) g.workDays.add(fecha);
    if (concepto) {
      const p = asistPanelPrimasPorConcepto_(concepto);
      if (typeof p.primaVac === 'number') g.vac += p.primaVac;
      if (typeof p.primaDom === 'number') g.dom += p.primaDom;
      if (typeof p.primaDF  === 'number') g.df  += p.primaDF;
    }
    // Compensación libre capturada en la celda (columnas Compensación_*).
    const cMonto = parseMonto(r['Compensación_monto'] || r['Compensacion_monto']);
    if (cMonto) g.comp += cMonto;
    const cConc = String(r['Compensación_concepto'] || r['Compensacion_concepto'] || '').trim();
    if (cConc && !g.compConceptos.includes(cConc)) g.compConceptos.push(cConc);
    g.ids.push(String(r.ID||''));
  }
  // Descanso proporcional a los DÍAS DE CONTRATO reales del empleado
  // (Dias_trabajo en la hoja Personal). Construyo un lookup por nombre.
  const contratoByNombre = new Map();
  (INC_STATE?.personalRows || []).forEach(r => {
    const n = _rhPersonalFullName_(r);
    if (!n) return;
    const dias = asistPanelParseDiasTrabajo_(r.Dias_trabajo || '');
    contratoByNombre.set(n, dias.size || 5);
  });
  grupos.forEach(g => {
    const N = g.workDays.size;
    const workContract = contratoByNombre.get(g.nombre) || 5;
    const restContract = Math.max(0, 7 - workContract);
    // Base + primas se devengan para TODO el personal (con o sin IMSS).
    // Alta IMSS solo decide si el monto cuenta en $ Salario reportado.
    const conImss = _empleadoAltaImss_(g.nombre);
    g.altaImss = conImss;
    g.diasTrab = N;
    g.workContract = workContract;
    g.restContract = restContract;
    g.factorLab = N;
    g.factorDes = restContract * Math.min(N / Math.max(1, workContract), 1);
    g.baseLab = ASIST_PANEL_SAL_BASE * g.factorLab;
    g.baseDes = ASIST_PANEL_SAL_BASE * g.factorDes;
    g.total = g.baseLab + g.baseDes + g.vac + g.dom + g.df + g.comp;
  });
  const allRows = Array.from(grupos.values())
    .sort((a,b) => (b.semana.lun - a.semana.lun) || a.nombre.localeCompare(b.nombre,'es'));
  // Opciones de filtro derivadas de los datos (antes de filtrar).
  const semanaOpts = Array.from(new Map(allRows.map(g => [g.semana.value, g.semana.label])).entries())
    .sort((a,b) => b[0].localeCompare(a[0]));
  const empleadoOpts = Array.from(new Set(allRows.map(g => g.nombre))).sort((a,b) => a.localeCompare(b,'es'));
  // Aplica filtros.
  const rows = allRows.filter(g => {
    if (F.semana   && g.semana.value !== F.semana)   return false;
    if (F.empleado && g.nombre       !== F.empleado) return false;
    if (F.altaImss === 'si' && !g.altaImss) return false;
    if (F.altaImss === 'no' &&  g.altaImss) return false;
    return true;
  });
  const filtersHtml = `
    <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:end;padding:10px 12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;margin-bottom:10px">
      <div style="display:flex;flex-direction:column;gap:3px;min-width:230px">
        <label style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em">Semana</label>
        <select onchange="asistResumenSetFilter('semana', this.value)" style="all:unset;padding:6px 10px;border:1.5px solid #cbd5e1;border-radius:6px;background:#fff;color:#0f172a;font-size:12px;font-weight:600;cursor:pointer">
          <option value="">— Todas —</option>
          ${semanaOpts.map(([v,l]) => `<option value="${esc(v)}"${F.semana===v?' selected':''}>${esc(l)}</option>`).join('')}
        </select>
      </div>
      <div style="display:flex;flex-direction:column;gap:3px;min-width:200px">
        <label style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em">Empleado</label>
        <select onchange="asistResumenSetFilter('empleado', this.value)" style="all:unset;padding:6px 10px;border:1.5px solid #cbd5e1;border-radius:6px;background:#fff;color:#0f172a;font-size:12px;font-weight:600;cursor:pointer">
          <option value="">— Todos —</option>
          ${empleadoOpts.map(n => `<option value="${esc(n)}"${F.empleado===n?' selected':''}>${esc(n)}</option>`).join('')}
        </select>
      </div>
      <div style="display:flex;flex-direction:column;gap:3px;min-width:160px">
        <label style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em">Alta en IMSS</label>
        <select onchange="asistResumenSetFilter('altaImss', this.value)" style="all:unset;padding:6px 10px;border:1.5px solid #cbd5e1;border-radius:6px;background:#fff;color:#0f172a;font-size:12px;font-weight:600;cursor:pointer">
          <option value="">— Todos —</option>
          <option value="si"${F.altaImss==='si'?' selected':''}>Sí</option>
          <option value="no"${F.altaImss==='no'?' selected':''}>No</option>
        </select>
      </div>
      ${(F.semana||F.empleado||F.altaImss) ? `<button type="button" onclick="asistResumenClearFilters()" style="all:unset;cursor:pointer;padding:6px 12px;background:#fee2e2;border:1.5px solid #fca5a5;border-radius:6px;font-size:11px;font-weight:800;color:#991b1b">Limpiar filtros</button>` : ''}
      <div style="margin-left:auto;font-size:11px;color:#64748b;font-weight:700">${rows.length} de ${allRows.length} renglones</div>
    </div>`;
  if (!rows.length) {
    wrap.innerHTML = toolbarHtml + filtersHtml + `<div style="text-align:center;padding:60px;color:#94a3b8;font-size:13px">${allRows.length ? 'Ningún renglón coincide con los filtros.' : 'Sin registros aún.'}</div>`;
    return;
  }
  // Aplica overrides manuales de Concepto y $ Compensación (si existen).
  rows.forEach(g => {
    const ov = _rhResOverrideGet_(g.nombre, g.semana.value);
    if (ov.monto != null) {
      g.compOverride = ov.monto;
      g.total = g.baseLab + g.baseDes + g.vac + g.dom + g.df + ov.monto;
    }
    if (ov.concepto) g.conceptoOverride = ov.concepto;
  });
  // Estilos tipo tabla de "Control de asistencias" — header oscuro, sticky.
  const th = (label, width) => `<th style="position:sticky;top:0;z-index:5;background:#1e293b;color:#fff;padding:9px 10px;text-align:left;font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap${width?`;width:${width}`:''}">${label}</th>`;
  const thNum = (label, width) => `<th style="position:sticky;top:0;z-index:5;background:#1e293b;color:#fff;padding:9px 10px;text-align:right;font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap${width?`;width:${width}`:''}">${label}</th>`;
  // Acciones y Empleado son sticky-left → sobreviven al scroll horizontal.
  // z-index más alto (7) que el resto de th sticky-top (5) para que ganen en la esquina.
  const thAcc = `<th style="position:sticky;top:0;left:0;z-index:7;background:#1e293b;color:#fff;padding:9px 8px;text-align:center;font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap;width:80px;min-width:80px">Acciones</th>`;
  const thEmpleado = `<th style="position:sticky;top:0;left:80px;z-index:7;background:#1e293b;color:#fff;padding:9px 10px;text-align:left;font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap;width:170px;min-width:170px;box-shadow:2px 0 4px rgba(15,23,42,.12)">Empleado</th>`;
  const td = (v, extraStyle) => `<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;color:#1f2937;white-space:nowrap${extraStyle?';'+extraStyle:''}">${v}</td>`;
  const tdNum = (v, extraStyle) => `<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;text-align:right;font-weight:700;color:#0f172a;white-space:nowrap${extraStyle?';'+extraStyle:''}">${v}</td>`;
  const tdAcc = (g) => {
    const editing = ASIST_RESUMEN_EDIT.has(_rhResRowKey_(g));
    const btnStyle = 'display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;border-radius:5px;font-weight:800;font-size:12px;line-height:1;cursor:pointer;border:1px solid';
    const rowKey = _rhResRowKey_(g);
    let btns;
    if (editing) {
      btns = `
        <button type="button" title="Guardar" onclick="asistResumenGuardarEdit('${esc(rowKey)}')" style="${btnStyle} #86efac;background:#dcfce7;color:#166534">✓</button>
        <button type="button" title="Cancelar" onclick="asistResumenCancelarEdit('${esc(rowKey)}')" style="${btnStyle} #fecaca;background:#fee2e2;color:#b91c1c">✕</button>`;
    } else {
      const pencil = `<button type="button" title="Editar compensación" onclick="asistResumenAbrirEdit('${esc(rowKey)}')" style="${btnStyle} #fde68a;background:#fef3c7;color:#92400e">✎</button>`;
      const del    = `<button type="button" title="Eliminar todos los renglones de este grupo" onclick="asistResumenEliminarGrupo('${g.ids.join(',')}')" style="${btnStyle} #fecaca;background:#fee2e2;color:#b91c1c">✕</button>`;
      btns = pencil + del;
    }
    return `<td style="position:sticky;left:0;z-index:2;background:#fff;padding:6px 4px;text-align:center;vertical-align:middle;border-bottom:1px solid #f1f5f9;width:80px;min-width:80px"><div style="display:inline-flex;align-items:center;justify-content:center;gap:4px">${btns}</div></td>`;
  };
  const tdEmpleadoSticky = (nombre) => `<td style="position:sticky;left:80px;z-index:2;background:#fff;padding:8px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;color:#1f2937;white-space:nowrap;font-weight:700;width:170px;min-width:170px;box-shadow:2px 0 4px rgba(15,23,42,.08)">${esc(nombre)}</td>`;
  const fmt = n => n ? asistPanelFmtMonto_(n) : '';
  // Celda editable de Concepto compensación. En modo edit muestra input
  // texto; fuera de edit muestra el override (concepto tachado + nuevo) o
  // la concatenación original de conceptos capturados por día.
  const tdConceptoComp = (g) => {
    const editing = ASIST_RESUMEN_EDIT.has(_rhResRowKey_(g));
    const origList = (g.compConceptos||[]).join(', ');
    if (editing) {
      const cur = g.conceptoOverride != null ? g.conceptoOverride : origList;
      return `<td style="padding:6px 8px;border-bottom:1px solid #f1f5f9;white-space:nowrap;background:#fefce8">
        <input type="text" value="${esc(cur)}"
          data-resumen-edit-key="${esc(_rhResRowKey_(g))}"
          data-resumen-edit-field="concepto"
          onkeydown="if(event.key==='Enter'){event.preventDefault();asistResumenGuardarEdit('${esc(_rhResRowKey_(g))}')} if(event.key==='Escape'){asistResumenCancelarEdit('${esc(_rhResRowKey_(g))}')}"
          placeholder="—"
          style="all:unset;padding:5px 8px;border:1.5px solid #f59e0b;border-radius:5px;font-size:12px;color:#0f172a;background:#fff;box-sizing:border-box;width:100%;font-weight:700">
      </td>`;
    }
    if (g.conceptoOverride && g.conceptoOverride !== origList) {
      const orig = origList ? `<span style="text-decoration:line-through;color:#94a3b8;font-size:10.5px;font-weight:600">${esc(origList)}</span>` : '';
      const nuevo = `<span style="color:#065f46;font-weight:900">${esc(g.conceptoOverride)}</span>`;
      return `<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;white-space:nowrap;color:#0f172a">
        <div style="display:flex;flex-direction:column;gap:1px">${orig}${nuevo}</div>
      </td>`;
    }
    return td(esc(origList), 'color:#475569');
  };
  // Celda editable de $ Compensación: si hay override, tacha el original y muestra el override.
  const tdComp = (g) => {
    const editing = ASIST_RESUMEN_EDIT.has(_rhResRowKey_(g));
    if (editing) {
      const cur = g.compOverride != null ? g.compOverride : g.comp;
      return `<td style="padding:6px 8px;border-bottom:1px solid #f1f5f9;text-align:right;white-space:nowrap;background:#fefce8">
        <input type="number" step="0.01" min="0" value="${cur}"
          data-resumen-edit-key="${esc(_rhResRowKey_(g))}"
          data-resumen-edit-field="monto"
          onkeydown="if(event.key==='Enter'){event.preventDefault();asistResumenGuardarEdit('${esc(_rhResRowKey_(g))}')} if(event.key==='Escape'){asistResumenCancelarEdit('${esc(_rhResRowKey_(g))}')}"
          style="all:unset;padding:5px 8px;border:1.5px solid #f59e0b;border-radius:5px;font-size:12px;color:#0f172a;background:#fff;box-sizing:border-box;width:120px;text-align:right;font-weight:800">
      </td>`;
    }
    if (g.compOverride != null && g.compOverride !== g.comp) {
      const orig = g.comp ? `<span style="text-decoration:line-through;color:#94a3b8;font-size:10.5px;font-weight:600">${asistPanelFmtMonto_(g.comp)}</span>` : '';
      const nuevo = `<span style="color:#065f46;font-weight:900">${asistPanelFmtMonto_(g.compOverride)}</span>`;
      return `<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;text-align:right;font-size:12px;white-space:nowrap;color:#0f172a">
        <div style="display:flex;flex-direction:column;align-items:flex-end;gap:1px">${orig}${nuevo}</div>
      </td>`;
    }
    return tdNum(fmt(g.compOverride != null ? g.compOverride : g.comp));
  };
  // Columnas de pago (siempre editables inline; se auto-persisten en localStorage).
  // $ Salario reportado = Base laborado + Base descanso + Prima vacacional
  // + Prima dominical + Prima día feriado. Excluye Compensación (esa se
  // suma solo en $ Salario TOTAL).
  const tdReportado = (g) => tdNum(fmt(g.altaImss ? (g.baseLab + g.baseDes + g.vac + g.dom + g.df) : 0), 'color:#334155');
  const tdMetodo = (g) => {
    const p = _rhResPagoGet_(g.nombre, g.semana.value);
    const opts = ['Transferencia bancaria','Efectivo','Cheque','Otro'];
    const options = ['<option value=""></option>'].concat(
      opts.map(o => `<option value="${esc(o)}"${p.metodo === o ? ' selected' : ''}>${esc(o)}</option>`)
    ).join('');
    return `<td style="padding:6px 8px;border-bottom:1px solid #f1f5f9;font-size:12px;white-space:nowrap">
      <select onchange="asistResumenPagoSet('${esc(_rhResRowKey_(g))}','metodo', this.value)"
        style="all:unset;padding:5px 8px;border:1.5px solid #cbd5e1;border-radius:5px;background:#fff;color:#0f172a;font-size:12px;font-weight:600;box-sizing:border-box;width:100%;cursor:pointer">${options}</select>
    </td>`;
  };
  const tdFecha = (g) => {
    const p = _rhResPagoGet_(g.nombre, g.semana.value);
    return `<td style="padding:6px 8px;border-bottom:1px solid #f1f5f9;font-size:12px;white-space:nowrap">
      <input type="date" value="${esc(p.fecha || '')}"
        onchange="asistResumenPagoSet('${esc(_rhResRowKey_(g))}','fecha', this.value)"
        style="all:unset;padding:5px 8px;border:1.5px solid #cbd5e1;border-radius:5px;background:#fff;color:#0f172a;font-size:12px;font-weight:600;box-sizing:border-box;width:100%;cursor:pointer">
    </td>`;
  };
  const tdEstado = (g) => {
    const p = _rhResPagoGet_(g.nombre, g.semana.value);
    const pagado = !!p.fecha;
    const chip = pagado
      ? `<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:800;font-size:11px;border:1px solid #86efac">✓ Pagado</span>`
      : `<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:#fef3c7;color:#92400e;font-weight:800;font-size:11px;border:1px solid #fde68a">⏳ Pendiente</span>`;
    return `<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;text-align:center;white-space:nowrap">${chip}</td>`;
  };
  const tdAltaImss = (g) => {
    const chip = g.altaImss
      ? `<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:800;font-size:11px;border:1px solid #86efac">✓ Sí</span>`
      : `<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:#fee2e2;color:#991b1b;font-weight:800;font-size:11px;border:1px solid #fca5a5">✕ No</span>`;
    return `<td style="padding:8px 10px;border-bottom:1px solid #f1f5f9;text-align:center;white-space:nowrap">${chip}</td>`;
  };
  const tdComentarios = (g) => {
    const p = _rhResPagoGet_(g.nombre, g.semana.value);
    return `<td style="padding:6px 8px;border-bottom:1px solid #f1f5f9;font-size:12px;white-space:nowrap">
      <input type="text" value="${esc(p.comentarios || '')}"
        oninput="asistResumenPagoSet('${esc(_rhResRowKey_(g))}','comentarios', this.value)"
        placeholder="—"
        style="all:unset;padding:5px 8px;border:1.5px solid #cbd5e1;border-radius:5px;background:#fff;color:#0f172a;font-size:12px;box-sizing:border-box;width:100%">
    </td>`;
  };
  const body = rows.map(g => `<tr data-resumen-row-key="${esc(_rhResRowKey_(g))}" style="transition:background .12s">
    ${tdAcc(g)}
    ${tdEmpleadoSticky(g.nombre)}
    ${tdAltaImss(g)}
    ${td(esc(g.semana.label), 'color:#475569')}
    ${tdNum(fmtHoras(g.horas))}
    ${tdNum(fmt(g.baseLab))}
    ${tdNum(fmt(g.baseDes))}
    ${tdNum(fmt(g.vac))}
    ${tdNum(fmt(g.dom))}
    ${tdNum(fmt(g.df))}
    ${tdConceptoComp(g)}
    ${tdComp(g)}
    ${tdReportado(g)}
    ${tdNum(fmt(g.total), 'color:#065f46;font-weight:900')}
    ${tdMetodo(g)}
    ${tdFecha(g)}
    ${tdEstado(g)}
    ${tdComentarios(g)}
  </tr>`).join('');
  wrap.innerHTML = toolbarHtml + filtersHtml + `<div style="background:#fff;border:1px solid #e2e8f0;border-radius:12px;overflow:auto;max-height:calc(100vh - 320px)"><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr>
    ${thAcc}${thEmpleado}${th('Alta en IMSS', '120px')}${th('Semana', '210px')}${thNum('Horas', '70px')}${thNum('$ Base laborado', '105px')}${thNum('$ Base descanso', '105px')}${thNum('$ Prima vac. (25%)', '100px')}${thNum('$ Prima dom. (25%)', '100px')}${thNum('$ Prima feriado (200%)', '115px')}${th('Concepto compensación', '170px')}${thNum('$ Compensación', '105px')}${thNum('$ Salario reportado', '115px')}${thNum('$ Salario TOTAL', '120px')}${th('Método de pago', '180px')}${th('Fecha de pago', '150px')}${th('Estado de pago', '120px')}${th('Comentarios', '220px')}
  </tr></thead><tbody>${body}</tbody></table></div>`;
}
// Handlers de filtros de la tabla del Resumen.
window.asistResumenSetFilter = function (field, value) {
  if (typeof ASIST_RESUMEN_FILTERS === 'undefined') window.ASIST_RESUMEN_FILTERS = { semana:'', empleado:'', altaImss:'' };
  ASIST_RESUMEN_FILTERS[field] = value || '';
  asistRenderResumen('rh-view');
};
window.asistResumenClearFilters = function () {
  window.ASIST_RESUMEN_FILTERS = { semana:'', empleado:'', altaImss:'' };
  asistRenderResumen('rh-view');
};
window.asistRenderResumen = asistRenderResumen;

// ── Edición en línea de la Compensación en la tabla del Resumen ───
// Override manual del monto sumado. Se persiste en localStorage por
// (empleado, semana). Si el valor difiere de la suma original se muestra
// el original tachado.
const ASIST_RESUMEN_EDIT = new Set(); // keys en modo edición
function _rhResRowKey_(g) { return `${g.nombre}||${g.semana.value}`; }
// Overrides de Concepto + $ Compensación viven en RH_Pagos_Semanal (misma
// hoja que Método/Fecha/Comentarios). Se persisten vía _rhResPagoSet_.
function _rhResOverrideGet_(nombre, semanaValue) {
  const p = _rhResPagoGet_(nombre, semanaValue);
  const rawMonto = String(p.compOverride || '').trim();
  const monto = rawMonto === '' ? null : Number(rawMonto);
  return {
    concepto: String(p.conceptoOverride || ''),
    monto: (monto != null && Number.isFinite(monto)) ? monto : null,
  };
}
function _rhResOverrideSet_(nombre, semanaValue, patch) {
  const send = {};
  if (Object.prototype.hasOwnProperty.call(patch, 'concepto')) {
    send.conceptoOverride = patch.concepto == null ? '' : String(patch.concepto);
  }
  if (Object.prototype.hasOwnProperty.call(patch, 'monto')) {
    send.compOverride = (patch.monto == null || patch.monto === '') ? '' : String(Number(patch.monto) || 0);
  }
  _rhResPagoSet_(nombre, semanaValue, send);
}
window.asistResumenAbrirEdit = function (rowKey) {
  ASIST_RESUMEN_EDIT.add(rowKey);
  asistRenderResumen('rh-view');
  // Focus + select el input de Concepto (viene primero); si no existe, monto.
  setTimeout(() => {
    const inp = document.querySelector(`input[data-resumen-edit-key="${rowKey}"][data-resumen-edit-field="concepto"]`)
             || document.querySelector(`input[data-resumen-edit-key="${rowKey}"][data-resumen-edit-field="monto"]`);
    if (inp) { inp.focus(); inp.select(); }
  }, 30);
};
window.asistResumenCancelarEdit = function (rowKey) {
  ASIST_RESUMEN_EDIT.delete(rowKey);
  asistRenderResumen('rh-view');
};
window.asistResumenGuardarEdit = function (rowKey) {
  const inpMonto = document.querySelector(`input[data-resumen-edit-key="${rowKey}"][data-resumen-edit-field="monto"]`);
  const inpConcepto = document.querySelector(`input[data-resumen-edit-key="${rowKey}"][data-resumen-edit-field="concepto"]`);
  if (!inpMonto && !inpConcepto) { ASIST_RESUMEN_EDIT.delete(rowKey); asistRenderResumen('rh-view'); return; }
  const [nombre, semanaValue] = rowKey.split('||');
  const patch = {};
  if (inpMonto)    patch.monto    = Number(String(inpMonto.value).replace(/[^0-9.-]/g,'')) || 0;
  if (inpConcepto) patch.concepto = String(inpConcepto.value || '').trim();
  _rhResOverrideSet_(nombre, semanaValue, patch);
  ASIST_RESUMEN_EDIT.delete(rowKey);
  asistRenderResumen('rh-view');
};
// Limpia AMBOS overrides (vuelve a mostrar el concepto y suma original).
window.asistResumenLimpiarOverride = function (nombre, semanaValue) {
  _rhResOverrideSet_(nombre, semanaValue, { concepto: '', monto: null });
  asistRenderResumen('rh-view');
};

// ── Datos de pago semanal (Método / Fecha / Comentarios) ──────────────
// Persistidos en localStorage por (empleado, semana). Estado se deriva
// de si hay Fecha de pago capturada. Cambios se auto-guardan al vuelo
// sin necesidad de entrar a modo edición.
// Cache en memoria (sheet-backed). Poblado por rhLoadPagosSemanal(). Fallback
// a localStorage si el fetch aún no completó — así el UI no muestra vacío
// mientras carga y sigue funcionando offline.
if (typeof RH_PAGOS_SEMANAL_CACHE === 'undefined') {
  window.RH_PAGOS_SEMANAL_CACHE = new Map(); // key "nombre||semanaValue" → { metodo, fecha, comentarios }
  window.RH_PAGOS_SEMANAL_LOADED = false;
  window.RH_PAGOS_SEMANAL_SAVE_TIMERS = new Map();  // debounce por rowKey
}
function _rhResPagoKey_(nombre, semanaValue) {
  return `${nombre}||${semanaValue}`;
}
function _rhResPagoGet_(nombre, semanaValue) {
  const k = _rhResPagoKey_(nombre, semanaValue);
  const mem = RH_PAGOS_SEMANAL_CACHE.get(k);
  const shape = {
    metodo:'', fecha:'', comentarios:'',
    conceptoOverride:'', compOverride:'',
  };
  if (mem) return {
    metodo: mem.metodo || '',
    fecha: mem.fecha || '',
    comentarios: mem.comentarios || '',
    conceptoOverride: mem.conceptoOverride || '',
    compOverride: mem.compOverride || '',
  };
  // Fallback: localStorage legacy (rh_resumen_pago:...) para no perder
  // datos guardados antes de la migración a sheet.
  try {
    const raw = localStorage.getItem(`rh_resumen_pago:${k}`);
    if (!raw) return shape;
    const obj = JSON.parse(raw);
    return {
      metodo: String(obj?.metodo || ''),
      fecha:  String(obj?.fecha  || ''),
      comentarios: String(obj?.comentarios || ''),
      conceptoOverride: String(obj?.conceptoOverride || ''),
      compOverride: String(obj?.compOverride || ''),
    };
  } catch(_) { return shape; }
}
async function rhLoadPagosSemanal(opts = {}) {
  if (RH_PAGOS_SEMANAL_LOADED && !opts.force) return;
  try {
    const res = await fetch(`${BACKEND}/rh/pagos-semanal?_cb=${Date.now()}`, { cache: 'no-store' });
    const data = await res.json();
    if (data && data.ok && Array.isArray(data.rows)) {
      RH_PAGOS_SEMANAL_CACHE.clear();
      for (const r of data.rows) {
        const k = _rhResPagoKey_(String(r.Empleado_Nombre || '').trim(), String(r.Semana || '').trim());
        RH_PAGOS_SEMANAL_CACHE.set(k, {
          metodo: String(r.Metodo_pago || ''),
          fecha:  String(r.Fecha_pago  || ''),
          comentarios: String(r.Comentarios || ''),
          conceptoOverride: String(r.Concepto_compensacion_override || ''),
          compOverride: String(r.Compensacion_override || ''),
        });
      }
      RH_PAGOS_SEMANAL_LOADED = true;
    }
  } catch (e) { console.warn('[RH] pagos-semanal:', e.message); }
}
async function _rhResPagoUpsertRemote_(nombre, semanaValue) {
  const k = _rhResPagoKey_(nombre, semanaValue);
  const cur = RH_PAGOS_SEMANAL_CACHE.get(k) || {};
  try {
    const res = await fetch(`${BACKEND}/rh/pagos-semanal`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        payload: {
          Empleado_Nombre: nombre,
          Semana: semanaValue,
          Metodo_pago: cur.metodo || '',
          Fecha_pago:  cur.fecha  || '',
          Comentarios: cur.comentarios || '',
          Concepto_compensacion_override: cur.conceptoOverride || '',
          Compensacion_override: cur.compOverride || '',
        }
      }),
    });
    const data = await res.json();
    if (!data || !data.ok) throw new Error((data && data.error) || 'save failed');
  } catch (e) { console.warn('[RH] pago-semanal save:', e.message); }
}
function _rhResPagoSet_(nombre, semanaValue, patch) {
  const k = _rhResPagoKey_(nombre, semanaValue);
  const cur = RH_PAGOS_SEMANAL_CACHE.get(k) || {};
  const next = { ...cur, ...patch };
  RH_PAGOS_SEMANAL_CACHE.set(k, next);
  // Cache local espejo (para offline/desconectado).
  try { localStorage.setItem(`rh_resumen_pago:${k}`, JSON.stringify(next)); } catch(_){}
  // Debounce por rowKey — comentarios se escriben letra a letra, no queremos
  // spammear Apps Script. 500 ms tras la última tecla persiste.
  const prev = RH_PAGOS_SEMANAL_SAVE_TIMERS.get(k);
  if (prev) clearTimeout(prev);
  RH_PAGOS_SEMANAL_SAVE_TIMERS.set(k, setTimeout(() => {
    RH_PAGOS_SEMANAL_SAVE_TIMERS.delete(k);
    _rhResPagoUpsertRemote_(nombre, semanaValue);
  }, 500));
}
window.asistResumenPagoSet = function (rowKey, field, value) {
  const [nombre, semanaValue] = rowKey.split('||');
  _rhResPagoSet_(nombre, semanaValue, { [field]: value });
  // Re-render solo si cambia el estado (fecha entra/sale) para no perder
  // el foco del input mientras el usuario escribe comentarios/métodos.
  // Fecha y Método sí cambian el chip "Pagado/Pendiente" → repintamos.
  if (field === 'fecha' || field === 'metodo') {
    // Actualiza solo el chip de esa fila.
    try {
      const tr = document.querySelector(`tr[data-resumen-row-key="${rowKey}"]`);
      if (tr) {
        // Estado de pago está en td[16]. Orden: 0 acc, 1 empleado, 2 alta IMSS,
        // 3 semana, 4 horas, 5 baseLab, 6 baseDes, 7 vac, 8 dom, 9 df,
        // 10 conceptoComp, 11 comp, 12 reportado, 13 total, 14 método,
        // 15 fecha, 16 estado, 17 comentarios.
        const chip = tr.querySelectorAll('td')[16];
        const p = _rhResPagoGet_(nombre, semanaValue);
        const pagado = !!p.fecha;
        chip.innerHTML = pagado
          ? `<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:#dcfce7;color:#166534;font-weight:800;font-size:11px;border:1px solid #86efac">✓ Pagado</span>`
          : `<span style="display:inline-flex;align-items:center;gap:5px;padding:4px 10px;border-radius:999px;background:#fef3c7;color:#92400e;font-weight:800;font-size:11px;border:1px solid #fde68a">⏳ Pendiente</span>`;
      }
    } catch(_){}
  }
};

// Acciones del resumen: saltar a la tabla filtrando los IDs, o borrar el grupo.
window.asistResumenIrATabla = function (idsCsv) {
  const ids = new Set(idsCsv.split(','));
  asistSetVis('tabla');
  const tbody = document.querySelector('#asist-tabla-wrap tbody');
  if (!tbody) return;
  const first = Array.from(tbody.querySelectorAll('tr')).find(tr => ids.has(tr.dataset.asistId));
  if (first) first.scrollIntoView({ block:'center' });
};

window.asistResumenEliminarGrupo = async function (idsCsv) {
  const ids = idsCsv.split(',').filter(Boolean);
  if (!ids.length) return;
  if (!confirm(`¿Eliminar los ${ids.length} registros de este grupo? No se puede deshacer.`)) return;
  // Detecta el contenedor activo: puede ser Nómina (#rh-view) o Control
  // de asistencias (#asist-resumen-wrap). Sin esta detección el UI no
  // se re-pintaba desde Nómina y parecía que el botón no hacía nada.
  const isNomina = !!document.getElementById('rh-view') && !document.getElementById('rh-section-nomina')?.classList.contains('hidden');
  const targetId = isNomina ? 'rh-view' : 'asist-resumen-wrap';
  asistStatusTabla('⏳ Eliminando…');
  let ok = 0, err = 0;
  // force=true: el usuario ya confirmó el DELETE del grupo entero; sin
  // esto, los registros con Metodo=WhatsApp fallan por la protección del
  // Apps Script.
  for (const id of ids) {
    try {
      const res = await fetch(`${BACKEND}/rh/asistencia/${encodeURIComponent(id)}?force=true&reason=${encodeURIComponent('resumen semanal: eliminar grupo')}&actor=admin`, { method:'DELETE' });
      const j = await res.json();
      if (j.ok) ok++; else err++;
    } catch { err++; }
  }
  asistStatusTabla(err ? `✓ ${ok} eliminados, ✗ ${err} con error` : `✓ ${ok} eliminados`);
  setTimeout(() => asistStatusTabla(''), 2500);
  await asistReloadList();
  asistRenderResumen(targetId);
  // Si hay error, avisamos al usuario porque el status inline solo existe
  // en Control de asistencias — desde Nómina no se ve.
  if (err && isNomina) alert(`✕ ${err} registros no se pudieron eliminar. Revisa consola.`);
};

// ── Modo Seleccionar — estilo idéntico a Guías: chip con span palomita 18x18 ──
window.asistToggleSeleccionar = function () {
  ASIST_STATE.seleccionar = !ASIST_STATE.seleccionar;
  const btn = document.getElementById('asist-btn-seleccionar');
  const btnDel = document.getElementById('asist-btn-eliminar');
  const check = btn?.querySelector('.asist-sel-check');
  if (ASIST_STATE.seleccionar) {
    if (btn) { btn.style.background = '#0d9488'; btn.style.color = '#fff'; }
    if (check) { check.style.borderColor = '#fff'; check.style.background = '#fff'; check.style.color = '#0d9488'; check.textContent = '✓'; }
    btnDel?.classList.remove('hidden');
  } else {
    if (btn) { btn.style.background = '#f1f5f9'; btn.style.color = '#475569'; }
    if (check) { check.style.borderColor = '#cbd5e1'; check.style.background = '#fff'; check.style.color = '#0d9488'; check.textContent = ''; }
    btnDel?.classList.add('hidden');
    ASIST_STATE.selected.clear();
  }
  asistUpdateSelBanner();
  asistRenderTabla();
};

/** Genera un checkbox estilo "palomita" (span 18x18 con ✓) — nunca native. */
function asistSelBox(checked, onclickCall) {
  const bg = checked ? '#0d9488' : '#fff';
  const border = checked ? '#0d9488' : '#cbd5e1';
  const fg = checked ? '#fff' : 'transparent';
  return `<span onclick="${onclickCall}" style="display:inline-flex;align-items:center;justify-content:center;width:18px;height:18px;border-radius:4px;border:1.5px solid ${border};background:${bg};color:${fg};font-size:12px;font-weight:900;flex-shrink:0;line-height:1;cursor:pointer">✓</span>`;
}

window.asistToggleRowSel = function (id, checked) {
  if (checked) ASIST_STATE.selected.add(id);
  else ASIST_STATE.selected.delete(id);
  asistUpdateSelBanner();
  asistRenderTabla();
};

window.asistSelectAll = function (checked) {
  if (checked) {
    for (const r of asistSortedRows()) ASIST_STATE.selected.add(String(r.ID||''));
  } else {
    ASIST_STATE.selected.clear();
  }
  asistUpdateSelBanner();
  asistRenderTabla();
};

function asistUpdateSelBanner() {
  const n = ASIST_STATE.selected.size;
  if (n) asistStatusTabla(`☑️ ${n} fila${n===1?'':'s'} seleccionada${n===1?'':'s'}`, 'warn');
  else asistStatusTabla('');
}

window.asistEliminarSeleccion = async function () {
  const ids = Array.from(ASIST_STATE.selected);
  if (!ids.length) { alert('No hay filas seleccionadas.'); return; }
  if (!confirm(`¿Eliminar ${ids.length} registro${ids.length===1?'':'s'} de asistencia? Esta acción no se puede deshacer.`)) return;
  asistStatusTabla('⏳ Eliminando…');
  let ok = 0, err = 0;
  for (const id of ids) {
    try {
      const res = await fetch(`${BACKEND}/rh/asistencia/${encodeURIComponent(id)}`, { method:'DELETE' });
      const j = await res.json();
      if (j.ok) { ok++; ASIST_STATE.selected.delete(id); }
      else err++;
    } catch (e) { err++; }
  }
  await asistReloadList();
  if (err) asistStatusTabla(`⚠ ${ok} eliminadas · ${err} con error`, 'warn');
  else asistStatusTabla(`✓ ${ok} registro${ok===1?'':'s'} eliminado${ok===1?'':'s'}`);
  setTimeout(() => asistStatusTabla(''), 3500);
};

async function asistReloadList() {
  // Coalesce: si ya hay una carga en vuelo, devolvemos esa promesa para
  // evitar dobles fetch al abrir Nómina + Control asistencias simultáneo.
  if (ASIST_STATE._reloadPromise) return ASIST_STATE._reloadPromise;
  const wrap = document.getElementById('asist-tabla-wrap');
  if (wrap) wrap.innerHTML = `<div style="text-align:center;padding:60px;color:#94a3b8;font-size:13px">⏳ Cargando registros…</div>`;
  ASIST_STATE.loading = true;
  ASIST_STATE._reloadPromise = (async () => {
  try {
    // Retry up to 3 veces con backoff — el backend a veces retorna
    // {ok:false, raw:<html>} cuando Apps Script tiene un glitch transitorio.
    let j = null; let lastErr = '';
    for (let a = 0; a < 3; a++) {
      const res = await fetch(`${BACKEND}/rh/asistencia?_cb=${Date.now()}`, { cache: 'no-store' });
      j = await res.json();
      if (j.ok) break;
      lastErr = j.error || j.message || 'respuesta sin ok';
      if (a < 2) await new Promise(r => setTimeout(r, 1000 * (a + 1)));
    }
    if (!j || !j.ok) throw new Error(lastErr || 'fetch falló tras 3 intentos');
    ASIST_STATE.rows = Array.isArray(j.rows) ? j.rows : [];
    ASIST_STATE.headers = Array.isArray(j.headers) && j.headers.length
      ? j.headers
      : (ASIST_STATE.rows[0] ? Object.keys(ASIST_STATE.rows[0]) : []);
    ASIST_STATE.loaded = true;
    asistStatusTabla('');
    // Modelo unificado: renderiza AMBAS vistas (Calendario arriba + Tabla
    // abajo). El Resumen se maneja aparte porque vive en la sección Nómina.
    if (ASIST_STATE.vis === 'resumen') { asistRenderResumen(); }
    else { asistRenderCalendar(); asistRenderTabla(); }
    const c = document.getElementById('asist-list-count');
    if (c) c.textContent = `${ASIST_STATE.rows.length} registro${ASIST_STATE.rows.length===1?'':'s'}`;
  } catch (e) {
    if (wrap) wrap.innerHTML = `<div style="text-align:center;padding:60px;color:#dc2626;font-size:13px">✗ Error: ${esc(e.message||String(e))}</div>`;
  } finally {
    ASIST_STATE.loading = false;
  }
  })();
  try { return await ASIST_STATE._reloadPromise; }
  finally { ASIST_STATE._reloadPromise = null; }
}
window.asistReloadList = asistReloadList;

// ── Filtros globales de Control de asistencias ───────────────────────
// Estado en memoria { nombre, mes (YYYY-MM), concepto }. Se aplican
// simultáneamente al calendario y a la tabla.
function asistFilters_() {
  if (!ASIST_STATE.filters) ASIST_STATE.filters = { nombre:'', mes:'', concepto:'' };
  return ASIST_STATE.filters;
}
function asistFiltersSyncCalMonth_() {
  const F = asistFilters_();
  if (!F.mes) return;
  const m = F.mes.match(/^(\d{4})-(\d{2})$/);
  if (!m) return;
  const y = Number(m[1]), mo = Number(m[2]) - 1;
  const cur = ASIST_STATE.calMonth;
  if (!cur || cur.getFullYear() !== y || cur.getMonth() !== mo) {
    ASIST_STATE.calMonth = new Date(y, mo, 1);
    ASIST_STATE._focusMode = 'month';
  }
}
function asistRenderFiltersBar_() {
  const bar = document.getElementById('asist-filters-bar');
  if (!bar) return;
  const F = asistFilters_();
  // Opciones dinámicas desde los datos actuales. Reconciliamos nombres
  // cortos (p.ej. "Adán") al canonical del Personal (p.ej. "Adán Ramos")
  // para no duplicar la persona en el dropdown.
  const _personal = asistPersonalOperativo();
  const _aliasCanon = _asistBuildAliasMap_(_personal);
  const _toCanon = (raw) => {
    const t = String(raw||'').trim(); if (!t) return t;
    return _aliasCanon.get(_normNombre_(t)) || t;
  };
  const nombres = Array.from(new Set(
    _personal.map(x => x.nombre)
      .concat((ASIST_STATE.rows||[]).map(r => _toCanon(String(r.Empleado_Nombre||'').trim())))
      .filter(n => n && !asistEsSinSalario_(n))
  )).sort((a,b)=>a.localeCompare(b,'es'));
  // Meses: derivados de las fechas presentes en los registros + 6 meses
  // hacia atrás/adelante desde hoy.
  const mesesSet = new Set();
  const now = new Date();
  for (let d = -6; d <= 6; d++) {
    const dt = new Date(now.getFullYear(), now.getMonth() + d, 1);
    mesesSet.add(`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}`);
  }
  (ASIST_STATE.rows||[]).forEach(r => {
    const f = String(r.Fecha||'').slice(0,7);
    if (/^\d{4}-\d{2}$/.test(f)) mesesSet.add(f);
  });
  const meses = Array.from(mesesSet).sort((a,b)=>b.localeCompare(a));
  const NOM_MESES = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  const mesLabel = (v) => {
    const m = v.match(/^(\d{4})-(\d{2})$/);
    if (!m) return v;
    return `${NOM_MESES[Number(m[2])-1]} ${m[1]}`;
  };
  // Conceptos: los del catálogo del panel.
  const conceptos = ASIST_PANEL_CONCEPTOS.map(c => c.k);
  const hasActive = !!(F.nombre || F.mes || F.concepto);
  bar.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:3px;min-width:200px">
      <label style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em">Nombre</label>
      <select onchange="asistSetFilter('nombre', this.value)" style="all:unset;padding:6px 10px;border:1.5px solid #cbd5e1;border-radius:6px;background:#fff;color:#0f172a;font-size:12px;font-weight:600;cursor:pointer">
        <option value="">— Todos —</option>
        ${nombres.map(n => `<option value="${esc(n)}"${F.nombre===n?' selected':''}>${esc(n)}</option>`).join('')}
      </select>
    </div>
    <div style="display:flex;flex-direction:column;gap:3px;min-width:160px">
      <label style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em">Mes</label>
      <select onchange="asistSetFilter('mes', this.value)" style="all:unset;padding:6px 10px;border:1.5px solid #cbd5e1;border-radius:6px;background:#fff;color:#0f172a;font-size:12px;font-weight:600;cursor:pointer">
        <option value="">— Todos —</option>
        ${meses.map(m => `<option value="${esc(m)}"${F.mes===m?' selected':''}>${esc(mesLabel(m))}</option>`).join('')}
      </select>
    </div>
    <div style="display:flex;flex-direction:column;gap:3px;min-width:160px">
      <label style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em">Concepto</label>
      <select onchange="asistSetFilter('concepto', this.value)" style="all:unset;padding:6px 10px;border:1.5px solid #cbd5e1;border-radius:6px;background:#fff;color:#0f172a;font-size:12px;font-weight:600;cursor:pointer">
        <option value="">— Todos —</option>
        ${conceptos.map(c => `<option value="${esc(c)}"${F.concepto===c?' selected':''}>${esc(c)}</option>`).join('')}
      </select>
    </div>
    ${hasActive ? `<button type="button" onclick="asistClearFilters()" style="all:unset;cursor:pointer;padding:6px 12px;background:#fee2e2;border:1.5px solid #fca5a5;border-radius:6px;font-size:11px;font-weight:800;color:#991b1b">Limpiar filtros</button>` : ''}
  `;
}
window.asistSetFilter = function (field, value) {
  const F = asistFilters_();
  F[field] = value || '';
  if (field === 'mes' && value) {
    // Sincroniza el calendario al mes elegido.
    asistFiltersSyncCalMonth_();
  }
  asistRenderCalendar();
  asistRenderTabla();
};
window.asistClearFilters = function () {
  ASIST_STATE.filters = { nombre:'', mes:'', concepto:'' };
  asistRenderCalendar();
  asistRenderTabla();
};

function asistStatusTabla(html, kind) {
  const el = document.getElementById('asist-status-tabla');
  if (!el) return;
  if (!html) { el.innerHTML = ''; el.style.display = 'none'; return; }
  el.style.display = 'block';
  el.style.color = kind === 'err' ? '#991b1b' : kind === 'warn' ? '#92400e' : '#065f46';
  el.innerHTML = html;
}

function asistSortedRows() {
  // Aplica filtros globales de Control de asistencias (nombre / mes / concepto).
  const F = asistFilters_();
  let rows = (ASIST_STATE.rows || []).slice().filter(r => !asistEsSinSalario_(r.Empleado_Nombre));
  if (F.nombre) {
    // Reconciliamos nombres cortos (p.ej. "Adán") al canonical del Personal
    // (p.ej. "Adán Ramos") para que el filtro atrape ambas variantes.
    const _personal = asistPersonalOperativo();
    const _alias = _asistBuildAliasMap_(_personal);
    const _canon = (raw) => {
      const t = String(raw||'').trim(); if (!t) return t;
      return _alias.get(_normNombre_(t)) || t;
    };
    const target = _canon(F.nombre);
    rows = rows.filter(r => _canon(String(r.Empleado_Nombre||'').trim()) === target);
  }
  if (F.mes) rows = rows.filter(r => String(r.Fecha||'').slice(0,7) === F.mes);
  if (F.concepto) {
    rows = rows.filter(r => {
      const c = asistPanelNormalizarConceptoLegado_(String(r.Concepto||'').trim() || ((String(r.Entrada||'').trim() || String(r.Salida||'').trim()) ? 'Regular' : ''));
      return c === F.concepto;
    });
  }
  // Default: si el usuario no ha elegido explícitamente un sortKey,
  // ordena por Fecha descendente (más reciente primero).
  const key = ASIST_STATE.sortKey || 'Fecha';
  const dir = ASIST_STATE.sortDir === 'asc'
    ? 1
    : (ASIST_STATE.sortDir === 'desc' || !ASIST_STATE.sortKey ? -1 : 1);
  return rows.sort((a, b) => {
    const va = String(a[key] ?? '');
    const vb = String(b[key] ?? '');
    // Numérico si ambos parsean a número
    const na = Number(va), nb = Number(vb);
    if (Number.isFinite(na) && Number.isFinite(nb) && va !== '' && vb !== '') return (na - nb) * dir;
    return va.localeCompare(vb, 'es', { numeric: true }) * dir;
  });
}

window.asistSortBy = function (col) {
  if (ASIST_STATE.sortKey === col) {
    ASIST_STATE.sortDir = ASIST_STATE.sortDir === 'asc' ? 'desc' : 'asc';
  } else {
    ASIST_STATE.sortKey = col;
    ASIST_STATE.sortDir = 'asc';
  }
  asistRenderTabla();
};

/** Índice (empleado|fecha) → { entrada, salida, horas } derivados de los rows. */
function asistBuildDayIndex_() {
  const idx = new Map();
  for (const r of ASIST_STATE.rows) {
    const nombre = String(r.Empleado_Nombre||'').trim();
    const fecha  = String(r.Fecha||'').slice(0,10);
    const tipo   = String(r.Tipo||'').toLowerCase();
    if (!nombre || !fecha) continue;
    const k = `${nombre}|${fecha}`;
    let d = idx.get(k);
    if (!d) { d = { entrada:'', salida:'', horas:'' }; idx.set(k, d); }
    const hora = String(r.Hora || '').trim();
    if (tipo === 'entrada' && hora && (!d.entrada || hora < d.entrada)) d.entrada = hora;
    else if (tipo === 'salida' && hora && (!d.salida || hora > d.salida)) d.salida = hora;
  }
  // Calcula horas
  for (const d of idx.values()) {
    const ent = asistParseTimeToMinutes(d.entrada);
    const sal = asistParseTimeToMinutes(d.salida);
    if (ent != null && sal != null && sal > ent) {
      const diff = sal - ent;
      d.horas = `${Math.floor(diff/60)}h${String(diff%60).padStart(2,'0')}`;
    }
  }
  return idx;
}

/** Monto ($) que corresponde a esta fila según los conceptos derivados
 *  del registro (Tipo/Observaciones/Entrada-Salida). */
function asistRowMonto_(row) {
  const conceptos = asistDeriveConceptos_([row]);
  let n = 0;
  conceptos.forEach(k => { n += asistPanelMontoDe_(k); });
  return n;
}

/** Normaliza un timestamp a "YYYY-MM-DD HH:MM:SS" acepta:
 *  - Date object serializado como ISO
 *  - "M/D/YYYY H:MM:SS" (formato Google Sheets US)
 *  - "YYYY-MM-DD HH:MM:SS" (ya normalizado)
 *  Devuelve la cadena original si no puede parsear. */
function _asistFmtTimestamp(v) {
  if (v == null || v === '') return '';
  const s = String(v).trim();
  // Ya viene en formato YYYY-MM-DD HH:MM(:SS) — solo asegura 2 dígitos.
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[T ](\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) {
    const [_, Y, Mo, D, H, Mi, Sec] = m;
    return `${Y}-${Mo.padStart(2,'0')}-${D.padStart(2,'0')} ${H.padStart(2,'0')}:${Mi}:${(Sec||'00').padStart(2,'0')}`;
  }
  // Formato US: "M/D/YYYY H:MM:SS"
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2})(?::(\d{2}))?/);
  if (m) {
    const [_, Mo, D, Y, H, Mi, Sec] = m;
    return `${Y}-${Mo.padStart(2,'0')}-${D.padStart(2,'0')} ${H.padStart(2,'0')}:${Mi}:${(Sec||'00').padStart(2,'0')}`;
  }
  // Intento último: Date parse
  const d = new Date(s);
  if (!isNaN(d.getTime())) {
    const pad = n => String(n).padStart(2,'0');
    return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
  }
  return s;
}

/** Devuelve el valor de una columna para un row, incluye columnas derivadas. */
function asistCellValue(row, col, dayIdx) {
  if (col === 'Timestamp') return _asistFmtTimestamp(row[col]);
  if (col === 'Entrada' || col === 'Salida' || col === 'Horas') {
    const nombre = String(row.Empleado_Nombre||'').trim();
    const fecha  = String(row.Fecha||'').slice(0,10);
    const d = dayIdx.get(`${nombre}|${fecha}`);
    const legacy = String(row[col] || '');
    // Normaliza "H:MM" → "HH:MM" (input type=time exige 2 dígitos de hora).
    const norm = s => { const m = String(s||'').match(/^(\d{1,2}):(\d{2})/); return m ? String(m[1]).padStart(2,'0') + ':' + m[2] : ''; };
    if (col === 'Entrada') return norm(d?.entrada || legacy);
    if (col === 'Salida')  return norm(d?.salida  || legacy);
    if (col === 'Horas') {
      // Horas SIEMPRE = Salida − Entrada (real, no la string guardada,
      // que suele ser un default hardcodeado tipo "5h00"). Solo si no
      // hay Entrada+Salida coherentes se cae al string almacenado.
      const entStr = norm(d?.entrada || row.Entrada || '');
      const salStr = norm(d?.salida  || row.Salida  || '');
      const ent = asistParseTimeToMinutes(entStr);
      const sal = asistParseTimeToMinutes(salStr);
      if (ent != null && sal != null && sal > ent) {
        const diff = sal - ent;
        return `${Math.floor(diff/60)}h${String(diff%60).padStart(2,'0')}`;
      }
      return d?.horas || legacy || '';
    }
  }
  if (ASIST_PRIMA_COLS.includes(col)) {
    const conceptos = asistDeriveConceptos_([row]);
    const primary = conceptos.values().next().value;
    const p = asistPanelPrimasPorConcepto_(primary);
    const fmt = v => v === '' ? '' : asistPanelFmtMonto_(v);
    if (col === '$ Salario base')             return fmt(p.salBase);
    if (col === '$ Prima vacacional (25%)')   return fmt(p.primaVac);
    if (col === '$ Prima dominical (25%)')    return fmt(p.primaDom);
    if (col === '$ Prima día feriado (200%)') return fmt(p.primaDF);
  }
  if (col === ASIST_TOTAL_COL) {
    const conceptos = asistDeriveConceptos_([row]);
    const primary = conceptos.values().next().value;
    const p = asistPanelPrimasPorConcepto_(primary);
    const total = ['salBase','primaVac','primaDom','primaDF']
      .reduce((s,k) => s + (typeof p[k] === 'number' ? p[k] : 0), 0);
    return total ? asistPanelFmtMonto_(total) : '';
  }
  // Columnas virtuales de ubicación:
  //   'Ubicación entrada' ← Ubicacion_Lat / Ubicacion_Lng
  //   'Ubicación salida'  ← Ubicacion_Salida_Lat / Ubicacion_Salida_Lng
  if (col === 'Ubicación entrada' || col === 'Ubicación' || col === 'Ubicacion') {
    const la = row.Ubicacion_Lat, ln = row.Ubicacion_Lng;
    if (la == null || la === '' || ln == null || ln === '') return '';
    return `${Number(la).toFixed(6)}, ${Number(ln).toFixed(6)}`;
  }
  if (col === 'Ubicación salida') {
    const la = row.Ubicacion_Salida_Lat, ln = row.Ubicacion_Salida_Lng;
    if (la == null || la === '' || ln == null || ln === '') return '';
    return `${Number(la).toFixed(6)}, ${Number(ln).toFixed(6)}`;
  }
  const raw = row[col] == null ? '' : String(row[col]);
  // Oculta el texto "Registro por lote (…)" en Observaciones.
  if (col === 'Observaciones' && /Registro por lote/i.test(raw)) return '';
  return raw;
}

function asistCellHtml(row, col, dayIdx, editing) {
  const v = asistCellValue(row, col, dayIdx);
  // Columnas virtuales de ubicación: lat, lng como link a Google Maps
  if (col === 'Ubicación entrada' || col === 'Ubicación salida' || col === 'Ubicación' || col === 'Ubicacion') {
    if (!v) return `<td style="padding:6px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;color:#94a3b8;font-style:italic">—</td>`;
    let la, ln;
    if (col === 'Ubicación salida') {
      la = row.Ubicacion_Salida_Lat;
      ln = row.Ubicacion_Salida_Lng;
    } else {
      la = row.Ubicacion_Lat;
      ln = row.Ubicacion_Lng;
    }
    const url = `https://www.google.com/maps?q=${Number(la)},${Number(ln)}`;
    return `<td style="padding:6px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;white-space:nowrap"><a href="${esc(url)}" target="_blank" rel="noopener" style="color:#2563eb;text-decoration:none;font-family:ui-monospace,monospace">📍 ${esc(v)}</a></td>`;
  }
  const isDerived = ASIST_DERIVED_COLS.includes(col);
  // Entrada/Salida son derivadas pero SÍ se editan (con time picker); Horas y
  // las primas siempre son solo-lectura (se recalculan automáticamente).
  const editableDerived = col === 'Entrada' || col === 'Salida';
  const isReadOnly = (isDerived && !editableDerived) || col === 'ID' || col === 'Timestamp';
  const id = String(row.ID||'');
  if (col === 'Comentarios') {
    if (!editing) return `<td style="padding:6px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;color:#334155;min-width:180px;max-width:320px;white-space:normal;word-break:break-word">${esc(v)}</td>`;
    return `<td style="padding:3px 6px;border-bottom:1px solid #f1f5f9;background:#fefce8"><input type="text" value="${esc(v)}" oninput="asistCellChange('${esc(id)}','Comentarios',this.value)" placeholder="Comentarios…" maxlength="500" style="width:100%;min-width:220px;padding:5px 7px;font-size:12px;border:1.5px solid #cbd5e1;border-radius:6px;background:#fff;color:#0f172a;font-weight:600"></td>`;
  }
  // Modo lectura (o campos read-only en modo edición)
  if (!editing || isReadOnly) {
    const bg = isReadOnly ? 'background:#f8fafc;color:#475569' : 'color:#334155';
    return `<td style="padding:6px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;white-space:nowrap;${bg}">${esc(v)}</td>`;
  }
  // Modo edición — dropdowns/inputs según el campo (mismo formato que form Nuevo)
  const inputCss = 'width:100%;min-width:120px;padding:5px 7px;font-size:12px;border:1.5px solid #cbd5e1;border-radius:6px;background:#fff;color:#0f172a;font-weight:600';
  let inner = '';
  if (col === 'Empleado_Nombre') {
    const opts = (INC_STATE?.personas || []).slice().sort((a,b)=>String(a).localeCompare(String(b),'es'));
    inner = `<select onchange="asistCellChange('${esc(id)}','${esc(col)}',this.value)" style="${inputCss}">
      <option value="">— Selecciona —</option>
      ${opts.map(n => `<option value="${esc(n)}"${n===v?' selected':''}>${esc(n)}</option>`).join('')}
    </select>`;
  } else if (col === 'Concepto') {
    const opts = ASIST_PANEL_CONCEPTOS.map(c => c.k);
    inner = `<select onchange="asistConceptoChange('${esc(id)}',this.value)" style="${inputCss}">
      <option value="">—</option>
      ${opts.map(o => `<option value="${esc(o)}"${o===v?' selected':''}>${esc(o)}</option>`).join('')}
    </select>`;
  } else if (col === 'Tipo') {
    const opts = ASIST_LISTAS.Tipo;
    const labels = { Entrada:'🟢 Entrada', Salida:'🔴 Salida', Break_inicio:'⏸ Inicio de descanso', Break_fin:'▶ Fin de descanso', Vacaciones:'🏖 Vacaciones', Asueto:'🎉 Asueto', Otro:'📝 Otro' };
    inner = `<select onchange="asistCellChange('${esc(id)}','${esc(col)}',this.value)" style="${inputCss}">
      <option value="">—</option>
      ${opts.map(o => `<option value="${esc(o)}"${o===v?' selected':''}>${esc(labels[o]||o)}</option>`).join('')}
    </select>`;
  } else if (col === 'Metodo') {
    const opts = ASIST_LISTAS.Metodo;
    inner = `<select onchange="asistCellChange('${esc(id)}','${esc(col)}',this.value)" style="${inputCss}">
      <option value="">—</option>
      ${opts.map(o => `<option value="${esc(o)}"${o===v?' selected':''}>${esc(o)}</option>`).join('')}
    </select>`;
  } else if (col === 'Fecha') {
    inner = `<input type="date" value="${esc(v)}" onchange="asistCellChange('${esc(id)}','${esc(col)}',this.value)" style="${inputCss}">`;
  } else if (col === 'Hora') {
    // r.Hora suele ser "HH:MM:SS" pero input type=time acepta "HH:MM"
    const timeVal = String(v).slice(0,5);
    inner = `<input type="time" step="1" value="${esc(timeVal)}" onchange="asistCellChange('${esc(id)}','${esc(col)}',this.value)" style="${inputCss}">`;
  } else if (col === 'Entrada' || col === 'Salida') {
    const def = col === 'Entrada' ? '08:30' : '13:30';
    const timeVal = String(v).slice(0,5) || def;
    inner = `<input type="time" value="${esc(timeVal)}" onchange="asistEntradaSalidaChange('${esc(id)}','${col}',this.value)" style="${inputCss}">`;
  } else if (col === 'Observaciones') {
    inner = `<input type="text" value="${esc(v)}" oninput="asistCellChange('${esc(id)}','${esc(col)}',this.value)" placeholder="Nota…" style="${inputCss}">`;
  } else if (col === 'Ubicacion_Lat' || col === 'Ubicacion_Lng' || col === 'GPS_Accuracy') {
    inner = `<input type="number" step="any" value="${esc(v)}" oninput="asistCellChange('${esc(id)}','${esc(col)}',this.value)" style="${inputCss};text-align:right">`;
  } else {
    inner = `<input type="text" value="${esc(v)}" oninput="asistCellChange('${esc(id)}','${esc(col)}',this.value)" style="${inputCss}">`;
  }
  return `<td style="padding:3px 6px;border-bottom:1px solid #f1f5f9;background:#fefce8">${inner}</td>`;
}

// ── Handlers de la columna Acciones (editar / eliminar / guardar / salir) ──
window.asistToggleRowEdit = function (id) {
  if (ASIST_STATE.editing.has(id)) {
    // Salir de edición — descarta cambios locales (recarga desde server)
    ASIST_STATE.editing.delete(id);
    ASIST_STATE.dirty.delete(id);
    asistReloadList();
  } else {
    ASIST_STATE.editing.add(id);
    asistRenderTabla();
  }
};

// Cambia Entrada/Salida en un renglón (campo directo del row), recalcula
// Horas y marca la fila como dirty. Re-renderiza la tabla para que el nuevo
// valor de Horas aparezca inmediatamente.
// Cambia el Concepto en un renglón y también las 4 columnas de dinero
// derivadas ($ Salario base, primas) + $ Salario total, que se recalculan
// al vuelo al re-render.
window.asistConceptoChange = function (id, value) {
  const r = ASIST_STATE.rows.find(x => String(x.ID||'') === String(id));
  if (!r) return;
  r.Concepto = value;
  const p = asistPanelPrimasPorConcepto_(value);
  const fmt = v => v === '' ? '' : asistPanelFmtMonto_(v);
  r['$ Salario base']             = fmt(p.salBase);
  r['$ Prima vacacional (25%)']   = fmt(p.primaVac);
  r['$ Prima dominical (25%)']    = fmt(p.primaDom);
  r['$ Prima día feriado (200%)'] = fmt(p.primaDF);
  const total = ['salBase','primaVac','primaDom','primaDF'].reduce((s,k) => s + (typeof p[k] === 'number' ? p[k] : 0), 0);
  r['$ Salario total'] = total ? asistPanelFmtMonto_(total) : '';
  ASIST_STATE.dirty.add(id);
  asistRenderTabla();
};

window.asistEntradaSalidaChange = function (id, col, value) {
  const r = ASIST_STATE.rows.find(x => String(x.ID||'') === String(id));
  if (!r) return;
  r[col] = String(value || '').slice(0,5);
  const ent = asistParseTimeToMinutes(r.Entrada);
  const sal = asistParseTimeToMinutes(r.Salida);
  r.Horas = (ent != null && sal != null && sal > ent)
    ? `${Math.floor((sal-ent)/60)}h${String((sal-ent)%60).padStart(2,'0')}`
    : '';
  ASIST_STATE.dirty.add(id);
  asistRenderTabla();
};

window.asistCellChange = function (id, col, value) {
  const r = ASIST_STATE.rows.find(x => String(x.ID||'') === String(id));
  if (!r) return;
  r[col] = value;
  ASIST_STATE.dirty.add(id);
  // Actualiza el estado del botón 💾 sin re-renderizar (mantiene foco en el input)
  const saveBtn = document.querySelector(`tr[data-asist-id="${id}"] button[data-asist-btn="save"]`);
  if (saveBtn) {
    saveBtn.disabled = false;
    saveBtn.style.background = '#16a34a';
    saveBtn.style.color = '#fff';
    saveBtn.style.borderColor = '#15803d';
    saveBtn.style.cursor = 'pointer';
    saveBtn.title = 'Guardar cambios';
  }
};

window.asistSaveRowEdit = async function (id) {
  const r = ASIST_STATE.rows.find(x => String(x.ID||'') === String(id));
  if (!r) return;
  if (!ASIST_STATE.dirty.has(id)) return;
  asistStatusTabla('⏳ Guardando…');
  try {
    const res = await fetch(`${BACKEND}/rh/asistencia`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ payload: r }),
    });
    const j = await res.json();
    if (!j.ok) throw new Error(j.error || 'Guardado falló');
    ASIST_STATE.dirty.delete(id);
    ASIST_STATE.editing.delete(id);
    asistStatusTabla(`✓ Registro ${id} guardado`);
    setTimeout(() => asistStatusTabla(''), 2500);
    asistReloadList();
  } catch (e) {
    asistStatusTabla(`✗ Error: ${esc(e.message||String(e))}`, 'err');
  }
};

window.asistDeleteRow = async function (id) {
  if (!confirm(`¿Eliminar el registro ${id}? Esta acción no se puede deshacer.`)) return;
  asistStatusTabla('⏳ Eliminando…');
  try {
    const res = await fetch(`${BACKEND}/rh/asistencia/${encodeURIComponent(id)}`, { method:'DELETE' });
    const j = await res.json();
    if (!j.ok) throw new Error(j.error || 'Falló');
    asistStatusTabla(`✓ Registro ${id} eliminado`);
    setTimeout(() => asistStatusTabla(''), 2500);
    ASIST_STATE.editing.delete(id);
    ASIST_STATE.dirty.delete(id);
    ASIST_STATE.selected.delete(id);
    asistReloadList();
  } catch (e) {
    asistStatusTabla(`✗ Error: ${esc(e.message||String(e))}`, 'err');
  }
};

/** HTML de la primera columna "Acciones" según estado de la fila. */
function asistActionsCellHtml(id) {
  const isEditing = ASIST_STATE.editing.has(id);
  const isDirty = ASIST_STATE.dirty.has(id);
  const btnStyle = 'display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:4px;font-weight:800;font-size:11px;line-height:1;cursor:pointer;border:1px solid';
  if (isEditing) {
    const canSave = isDirty;
    const saveBg = canSave ? '#16a34a' : '#e5e7eb';
    const saveFg = canSave ? '#fff' : '#9ca3af';
    const saveBd = canSave ? '#15803d' : '#d1d5db';
    const saveCur = canSave ? 'pointer' : 'not-allowed';
    const saveBtn = `<button type="button" data-asist-btn="save" onclick="asistSaveRowEdit('${esc(id)}')" title="${canSave?'Guardar cambios':'Sin cambios que guardar'}" ${canSave?'':'disabled'}
      style="${btnStyle} ${saveBd};background:${saveBg};color:${saveFg};cursor:${saveCur}">💾</button>`;
    const exitBtn = `<button type="button" onclick="asistToggleRowEdit('${esc(id)}')" title="Salir de edición sin guardar"
      style="display:inline-flex;align-items:center;justify-content:center;padding:0 8px;height:22px;border-radius:4px;background:#fee2e2;color:#b91c1c;border:1px solid #fecaca;font-weight:800;font-size:10.5px;line-height:1;cursor:pointer;letter-spacing:.02em">Salir</button>`;
    return `<td style="padding:2px 4px;text-align:center;vertical-align:middle;border-bottom:1px solid #f1f5f9;background:#fefce8"><div style="display:inline-flex;align-items:center;justify-content:center;gap:4px">${saveBtn}${exitBtn}</div></td>`;
  } else {
    const editBtn = `<button type="button" onclick="asistToggleRowEdit('${esc(id)}')" title="Editar renglón"
      style="${btnStyle} #93c5fd;background:#dbeafe;color:#1d4ed8">✎</button>`;
    const delBtn = `<button type="button" onclick="asistDeleteRow('${esc(id)}')" title="Eliminar renglón"
      style="${btnStyle} #fecaca;background:#fee2e2;color:#b91c1c">✕</button>`;
    return `<td style="padding:2px 4px;text-align:center;vertical-align:middle;border-bottom:1px solid #f1f5f9"><div style="display:inline-flex;align-items:center;justify-content:center;gap:4px">${editBtn}${delBtn}</div></td>`;
  }
}

/** Headers visibles = headers del sheet + derivados − ocultos. Los derivados
 *  (Entrada, Salida, Horas) se insertan después de Fecha. Si el sheet devuelve
 *  las columnas legacy 'Entrada'/'Salida'/'Horas' se toman como equivalentes
 *  a las derivadas (no se duplican). */
function asistVisibleHeaders() {
  const raw = ASIST_STATE.headers.length ? ASIST_STATE.headers : (ASIST_STATE.rows[0] ? Object.keys(ASIST_STATE.rows[0]) : []);
  // Meta que va antes de los dinero (después de Fecha/Entrada/Salida/Horas).
  const META_COLS = new Set(['Concepto','Metodo']);
  // Columnas que NO se muestran en la tabla de Control de asistencias
  // (dinero, compensación y observaciones — el detalle vive en Nómina).
  const EXCLUDED = new Set([
    '$ Salario base',
    '$ Prima vacacional (25%)',
    '$ Prima dominical (25%)',
    '$ Prima día feriado (200%)',
    '$ Salario total',
    'Compensación_concepto',
    'Compensación_monto',
    'Observaciones',
  ]);
  const out = [];
  for (const h of raw) {
    if (ASIST_HIDDEN_COLS.has(h)) continue;
    if (ASIST_DERIVED_COLS.includes(h)) continue;
    if (META_COLS.has(h)) continue;
    if (EXCLUDED.has(h)) continue;
    out.push(h);
    if (h === 'Fecha') {
      // Entrada, Salida, Horas (derivadas)
      for (const d of ['Entrada','Salida','Horas']) if (!out.includes(d)) out.push(d);
      // Meta (Concepto, Metodo)
      for (const m of ['Concepto','Metodo']) if (raw.includes(m) && !out.includes(m)) out.push(m);
      // Ubicación entrada + salida (virtuales, separadas por evento)
      if (!out.includes('Ubicación entrada')) out.push('Ubicación entrada');
      if (!out.includes('Ubicación salida')) out.push('Ubicación salida');
    }
  }
  // Fallback si no hubo Fecha: solo derivadas no-dinero.
  for (const d of ['Entrada','Salida','Horas']) if (!out.includes(d)) out.push(d);
  for (const m of ['Concepto','Metodo']) if (raw.includes(m) && !out.includes(m)) out.push(m);
  if (!out.includes('Ubicación entrada')) out.push('Ubicación entrada');
  if (!out.includes('Ubicación salida')) out.push('Ubicación salida');
  // Comentarios (texto libre) — siempre al final, aunque la columna aún no
  // exista en la hoja (se crea sola en RH_Asistencia al primer guardado).
  const iCom = out.indexOf('Comentarios');
  if (iCom >= 0) out.splice(iCom, 1);
  out.push('Comentarios');
  return out;
}

function asistRenderTabla() {
  const wrap = document.getElementById('asist-tabla-wrap');
  if (!wrap) return;
  const rows = asistSortedRows();
  const headers = asistVisibleHeaders();
  if (!headers.length) {
    wrap.innerHTML = `<div style="text-align:center;padding:60px;color:#94a3b8;font-size:13px">Sin registros aún. Usa "Nuevo registro de asistencia" para agregar el primero.</div>`;
    return;
  }
  const sel = ASIST_STATE.seleccionar;
  const dayIdx = asistBuildDayIndex_();
  const sortIcon = (col) => {
    if (ASIST_STATE.sortKey !== col) return '<span style="color:#cbd5e1;font-size:9px">↕</span>';
    return ASIST_STATE.sortDir === 'asc'
      ? '<span style="color:#93c5fd;font-size:10px;font-weight:900">↑ A-Z</span>'
      : '<span style="color:#93c5fd;font-size:10px;font-weight:900">↓ Z-A</span>';
  };
  const allSel = sel && rows.length > 0 && rows.every(r => ASIST_STATE.selected.has(String(r.ID||'')));
  const selHead = sel
    ? `<th style="position:sticky;top:0;z-index:5;background:#1e293b;padding:9px 6px;text-align:center;width:36px">${asistSelBox(allSel, `asistSelectAll(${!allSel})`)}</th>`
    : '';
  // Columna Acciones — siempre presente como primera columna (después de Seleccionar si activo)
  const accHead = `<th style="position:sticky;top:0;z-index:5;background:#1e293b;color:#fff;padding:9px 8px;text-align:center;font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap;user-select:none;width:80px">Acciones</th>`;
  const headHtml = headers.map(h => `
    <th onclick="asistSortBy('${esc(h)}')"
        style="position:sticky;top:0;z-index:5;background:#1e293b;color:#fff;padding:9px 10px;text-align:left;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.04em;cursor:pointer;white-space:nowrap;user-select:none">
      <div style="display:inline-flex;align-items:center;gap:6px">${esc(h)} ${sortIcon(h)}</div>
    </th>`).join('');
  const totalCols = headers.length + (sel?1:0) + 1;
  const bodyHtml = rows.length
    ? rows.map(r => {
        const id = String(r.ID||'');
        const isSel = sel && ASIST_STATE.selected.has(id);
        const isEditing = ASIST_STATE.editing.has(id);
        const trBg = isEditing ? 'background:#fefce8' : (isSel ? 'background:#dbeafe' : '');
        const selCell = sel
          ? `<td style="padding:6px;text-align:center;border-bottom:1px solid #f1f5f9">${asistSelBox(isSel, `asistToggleRowSel('${esc(id)}',${!isSel})`)}</td>`
          : '';
        const accCell = asistActionsCellHtml(id);
        return `<tr data-asist-id="${esc(id)}" style="${trBg}">${selCell}${accCell}${headers.map(h => asistCellHtml(r, h, dayIdx, isEditing)).join('')}</tr>`;
      }).join('')
    : `<tr><td colspan="${totalCols}" style="text-align:center;padding:40px;color:#94a3b8;font-size:12px">Sin registros.</td></tr>`;
  wrap.innerHTML = `<table style="width:100%;border-collapse:collapse"><thead><tr>${selHead}${accHead}${headHtml}</tr></thead><tbody>${bodyHtml}</tbody></table>`;
}

// ── Vista Calendario (rows = personal operativo · cols = días) ──
// ═══════════════════════════════════════════════════════════════════════════
// ║ Modo edición del calendario principal (Control de asistencias)          ║
// ║ - Por defecto: calendario READ-ONLY. Click en celda NO hace nada.        ║
// ║ - Al oprimir "✏️ Editar" entra en modo edición: click en celda abre el   ║
// ║   popup y los cambios se guardan optimistamente + background.            ║
// ║ - Al detectar el 1er cambio aparece "💾 Guardar cambios" — al oprimirlo  ║
// ║   se pinta la tabla con el estado local (instantáneo) y se sale.         ║
// ║ - "🚪 Salir" sale del modo edición sin refrescar.                        ║
// ═══════════════════════════════════════════════════════════════════════════
const ASIST_CAL_MODE = { editing: false, dirty: false, pending: new Set(), chains: new Map(), idMap: new Map() };

// Chip discreto "Sincronizando…" junto al botón de la toolbar mientras hay
// guardados en segundo plano. Se actualiza sin re-renderizar el calendario.
function _asistCalSyncChipHtml_() {
  const n = ASIST_CAL_MODE.pending.size;
  if (!n) return '';
  return `<span style="width:11px;height:11px;border:2px solid #cbd5e1;border-top-color:#16a34a;border-radius:50%;display:inline-block;animation:hu-spin .7s linear infinite"></span> Sincronizando ${n}…`;
}
function _asistCalSyncChip_() {
  const el = document.getElementById('asist-cal-sync-chip');
  if (el) el.innerHTML = _asistCalSyncChipHtml_();
}

function _asistCalEditToolbarButtons_() {
  const syncChip = `<span id="asist-cal-sync-chip" style="display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;color:#64748b">${_asistCalSyncChipHtml_()}</span>`;
  if (!ASIST_CAL_MODE.editing) {
    return `<button type="button" onclick="asistCalToggleEdit(true)"
              title="Habilitar edición del calendario"
              style="all:unset;cursor:pointer;padding:7px 14px;background:#fff;color:#0f172a;border:1.5px solid #cbd5e1;border-radius:8px;font-weight:900;font-size:12px;display:inline-flex;align-items:center;gap:6px">
              <span style="display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:4px;border:1.5px solid #cbd5e1;background:#fff;font-size:11px;font-weight:900;line-height:1"></span>
              ✏️ Editar
            </button>${syncChip}`;
  }
  // En modo edición: chip "Editando", opcional Guardar cambios + Salir.
  const saveBtn = ASIST_CAL_MODE.dirty
    ? `<button type="button" onclick="asistCalSaveExit()"
        title="Guardar cambios y salir del modo edición"
        style="all:unset;cursor:pointer;padding:7px 14px;background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border-radius:8px;font-weight:900;font-size:12px;box-shadow:0 3px 8px rgba(22,163,74,.35)">💾 Guardar cambios</button>`
    : '';
  return `
    <div style="display:inline-flex;align-items:center;gap:6px;padding:5px 10px;background:#fef3c7;border:1.5px solid #fcd34d;border-radius:8px;font-size:11px;font-weight:800;color:#78350f">
      <span style="display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:4px;background:#0f172a;color:#fff;font-size:11px;font-weight:900;line-height:1">✓</span>
      ✏️ EDITANDO
    </div>
    ${saveBtn}
    <button type="button" onclick="asistCalToggleEdit(false)"
      title="Salir del modo edición sin guardar"
      style="all:unset;cursor:pointer;padding:7px 14px;background:#fff;color:#334155;border:1.5px solid #cbd5e1;border-radius:8px;font-weight:800;font-size:12px">🚪 Salir</button>${syncChip}`;
}

window.asistCalToggleEdit = function (on) {
  ASIST_CAL_MODE.editing = !!on;
  if (!on) ASIST_CAL_MODE.dirty = false;
  asistRenderCalendar();
};

window.asistCalSaveExit = function () {
  // INSTANTÁNEO: cada cambio ya se está guardando en segundo plano (1 sola
  // llamada por celda) y ASIST_STATE.rows ya refleja el resultado. Aquí solo
  // salimos del modo edición y pintamos la tabla de abajo con el estado
  // local — sin volver a descargar la lista (~5s). Si algún guardado falla,
  // su job avisa y recarga los registros reales.
  const _t0 = performance.now();
  ASIST_CAL_MODE.editing = false;
  ASIST_CAL_MODE.dirty = false;
  ASIST_STATE._focusMode = 'preserve';
  asistRenderCalendar();
  asistRenderTabla();
  const c = document.getElementById('asist-list-count');
  if (c) c.textContent = `${ASIST_STATE.rows.length} registro${ASIST_STATE.rows.length===1?'':'s'}`;
  console.log(`[asist-cal] Guardar cambios → UI lista en ${Math.round(performance.now() - _t0)}ms (${ASIST_CAL_MODE.pending.size} guardado(s) terminando en 2º plano)`);
};

// Marca el calendario como "sucio" (hay cambios sin visualizar aún el
// botón Guardar). Se llama después de cada save optimista exitoso.
function _asistCalMarkDirty_() {
  if (!ASIST_CAL_MODE.editing) return;
  if (ASIST_CAL_MODE.dirty) return;
  ASIST_CAL_MODE.dirty = true;
  // Refresca solo la toolbar (barato) para mostrar el botón Guardar.
  try {
    const tb = document.getElementById('asist-cal-toolbar');
    if (tb) asistRenderCalendar();
  } catch(_){}
}

function asistRenderCalendar() {
  const cont = document.getElementById('asist-cal-wrap');
  if (!cont) return;
  // Sincroniza calMonth con el filtro de Mes si está activo.
  asistFiltersSyncCalMonth_();
  if (!ASIST_STATE.calMonth) {
    const t = new Date(); ASIST_STATE.calMonth = new Date(t.getFullYear(), t.getMonth(), 1);
  }
  const month = ASIST_STATE.calMonth;
  const y0 = month.getFullYear(), m0 = month.getMonth();
  const today = new Date(); today.setHours(0,0,0,0);
  const MB = 2, MA = 4; // meses antes/después
  const rangeStart = new Date(y0, m0 - MB, 1);
  const rangeEnd   = new Date(y0, m0 + MA + 1, 0);
  const totalDays = Math.round((rangeEnd - rangeStart) / 86400000) + 1;
  // Personal operativo (sin administrativos). Ordena alfabéticamente.
  let personalRows = asistPersonalOperativo().slice().sort((a,b)=>a.nombre.localeCompare(b.nombre,'es'));
  const F = asistFilters_();
  // Reconciliación de nombres: registros creados con solo "Adán" deben
  // matchear con "Adán Ramos" del Personal (canonical). Construimos el
  // mapa ANTES del filtro para poder reconciliar F.nombre también.
  const _aliasToCanonical = _asistBuildAliasMap_(personalRows);
  const _canonNom = (raw) => {
    const t = String(raw || '').trim();
    if (!t) return t;
    return _aliasToCanonical.get(_normNombre_(t)) || t;
  };
  // Filtro por Empleado_Nombre — reconciliamos F.nombre al canonical.
  if (F.nombre) {
    const target = _canonNom(F.nombre);
    personalRows = personalRows.filter(p => p.nombre === target);
  }
  const personas = personalRows.map(x => x.nombre);
  // Index: `${persona}|${YYYY-MM-DD}` → [rows]. Usa el nombre canónico.
  const idx = new Map();
  for (const r of ASIST_STATE.rows) {
    const n = _canonNom(String(r.Empleado_Nombre||'').trim());
    const f = String(r.Fecha||'').slice(0,10);
    if (!n || !f) continue;
    // Filtro por Concepto: si activo, solo indexamos registros que matchean.
    if (F.concepto) {
      const c = asistPanelNormalizarConceptoLegado_(String(r.Concepto||'').trim() || ((String(r.Entrada||'').trim() || String(r.Salida||'').trim()) ? 'Regular' : ''));
      if (c !== F.concepto) continue;
    }
    const k = `${n}|${f}`;
    if (!idx.has(k)) idx.set(k, []);
    idx.get(k).push(r);
  }
  // Re-renderiza también la barra de filtros por si cambió el catálogo.
  asistRenderFiltersBar_();

  // Toolbar renderiza en un contenedor SEPARADO (arriba del calendario, no
  // dentro de la tabla) para no chocar con el header sticky de la grid.
  const toolbar = document.getElementById('asist-cal-toolbar');
  if (toolbar) {
    toolbar.classList.remove('hidden');
    const weekOpts = (typeof nomWeekOptions === 'function') ? nomWeekOptions() : [];
    // Marca la semana que contiene TODAY como default (si no hay una previamente seleccionada)
    let selWeekValue = ASIST_STATE.selWeek || '';
    if (!selWeekValue && weekOpts.length) {
      // primera opción (más reciente) es la semana en curso
      selWeekValue = weekOpts[0]?.value || '';
    }
    toolbar.innerHTML = `
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:10px 12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px">
        <button type="button" onclick="asistCalNav(-1)" title="Mes anterior"
                style="all:unset;cursor:pointer;padding:6px 12px;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;font-weight:800;color:#334155">←</button>
        <div id="asist-cal-month-label" style="font-weight:900;font-size:14px;color:#0f172a;min-width:150px;text-align:center">${OCUP_MESES[m0]} ${y0}</div>
        <button type="button" onclick="asistCalNav(1)" title="Mes siguiente"
                style="all:unset;cursor:pointer;padding:6px 12px;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;font-weight:800;color:#334155">→</button>
        <button type="button" onclick="asistCalHoy()"
                style="all:unset;cursor:pointer;padding:7px 14px;background:linear-gradient(135deg,#0ea5e9,#0369a1);color:#fff;border-radius:8px;font-weight:900;box-shadow:0 3px 8px rgba(14,165,233,.35)">📅 Ir a hoy</button>
        ${_asistCalEditToolbarButtons_()}
        <label style="display:inline-flex;align-items:center;gap:6px;font-size:11px;color:#475569;font-weight:700">
          <span style="text-transform:uppercase;letter-spacing:.06em">Semana:</span>
          <select onchange="asistCalGoToWeek(this.value)"
                  style="padding:6px 10px;border:1.5px solid #cbd5e1;border-radius:8px;font-size:12px;font-weight:700;color:#0f172a;background:#fff;cursor:pointer;min-width:220px">
            ${weekOpts.map(o => `<option value="${esc(o.value)}"${o.value===selWeekValue?' selected':''}>${esc(o.label)}</option>`).join('')}
          </select>
        </label>
        <div style="margin-left:auto;font-size:11px;color:#475569;display:inline-flex;align-items:center;gap:10px;flex-wrap:wrap">
          <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:9px;height:9px;border-radius:50%;background:#16a34a;box-shadow:0 0 0 1px #fff,0 0 0 2px #16a34a"></span> asistencia</span>
          <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:9px;height:9px;border-radius:50%;background:#f59e0b;box-shadow:0 0 0 1px #fff,0 0 0 2px #f59e0b"></span> vacaciones/asueto</span>
          <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:9px;height:9px;border-radius:50%;background:#0ea5e9;box-shadow:0 0 0 1px #fff,0 0 0 2px #0ea5e9"></span> día feriado</span>
          <span style="display:inline-flex;align-items:center;gap:4px"><span style="width:9px;height:9px;border-radius:50%;background:#dc2626;box-shadow:0 0 0 1px #fff,0 0 0 2px #dc2626"></span> falta</span>
        </div>
      </div>`;
  }

  let html = `<div class="ocup-cal" data-asist-cal="continuous" style="--ocup-days:${totalDays}">`;
  html += `<div class="ocup-cal-head"><div class="ocup-head-aloj">👥 Personal · ${personas.length}</div>`;
  let todayIdx = -1;
  // Abreviaturas de mes (3 letras) — se usa arriba del número de cada día.
  const _mesAbr = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  for (let i = 0; i < totalDays; i++) {
    const d = new Date(rangeStart); d.setDate(d.getDate()+i);
    const dow = d.getDay();
    const isToday = d.getTime() === today.getTime();
    if (isToday) todayIdx = i;
    const isWeekend = dow === 0 || dow === 6;
    const isFirst = d.getDate() === 1;
    // Etiqueta de mes+año en la primera fecha de cada mes (siempre visible,
    // no absoluta) para que al hacer scroll horizontal el usuario vea con
    // claridad dónde empieza cada mes.
    const monthLabel = isFirst
      ? `<div style="font-size:9.5px;font-weight:900;color:#3730a3;background:#e0e7ff;border:1px solid #a5b4fc;padding:1px 5px;border-radius:6px;margin-bottom:2px;white-space:nowrap;line-height:1.2">${OCUP_MESES[d.getMonth()]} ${d.getFullYear()}</div>`
      : `<div style="font-size:8.5px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.03em;line-height:1.2">${_mesAbr[d.getMonth()]}</div>`;
    html += `<div class="ocup-head-cell ${isToday?'is-today':''} ${isWeekend?'is-weekend':''}" data-day-idx="${i}" style="position:relative">
      ${monthLabel}
      <div class="ocup-head-dow" style="margin-top:1px">${OCUP_DOW[dow]}</div>
      <div class="ocup-head-day">${d.getDate()}</div>
    </div>`;
  }
  html += `</div>`;

  // Días laborales por empleado (Dias_trabajo en Personal). Se usa para
  // pintar en gris claro las celdas de los días que la persona trabaja
  // aunque no haya registro capturado ese día — visualiza el "esperado".
  const _diasTrabajoByNombre = new Map();
  (INC_STATE?.personalRows || []).forEach(pr => {
    const n = _rhPersonalFullName_(pr);
    if (!n) return;
    _diasTrabajoByNombre.set(n, asistPanelParseDiasTrabajo_(pr.Dias_trabajo || ''));
  });
  personalRows.forEach(({ nombre, puesto }) => {
    const _workDows = _diasTrabajoByNombre.get(nombre) || null;
    html += `<div class="ocup-cal-row" data-persona="${esc(nombre)}">`;
    html += `<div class="ocup-aloj-cell">
      <div class="ocup-aloj-img">👤</div>
      <div class="ocup-aloj-info">
        <div class="ocup-aloj-name" title="${esc(nombre)}${puesto?' · '+esc(puesto):''}">${esc(nombre)}</div>
        ${puesto ? `<div class="ocup-aloj-id">${esc(puesto)}</div>` : ''}
      </div>
    </div>`;
    for (let i = 0; i < totalDays; i++) {
      const d = new Date(rangeStart); d.setDate(d.getDate()+i);
      const iso = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
      const dow = d.getDay();
      const isToday = d.getTime() === today.getTime();
      const isWeekend = dow === 0 || dow === 6;
      const recs = idx.get(`${nombre}|${iso}`) || [];
      // Contenido de celda: Estado (concepto normalizado) + Entrada→Salida.
      // No mostramos el monto acá, esa vista es más para la nómina; el
      // calendario grande sirve para revisar cuál fue el estado y las
      // horas del día de un vistazo.
      const conceptos = asistDeriveConceptos_(recs);
      // Día laboral esperado según Dias_trabajo — pinta la celda vacía
      // en gris claro cuando no hay registro para dejar visualmente
      // marcado que ese día "sí trabaja".
      const isWorkDow = !!(_workDows && _workDows.has(dow));
      const bgStyle = conceptos.size
        ? `background:${asistPanelBgFor_(conceptos)};`
        : (isWorkDow ? 'background:#e2e8f0;' : '');
      const semStyle = conceptos.size ? asistPanelSemaforo_(conceptos) : '';
      let inner = '';
      const _com = recs.map(r => String(r.Comentarios || '').trim()).filter(Boolean).join(' · ');
      const _comChip = _com ? `<span title="${esc(_com)}" style="font-size:8px;font-weight:900;color:#1e40af;background:#dbeafe;border:1px solid #93c5fd;border-radius:6px;padding:0 4px;line-height:1.3;white-space:nowrap">💬</span>` : '';
      if (conceptos.size) {
        // Estado: primer concepto normalizado ('Regular', 'Falta', ...).
        const concKey = Array.from(conceptos)[0];
        const concNorm = asistPanelNormalizarConceptoLegado_(concKey);
        const grupo = ASIST_PANEL_CONCEPTO_MAP[concNorm]?.group || concNorm;
        // Estado compacto para caber en 64px:
        // - Grupo Asistencia → muestra la sub (Regular, Vac laboradas, Día feriado, Domingo).
        // - Otros grupos     → muestra el grupo (Falta, Vacaciones, Incapacidad).
        const estadoLabel = grupo === 'Asistencia' ? concNorm : grupo;
        // Entrada / Salida: primer registro con Entrada o Salida definidas.
        const rEnt = recs.find(r => String(r.Entrada || '').trim()) || {};
        const rSal = recs.find(r => String(r.Salida  || '').trim()) || {};
        const ent = String(rEnt.Entrada || '').trim().slice(0,5);
        const sal = String(rSal.Salida  || '').trim().slice(0,5);
        const horas = (ent || sal) ? `${ent || '—'} → ${sal || '—'}` : '';
        inner = `
          <div style="display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1.1;padding:1px 2px;gap:1px">
            <span style="font-size:8.5px;font-weight:900;color:#0f172a;text-align:center;white-space:nowrap;text-transform:none">${esc(estadoLabel)}</span>
            ${horas ? `<span style="font-size:7.5px;font-weight:700;color:#475569;text-align:center;white-space:nowrap;font-variant-numeric:tabular-nums">${esc(horas)}</span>` : ''}
            ${_comChip}
          </div>`;
      } else if (_comChip) {
        inner = `<div style="display:flex;align-items:center;justify-content:center">${_comChip}</div>`;
      }
      const wrap = inner
        ? `<div style="display:flex;align-items:center;justify-content:center;width:100%;height:100%">${inner}</div>`
        : '';
      const tip = recs.length
        ? recs.map(r => {
            const e = String(r.Entrada||'').trim().slice(0,5);
            const s = String(r.Salida ||'').trim().slice(0,5);
            const rawC = String(r.Concepto||'').trim();
            const c = rawC || (e || s) ? asistPanelNormalizarConceptoLegado_(rawC || 'Regular') : '';
            const h = e || s ? ` · ${e || '?'}→${s || '?'}` : '';
            const cm = String(r.Comentarios || '').trim();
            return [c ? `${c}${h}` : '', cm ? `💬 ${cm}` : ''].filter(Boolean).join(' · ');
          }).filter(Boolean).join(' | ')
        : '';
      html += `<div class="ocup-day-cell ${isToday?'is-today':''} ${isWeekend?'is-weekend':''}" style="${bgStyle}${semStyle}cursor:${ASIST_CAL_MODE.editing?'pointer':'default'}" title="${esc(tip)}" onclick="asistCalClick('${esc(nombre).replace(/'/g,"\\'")}','${iso}',event)">${wrap}</div>`;
    }
    html += `</div>`;
  });

  html += `</div>`;
  cont.innerHTML = html;

  // Al hacer scroll horizontal, actualiza el label del mes según el día central
  // visible (sin re-renderear el calendario).
  const rangeStartMs = rangeStart.getTime();
  cont.onscroll = () => {
    const label = document.getElementById('asist-cal-month-label');
    if (!label) return;
    const scrRect = cont.getBoundingClientRect();
    const midX = scrRect.left + scrRect.width / 2;
    const el = document.elementFromPoint(midX, scrRect.top + 30);
    const cell = el && el.closest && el.closest('[data-day-idx]');
    if (!cell) return;
    const i = Number(cell.dataset.dayIdx);
    const d = new Date(rangeStartMs + i * 86400000);
    label.textContent = `${OCUP_MESES[d.getMonth()]} ${d.getFullYear()}`;
  };

  // Auto-scroll: usa el modo pedido (default = 'today' — hoy siempre
  // centrado). Cuando el usuario está editando (guardado optimista tras
  // clasificar), pedimos 'preserve' para NO mover el scrollbar y evitar
  // que la vista salte de posición.
  //   'today'    → centra hoy (default, primera carga)
  //   'month'    → centra el primer día del calMonth (navegación con flechas)
  //   'preserve' → deja el scrollLeft actual sin tocarlo (post-save)
  //   'week'     → ya maneja asistCalGoToWeek su propio scroll aparte
  const focusMode = ASIST_STATE._focusMode || 'today';
  ASIST_STATE._focusMode = null; // reset después de usarlo
  if (focusMode === 'preserve') {
    // No hacer nada: el navegador conserva el scrollLeft del contenedor
    // porque no destruimos el asist-cal-wrap, solo reemplazamos su hijo
    // .ocup-cal (asistRenderCalendar reasigna cont.innerHTML manteniendo
    // el mismo cont). scrollLeft se preserva automáticamente en la
    // mayoría de navegadores porque cont es el scroller.
    return;
  }
  setTimeout(() => asistCalCenterOnMonthOrToday_(cont, rangeStart, month, focusMode), 40);
}

/** Centra en el viewport un día del calendario según el modo:
 *   - 'today' : hoy (si está en rango)
 *   - 'month' : primer día del mes visible (default) */
function asistCalCenterOnMonthOrToday_(cont, rangeStart, month, mode) {
  if (!cont) return;
  const today = new Date(); today.setHours(0,0,0,0);
  const todayIdx = Math.round((today - rangeStart) / 86400000);
  let target = null;
  if (mode === 'today' && todayIdx >= 0) target = cont.querySelector(`[data-day-idx="${todayIdx}"]`);
  if (!target) {
    const monthIdx = Math.round((month - rangeStart) / 86400000);
    target = cont.querySelector(`[data-day-idx="${monthIdx}"]`);
  }
  if (!target) return;
  // El scroller horizontal es el CONTENEDOR (#asist-cal-wrap con overflow:auto);
  // fallback a .ocup-cal si el contenedor no tiene scroll.
  const scroller = (cont.scrollWidth > cont.clientWidth)
    ? cont
    : (cont.querySelector('.ocup-cal') || target.parentElement);
  if (!scroller || !scroller.scrollTo) { target.scrollIntoView({ inline:'center', block:'nearest' }); return; }
  const targetRect = target.getBoundingClientRect();
  const scrRect = scroller.getBoundingClientRect();
  const currentScroll = scroller.scrollLeft;
  const offsetInScr = targetRect.left - scrRect.left + currentScroll;
  const desired = offsetInScr - (scrRect.width / 2) + (targetRect.width / 2);
  const behavior = (mode === 'today') ? 'smooth' : 'auto';
  scroller.scrollTo({ left: Math.max(0, desired), behavior });
}

window.asistCalNav = function (delta) {
  const m = ASIST_STATE.calMonth || new Date();
  ASIST_STATE.calMonth = new Date(m.getFullYear(), m.getMonth() + delta, 1);
  ASIST_STATE.selWeek = '';
  asistRenderCalendar();
};
window.asistCalHoy = function () {
  const t = new Date();
  ASIST_STATE.calMonth = new Date(t.getFullYear(), t.getMonth(), 1);
  ASIST_STATE.selWeek = '';
  ASIST_STATE._focusMode = 'today';
  asistRenderCalendar();
};

/** Salta a la semana seleccionada (value `S:YYYY-MM-DD_YYYY-MM-DD`) y centra
 *  el viewport en el rango. Si la semana cae en otro mes, ajusta calMonth. */
window.asistCalGoToWeek = function (weekValue) {
  const m = String(weekValue||'').match(/^S:(\d{4}-\d{2}-\d{2})_(\d{4}-\d{2}-\d{2})$/);
  if (!m) return;
  ASIST_STATE.selWeek = weekValue;
  const start = new Date(m[1] + 'T00:00:00');
  const end   = new Date(m[2] + 'T00:00:00');
  // Ajusta calMonth al mes del centro de la semana si no está en rango visible
  const mid = new Date((start.getTime() + end.getTime()) / 2);
  ASIST_STATE.calMonth = new Date(mid.getFullYear(), mid.getMonth(), 1);
  asistRenderCalendar();
  // Después del render, centra el viewport en el rango de la semana
  setTimeout(() => {
    const cont = document.getElementById('asist-cal-wrap');
    if (!cont) return;
    // Recalcula rangeStart tal como asistRenderCalendar
    const y0 = ASIST_STATE.calMonth.getFullYear(), m0 = ASIST_STATE.calMonth.getMonth();
    const MB = 2;
    const rangeStart = new Date(y0, m0 - MB, 1);
    const startIdx = Math.round((start - rangeStart) / 86400000);
    const endIdx   = Math.round((end   - rangeStart) / 86400000);
    if (startIdx < 0) return;
    const startCell = cont.querySelector(`[data-day-idx="${startIdx}"]`);
    const endCell   = cont.querySelector(`[data-day-idx="${endIdx}"]`);
    // El scroller horizontal es el CONTENEDOR (#asist-cal-wrap con overflow:auto),
    // no el `.ocup-cal` interior. Detectamos cuál tiene el scroll disponible.
    const scroller = (cont.scrollWidth > cont.clientWidth)
      ? cont
      : cont.querySelector('.ocup-cal');
    if (!startCell || !endCell || !scroller || !scroller.scrollTo) return;
    const startRect = startCell.getBoundingClientRect();
    const endRect   = endCell.getBoundingClientRect();
    const scrRect   = scroller.getBoundingClientRect();
    const currentScroll = scroller.scrollLeft;
    const startOffset = startRect.left - scrRect.left + currentScroll;
    const endOffset   = endRect.right  - scrRect.left + currentScroll;
    const midOffset   = (startOffset + endOffset) / 2;
    scroller.scrollTo({ left: Math.max(0, midOffset - scrRect.width / 2), behavior: 'smooth' });
  }, 80);
};
// ── Popup del calendario grande (Control de asistencias) ────────────────
// Estado del edit en curso — mismo modelo que el panel: 1 concepto + 1 comp.
const ASIST_CAL_EDIT = { nombre: '', iso: '', concepto: '', comp: null, comentarios: '', saving: false };

// Permitir capturar hasta N días adelante de hoy (para programar turnos,
// vacaciones o descansos con antelación). Cambiar aquí si el negocio quiere
// una ventana más grande/pequeña.
const ASIST_CAL_FUTURE_DAYS = 7;
function _asistCalMaxIso_() {
  const d = new Date();
  d.setDate(d.getDate() + ASIST_CAL_FUTURE_DAYS);
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
}

window.asistCalClick = function (nombre, iso, ev) {
  // Modo lectura por defecto: click no hace nada si no está en modo edición.
  if (!ASIST_CAL_MODE.editing) {
    if (ev) ev.stopPropagation();
    return;
  }
  // Ventana permitida: hoy + ASIST_CAL_FUTURE_DAYS. Fechas más allá se
  // bloquean para nuevos registros (los existentes se pueden abrir para
  // borrarlos).
  const _maxIso = _asistCalMaxIso_();
  if (iso > _maxIso) {
    const existe = _asistCalRowFor_(nombre, iso);
    if (!existe) {
      alert('⚠️ No se pueden agregar registros más allá de ' + ASIST_CAL_FUTURE_DAYS + ' días a futuro.\n\nÚltima fecha permitida: ' + _maxIso + '.');
      if (ev) ev.stopPropagation();
      return;
    }
  }
  asistCalOpenCellMenu(nombre, iso, ev);
};

/** Construye el mapa alias→canonical usado para reconciliar nombres
 *  cortos (p.ej. "Sandra" o "Sandra Sánchez") contra el nombre completo
 *  del Personal ("Sandra Sánchez Rojas"). Registra TODOS los prefijos
 *  de palabras del nombre — el más largo gana si hay conflictos entre
 *  personas con el mismo primer nombre. */
function _asistBuildAliasMap_(personalRows) {
  const alias = new Map();
  (personalRows || []).forEach(p => {
    const full = String(p?.nombre || '').trim();
    if (!full) return;
    const words = full.split(/\s+/).filter(Boolean);
    alias.set(_normNombre_(full), full);
    // Prefijos de 1..N-1 palabras — solo se registran si aún no existen
    // (evita que dos personas con el mismo primer nombre se pisen).
    for (let i = 1; i < words.length; i++) {
      const pref = words.slice(0, i).join(' ');
      const key = _normNombre_(pref);
      if (!alias.has(key)) alias.set(key, full);
    }
  });
  // Variantes informales sin segundo nombre ("Adán Ramos Lozano", "Adán
  // Ramos") con las que el bot de WhatsApp / capturas viejas guardaron
  // registros — mismas reglas que el resto de RH (_rhRegisterPersonalAliases_).
  if (typeof _rhRegisterPersonalAliases_ === 'function' && typeof INC_STATE !== 'undefined') {
    const fulls = new Set((personalRows || []).map(p => String(p?.nombre || '').trim()).filter(Boolean));
    const extra = new Map();
    (INC_STATE.personalRows || []).forEach(pr => _rhRegisterPersonalAliases_(extra, pr));
    extra.forEach((full, key) => { if (fulls.has(full) && !alias.has(key)) alias.set(key, full); });
  }
  return alias;
}
function _asistCalRowFor_(nombre, iso) {
  const all = _asistCalAllRowsFor_(nombre, iso);
  return all.length ? all[0] : null;
}
/** Todos los registros de un (empleado, día) — usado para deduplicar en
 *  cada guardado. Reconcilia nombres cortos (p.ej. "Alma") contra el
 *  canonical del Personal (p.ej. "Alma Abigail Robledo Gutiérrez"). */
function _asistCalAllRowsFor_(nombre, iso) {
  const _personal = (typeof asistPersonalOperativo === 'function') ? asistPersonalOperativo() : [];
  const _alias = _asistBuildAliasMap_(_personal);
  const canon = (raw) => {
    const t = String(raw||'').trim(); if (!t) return t;
    return _alias.get(_normNombre_(t)) || t;
  };
  const target = canon(nombre);
  return (ASIST_STATE.rows || []).filter(r =>
    canon(String(r.Empleado_Nombre || '').trim()) === target &&
    String(r.Fecha || '').slice(0, 10) === iso
  );
}

window.asistCalOpenCellMenu = function (nombre, iso, ev) {
  if (ev) ev.stopPropagation();
  // Estado inicial: leer del registro existente (si hay).
  const row = _asistCalRowFor_(nombre, iso);
  let concepto = '';
  if (row) {
    const raw = String(row.Concepto || '').trim();
    if (raw) concepto = asistPanelNormalizarConceptoLegado_(raw);
    else if (String(row.Entrada||'').trim() || String(row.Salida||'').trim()) concepto = 'Regular';
  }
  const compMonto = row ? (Number(String(row['Compensación_monto']||'').replace(/[$,\s]/g,'')) || 0) : 0;
  const compConc  = row ? String(row['Compensación_concepto'] || '').trim() : '';
  const compInit  = (compMonto > 0 || compConc) ? { concepto: compConc, monto: compMonto } : null;
  ASIST_CAL_EDIT.nombre = nombre;
  ASIST_CAL_EDIT.iso    = iso;
  ASIST_CAL_EDIT.concepto = concepto;
  ASIST_CAL_EDIT.comp   = compInit ? { ...compInit } : null;
  ASIST_CAL_EDIT.comentarios = row ? String(row.Comentarios || '') : '';
  ASIST_CAL_EDIT.saving = false;
  _asistCalRenderMenu_(ev);
};

function _asistCalRenderMenu_(ev) {
  let m = document.getElementById('asist-panel-cell-menu'); // reuso el mismo elemento
  if (!m) {
    m = document.createElement('div');
    m.id = 'asist-panel-cell-menu';
    m.style.cssText = 'position:fixed;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;box-shadow:0 8px 20px rgba(15,23,42,.18);z-index:99999;padding:6px;min-width:220px';
    document.body.appendChild(m);
  } else if (m.parentElement !== document.body) {
    document.body.appendChild(m);
  }
  const S = ASIST_CAL_EDIT;
  const curNorm = asistPanelNormalizarConceptoLegado_(S.concepto || '');
  const curGroup = ASIST_PANEL_CONCEPTO_MAP[curNorm]?.group || '';
  const rowHtml = (label, sel, sub, key) => `
    <div onclick="event.stopPropagation();asistCalMenuSetConcepto('${key}')"
      style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;cursor:pointer;user-select:none;${sub?'padding-left:26px;font-size:11px':''}">
      <span style="display:inline-flex;align-items:center;justify-content:center;width:${sub?14:16}px;height:${sub?14:16}px;border-radius:50%;border:1.5px solid ${sel?'#0f172a':'#cbd5e1'};background:${sel?'#0f172a':'#fff'};color:#fff;font-size:10px;font-weight:900;flex-shrink:0;line-height:1">${sel?'●':''}</span>
      ${label}
    </div>`;
  const primarios = [
    { k:'',            label:'<span style="font-size:11.5px;color:#64748b;font-style:italic">— Sin registro —</span>' },
    { k:'Asistencia',  label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Asistencia']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Asistencia</span>` },
    { k:'Falta',       label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Falta']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Falta</span>` },
    { k:'Vacaciones',  label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Vacaciones']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Vacaciones</span>` },
    { k:'Incapacidad', label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Incapacidad']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Incapacidad</span>` },
    { k:'Feriado',     label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Feriado']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Día feriado</span>` },
  ];
  let html = '<div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em;padding:4px 8px 2px">Estado</div>';
  primarios.forEach(p => {
    let sel;
    if (p.k === '') sel = !S.concepto;
    else if (p.k === 'Asistencia') sel = curGroup === 'Asistencia';
    else sel = curNorm === p.k;
    const sendKey = p.k === 'Asistencia' ? 'Regular' : p.k;
    html += rowHtml(p.label, sel, false, sendKey);
  });
  if (curGroup === 'Asistencia') {
    html += '<div style="height:1px;background:#e2e8f0;margin:4px 0"></div>';
    html += '<div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em;padding:4px 8px 2px">Tipo de asistencia</div>';
    ASIST_PANEL_SUBS_ASISTENCIA.forEach(subKey => {
      const c = ASIST_PANEL_CONCEPTO_MAP[subKey];
      const sel = curNorm === subKey;
      const monto = asistPanelFmtMonto_(ASIST_PANEL_SAL_BASE * c.mult);
      const displayLabel = c.label || subKey;
      const labelHtml = `
        <span style="width:8px;height:8px;border-radius:50%;background:${c.color};display:inline-block"></span>
        <span style="font-size:11px;font-weight:700;color:#334155">${displayLabel}</span>
        <span style="margin-left:auto;font-size:10.5px;font-weight:800;color:#0f172a;background:#f1f5f9;padding:1px 6px;border-radius:4px">${monto}</span>`;
      html += rowHtml(labelHtml, sel, true, subKey);
    });
  }
  const compOn = !!S.comp;
  html += '<div style="height:1px;background:#e2e8f0;margin:4px 0"></div>';
  html += `<div onclick="event.stopPropagation();asistCalMenuToggleComp()"
    style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;cursor:pointer;user-select:none">
    <span style="display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:4px;border:1.5px solid ${compOn?'#0d9488':'#cbd5e1'};background:${compOn?'#0d9488':'#fff'};color:#fff;font-size:11px;font-weight:900;flex-shrink:0;line-height:1">${compOn?'✓':''}</span>
    <span style="width:10px;height:10px;border-radius:2px;background:#0d9488;display:inline-block"></span>
    <span style="font-size:12px;font-weight:800;color:#0f172a">Compensación</span>
  </div>`;
  if (compOn) {
    const cVal = S.comp || { concepto:'', monto:0 };
    html += `
      <div style="padding:4px 8px 8px 30px;display:flex;flex-direction:column;gap:6px" onclick="event.stopPropagation()">
        <div style="display:flex;flex-direction:column;gap:3px">
          <label style="font-size:10px;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:.03em">Concepto</label>
          <input type="text" value="${esc(cVal.concepto)}" oninput="asistCalMenuSetComp('concepto', this.value)"
            style="all:unset;padding:5px 8px;border:1.5px solid #cbd5e1;border-radius:5px;font-size:11.5px;color:#0f172a;background:#fff;box-sizing:border-box;width:100%"
            placeholder="p. ej. Ajuste transporte">
        </div>
        <div style="display:flex;flex-direction:column;gap:3px">
          <label style="font-size:10px;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:.03em">Monto</label>
          <input type="number" step="0.01" min="0" value="${cVal.monto || ''}" oninput="asistCalMenuSetComp('monto', this.value)"
            style="all:unset;padding:5px 8px;border:1.5px solid #cbd5e1;border-radius:5px;font-size:11.5px;color:#0f172a;background:#fff;box-sizing:border-box;width:100%;text-align:right;font-weight:800"
            placeholder="0.00">
        </div>
      </div>`;
  }
  // Comentarios — texto libre, siempre visible (no es check).
  html += '<div style="height:1px;background:#e2e8f0;margin:4px 0"></div>';
  html += `
    <div style="padding:4px 8px 6px;display:flex;flex-direction:column;gap:4px" onclick="event.stopPropagation()">
      <label style="display:flex;align-items:center;gap:6px;font-size:12px;font-weight:800;color:#0f172a">💬 Comentarios</label>
      <textarea rows="2" maxlength="500" oninput="asistCalMenuSetComentarios(this.value)"
        style="all:unset;padding:5px 8px;border:1.5px solid #cbd5e1;border-radius:5px;font-size:11.5px;color:#0f172a;background:#fff;box-sizing:border-box;width:100%;min-height:38px;white-space:pre-wrap;word-break:break-word;resize:vertical"
        placeholder="Escribe un comentario…">${esc(S.comentarios || '')}</textarea>
    </div>`;
  html += `<div style="display:flex;gap:6px;padding:6px 4px 2px;margin-top:4px;border-top:1px solid #e2e8f0">
    <button type="button" onclick="asistCalMenuGuardar()" ${S.saving?'disabled':''}
      style="all:unset;cursor:pointer;flex:1;text-align:center;padding:7px 10px;border-radius:6px;background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;font-size:11.5px;font-weight:900;letter-spacing:.02em">
      ${S.saving ? '⏳ Guardando…' : '💾 Guardar'}
    </button>
    <button type="button" onclick="asistCalMenuCerrar()"
      style="all:unset;cursor:pointer;text-align:center;padding:7px 12px;border-radius:6px;background:#f1f5f9;color:#334155;font-size:11.5px;font-weight:700">
      Cancelar
    </button>
  </div>`;
  m.innerHTML = html;
  // Posicionamiento
  m.style.visibility = 'hidden';
  const x = ev ? ev.clientX : window.innerWidth/2;
  const y = ev ? ev.clientY : window.innerHeight/2;
  m.style.left = `${Math.max(8, Math.min(x, window.innerWidth - 240))}px`;
  m.style.top  = `${y + 8}px`;
  m.style.visibility = '';
  const menuRect = m.getBoundingClientRect();
  if (menuRect.bottom > window.innerHeight - 8) {
    m.style.top = `${Math.max(8, y - menuRect.height - 8)}px`;
  }
  if (menuRect.right > window.innerWidth - 8) {
    m.style.left = `${Math.max(8, window.innerWidth - menuRect.width - 8)}px`;
  }
  // Close on outside click
  setTimeout(() => document.addEventListener('click', asistCalMenuCloseOnOutside, { once:true }), 0);
}

function asistCalMenuCloseOnOutside(ev) {
  const m = document.getElementById('asist-panel-cell-menu');
  if (!m) return;
  if (m.contains(ev.target)) { document.addEventListener('click', asistCalMenuCloseOnOutside, { once:true }); return; }
  // Auto-guarda al cerrar por clic afuera. Si el usuario cambió algo y
  // simplemente hizo clic fuera del popup (sin oprimir Guardar), asumimos
  // que quiso confirmar — de otra forma el cambio se pierde y la celda
  // no refleja nada (requería refresh manual de la página).
  m.remove();
  if (typeof asistCalMenuGuardar === 'function' && !ASIST_CAL_EDIT.saving) {
    asistCalMenuGuardar();
  }
}

window.asistCalMenuCerrar = function () {
  const m = document.getElementById('asist-panel-cell-menu');
  if (m) m.remove();
};

window.asistCalMenuSetConcepto = function (concepto) {
  const S = ASIST_CAL_EDIT;
  const prevGroup = ASIST_PANEL_CONCEPTO_MAP[asistPanelNormalizarConceptoLegado_(S.concepto)]?.group || '';
  S.concepto = concepto || '';
  const newGroup = ASIST_PANEL_CONCEPTO_MAP[asistPanelNormalizarConceptoLegado_(S.concepto)]?.group || '';
  // Auto-guarda inmediato en estos casos (no requiere sub-clasificación ni
  // compensación adicional): Sin registro (delete), Falta, Vacaciones,
  // Incapacidad, o cualquier sub de Asistencia (Regular, Vac laboradas,
  // Día feriado, Domingo). Si el usuario acaba de elegir Asistencia por
  // primera vez, dejamos el menú abierto para escoger la sub.
  const abrirParaSub = newGroup === 'Asistencia' && prevGroup !== 'Asistencia';
  if (abrirParaSub) {
    _asistCalRenderMenu_();  // Mantiene abierto para elegir sub.
  } else {
    // Cierra + guarda.
    const m = document.getElementById('asist-panel-cell-menu');
    if (m) m.remove();
    if (!ASIST_CAL_EDIT.saving) asistCalMenuGuardar();
  }
};

window.asistCalMenuToggleComp = function () {
  const S = ASIST_CAL_EDIT;
  if (S.comp) S.comp = null;
  else S.comp = { concepto:'', monto:0 };
  _asistCalRenderMenu_();
};

window.asistCalMenuSetComp = function (field, value) {
  const S = ASIST_CAL_EDIT;
  if (!S.comp) S.comp = { concepto:'', monto:0 };
  if (field === 'monto') S.comp.monto = Number(String(value).replace(/[^0-9.-]/g,'')) || 0;
  else S.comp.concepto = String(value || '').slice(0, 120);
};

window.asistCalMenuSetComentarios = function (value) {
  ASIST_CAL_EDIT.comentarios = String(value || '').slice(0, 500);
};

window.asistCalMenuGuardar = async function () {
  const S = ASIST_CAL_EDIT;
  if (S.saving) return;
  S.saving = true;
  _asistCalRenderMenu_();
  const nombre = S.nombre;
  const iso    = S.iso;
  const row    = _asistCalRowFor_(nombre, iso);
  const concepto = S.concepto || '';
  const compFinal = (S.comp && (S.comp.concepto || Number(S.comp.monto) > 0)) ? S.comp : null;
  const comentarios = String(S.comentarios || '').trim();
  // Guardarail: no crear nuevos registros más allá de la ventana permitida
  // (hoy + ASIST_CAL_FUTURE_DAYS). Solo se permite operar sobre registros
  // existentes para borrarlos.
  const _maxIso = _asistCalMaxIso_();
  if (iso > _maxIso && !row) {
    alert('⚠️ No se pueden agregar registros más allá de ' + ASIST_CAL_FUTURE_DAYS + ' días a futuro.\n\nÚltima fecha permitida: ' + _maxIso + '.');
    asistCalMenuCerrar(); S.saving = false; return;
  }
  // Sin cambios reales → cierra sin trabajo.
  const rowConceptoNorm = row
    ? asistPanelNormalizarConceptoLegado_(String(row.Concepto||'').trim() || ((String(row.Entrada||'').trim() || String(row.Salida||'').trim()) ? 'Regular' : ''))
    : '';
  const rowCompMonto  = row ? (Number(String(row['Compensación_monto']||'').replace(/[$,\s]/g,'')) || 0) : 0;
  const rowCompConc   = row ? String(row['Compensación_concepto'] || '').trim() : '';
  const conceptoIgual = rowConceptoNorm === concepto;
  const compIgual = ((rowCompMonto === (compFinal ? Number(compFinal.monto)||0 : 0))
                   && (rowCompConc === (compFinal ? String(compFinal.concepto||'') : '')));
  const comIgual = String(row ? row.Comentarios || '' : '').trim() === comentarios;
  if (conceptoIgual && compIgual && comIgual) { asistCalMenuCerrar(); S.saving = false; return; }
  if (!row && !concepto && !compFinal && !comentarios) { asistCalMenuCerrar(); S.saving = false; return; }

  // ── ACTUALIZACIÓN OPTIMISTA en ASIST_STATE.rows + re-render inmediato ──
  // El usuario ve el cambio en el calendario al instante. Las llamadas al
  // backend corren en background; si fallan, revertimos y avisamos.
  const isAs = asistPanelEsDiaTrabajado_(concepto);
  const p    = asistPanelPrimasPorConcepto_(concepto);
  const fmt  = v => v === '' ? '' : asistPanelFmtMonto_(v);
  const totalPago = ['salBase','primaVac','primaDom','primaDF'].reduce((s,k)=>s+(typeof p[k]==='number'?p[k]:0),0)
                 + (compFinal ? Number(compFinal.monto)||0 : 0);
  const preserve = row || {};
  // Registro de SOLO comentario (sin estado ni compensación): sin horas,
  // sin método y sin montos — solo Timestamp, Empleado, Fecha y Comentarios.
  const soloComentario = !concepto && !compFinal && !!comentarios;
  const metodoFinal = String(preserve.Metodo||'').trim() || (soloComentario ? '' : 'Manual');
  const entrada = concepto ? (String(preserve.Entrada||'').trim() || (isAs ? '08:30' : '')) : '';
  const salida  = concepto ? (String(preserve.Salida ||'').trim() || (isAs ? '13:30' : '')) : '';
  const horas   = concepto ? (String(preserve.Horas  ||'').trim() || (isAs ? '5h00'  : '')) : '';
  const _now = new Date();
  const _ts = `${_now.getFullYear()}-${String(_now.getMonth()+1).padStart(2,'0')}-${String(_now.getDate()).padStart(2,'0')} ${String(_now.getHours()).padStart(2,'0')}:${String(_now.getMinutes()).padStart(2,'0')}:${String(_now.getSeconds()).padStart(2,'0')}`;
  const optimisticRow = row ? { ...row } : {
    ID: 'AST-tmp-' + Date.now(),
    Timestamp: _ts,
    Empleado_Nombre: nombre,
    Fecha: iso,
  };
  optimisticRow.Comentarios = comentarios;
  if (!concepto) optimisticRow.Tipo = '';
  optimisticRow.Concepto = concepto;
  optimisticRow.Entrada  = entrada;
  optimisticRow.Salida   = salida;
  optimisticRow.Horas    = horas;
  optimisticRow['$ Salario base']             = fmt(p.salBase);
  optimisticRow['$ Prima vacacional (25%)']   = fmt(p.primaVac);
  optimisticRow['$ Prima dominical (25%)']    = fmt(p.primaDom);
  optimisticRow['$ Prima día feriado (200%)'] = fmt(p.primaDF);
  optimisticRow['$ Salario total']            = totalPago ? asistPanelFmtMonto_(totalPago) : '';
  optimisticRow.Metodo                        = metodoFinal;
  optimisticRow['Compensación_concepto']      = compFinal ? String(compFinal.concepto || '') : '';
  optimisticRow['Compensación_monto']         = compFinal && compFinal.monto ? asistPanelFmtMonto_(Number(compFinal.monto)) : '';
  const backupRows = (ASIST_STATE.rows || []).slice();
  const isDeletion = row && !concepto && !compFinal && !comentarios;
  const arr = ASIST_STATE.rows || [];
  // Todos los registros previos de este (empleado, día) — hay que
  // borrarlos para evitar duplicados si el usuario cambió el concepto
  // varias veces o si arrastramos rows desde reloads previos.
  const allExisting = _asistCalAllRowsFor_(nombre, iso);
  const existingIds = new Set(allExisting.map(r => String(r.ID)));
  if (isDeletion) {
    ASIST_STATE.rows = arr.filter(r => !existingIds.has(String(r.ID)));
  } else {
    ASIST_STATE.rows = arr.filter(r => !existingIds.has(String(r.ID))).concat([optimisticRow]);
  }
  asistCalMenuCerrar();
  S.saving = false;
  ASIST_STATE._focusMode = 'preserve'; // no mover el scroll horizontal
  // Marca dirty ANTES del render para que la toolbar salga con el botón
  // "Guardar cambios" visible en la misma pasada.
  try { _asistCalMarkDirty_(); } catch(_){}
  if (typeof asistRenderCalendar === 'function') asistRenderCalendar();

  // ── Reales al backend en background ──
  // Medido (sep-2026): el flujo anterior hacía GET lista (~5s) + DELETE con
  // papelera (~4s) + POST insert (~5.6s) + GET lista (~5s) ≈ 20s por celda.
  // Ahora: UNA sola llamada — update in-place por ID (~3.7s) si la celda ya
  // tenía registro, insert si no, DELETE solo si se vacía. Sin recargar la
  // lista: el estado local ya es la verdad. Los guardados de una misma celda
  // se encadenan para que un 2º cambio use el ID real del 1º.
  const _cellKey = nombre + '|' + iso;
  const _prev = ASIST_CAL_MODE.chains.get(_cellKey) || Promise.resolve();
  const _job = _prev.catch(() => {}).then(async () => {
    const _t0 = performance.now();
    const _idMap = ASIST_CAL_MODE.idMap;
    const _resolve = (id) => { id = String(id || ''); while (_idMap.has(id)) id = _idMap.get(id); return id; };
    const ids = Array.from(existingIds).map(_resolve).filter(id => id && !id.startsWith('AST-tmp-'));
    const _del = (id, why) => fetch(`${BACKEND}/rh/asistencia/${encodeURIComponent(id)}?force=true&reason=` + encodeURIComponent(why), { method:'DELETE' })
      .then(r => r.json()).then(j => { if (!j || !j.ok) throw new Error((j && j.error) || 'DELETE falló'); });
    try {
      if (isDeletion) {
        await Promise.all(ids.map(id => _del(id, 'borrado desde calendario')));
      } else {
        const payload = {
          Empleado_Nombre: nombre, Fecha: iso, Concepto: concepto,
          Entrada: entrada, Salida: salida, Horas: horas,
          '$ Salario base':             fmt(p.salBase),
          '$ Prima vacacional (25%)':   fmt(p.primaVac),
          '$ Prima dominical (25%)':    fmt(p.primaDom),
          '$ Prima día feriado (200%)': fmt(p.primaDF),
          '$ Salario total':            totalPago ? asistPanelFmtMonto_(totalPago) : '',
          Metodo: metodoFinal,
          'Compensación_concepto': compFinal ? String(compFinal.concepto || '') : '',
          'Compensación_monto':    compFinal && compFinal.monto ? asistPanelFmtMonto_(Number(compFinal.monto)) : '',
          Comentarios: comentarios,
        };
        if (!concepto) payload.Tipo = '';
        const primary = ids[0] || '';
        if (primary) payload.ID = primary; // update in-place (conserva GPS, Timestamp, etc.)
        else { payload.Observaciones = ''; payload.Timestamp = optimisticRow.Timestamp || ''; }
        const [j] = await Promise.all([
          fetch(`${BACKEND}/rh/asistencia`, {
            method:'POST', headers:{ 'Content-Type':'application/json' },
            body: JSON.stringify({ payload }),
          }).then(r => r.json()),
          // Duplicados viejos del mismo (empleado, día) — se borran en paralelo.
          ...ids.slice(1).map(id => _del(id, 'duplicado (empleado, día) desde calendario')),
        ]);
        if (!j || !j.ok) throw new Error((j && j.error) || 'POST falló');
        const realId = String(j.id || primary || '');
        if (realId && String(optimisticRow.ID) !== realId) {
          _idMap.set(String(optimisticRow.ID), realId);
          optimisticRow.ID = realId;
        }
      }
      console.log(`[asist-cal] guardado ${nombre} ${iso} (${isDeletion ? 'delete' : (ids.length ? 'update' : 'insert')}) en ${Math.round(performance.now() - _t0)}ms`);
    } catch (e) {
      console.warn('[asist-cal] guardar falló (background):', e.message);
      alert('❌ Error al guardar ' + nombre + ' ' + iso + ': ' + e.message + '\n\nSe recargarán los registros reales.');
      try { await asistReloadList(); } catch(_){}
      throw e;
    }
  });
  ASIST_CAL_MODE.chains.set(_cellKey, _job);
  ASIST_CAL_MODE.pending.add(_job);
  _asistCalSyncChip_();
  _job.catch(() => {}).finally(() => {
    ASIST_CAL_MODE.pending.delete(_job);
    if (ASIST_CAL_MODE.chains.get(_cellKey) === _job) ASIST_CAL_MODE.chains.delete(_cellKey);
    _asistCalSyncChip_();
  });
};

/** Puebla el <select> del empleado con nombres de la hoja Personal. */
function asistPopulateEmpleadoSelect() {
  const sel = document.getElementById('asist-empleado');
  if (!sel) return;
  const personas = (INC_STATE && Array.isArray(INC_STATE.personas)) ? INC_STATE.personas.slice() : [];
  personas.sort((a, b) => String(a).localeCompare(String(b), 'es'));
  sel.innerHTML = `<option value="">— Selecciona —</option>` +
    personas.map(n => `<option value="${esc(n)}">${esc(n)}</option>`).join('');
}

/** Botón principal: abre el panel deslizable (derecha → centro), captura
 *  fecha/hora AHORA e inicia geolocalización. Mueve el panel a <body> por si
 *  algún ancestro tiene display:none (mismo patrón que otros paneles inc/obj). */
// ── Panel lateral "Registro de asistencia": semana + mini-calendario ──
// Formato Dias_trabajo en hoja Personal: "L,M,Mi,J,V,S,D"
// L=1(Lun) M=2(Mar) Mi=3(Mié) J=4(Jue) V=5(Vie) S=6(Sáb) D=0(Dom)
const ASIST_DIAS_MAP = { L:1, M:2, MI:3, J:4, V:5, S:6, D:0 };
// Conceptos disponibles con su color asignado.
// ── Modelo de conceptos ──────────────────────────────────────────────────
// Estado principal (radio): Asistencia · Falta · Vacaciones · Incapacidad · vacío.
// Sub-clasificación (solo si Asistencia): Regular · Vac laboradas · Día feriado · Domingo.
// El sub concepto sustituye al principal como valor guardado en la celda —
// así el sheet almacena un solo Concepto por fila y basta con leerlo para
// derivar tanto el grupo (color) como el monto/primas.
const ASIST_PANEL_SAL_BASE = 315.04;
const ASIST_PANEL_PRIMA_VAC = 0.25;
const ASIST_PANEL_PRIMA_DOM = 0.25;
const ASIST_PANEL_PRIMA_DF  = 2.00;
// mult = factor por el que se multiplica SAL_BASE para obtener el pago del día.
const ASIST_PANEL_CONCEPTOS = [
  // Asistencia (grupo verde) — 5 sub-clasificaciones.
  { k:'Regular',        color:'#16a34a', group:'Asistencia', mult: 1                                      },
  { k:'Vac laboradas',  color:'#0d9488', group:'Asistencia', mult: 1 + ASIST_PANEL_PRIMA_VAC              },
  { k:'Día feriado',    color:'#1d4ed8', group:'Asistencia', mult: 1 + ASIST_PANEL_PRIMA_DF, label: 'Día feriado laborado' },
  { k:'Domingo',        color:'#4f46e5', group:'Asistencia', mult: 1 + ASIST_PANEL_PRIMA_DOM              },
  // "Sin beneficios": el empleado asistió pero no cobra base ni primas
  // (arreglo especial). Solo puede llevar compensación libre en esa celda.
  { k:'Sin beneficios', color:'#94a3b8', group:'Asistencia', mult: 0                                      },
  // Estados principales sin sub.
  { k:'Falta',         color:'#dc2626', group:'Falta',      mult: 0                                      },
  { k:'Vacaciones',    color:'#f59e0b', group:'Vacaciones', mult: 1 + ASIST_PANEL_PRIMA_VAC              },
  { k:'Incapacidad',   color:'#7c3aed', group:'Incapacidad',mult: 0                                      },
  // "Feriado" (día feriado NO trabajado): empleado no vino pero se le paga
  // el salario base. Clave interna 'Feriado' para no colisionar con la sub
  // 'Día feriado' (worked, mult=3). Label UI = "Día feriado".
  { k:'Feriado',       color:'#0ea5e9', group:'Feriado',    mult: 1,           label: 'Día feriado'      },
];
const ASIST_PANEL_CONCEPTO_MAP = Object.fromEntries(ASIST_PANEL_CONCEPTOS.map(c => [c.k, c]));
const ASIST_PANEL_CONCEPTO_COLOR = Object.fromEntries(ASIST_PANEL_CONCEPTOS.map(c => [c.k, c.color]));
// Colores por grupo (para el fondo de la celda — no importa cuál sub).
const ASIST_PANEL_GROUP_COLOR = {
  'Asistencia':  '#16a34a',
  'Falta':       '#dc2626',
  'Vacaciones':  '#f59e0b',
  'Incapacidad': '#7c3aed',
  'Feriado':     '#0ea5e9',
};
// Sub-clasificaciones válidas para "Asistencia".
const ASIST_PANEL_SUBS_ASISTENCIA = ['Regular','Vac laboradas','Día feriado','Domingo','Sin beneficios'];
// Alias de compatibilidad: registros viejos con Concepto='Asistencia' se
// tratan como 'Regular' al leerlos del sheet.
function asistPanelNormalizarConceptoLegado_(concepto) {
  const s = String(concepto || '').trim();
  if (s === 'Asistencia') return 'Regular';
  return s;
}
function asistPanelMontoDe_(concepto) {
  const c = ASIST_PANEL_CONCEPTO_MAP[asistPanelNormalizarConceptoLegado_(concepto)];
  return c ? ASIST_PANEL_SAL_BASE * c.mult : 0;
}
function asistPanelFmtMonto_(n) {
  return '$' + n.toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
/** Desglose ($ por columna) que corresponde a UN concepto. Cada columna se
 *  llena solo cuando el concepto la justifica; el resto queda vacío. */
function asistPanelPrimasPorConcepto_(concepto) {
  const base = ASIST_PANEL_SAL_BASE;
  const k = asistPanelNormalizarConceptoLegado_(concepto);
  const empty = { salBase: '', primaVac: '', primaDom: '', primaDF: '' };
  switch (k) {
    case 'Regular':       return { salBase: base, primaVac: '',                          primaDom: '',                          primaDF: '' };
    case 'Vac laboradas': return { salBase: base, primaVac: base * ASIST_PANEL_PRIMA_VAC, primaDom: '',                          primaDF: '' };
    case 'Día feriado':   return { salBase: base, primaVac: '',                          primaDom: '',                          primaDF: base * ASIST_PANEL_PRIMA_DF };
    case 'Domingo':       return { salBase: base, primaVac: '',                          primaDom: base * ASIST_PANEL_PRIMA_DOM, primaDF: '' };
    case 'Vacaciones':    return { salBase: base, primaVac: base * ASIST_PANEL_PRIMA_VAC, primaDom: '',                          primaDF: '' };
    case 'Falta':         return empty;
    case 'Incapacidad':   return empty;
    // "Sin beneficios": no paga base ni primas (solo compensación libre
    // capturada aparte en la celda).
    case 'Sin beneficios': return empty;
    default:              return empty;
  }
}
// Un concepto "cuenta como día trabajado" para la fórmula del salario semanal
// si su grupo es 'Asistencia' (Regular, Vac laboradas, Día feriado, Domingo).
function asistPanelEsDiaTrabajado_(concepto) {
  const c = ASIST_PANEL_CONCEPTO_MAP[asistPanelNormalizarConceptoLegado_(concepto)];
  return !!(c && c.group === 'Asistencia');
}
// Un concepto "paga salario base" (aporta al Base laborado semanal) cuando
// el empleado recibe salario base ese día — no solo días efectivamente
// trabajados, también Vacaciones y Feriado no trabajado (ambos son días
// pagados por ley). NO pagan base: 'Falta', 'Incapacidad' y 'Sin beneficios'
// (esta última es asistencia sin salario — solo permite compensación libre).
function asistPanelPagaSalarioBase_(concepto) {
  const k = asistPanelNormalizarConceptoLegado_(concepto);
  const c = ASIST_PANEL_CONCEPTO_MAP[k];
  if (!c) return false;
  if (k === 'Sin beneficios') return false;
  return c.group === 'Asistencia' || c.group === 'Vacaciones' || c.group === 'Feriado';
}
function asistPanelParseDiasTrabajo_(str) {
  const out = new Set();
  String(str||'').split(/[,;\s]+/).map(t => t.trim().toUpperCase()).filter(Boolean).forEach(tok => {
    if (ASIST_DIAS_MAP[tok] != null) out.add(ASIST_DIAS_MAP[tok]);
  });
  return out;
}
function asistPanelParseSemanaValue_(val) {
  const m = String(val||'').match(/^S:(\d{4}-\d{2}-\d{2})_(\d{4}-\d{2}-\d{2})$/);
  if (!m) return null;
  const [y1,mo1,d1] = m[1].split('-').map(Number);
  const [y2,mo2,d2] = m[2].split('-').map(Number);
  return { lunes: new Date(y1, mo1-1, d1), domingo: new Date(y2, mo2-1, d2) };
}

window.asistNuevoRegistro = function () {
  ['asist-form-backdrop','asist-form-panel'].forEach(id => {
    const el = document.getElementById(id);
    if (el && el.parentElement !== document.body) document.body.appendChild(el);
  });
  const panel = document.getElementById('asist-form-panel');
  const back  = document.getElementById('asist-form-backdrop');
  if (!panel || !back) return;
  back.classList.remove('hidden');
  panel.classList.remove('hidden');
  setTimeout(() => { back.classList.add('visible'); panel.classList.add('open'); }, 10);
  // Estado inicial del panel: semana actual y celdas marcadas según Dias_trabajo
  const weekOpts = (typeof nomWeekOptions === 'function') ? nomWeekOptions() : [];
  const sel = document.getElementById('asist-panel-semana');
  if (sel) sel.innerHTML = weekOpts.map(o => `<option value="${esc(o.value)}">${esc(o.label)}</option>`).join('');
  const semana = weekOpts[0]?.value || '';
  ASIST_STATE.panel = { semana, celdas: new Map(), compensaciones: new Map() };
  if (sel) sel.value = semana;
  const status = document.getElementById('asist-status');
  if (status) status.textContent = '';
  // Reset dirty + colas pendientes: arranca vacío con "Guardar registro" disabled.
  ASIST_STATE.panel._dirtyChanges = false;
  ASIST_STATE.panel.pendingCreate = new Map();
  ASIST_STATE.panel.pendingDelete = new Set();
  asistPanelUpdateSaveBtn_();
  asistPanelRender();
  // Si el catálogo Personal aún no está cargado en INC_STATE.personalRows,
  // dispara la carga y re-renderiza al terminar. Sin esto, el panel abierto
  // desde el Resumen semanal (donde nunca se abrió Incidencias) cae al
  // fallback INC_STATE.personas (lista hardcoded de 9 personas que NO incluye
  // a todo el personal actual de la hoja Personal).
  try {
    const rows = (INC_STATE && INC_STATE.personalRows) || [];
    if (!rows.length && typeof incLoadPersonal === 'function') {
      incLoadPersonal().then(() => { try { asistPanelRender(); } catch(_){} });
    }
  } catch(_){}
};

function asistPanelState_() {
  if (!ASIST_STATE.panel) ASIST_STATE.panel = { semana:'', celdas:new Map(), compensaciones:new Map() };
  if (!(ASIST_STATE.panel.celdas instanceof Map)) ASIST_STATE.panel.celdas = new Map();
  if (!(ASIST_STATE.panel.compensaciones instanceof Map)) ASIST_STATE.panel.compensaciones = new Map();
  return ASIST_STATE.panel;
}

window.asistPanelSetSemana = function (val) {
  const st = asistPanelState_();
  st.semana = val;
  st.celdas = new Map();
  st._userTouched = false;
  asistPanelRender();
};

// Menú por-celda (single-select): al elegir un concepto se reemplaza el que
// ya tuviera. Volver a elegir el mismo concepto lo quita (limpia la celda).
window.asistPanelCellToggleConcepto = function (nombre, iso, concepto, ev) {
  if (ev) ev.stopPropagation();
  const st = asistPanelState_();
  const k = `${nombre}|${iso}`;
  const cur = st.celdas.get(k);
  const wasSelected = cur && cur.has(concepto);
  if (cur && cur.size === 1 && cur.has(concepto)) st.celdas.delete(k);
  else st.celdas.set(k, new Set([concepto]));
  st._userTouched = true;
  st._dirtyChanges = true;  // habilita "Guardar cambios"
  asistPanelRender();
  asistPanelUpdateSaveBtn_();
  // Cierra el menú tras la selección (single-select).
  const m = document.getElementById('asist-panel-cell-menu');
  if (m) m.remove();
  // El diff real (creates/deletes/updates) se computa al oprimir "Guardar
  // cambios" comparando st.celdas contra ASIST_STATE.rows. Solo marcamos
  // el flag dirty y salimos.
};

// Single-select radio: fija UN concepto en la celda (o la limpia si concepto="").
// Mantiene el menú abierto cuando el usuario cambió el estado principal a
// "Asistencia" para que pueda elegir la sub-clasificación en el mismo popup.
window.asistPanelCellSetConcepto = function (nombre, iso, concepto, ev) {
  if (ev) ev.stopPropagation();
  const st = asistPanelState_();
  const k = `${nombre}|${iso}`;
  const cur = st.celdas.get(k);
  const prevKey = cur ? Array.from(cur)[0] : '';
  const prevGroup = ASIST_PANEL_CONCEPTO_MAP[asistPanelNormalizarConceptoLegado_(prevKey)]?.group || '';
  if (!concepto) st.celdas.delete(k);
  else st.celdas.set(k, new Set([concepto]));
  st._userTouched = true;
  st._dirtyChanges = true;
  asistPanelRender();
  asistPanelUpdateSaveBtn_();
  // Si el usuario pasó de "no-Asistencia" a "Asistencia" (default Regular),
  // deja abierto el menú para que elija sub-clasificación. En cualquier otro
  // cambio cierra el menú tras la selección.
  const newGroup = ASIST_PANEL_CONCEPTO_MAP[asistPanelNormalizarConceptoLegado_(concepto)]?.group || '';
  const abrirDeNuevo = newGroup === 'Asistencia' && prevGroup !== 'Asistencia';
  const m = document.getElementById('asist-panel-cell-menu');
  if (m) m.remove();
  if (abrirDeNuevo) {
    // Re-abre inmediatamente para mostrar la sub-clasificación.
    setTimeout(() => asistPanelOpenCellMenu(nombre, iso, null), 0);
  }
};

// Toggle del checkbox "Compensación" en el popup — al activarlo, deja
// asentada una compensación con concepto/monto vacíos; al desactivarlo
// borra la compensación de la celda.
window.asistPanelToggleCompensacion = function (nombre, iso, ev) {
  if (ev) ev.stopPropagation();
  const st = asistPanelState_();
  const k = `${nombre}|${iso}`;
  const cur = st.compensaciones.get(k);
  if (cur) st.compensaciones.delete(k);
  else st.compensaciones.set(k, { concepto: '', monto: 0 });
  st._userTouched = true;
  st._dirtyChanges = true;
  // Re-abrimos el popup en el mismo lugar para mostrar/ocultar los inputs
  // sin cerrarlo, y re-renderizamos el calendario para reflejar el monto
  // en la celda.
  asistPanelRender();
  asistPanelUpdateSaveBtn_();
  const m = document.getElementById('asist-panel-cell-menu');
  if (m) m.remove();
  setTimeout(() => asistPanelOpenCellMenu(nombre, iso, null), 0);
};

// Actualiza uno de los campos (concepto / monto) de la compensación de
// la celda. Se dispara con cada 'input' — no re-abre el menú para no
// perder el foco del campo mientras el usuario escribe.
window.asistPanelUpdateCompensacion = function (nombre, iso, field, value) {
  const st = asistPanelState_();
  const k = `${nombre}|${iso}`;
  const cur = st.compensaciones.get(k) || { concepto: '', monto: 0 };
  if (field === 'monto') cur.monto = Number(String(value).replace(/[^0-9.-]/g,'')) || 0;
  else if (field === 'concepto') cur.concepto = String(value || '').slice(0, 120);
  st.compensaciones.set(k, cur);
  st._userTouched = true;
  st._dirtyChanges = true;
  asistPanelUpdateSaveBtn_();
  // Re-render completo: el popup vive como hijo del <body> (position:fixed)
  // así que NO se pierde al reconstruir las celdas del calendario, y el
  // input activo mantiene el foco. Necesitamos el re-render completo para
  // actualizar (a) la celda del día con el desglose y (b) la columna
  // semanal "$ Compensación" + "Salario TOTAL" del empleado.
  asistPanelRender();
};

async function _asistPanelEliminarRegistro(id) {
  try {
    const res = await fetch(`${BACKEND}/rh/asistencia/${encodeURIComponent(id)}`, { method:'DELETE' });
    const j = await res.json();
    if (!j.ok) throw new Error(j.error || 'error');
    if (typeof asistReloadList === 'function') asistReloadList();
  } catch (e) {
    console.warn('[asist-panel] eliminar registro falló:', e.message);
  }
}

async function _asistPanelCrearRegistroAsistencia(nombre, iso) {
  // GUARD anti-duplicados: si ya hay un fetch en vuelo para este par
  // {empleado, fecha}, no lo mandes de nuevo (los clicks rápidos y el
  // asistReloadList que aún no ha respondido con la fila nueva causan
  // race conditions que meten hasta 4 filas iguales al sheet).
  window.__asistCreandoSet = window.__asistCreandoSet || new Set();
  const key = `${nombre}|${iso}`;
  if (window.__asistCreandoSet.has(key)) return;
  // También agrega optimistamente a ASIST_STATE.rows para que las
  // comprobaciones de "yaExiste" siguientes vean la fila y no re-posteen.
  ASIST_STATE.rows = ASIST_STATE.rows || [];
  ASIST_STATE.rows.push({
    ID: 'AST-tmp-' + Date.now(),
    Empleado_Nombre: nombre, Fecha: iso,
    Entrada: '08:30', Salida: '13:30',
    Concepto: 'Regular', Metodo: 'Manual', _pending: true,
  });
  window.__asistCreandoSet.add(key);
  const entrada = '08:30';
  const salida  = '13:30';
  const em = asistParseTimeToMinutes(entrada), sm = asistParseTimeToMinutes(salida);
  const horas = (em != null && sm != null && sm >= em)
    ? `${Math.floor((sm-em)/60)}h${String((sm-em)%60).padStart(2,'0')}`
    : '';
  const p = asistPanelPrimasPorConcepto_('Regular');
  const fmt = v => v === '' ? '' : asistPanelFmtMonto_(v);
  const payload = {
    Empleado_Nombre: nombre,
    Fecha: iso,
    Concepto: 'Regular',
    Entrada: entrada,
    Salida:  salida,
    Horas:   horas,
    '$ Salario base':             fmt(p.salBase),
    '$ Prima vacacional (25%)':   fmt(p.primaVac),
    '$ Prima dominical (25%)':    fmt(p.primaDom),
    '$ Prima día feriado (200%)': fmt(p.primaDF),
    '$ Salario total':            (() => { const t = ['salBase','primaVac','primaDom','primaDF'].reduce((s,k) => s + (typeof p[k] === 'number' ? p[k] : 0), 0); return t ? asistPanelFmtMonto_(t) : ''; })(),
    Metodo: 'Manual',
    Observaciones: '',
  };
  try {
    const res = await fetch(`${BACKEND}/rh/asistencia`, {
      method:'POST', headers:{ 'Content-Type':'application/json' },
      body: JSON.stringify({ payload }),
    });
    const j = await res.json();
    if (!j.ok) throw new Error(j.error || 'error');
    // Refresca la tabla para que la nueva fila aparezca reflejada.
    if (typeof asistReloadList === 'function') asistReloadList();
  } catch (e) {
    console.warn('[asist-panel] crear registro falló:', e.message);
  } finally {
    // Libera el lock del par {empleado, fecha} tras completar el fetch
    // (éxito o error) — permite marcar de nuevo si el usuario lo requiere.
    if (window.__asistCreandoSet) window.__asistCreandoSet.delete(key);
  }
}

// Popover con checkboxes de conceptos para una celda concreta. Se posiciona
// absolutamente sobre la celda.
window.asistPanelOpenCellMenu = function (nombre, iso, ev) {
  if (ev) ev.stopPropagation();
  const cont = document.getElementById('asist-panel-cal-wrap');
  if (!cont) return;
  const cell = cont.querySelector(`[data-cell-key="${CSS.escape(`${nombre}|${iso}`)}"]`);
  if (!cell) return;
  // Se ancla al <body> con position:fixed para que NO lo recorten el overflow
  // del contenedor scrollable (asist-panel-cal-wrap). Antes quedaba cortado
  // cuando se abría en la última fila del calendario.
  let m = document.getElementById('asist-panel-cell-menu');
  if (!m) {
    m = document.createElement('div');
    m.id = 'asist-panel-cell-menu';
    m.style.cssText = 'position:fixed;background:#fff;border:1.5px solid #cbd5e1;border-radius:8px;box-shadow:0 8px 20px rgba(15,23,42,.18);z-index:99999;padding:6px;min-width:180px';
    document.body.appendChild(m);
  } else if (m.parentElement !== document.body) {
    document.body.appendChild(m);
  }
  const st = asistPanelState_();
  const cur = st.celdas.get(`${nombre}|${iso}`) || new Set();
  const curKey = Array.from(cur)[0] || '';
  const curNorm = asistPanelNormalizarConceptoLegado_(curKey);
  const curGroup = ASIST_PANEL_CONCEPTO_MAP[curNorm]?.group || '';
  const row = (label, sel, sub, key) => `
    <div onclick="event.stopPropagation();asistPanelCellSetConcepto('${esc(nombre).replace(/'/g,"\\'")}','${iso}','${key}')"
      style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;cursor:pointer;user-select:none;${sub?'padding-left:26px;font-size:11px':''}">
      <span style="display:inline-flex;align-items:center;justify-content:center;width:${sub?14:16}px;height:${sub?14:16}px;border-radius:50%;border:1.5px solid ${sel?'#0f172a':'#cbd5e1'};background:${sel?'#0f172a':'#fff'};color:#fff;font-size:10px;font-weight:900;flex-shrink:0;line-height:1">${sel?'●':''}</span>
      ${label}
    </div>`;
  // Sección 1: Estado principal (radio).
  const primarios = [
    { k:'',            label:'<span style="font-size:11.5px;color:#64748b;font-style:italic">— Sin registro —</span>' },
    { k:'Asistencia',  label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Asistencia']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Asistencia</span>` },
    { k:'Falta',       label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Falta']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Falta</span>` },
    { k:'Vacaciones',  label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Vacaciones']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Vacaciones</span>` },
    { k:'Incapacidad', label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Incapacidad']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Incapacidad</span>` },
    { k:'Feriado',     label:`<span style="width:10px;height:10px;border-radius:2px;background:${ASIST_PANEL_GROUP_COLOR['Feriado']};display:inline-block"></span><span style="font-size:12px;font-weight:800;color:#0f172a">Día feriado</span>` },
  ];
  let html = '<div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em;padding:4px 8px 2px">Estado</div>';
  primarios.forEach(p => {
    let sel;
    if (p.k === '') sel = !curKey;
    else if (p.k === 'Asistencia') sel = curGroup === 'Asistencia';
    else sel = curNorm === p.k;
    // Para el estado principal "Asistencia", la key enviada es 'Regular' (default);
    // el sub se elige en la sección de abajo.
    const sendKey = p.k === 'Asistencia' ? 'Regular' : p.k;
    html += row(p.label, sel, false, sendKey);
  });
  // Sección 2: Sub-clasificación (solo si Asistencia).
  if (curGroup === 'Asistencia') {
    html += '<div style="height:1px;background:#e2e8f0;margin:4px 0"></div>';
    html += '<div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase;letter-spacing:.05em;padding:4px 8px 2px">Tipo de asistencia</div>';
    ASIST_PANEL_SUBS_ASISTENCIA.forEach(subKey => {
      const c = ASIST_PANEL_CONCEPTO_MAP[subKey];
      const sel = curNorm === subKey;
      const monto = asistPanelFmtMonto_(ASIST_PANEL_SAL_BASE * c.mult);
      const displayLabel = c.label || subKey;
      const labelHtml = `
        <span style="width:8px;height:8px;border-radius:50%;background:${c.color};display:inline-block"></span>
        <span style="font-size:11px;font-weight:700;color:#334155">${displayLabel}</span>
        <span style="margin-left:auto;font-size:10.5px;font-weight:800;color:#0f172a;background:#f1f5f9;padding:1px 6px;border-radius:4px">${monto}</span>`;
      html += row(labelHtml, sel, true, subKey);
    });
  }
  // Sección 3: Compensación (checkbox + Concepto + Monto libres).
  const comp = st.compensaciones.get(`${nombre}|${iso}`) || null;
  const compOn = !!comp;
  const compConcepto = comp ? String(comp.concepto || '') : '';
  const compMonto = comp && typeof comp.monto === 'number' ? comp.monto : (comp ? Number(comp.monto || 0) : 0);
  html += '<div style="height:1px;background:#e2e8f0;margin:4px 0"></div>';
  html += `
    <div onclick="event.stopPropagation();asistPanelToggleCompensacion('${esc(nombre).replace(/'/g,"\\'")}','${iso}')"
      style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;cursor:pointer;user-select:none">
      <span style="display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;border-radius:4px;border:1.5px solid ${compOn?'#0d9488':'#cbd5e1'};background:${compOn?'#0d9488':'#fff'};color:#fff;font-size:11px;font-weight:900;flex-shrink:0;line-height:1">${compOn?'✓':''}</span>
      <span style="width:10px;height:10px;border-radius:2px;background:#0d9488;display:inline-block"></span>
      <span style="font-size:12px;font-weight:800;color:#0f172a">Compensación</span>
    </div>`;
  if (compOn) {
    html += `
      <div style="padding:4px 8px 8px 30px;display:flex;flex-direction:column;gap:6px" onclick="event.stopPropagation()">
        <div style="display:flex;flex-direction:column;gap:3px">
          <label style="font-size:10px;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:.03em">Concepto</label>
          <input type="text" value="${esc(compConcepto)}"
            oninput="asistPanelUpdateCompensacion('${esc(nombre).replace(/'/g,"\\'")}','${iso}','concepto', this.value)"
            style="all:unset;padding:5px 8px;border:1.5px solid #cbd5e1;border-radius:5px;font-size:11.5px;color:#0f172a;background:#fff;box-sizing:border-box;width:100%"
            placeholder="p. ej. Ajuste transporte">
        </div>
        <div style="display:flex;flex-direction:column;gap:3px">
          <label style="font-size:10px;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:.03em">Monto</label>
          <input type="number" step="0.01" min="0" value="${compMonto || ''}"
            oninput="asistPanelUpdateCompensacion('${esc(nombre).replace(/'/g,"\\'")}','${iso}','monto', this.value)"
            style="all:unset;padding:5px 8px;border:1.5px solid #cbd5e1;border-radius:5px;font-size:11.5px;color:#0f172a;background:#fff;box-sizing:border-box;width:100%;text-align:right;font-weight:800"
            placeholder="0.00">
        </div>
      </div>`;
  }
  m.innerHTML = html;
  // Posicionamiento fixed en coordenadas de viewport. Si el menú se saldría
  // por debajo del viewport, lo abrimos hacia ARRIBA de la celda.
  const cellRect = cell.getBoundingClientRect();
  m.style.visibility = 'hidden';
  m.style.left = `${Math.max(8, Math.min(cellRect.left, window.innerWidth - 200))}px`;
  m.style.top  = `${cellRect.bottom + 4}px`;
  m.style.visibility = '';
  const menuRect = m.getBoundingClientRect();
  if (menuRect.bottom > window.innerHeight - 8) {
    // No cabe abajo → posiciona arriba de la celda.
    m.style.top = `${Math.max(8, cellRect.top - menuRect.height - 4)}px`;
  }
  if (menuRect.right > window.innerWidth - 8) {
    m.style.left = `${Math.max(8, window.innerWidth - menuRect.width - 8)}px`;
  }
  setTimeout(() => document.addEventListener('click', asistPanelCloseCellMenu_, { once:true }), 0);
};
function asistPanelCloseCellMenu_(ev) {
  const m = document.getElementById('asist-panel-cell-menu');
  if (!m) return;
  if (m.contains(ev.target)) { document.addEventListener('click', asistPanelCloseCellMenu_, { once:true }); return; }
  m.remove();
}

/** Fondo de la celda: color del grupo del concepto principal (Asistencia,
 *  Falta, Vacaciones, Incapacidad) con transparencia ~20%. Sub-clasificaciones
 *  de Asistencia comparten el mismo verde para no confundir visualmente. */
function asistPanelBgFor_(conceptos) {
  const arr = Array.from(conceptos || []);
  if (!arr.length) return '';
  const first = asistPanelNormalizarConceptoLegado_(arr[0]);
  const c = ASIST_PANEL_CONCEPTO_MAP[first];
  if (!c) return '';
  const groupCol = ASIST_PANEL_GROUP_COLOR[c.group] || c.color;
  return groupCol + '33';
}

/** Semáforo izquierdo: usa el color del sub-concepto (así se distingue
 *  Regular de Día feriado / Domingo / Vac laboradas dentro del mismo verde). */
function asistPanelSemaforo_(conceptos) {
  const arr = Array.from(conceptos || []);
  const first = asistPanelNormalizarConceptoLegado_(arr[0]);
  const c = ASIST_PANEL_CONCEPTO_MAP[first];
  return c ? `box-shadow:inset 3px 0 0 ${c.color};` : '';
}

// Renderiza el contenido de UNA celda (base / prima / compensación / total).
// Retorna HTML sin wrapper — se pega dentro del <div flex> de la celda.
function _asistPanelCellInner_(conceptos, comp) {
  const hasConc = !!(conceptos && conceptos.size);
  const compMonto = comp && Number(comp.monto) > 0 ? Number(comp.monto) : 0;
  if (!hasConc && !compMonto) return '';
  let baseN = 0, primaN = 0;
  if (hasConc) {
    const concKey = Array.from(conceptos)[0];
    const p = asistPanelPrimasPorConcepto_(concKey);
    baseN = typeof p.salBase === 'number' ? p.salBase : 0;
    primaN = (typeof p.primaVac === 'number' ? p.primaVac : 0)
           + (typeof p.primaDom === 'number' ? p.primaDom : 0)
           + (typeof p.primaDF  === 'number' ? p.primaDF  : 0);
  }
  const totalN = baseN + primaN + compMonto;
  // Si solo hay una cifra (base, sin prima, sin compensación), muestra
  // el total en una sola línea centrada.
  const partes = [];
  if (baseN > 0) partes.push({ label: asistPanelFmtMonto_(baseN),      color: '#475569', prefix: '' });
  if (primaN > 0) partes.push({ label: asistPanelFmtMonto_(primaN),    color: '#0891b2', prefix: '+' });
  if (compMonto) partes.push({ label: asistPanelFmtMonto_(compMonto),  color: '#c026d3', prefix: '+' });
  if (partes.length <= 1) {
    return `<span style="font-size:10px;font-weight:900;color:#0f172a;line-height:1.05;text-align:center;padding:0 2px">${asistPanelFmtMonto_(totalN)}</span>`;
  }
  return `
    <div style="display:flex;flex-direction:column;align-items:center;line-height:1.05;padding:1px 2px">
      ${partes.map(p => `<span style="font-size:8px;color:${p.color};font-weight:${p.prefix==='+'?800:700}">${p.prefix}${p.label}</span>`).join('')}
      <span style="font-size:9px;color:#0f172a;font-weight:900;border-top:1px solid #cbd5e155;padding-top:1px;margin-top:1px">${asistPanelFmtMonto_(totalN)}</span>
    </div>`;
}

// Normaliza un nombre para hacer matching: trim, lowercase, quita acentos y
// colapsa espacios. Se usa para reconciliar "Adán" con "Adán Ramos".
function _normNombre_(s) {
  return String(s || '')
    .trim()
    .toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/\s+/g, ' ');
}
/** Nombre COMPLETO del empleado a partir de la estructura actual de la hoja
 *  Personal (3 campos: Nombre + Apellido_paterno + Apellido_materno).
 *  Homologa el match/display con los nombres completos que las hojas de
 *  asistencia y nómina guardaron con la estructura anterior (un solo campo
 *  con nombre + apellidos). Maneja registros aún NO migrados: si "Nombre" ya
 *  contiene los apellidos, lo usa tal cual (no los duplica). */
function _rhPersonalFullName_(pr) {
  const nom = String(pr?.Nombre || '').trim();
  const ap  = String(pr?.Apellido_paterno || pr?.['Apellido paterno'] || '').trim();
  const am  = String(pr?.Apellido_materno || pr?.['Apellido materno'] || '').trim();
  if (!ap && !am) return nom;
  const nomN = _normNombre_(nom);
  const apN  = _normNombre_(ap);
  const amN  = _normNombre_(am);
  const yaTiene = (!apN || nomN.includes(apN)) && (!amN || nomN.includes(amN));
  if (yaTiene) return nom;
  return [nom, ap, am].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
}
/** Registra en `map` (Map de nombre-normalizado → nombre canónico) las
 *  variantes plausibles de escritura del empleado, para reconciliar los
 *  nombres INFORMALES con que asistencia/nómina guardaron los registros
 *  (p.ej. "Adán Ramos" o "Sandra Sánchez") contra la estructura ACTUAL de 3
 *  campos, donde el nombre oficial puede traer segundo nombre / segundo
 *  apellido ("Adán Isidro Ramos Lozano", "Sandra Sánchez Rojas").
 *  Las claves fuertes (nombre completo y campo Nombre) se fijan siempre; las
 *  variantes informales no sobrescriben una clave ya tomada por otro empleado. */
function _rhRegisterPersonalAliases_(map, pr) {
  const full = _rhPersonalFullName_(pr);
  if (!full) return;
  const nom = String(pr?.Nombre || '').trim();
  const ap  = String(pr?.Apellido_paterno || pr?.['Apellido paterno'] || '').trim();
  const am  = String(pr?.Apellido_materno || pr?.['Apellido materno'] || '').trim();
  const t1  = nom.split(/\s+/)[0] || '';
  const put = (k, force) => {
    const key = _normNombre_(k);
    if (!key) return;
    if (force || !map.has(key)) map.set(key, full);
  };
  put(full, true);
  if (nom) put(nom, true);
  if (t1 && ap)       put(`${t1} ${ap}`);        // "Adán Ramos", "Sandra Sánchez"
  if (t1 && ap && am) put(`${t1} ${ap} ${am}`);  // "Adán Ramos Lozano"
  if (nom && ap)      put(`${nom} ${ap}`);
  if (t1)             put(t1);                    // solo primer nombre
}
/** IMSS (No. de Seguridad Social) + RFC del empleado, buscando por nombre
 *  completo en la hoja Personal. Para mostrar en los headers de nómina. */
function _rhEmpleadoDatosFiscales_(nombre) {
  const t = _normNombre_(nombre);
  const pr = (INC_STATE?.personalRows || []).find(x => _normNombre_(_rhPersonalFullName_(x)) === t);
  return {
    imss: pr ? String(pr['No. De Seguridad (IMSS)'] || pr['NSS'] || '').trim() : '',
    rfc:  pr ? String(pr['RFC'] || '').trim() : '',
  };
}
// Alta en IMSS del empleado (true si "Sí" o similares). Se usa para pagar
// o no los días de descanso del contrato.
function _empleadoAltaImss_(nombreCanonical) {
  const p = (INC_STATE?.personalRows || []).find(pr =>
    _normNombre_(_rhPersonalFullName_(pr)) === _normNombre_(nombreCanonical)
  );
  const v = String(p?.['Alta en IMSS'] || '').trim().toLowerCase();
  return v === 'sí' || v === 'si' || v === 'true' || v === '1' || v === 'yes';
}

function asistPanelRender() {
  const cont = document.getElementById('asist-panel-cal-wrap');
  if (!cont) return;
  const st = asistPanelState_();
  const range = asistPanelParseSemanaValue_(st.semana);
  if (!range) { cont.innerHTML = ''; return; }
  const dias = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(range.lunes); d.setDate(range.lunes.getDate() + i);
    dias.push(d);
  }
  const personalRows = asistPersonalOperativo().slice().sort((a,b)=>a.nombre.localeCompare(b.nombre,'es'));
  const diasDict = new Map();
  (INC_STATE?.personalRows || []).forEach(r => {
    const n = _rhPersonalFullName_(r);
    if (n) diasDict.set(n, asistPanelParseDiasTrabajo_(r.Dias_trabajo));
  });
  // Semilla: solo marca 'Asistencia' celdas donde YA HAY un registro previo
  // (con Entrada Y/O Salida). Las celdas del día teórico de trabajo sin
  // registro salen en gris claro (no auto-verdes) — se sombrean como
  // "esperado" pero sin monto hasta que exista el registro real.
  // Recorre filas reales y guarda el CONCEPTO exacto de cada una (no
  // hardcodeamos 'Asistencia' — si la fila del sheet tiene Concepto vacío,
  // usamos 'Asistencia' como default para reflejar la ausencia sin generar
  // un diff artificial en el guardado).
  // Mapa de aliases: primer nombre → canonical (nombre completo del Personal).
  // Sirve para reconciliar registros creados con solo "Adán" contra el
  // renglón "Adán Ramos" de la hoja Personal — de otra forma no aparecerían
  // en el calendario.
  const aliasToCanonical = new Map();
  (INC_STATE?.personalRows || []).forEach(pr => _rhRegisterPersonalAliases_(aliasToCanonical, pr));
  const _canonNombre = (raw) => {
    const t = String(raw || '').trim();
    if (!t) return t;
    return aliasToCanonical.get(_normNombre_(t)) || t;
  };
  const conceptoRealByKey = new Map();
  const compensacionRealByKey = new Map();
  (ASIST_STATE?.rows || []).forEach(r => {
    const nm = _canonNombre(String(r.Empleado_Nombre || '').trim());
    let fecha = r.Fecha;
    if (fecha instanceof Date) {
      const pad = n => String(n).padStart(2,'0');
      fecha = `${fecha.getFullYear()}-${pad(fecha.getMonth()+1)}-${pad(fecha.getDate())}`;
    } else {
      fecha = String(fecha || '').slice(0,10);
    }
    if (!nm || !fecha) return;
    const ent = String(r.Entrada || '').trim();
    const sal = String(r.Salida || '').trim();
    // Concepto: solo se asume 'Regular' cuando hay evidencia de trabajo
    // (Entrada/Salida). Un registro que solo tiene compensación —sin
    // Concepto y sin Ent/Sal— NO debe pintar celda de Asistencia.
    let conc = String(r.Concepto || '').trim();
    if (!conc && (ent || sal)) conc = 'Regular';
    conc = asistPanelNormalizarConceptoLegado_(conc);
    if (conc) conceptoRealByKey.set(`${nm}|${fecha}`, conc);
    // Compensación real (si la fila tiene columnas Compensación_concepto /
    // Compensación_monto). Seed en un mapa aparte. IMPORTANTE: el monto
    // se guarda formateado como "$X.XX", así que hay que quitar el "$" y
    // comas antes de convertir a número — con Number('$650.00') sale NaN.
    const _rawMonto = String(r['Compensación_monto'] || r['Compensacion_monto'] || '').replace(/[$,\s]/g, '');
    const compMonto = Number(_rawMonto) || 0;
    const compConcepto = String(r['Compensación_concepto'] || r['Compensacion_concepto'] || '').trim();
    if (compMonto > 0 || compConcepto) {
      compensacionRealByKey.set(`${nm}|${fecha}`, { concepto: compConcepto, monto: compMonto });
    }
  });
  const shouldSeed = st.celdas.size === 0 && !st._userTouched;
  if (shouldSeed) {
    conceptoRealByKey.forEach((concepto, key) => {
      st.celdas.set(key, new Set([concepto]));
    });
    compensacionRealByKey.forEach((comp, key) => {
      st.compensaciones.set(key, { ...comp });
    });
  }
  let html = `<div style="display:flex;flex-wrap:wrap;gap:10px;padding:6px 4px 10px;font-size:11px;color:#475569;font-weight:700">`;
  // Leyenda por grupo principal (no por sub) — mismos 4 colores que las
  // celdas usan de fondo.
  Object.entries(ASIST_PANEL_GROUP_COLOR).forEach(([g, col]) => {
    html += `<span style="display:inline-flex;align-items:center;gap:5px">
      <span style="width:11px;height:11px;border-radius:3px;background:${col};box-shadow:0 0 0 1px rgba(0,0,0,.08)"></span>${g}
    </span>`;
  });
  html += `</div>`;
  // 14 columnas: 7 días + 7 columnas de nómina semanal (Base laborado,
  // Base descanso, Vac, Dom, DF, Compensación, Total).
  html += `<div class="ocup-cal" data-asist-cal="continuous" style="--ocup-days:14">`;
  html += `<div class="ocup-cal-head"><div class="ocup-head-aloj">👥 Personal · ${personalRows.length}</div>`;
  const today = new Date(); today.setHours(0,0,0,0);
  dias.forEach(d => {
    const dow = d.getDay();
    const isToday = d.getTime() === today.getTime();
    const isWeekend = dow === 0 || dow === 6;
    html += `<div class="ocup-head-cell ${isToday?'is-today':''} ${isWeekend?'is-weekend':''}">
      <div class="ocup-head-dow">${OCUP_DOW[dow]}</div>
      <div class="ocup-head-day">${d.getDate()}</div>
    </div>`;
  });
  // 5 columnas de nómina semanal (fondo oscuro para distinguir del bloque diario).
  const salHeader = (icon, dow, day, title) => `
    <div class="ocup-head-cell" style="background:#0f172a;color:#fff" title="${esc(title)}">
      <div class="ocup-head-dow" style="color:#cbd5e1;font-size:10px">${icon} ${dow}</div>
      <div class="ocup-head-day" style="font-size:9.5px;font-weight:800">${day}</div>
    </div>`;
  html += salHeader('💰', 'Base sem.', 'laborado',     'Salario base laborado = $315.04 × N (días efectivamente trabajados).');
  html += salHeader('💤', 'Base sem.', 'descanso',     'Descanso proporcional = $315.04 × 2 × (N/5). Si N≥5 son 2 días completos; si trabajó 4 solo paga 4/5 de esos 2 (1.6 días).');
  html += salHeader('🌴', 'Prima',   'vacac. (25%)',  'Suma de la prima vacacional (25% del base) por los días con concepto Vac laboradas o Vacaciones.');
  html += salHeader('☀️', 'Prima',   'dom. (25%)',    'Suma de la prima dominical (25% del base) por los días con concepto Domingo.');
  html += salHeader('🎉', 'Prima',   'feriado (200%)','Suma de la prima de día feriado (200% del base) por los días con concepto Día feriado.');
  html += salHeader('🎁', '\$', 'Compensación',      'Suma de las compensaciones manuales (concepto+monto) capturadas en las celdas.');
  html += salHeader('💵', 'Salario', 'TOTAL',         'Base laborado + descanso proporcional + primas + compensación.');
  html += `</div>`;
  let totalSemana = 0;
  personalRows.forEach(({ nombre, puesto }) => {
    html += `<div class="ocup-cal-row">`;
    html += `<div class="ocup-aloj-cell">
      <div class="ocup-aloj-img">👤</div>
      <div class="ocup-aloj-info">
        <div class="ocup-aloj-name" title="${esc(nombre)}${puesto?' · '+esc(puesto):''}">${esc(nombre)}</div>
        ${puesto ? `<div class="ocup-aloj-id">${esc(puesto)}</div>` : ''}
      </div>
    </div>`;
    const workDays = diasDict.get(nombre) || new Set();
    dias.forEach(d => {
      const iso = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
      const conceptos = st.celdas.get(`${nombre}|${iso}`);
      const dow = d.getDay();
      const isWeekend = dow === 0 || dow === 6;
      const isTheoreticalWorkday = workDays.has(dow);
      // Estilos:
      //  - Con conceptos: color del concepto (verde para Asistencia).
      //  - Sin conceptos y día teórico laboral: gris claro sombreado.
      //  - Sin conceptos y día NO laboral: sin fondo especial.
      let bg = '';
      let sem = '';
      let title = 'Click para seleccionar conceptos';
      if (conceptos) {
        bg = `background:${asistPanelBgFor_(conceptos)};`;
        sem = asistPanelSemaforo_(conceptos);
        title = Array.from(conceptos).join(' · ');
      } else if (isTheoreticalWorkday) {
        bg = 'background:#f1f5f9;';
        title = 'Día laboral · sin registro aún';
      }
      // Etiqueta central: desglose (base / prima / compensación / total).
      const compEnCelda = st.compensaciones.get(`${nombre}|${iso}`);
      const inner = _asistPanelCellInner_(conceptos, compEnCelda);
      html += `<div class="ocup-day-cell ${isWeekend?'is-weekend':''}"
        data-cell-key="${esc(nombre)}|${iso}"
        style="${bg}${sem}cursor:pointer"
        onclick="asistPanelOpenCellMenu('${esc(nombre).replace(/'/g,"\\'")}','${iso}',event)"
        title="${esc(title)}">
        <div style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;gap:1px">${inner}</div>
      </div>`;
    });
    // ── Nómina semanal (6 columnas) ───────────────────────────────────
    // Base semanal: Fórmula sobre días trabajados. min(7, N+2) × base.
    // Primas: suma por día según concepto. Compensación: suma libre.
    let diasTrab = 0;
    let primaVacSem = 0, primaDomSem = 0, primaDFSem = 0, compSem = 0;
    dias.forEach(d => {
      const iso2 = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
      const cs = st.celdas.get(`${nombre}|${iso2}`);
      if (cs) {
        let cuenta = false;
        for (const k of cs) {
          // Cuenta como día pagado si el concepto paga salario base
          // (Asistencia + Vacaciones + Feriado no trabajado).
          if (asistPanelPagaSalarioBase_(k)) cuenta = true;
          const p = asistPanelPrimasPorConcepto_(k);
          if (typeof p.primaVac === 'number') primaVacSem += p.primaVac;
          if (typeof p.primaDom === 'number') primaDomSem += p.primaDom;
          if (typeof p.primaDF  === 'number') primaDFSem  += p.primaDF;
        }
        if (cuenta) diasTrab++;
      }
      const comp = st.compensaciones.get(`${nombre}|${iso2}`);
      if (comp) compSem += Number(comp.monto) || 0;
    });
    // Fórmula: laborado = N × base.
    // Descanso proporcional sobre los DÍAS DE CONTRATO REALES del empleado
    // (leídos de la columna Dias_trabajo). Si trabaja 6d/semana solo tiene
    // 1 día de descanso; 5d/semana → 2 días; 7d/semana → 0.
    const _workContract = (workDays && workDays.size) || 5;
    const _restContract = Math.max(0, 7 - _workContract);
    // Descanso proporcional para TODO el personal (con o sin IMSS).
    const factorLab = diasTrab;
    const factorDes = _restContract * Math.min(diasTrab / Math.max(1, _workContract), 1);
    const salBaseLab = ASIST_PANEL_SAL_BASE * factorLab;
    const salBaseDes = ASIST_PANEL_SAL_BASE * factorDes;
    const salTotal = salBaseLab + salBaseDes + primaVacSem + primaDomSem + primaDFSem + compSem;
    totalSemana += salTotal;
    const salCell = (v, extra) => `<div class="ocup-day-cell" style="background:#f8fafc;border-left:${extra?.borderLeft || '1px solid #e2e8f0'}"
      title="${esc(extra?.title || '')}">
      <div style="display:flex;align-items:center;justify-content:center;width:100%;height:100%;flex-direction:column;gap:1px;padding:0 3px">
        <span style="font-size:10px;font-weight:${extra?.strong?900:800};color:${extra?.color || '#0f172a'};line-height:1">${v ? asistPanelFmtMonto_(v) : '—'}</span>
        ${extra?.sub ? `<span style="font-size:8.5px;color:#64748b;font-weight:700">${extra.sub}</span>` : ''}
      </div>
    </div>`;
    html += salCell(salBaseLab, { borderLeft:'2px solid #0f172a', title:`Base laborado: ${diasTrab}d × $${ASIST_PANEL_SAL_BASE.toFixed(2)}`, sub:`${diasTrab}d` });
    html += salCell(salBaseDes, {
      title: `Descanso proporcional: ${_restContract}d contrato × min(${diasTrab}/${_workContract}, 1) = ${factorDes.toFixed(2)}d`,
      sub: `${factorDes.toFixed(2)}d de ${_restContract}`,
      color: '#0369a1' });
    html += salCell(primaVacSem, { title:'Suma prima vacacional (25%) de la semana' });
    html += salCell(primaDomSem, { title:'Suma prima dominical (25%) de la semana' });
    html += salCell(primaDFSem,  { title:'Suma prima día feriado (200%) de la semana' });
    html += salCell(compSem,     { title:'Suma de compensaciones libres capturadas en la semana', color:'#86198f' });
    html += salCell(salTotal,    { borderLeft:'2px solid #16a34a', title:'Base laborado + descanso proporcional + primas + compensación', strong:true, color:'#065f46' });
    html += `</div>`;
  });
  html += `</div>`;
  // Total de la semana: suma de la columna "$ Salario semanal" (una por empleado).
  html += `<div style="margin-top:10px;padding:10px 14px;background:linear-gradient(135deg,#0f172a,#1e293b);color:#fff;border-radius:8px;display:flex;justify-content:space-between;align-items:center;font-weight:800">
    <span style="font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:#cbd5e1">Total semana · todos los trabajadores</span>
    <span style="font-size:16px">${asistPanelFmtMonto_(totalSemana)}</span>
  </div>`;
  cont.innerHTML = html;
}
window.asistPanelRender = asistPanelRender;

/** Actualiza el botón "Guardar registro/cambios" según el estado dirty.
 *  Cuando el usuario ha creado o eliminado registros manuales desde el
 *  calendario, el botón pasa a "💾 Guardar cambios" y se habilita. */
function asistPanelUpdateSaveBtn_() {
  const btn = document.getElementById('asist-btn-guardar');
  if (!btn) return;
  const st = asistPanelState_();
  const dirty = !!st._dirtyChanges;
  btn.textContent = dirty ? '💾 Guardar cambios' : '💾 Guardar registro';
  btn.disabled = !dirty;
  btn.style.opacity = dirty ? '1' : '.5';
  btn.style.cursor  = dirty ? 'pointer' : 'not-allowed';
}
window.asistPanelUpdateSaveBtn_ = asistPanelUpdateSaveBtn_;

/** Captura la ubicación GPS via navegador con fallback a baja precisión. */
function asistCaptureGeo(opts) {
  opts = opts || {};
  const info = document.getElementById('asist-ubicacion-info');
  if (!opts._retry) {
    ASIST_STATE.currentGeo = null;
    document.getElementById('asist-lat').value = '';
    document.getElementById('asist-lng').value = '';
    document.getElementById('asist-accuracy').value = '';
  }
  if (!navigator.geolocation) {
    info.style.background = '#fef2f2';
    info.style.borderColor = '#fecaca';
    info.style.color = '#991b1b';
    info.textContent = '⚠ El navegador no soporta geolocalización.';
    return;
  }
  info.style.background = '#eff6ff';
  info.style.borderColor = '#93c5fd';
  info.style.color = '#1e40af';
  const highAcc = opts._retry ? false : true;
  info.textContent = opts._retry
    ? '⏳ Reintentando con precisión reducida (WiFi/IP)…'
    : '⏳ Detectando ubicación… (permite el acceso si el navegador lo pide)';
  navigator.geolocation.getCurrentPosition((pos) => {
    const { latitude, longitude, accuracy } = pos.coords;
    ASIST_STATE.currentGeo = { lat: latitude, lng: longitude, accuracy, timestamp: pos.timestamp };
    document.getElementById('asist-lat').value = latitude;
    document.getElementById('asist-lng').value = longitude;
    document.getElementById('asist-accuracy').value = accuracy;
    info.style.background = '#f0fdf4';
    info.style.borderColor = '#bbf7d0';
    info.style.color = '#065f46';
    const acc = Math.round(accuracy);
    info.innerHTML = `✓ Ubicación capturada · <b>${latitude.toFixed(6)}, ${longitude.toFixed(6)}</b> · precisión ±${acc}m
      <a href="https://maps.google.com/?q=${latitude},${longitude}" target="_blank" rel="noopener" style="margin-left:8px;color:#065f46;font-weight:800;text-decoration:underline">🗺 ver en mapa</a>`;
  }, (err) => {
    // Fallback: si la primera falla (típico code 2 en desktop sin GPS), intenta con precisión baja.
    if (!opts._retry && (err.code === 2 || err.code === 3)) {
      return asistCaptureGeo({ _retry: true });
    }
    let msg = '', hint = '';
    if (err.code === 1) {
      msg = 'Permiso denegado.';
      hint = 'En Chrome: clic en el candado 🔒 al lado de la URL → Configuración del sitio → Ubicación → Permitir. Luego recarga.';
    } else if (err.code === 2) {
      msg = 'Ubicación no disponible.';
      // Chrome/Safari desktop en macOS necesitan Wi-Fi ENCENDIDO para triangular
      // (usan escaneo de redes WiFi cercanas), incluso si estás por Ethernet.
      // Este es el caso #1 de fallo cuando permisos están OK.
      hint = 'Causa más común en Mac/PC de escritorio: <b>Wi-Fi apagado</b>. Enciende Wi-Fi aunque uses Ethernet — macOS triangula por redes WiFi cercanas. Alternativas: (a) en Chrome, revisa 🔒 → Configuración del sitio → Ubicación = "Permitir"; (b) desactiva VPN si tienes; (c) reinicia Chrome tras cambios de permisos.';
    } else if (err.code === 3) {
      msg = 'Tiempo agotado detectando ubicación.';
      hint = 'La red o el GPS tardaron demasiado en responder.';
    } else {
      msg = err.message || 'Error desconocido';
    }
    info.style.background = '#fef2f2';
    info.style.borderColor = '#fecaca';
    info.style.color = '#991b1b';
    info.innerHTML = `⚠ <b>${esc(msg)}</b>${hint ? `<div style="font-weight:500;margin-top:4px;font-size:11px">${hint}</div>` : ''}
      <div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap">
        <button type="button" onclick="asistCaptureGeo()" style="font-size:11px;padding:4px 10px;border-radius:6px;border:1px solid #fca5a5;background:#fff;color:#991b1b;font-weight:800;cursor:pointer">↻ Reintentar</button>
        <button type="button" onclick="asistContinuarSinGeo()" style="font-size:11px;padding:4px 10px;border-radius:6px;border:1px solid #cbd5e1;background:#fff;color:#475569;font-weight:800;cursor:pointer">Continuar sin ubicación</button>
      </div>`;
  }, { enableHighAccuracy: highAcc, timeout: highAcc ? 12000 : 20000, maximumAge: highAcc ? 0 : 60000 });
}
window.asistCaptureGeo = asistCaptureGeo;

/** Permite guardar el registro sin ubicación (para dispositivos sin GPS/permiso). */
