async function inqUploadFile_(kind, file) {
  // Base64 → POST /inquilinos/upload
  const dataUrl = await new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(r.result);
    r.onerror = reject;
    r.readAsDataURL(file);
  });
  const b64 = String(dataUrl || '').replace(/^data:[^;]*;base64,/, '');
  if (!b64) throw new Error('archivo vacío o ilegible');
  const iid = INQ_STATE.formData.ID || 'nuevo_' + Date.now();
  // Timeout cliente de 90s (Apps Script + Drive puede tardar). Si expira,
  // el placeholder se elimina y el usuario recibe un error visible en vez
  // de un spinner eterno.
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 90000);
  try {
    const resp = await fetch(`${BACKEND}/inquilinos/upload`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ inquilino_id: iid, filename: file.name || 'archivo', mime: file.type || 'application/octet-stream', data: b64, kind }),
      signal: controller.signal,
    });
    const j = await resp.json();
    if (!j.ok) throw new Error(j.error || 'upload failed');
    return j.file;
  } catch (err) {
    if (err.name === 'AbortError') throw new Error('timeout (>90s)');
    throw err;
  } finally { clearTimeout(timer); }
}

// Sube archivos con feedback visual: agrega un tile placeholder con spinner
// mientras el POST está en curso, y muestra un toast global "Subiendo N…".
// Al terminar reemplaza el placeholder con el archivo real (o lo elimina si falla).
async function inqAddFilesWithFeedback_(kind, fileList, targetArrayName, renderFn) {
  const files = Array.from(fileList || []);
  if (!files.length) return;
  // Push placeholders y captura sus refs para poder localizarlos después
  const placeholders = files.map(f => ({ _uploading: true, name: f.name || 'archivo', mime: f.type || '' }));
  placeholders.forEach(p => INQ_STATE.formData[targetArrayName].push(p));
  window.__inqUploadCount += files.length;
  inqShowUploadToast_();
  renderFn();
  // Subida en PARALELO (antes: secuencial ⇒ 2 archivos ≈ 40s de spinner en Aval).
  // Cloud Run + Apps Script + Drive tarda ~20s por archivo por cold-start; en
  // paralelo N archivos se completan en el tiempo del más lento, no la suma.
  await Promise.all(files.map(async (f, i) => {
    const ph = placeholders[i];
    try {
      const uploaded = await inqUploadFile_(kind, f);
      const idx = INQ_STATE.formData[targetArrayName].indexOf(ph);
      if (idx >= 0) INQ_STATE.formData[targetArrayName][idx] = uploaded;
    } catch (e) {
      const idx = INQ_STATE.formData[targetArrayName].indexOf(ph);
      if (idx >= 0) INQ_STATE.formData[targetArrayName].splice(idx, 1);
      alert('Error subiendo ' + (f.name || 'archivo') + ': ' + e.message);
    } finally {
      window.__inqUploadCount = Math.max(0, window.__inqUploadCount - 1);
      inqShowUploadToast_();
      renderFn();
    }
  }));
  inqHideUploadToastIfDone_();
}

