// Los 3 templates hardcoded (bienvenida/checkin/checkout) fueron removidos.
// Ahora la ÚNICA fuente de templates es la sección "Templates de mensajes
// programados" (hoja WA_Templates) cargada en WA_ADMIN.adminTemplates.
const WA_TEMPLATES = [];

function waFirstName_(b) {
  const cand = b && (
    b.GuestName || b.guest_name || b.Nombre || b.nombre ||
    b.nombre_reservacion || b['Nombre reservación'] || b['Nombre completo'] ||
    b['Nombre reservacion'] || b['Nombre'] || b['Name']
  );
  const full = String(cand || '').trim();
  return full.split(/\s+/)[0] || 'Huésped';
}
/** Extrae Propiedad + # Departamento del booking desde muchas rutas posibles. */
function waPropDept_(b) {
  if (!b) return { prop: '', dept: '' };
  const prop = String(
    b.PropertyName || b.property_name || b._propiedad || b.Propiedad ||
    b['Propiedad'] || b.propiedad || ''
  ).trim();
  const dept = String(
    b.RoomTypeName || b._departamento || b['# Departamento'] || b['Departamento'] ||
    b['# depto'] || b['depto'] || b.departamento || ''
  ).trim();
  return { prop, dept };
}
function waAlojamientoLabel_(b) {
  const { prop, dept } = waPropDept_(b);
  if (prop && dept) return `${prop} #${dept}`;
  if (prop || dept) return prop || dept;
  // Fallback: resolver por HouseId contra catálogo (Lodgify HouseName suele
  // venir vacío en el sync — el nombre real vive en la hoja alojamientos).
  try {
    if (typeof _pagosAlojName === 'function') {
      const n = _pagosAlojName(b);
      if (n && !/^HouseId /.test(n) && n !== '—') return n;
    }
  } catch(_){}
  return 'tu alojamiento';
}
/** Busca en el catálogo de alojamientos (WA_ADMIN.alojIdx) por Propiedad+Dept
 *  o por HouseId. Devuelve el row completo o null. */
function waFindAlojRow_(b) {
  const idx = (window.WA_ADMIN && WA_ADMIN.alojIdx) || null;
  if (!idx) return null;
  const houseId = String(
    (b && (b.HouseId || b.house_id || b.PropertyId || b.property_id ||
           b._houseId || b['HouseId'])) || ''
  ).trim();
  if (houseId && idx.byId[houseId]) return idx.byId[houseId];
  const { prop, dept } = waPropDept_(b);
  const key = (prop + '||' + dept).toLowerCase();
  return idx.byPropDept[key] || null;
}
function waGuiaUrl_(b) {
  const row = waFindAlojRow_(b);
  // Preferir url_guia real de la hoja alojamientos
  if (row && row.url_guia) return String(row.url_guia).trim();
  // Fallback: construir con HouseId si existe
  const id = row && row.HouseId ? String(row.HouseId).trim()
    : String((b && (b.HouseId || b.house_id || b.PropertyId || b.property_id)) || '').trim();
  return id ? `https://www.check-inn.mx/public/guia/?id=${encodeURIComponent(id)}` : 'https://www.check-inn.mx';
}
/** Precarga catálogo de alojamientos al primer uso. Se cachea en memoria. */
async function waEnsureAlojIndex_() {
  if (window.WA_ADMIN && WA_ADMIN.alojIdx) return WA_ADMIN.alojIdx;
  window.WA_ADMIN = window.WA_ADMIN || { config: {}, logs: {}, loading: new Set() };
  try {
    const r = await fetch('https://api.check-inn.mx/alojamientos-list');
    const j = await r.json();
    const rows = (j && j.rows) || [];
    const byId = {}, byPropDept = {};
    for (const a of rows) {
      const id = String(a.HouseId || '').trim();
      if (id) byId[id] = a;
      const p = String(a.Propiedad || '').trim().toLowerCase();
      const d = String(a['# Departamento'] || '').trim();
      if (p) byPropDept[p + '||' + d] = a;
    }
    WA_ADMIN.alojIdx = { byId, byPropDept, count: rows.length };
    return WA_ADMIN.alojIdx;
  } catch (e) {
    console.warn('[wa] alojamientos-list falló:', e.message);
    return null;
  }
}
function waBookingId_(b) {
  // ID único de la reserva. Diferentes contextos usan claves distintas.
  return String((b && (
    b.Id || b.id || b.ID || b.bookingId || b.booking_id ||
    b['ID'] || b['Booking ID'] || b['row_number'] || b['RowNumber']
  )) || '').trim();
}
/** Extrae solo la hora HH:MM formateada en 12h ("3:00 pm") de un valor que
 *  puede ser ISO de Sheets ("1899-12-31T01:41:16.000Z"), string libre
 *  ("3:00 pm"), o Date. */
function _waExtractHora(v) {
  if (v == null || v === '') return '';
  const s = String(v).trim();
  // ISO date-time (típico de celda TIME en Google Sheets → epoch 1899-12-31)
  const iso = s.match(/T(\d{1,2}):(\d{2})/);
  if (iso) {
    let h = parseInt(iso[1], 10);
    const m = iso[2];
    const ampm = h >= 12 ? 'pm' : 'am';
    h = h % 12; if (h === 0) h = 12;
    return `${h}:${m} ${ampm}`;
  }
  // Solo HH:MM o similares
  const hm = s.match(/^(\d{1,2}):(\d{2})(?:\s*(am|pm|AM|PM))?/);
  if (hm) {
    let h = parseInt(hm[1], 10);
    const m = hm[2];
    let ampm = (hm[3] || '').toLowerCase();
    if (!ampm) { ampm = h >= 12 ? 'pm' : 'am'; if (h > 12) h -= 12; }
    return `${h}:${m} ${ampm}`;
  }
  return s;
}
function waFechaHora_(iso, hora) {
  try {
    const d = iso ? new Date(iso + 'T00:00:00') : null;
    const meses = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
    const fecha = d ? `${d.getDate()} de ${meses[d.getMonth()]}` : '';
    const h = _waExtractHora(hora);
    return h ? `${fecha}, ${h}` : (fecha || 'próximo');
  } catch(_) { return 'próximo'; }
}
function waHoraSalida_(b) {
  const raw = b && (b.hu_HoraSalida || b.HoraSalida);
  const h = _waExtractHora(raw);
  return h || '12:00 pm';
}

/** Normaliza a formato E.164 canónico para Twilio (MX: siempre +521XXXXXXXXXX). */
function waNormalizePhoneE164_(raw) {
  let s = String(raw || '').replace(/[^\d+]/g, '');
  if (!s) return '';
  // Sin +: 10 dígitos → celular MX; 12 con 52 → agrega 1; 13 con 521 → OK
  if (!s.startsWith('+')) {
    if (s.length === 10) return '+521' + s;
    if (s.length === 12 && s.startsWith('52')) return '+521' + s.slice(2);
    if (s.length === 13 && s.startsWith('521')) return '+' + s;
    return '+' + s;
  }
  // Con +: si es +52XXXXXXXXXX (12 dígitos), agregar el 1 (móvil MX)
  if (/^\+52\d{10}$/.test(s)) return '+521' + s.slice(3);
  return s;
}
/** Devuelve la forma "amigable" para mostrar (sin el "1" técnico de MX). */
function waDisplayPhone_(raw) {
  const s = String(raw || '').replace(/^whatsapp:/, '');
  const m = s.match(/^\+521(\d{10})$/);
  if (m) return '+52 ' + m[1];
  return s;
}
/** True si dos números representan el mismo destino (ignora +52 vs +521). */
function waPhonesEqual_(a, b) {
  return waNormalizePhoneE164_(String(a||'').replace(/^whatsapp:/,'')) ===
         waNormalizePhoneE164_(String(b||'').replace(/^whatsapp:/,''));
}
/** Normaliza toda la lista a `whatsapp:+521...` y elimina duplicados
 *  ("+52X" y "+521X" son el mismo número). Preserva orden de aparición. */
function waDedupeRecipients_(list) {
  const out = [];
  const seenCanonical = new Set();
  for (const raw of (list || [])) {
    const s = String(raw || '').replace(/^whatsapp:/,'');
    const norm = waNormalizePhoneE164_(s);
    if (!norm) continue;
    if (seenCanonical.has(norm)) continue;
    seenCanonical.add(norm);
    out.push('whatsapp:' + norm);
  }
  return out;
}

function waRenderPreview_(bodyTemplate, vals) {
  return String(bodyTemplate).replace(/\{\{(\d+)\}\}/g, (_, n) => vals[n] || `{{${n}}}`);
}

function _waFmtDateEs(iso) {
  try {
    const d = iso ? new Date(iso + 'T00:00:00') : null;
    if (!d) return '';
    const meses = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
    return `${d.getDate()} ${meses[d.getMonth()]}`;
  } catch(_){ return ''; }
}
function _waTodayIso() {
  const d = new Date();
  const p = n => String(n).padStart(2,'0');
  return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`;
}
/** Calcula los próximos envíos automáticos previstos según fechas del booking. */
function _waNextAutoSends(b) {
  const arrival   = String(b.DateArrival || b.arrival || '').slice(0,10);
  const departure = String(b.DateDeparture || b.departure || '').slice(0,10);
  const hoy = _waTodayIso();
  const items = [];
  if (arrival && arrival > hoy) {
    // Recordatorio check-in se dispara el día ANTES a las 6pm.
    const d = new Date(arrival + 'T00:00:00'); d.setDate(d.getDate()-1);
    const isoDay = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
    items.push({ tipo: 'checkin', when: `${_waFmtDateEs(isoDay)} 6:00 pm`, isoDay });
  }
  if (departure && departure >= hoy) {
    // Recordatorio check-out se dispara el día de salida a las 8am.
    items.push({ tipo: 'checkout', when: `${_waFmtDateEs(departure)} 8:00 am`, isoDay: departure });
  }
  return items;
}

