/** Deduplica HU_STATE.rows por últimos 10 dígitos del celular, elige el
 *  row más reciente (mayor Fecha de ingreso) y arma el objeto persona. */
function personasBuildFromHu_() {
  const rows = (HU_STATE && Array.isArray(HU_STATE.rows)) ? HU_STATE.rows : [];
  const tail = (v) => { const s = String(v||'').replace(/\D/g,''); return s.length>=10 ? s.slice(-10) : ''; };
  const byPhone = new Map();
  const noPhone = [];
  for (const r of rows) {
    const p10 = tail(r['Cel/Whatsapp (principal)']);
    if (!p10) { noPhone.push(r); continue; }
    const cur = byPhone.get(p10);
    const dThis = String(r['Fecha de ingreso'] || '');
    if (!cur || dThis > String(cur['Fecha de ingreso'] || '')) byPhone.set(p10, r);
  }
  // Nombre canónico prefiriendo el de Perfiles vía BOTC_STATE.conversations.
  const perfilNameByPhone = new Map();
  try {
    if (typeof BOTC_STATE === 'object' && BOTC_STATE && Array.isArray(BOTC_STATE.conversations)) {
      BOTC_STATE.conversations.forEach(c => { if (c && c.phone && c.name) perfilNameByPhone.set(String(c.phone), String(c.name).trim()); });
    }
  } catch(_){}
  const _pickName = (r, p10) => {
    const perf = p10 ? perfilNameByPhone.get(p10) : '';
    if (perf) return perf;
    const cands = [
      r['Nombre del huésped'],
      String(r['Nombres de TODOS los huéspedes (separados por comas)']||'').split(',')[0],
      r['Nombre de la persona que hizo la reservación'],
    ];
    const PLC = new Set(['falta el nombre del huésped','falta el nombre del huesped','sin nombre','n/a','na','-','—']);
    for (const c of cands) { const v = String(c||'').trim(); if (v && !PLC.has(v.toLowerCase())) return v; }
    return '';
  };
  const arr = [];
  const push = (p10, r) => {
    const kpis = (window.__perfilKpisByPhone || {})[p10] || {};
    let stats = null;
    if (kpis && (kpis.noches || kpis.visitas || kpis.monto)) {
      stats = { totalNoches: Number(kpis.noches)||0, visitas: Number(kpis.visitas)||0, montoTotal: Number(kpis.monto)||0, montoGlobal: Number(kpis.monto)||0, __source:'perfiles-cache' };
    } else if (typeof huComputeGuestStats === 'function') {
      try { stats = huComputeGuestStats(r, rows); } catch(_){ stats = null; }
    }
    const score = (stats && typeof huComputeLoyaltyScore === 'function') ? huComputeLoyaltyScore(stats) : 0;
    // Prefiere kpi_clasificacion persistido del Apps Script; fallback al
    // cálculo de tier local. Si el backend ya lo escribió, ese label es
    // la fuente de verdad (elimina posible desfase entre frontend/backend).
    let tier = null;
    const persisted = String(kpis.clasificacion || '').trim();
    if (persisted && typeof huGuestTier === 'function') {
      // Reconstruye el chip usando huGuestTier con score/stats reales para
      // mantener colores/ícono, pero fuerza el label persistido.
      tier = huGuestTier(score, stats);
      if (tier && tier.label !== persisted) tier.label = persisted;
      // Si no hubo tier local pero el backend sí clasificó, sintetiza uno.
      if (!tier) tier = { score, label: persisted, icon: '⭐', bg:'#f1f5f9', fg:'#334155', border:'#cbd5e1', tooltip:`${persisted} (persistido)` };
    } else {
      tier = (stats && typeof huGuestTier === 'function') ? huGuestTier(score, stats) : null;
    }
    arr.push({
      phone10: p10,
      row: r,
      nombre: _pickName(r, p10) || 'Sin nombre',
      email:  String(r['Correo electrónico'] || '').trim(),
      celular: String(r['Cel/Whatsapp (principal)'] || '').trim(),
      rfc:    String(r['RFC'] || '').trim(),
      razonSocial: String(r['Razón social'] || r['Razon social'] || '').trim(),
      regimenFiscal: String(r['Régimen fiscal'] || r['Regimen fiscal'] || '').trim(),
      requiereFactura: String(r['¿Requiere factura?'] || '').trim(),
      vehMarca:  String(r['Vehículo marca']  || r['Marca del vehículo']  || '').trim(),
      vehModelo: String(r['Vehículo modelo'] || r['Modelo del vehículo'] || '').trim(),
      vehPlacas: String(r['Placas'] || r['Placas del vehículo'] || '').trim(),
      vehColor:  String(r['Color'] || r['Color del vehículo'] || '').trim(),
      stats, score, tier,
    });
  };
  byPhone.forEach((r, p10) => push(p10, r));
  noPhone.forEach(r => push('', r));
  arr.sort((a,b) => String(a.nombre||'').localeCompare(String(b.nombre||''), 'es'));
  arr.forEach(personasClasificar_);
  PERSONAS_STATE.personas = arr;
  PERSONAS_STATE.loaded = true;
}

window.personasSetView = function(v) {
  PERSONAS_STATE.view = v;
  const bC = document.getElementById('personas-view-cards');
  const bT = document.getElementById('personas-view-tabla');
  if (bC) bC.setAttribute('style', bC.getAttribute('style').replace(/background:[^;]*/, 'background:'+(v==='cards'?'#0f172a':'transparent')).replace(/color:[^;]*/, 'color:'+(v==='cards'?'#fff':'#475569')));
  if (bT) bT.setAttribute('style', bT.getAttribute('style').replace(/background:[^;]*/, 'background:'+(v==='tabla'?'#0f172a':'transparent')).replace(/color:[^;]*/, 'color:'+(v==='tabla'?'#fff':'#475569')));
  personasRender();
};
window.personasSetSearch = function(s) {
  PERSONAS_STATE.search = String(s||'').trim().toLowerCase();
  personasRender();
};

function personasFilter_() {
  const q = PERSONAS_STATE.search;
  const all = PERSONAS_STATE.personas || [];
  const norm = v => String(v||'').toLowerCase();
  const passSearch = (p) => !q ||
    norm(p.nombre).includes(q) || norm(p.email).includes(q) ||
    norm(p.celular).includes(q) || norm(p.rfc).includes(q) ||
    norm(p.razonSocial).includes(q) || norm(p.vehPlacas).includes(q);
  const passMulti = (p) => {
    const regSet = PERSONAS_MULTI.multiSel.regimen;
    if (regSet && regSet.size !== personasMultiGetOptions('regimen').length) {
      if (!regSet.has(p.regimenFiscal || '')) return false;
    }
    const reqSet = PERSONAS_MULTI.multiSel.requiere_factura;
    if (reqSet && reqSet.size !== personasMultiGetOptions('requiere_factura').length) {
      if (!reqSet.has(p.requiereFactura || '')) return false;
    }
    const claSet = PERSONAS_MULTI.multiSel.clasificacion;
    if (claSet && claSet.size !== personasMultiGetOptions('clasificacion').length) {
      if (!(p.clasifs || [(p.tier && p.tier.label) || '']).some(v => claSet.has(v))) return false;
    }
    return true;
  };
  return all.filter(p => passSearch(p) && passMulti(p));
}

// ═══════════════════════════════════════════════════════════════════════════
// ║ Filtros multi-select para módulo Huéspedes/Inquilinos (module-personas). ║
// ║ Client-side, permanecen abiertos al marcar, cierran al click fuera.      ║
// ║ Reutilizan CSS .lg-multi-* de Gestión de reservas.                      ║
// ═══════════════════════════════════════════════════════════════════════════
const PERSONAS_MULTI = { multiSel: {}, multiOpen: {} };
const PERSONAS_MULTI_LABELS = {
  regimen: 'Régimen fiscal',
  requiere_factura: '¿Requiere factura?',
  clasificacion: 'Clasificación',
};

function personasMultiGetOptions(key) {
  const arr = PERSONAS_STATE.personas || [];
  const set = new Set();
  if (key === 'regimen') arr.forEach(p => { const v = String(p.regimenFiscal||'').trim(); if (v) set.add(v); });
  else if (key === 'requiere_factura') arr.forEach(p => { const v = String(p.requiereFactura||'').trim(); if (v) set.add(v); });
  else if (key === 'clasificacion') arr.forEach(p => (p.clasifs || [p.tier && p.tier.label]).forEach(v => { v = String(v || '').trim(); if (v) set.add(v); }));
  return Array.from(set).sort();
}

function personasMultiInit(key) {
  // Si el filtro se creó antes de que llegaran los huéspedes (sin opciones),
  // quedaba vacío = "Ninguno" y ocultaba a todos. Se re-inicia a "Todos".
  const sinOpc = PERSONAS_MULTI.vacio && PERSONAS_MULTI.vacio[key];
  if (PERSONAS_MULTI.multiSel[key] instanceof Set && !sinOpc) return;
  const opts = personasMultiGetOptions(key);
  PERSONAS_MULTI.multiSel[key] = new Set(opts);
  (PERSONAS_MULTI.vacio = PERSONAS_MULTI.vacio || {})[key] = !opts.length;
}

function personasMultiRender(key, label) {
  const cont = document.getElementById(`personas-multi-${key}`);
  if (!cont) return;
  personasMultiInit(key);
  const allValues = personasMultiGetOptions(key);
  const sel = PERSONAS_MULTI.multiSel[key];
  const total = allValues.length;
  const selCount = sel.size;
  const labelTxt = selCount === total ? `Todos (${total})`
                 : selCount === 0     ? 'Ninguno'
                 : selCount === 1     ? [...sel][0]
                 : `${selCount} de ${total}`;
  const renderOption = (v) => `
    <label class="lg-multi-opt">
      <input type="checkbox" class="lg-multi-cb" value="${esc(v)}" ${sel.has(v)?'checked':''}
             onchange="personasMultiToggle('${key}', this.value)">
      <span class="lg-multi-opt-txt">${esc(v)}</span>
    </label>`;
  const isOpen = !!PERSONAS_MULTI.multiOpen[key];
  cont.innerHTML = `
    <label style="display:block;font-size:11px;color:#64748b;font-weight:700;text-transform:uppercase;letter-spacing:.04em;margin-bottom:4px">${esc(label)}</label>
    <div class="lg-multi-wrap personas-multi-wrap">
      <button type="button" onclick="personasMultiTogglePanel('${key}',event)"
              id="personas-multi-btn-${key}" class="lg-multi-btn">
        <span class="lg-multi-btn-lbl" id="personas-multi-lbl-${key}">${esc(labelTxt)}</span>
        <span class="lg-multi-btn-caret">▾</span>
      </button>
      <div id="personas-multi-panel-${key}" class="lg-multi-panel ${isOpen?'':'hidden'}" onclick="event.stopPropagation()">
        <div class="lg-multi-actions">
          <button type="button" onclick="event.stopPropagation();personasMultiSetAll('${key}')" class="lg-multi-action">✓ Todos</button>
          <button type="button" onclick="event.stopPropagation();personasMultiSetNone('${key}')" class="lg-multi-action">✕ Ninguno</button>
        </div>
        <div class="lg-multi-options">
          ${allValues.length ? allValues.map(renderOption).join('') : '<div style="padding:6px 8px;color:#94a3b8;font-size:12px;font-style:italic">Sin valores</div>'}
        </div>
      </div>
    </div>`;
}

function personasBuildFilters() {
  const cont = document.getElementById('personas-filters');
  if (!cont) return;
  cont.innerHTML = `
    <div id="personas-multi-regimen"></div>
    <div id="personas-multi-requiere_factura"></div>
    <div id="personas-multi-clasificacion"></div>`;
  personasMultiRender('regimen',          PERSONAS_MULTI_LABELS.regimen);
  personasMultiRender('requiere_factura', PERSONAS_MULTI_LABELS.requiere_factura);
  personasMultiRender('clasificacion',    PERSONAS_MULTI_LABELS.clasificacion);
}

window.personasMultiTogglePanel = function(key, ev) {
  if (ev) ev.stopPropagation();
  Object.keys(PERSONAS_MULTI.multiOpen).forEach(k => {
    if (k !== key) {
      PERSONAS_MULTI.multiOpen[k] = false;
      const op = document.getElementById(`personas-multi-panel-${k}`);
      if (op) op.classList.add('hidden');
    }
  });
  const p = document.getElementById(`personas-multi-panel-${key}`);
  const willOpen = p ? p.classList.contains('hidden') : !PERSONAS_MULTI.multiOpen[key];
  PERSONAS_MULTI.multiOpen[key] = willOpen;
  if (p) p.classList.toggle('hidden', !willOpen);
};

window.personasMultiToggle = function(key, value) {
  const set = PERSONAS_MULTI.multiSel[key];
  if (!set) return;
  if (set.has(value)) set.delete(value); else set.add(value);
  const opts = personasMultiGetOptions(key);
  const lbl = document.getElementById(`personas-multi-lbl-${key}`);
  if (lbl) {
    lbl.textContent = set.size === opts.length ? `Todos (${opts.length})`
                    : set.size === 0 ? 'Ninguno'
                    : set.size === 1 ? [...set][0]
                    : `${set.size} de ${opts.length}`;
  }
  try { personasRender(); } catch(_) {}
};

window.personasMultiSetAll = function(key) {
  PERSONAS_MULTI.multiSel[key] = new Set(personasMultiGetOptions(key));
  personasMultiRender(key, PERSONAS_MULTI_LABELS[key]);
  PERSONAS_MULTI.multiOpen[key] = true;
  const p = document.getElementById(`personas-multi-panel-${key}`);
  if (p) p.classList.remove('hidden');
  try { personasRender(); } catch(_) {}
};

window.personasMultiSetNone = function(key) {
  PERSONAS_MULTI.multiSel[key] = new Set();
  personasMultiRender(key, PERSONAS_MULTI_LABELS[key]);
  PERSONAS_MULTI.multiOpen[key] = true;
  const p = document.getElementById(`personas-multi-panel-${key}`);
  if (p) p.classList.remove('hidden');
  try { personasRender(); } catch(_) {}
};

if (!window.__personasMultiOutsideClickBound) {
  window.__personasMultiOutsideClickBound = true;
  document.addEventListener('click', function(e) {
    if (!e.target.closest('.personas-multi-wrap')) {
      let changed = false;
      Object.keys(PERSONAS_MULTI.multiOpen).forEach(k => {
        if (PERSONAS_MULTI.multiOpen[k]) { PERSONAS_MULTI.multiOpen[k] = false; changed = true; }
      });
      if (changed) document.querySelectorAll('.personas-multi-wrap .lg-multi-panel').forEach(p => p.classList.add('hidden'));
    }
  });
}

function personasRender() {
  const st = dxSearchSave_('personas-search');
  _personasRenderCore();
  dxSearchMount_(document.getElementById('personas-container'), 'personas-search', st);
}
function _personasRenderCore() {
  huReglasRender_();
  const cont = document.getElementById('personas-container');
  const lbl  = document.getElementById('personas-status-label');
  if (!cont) return;
  // Asegura que el panel de filtros exista o esté actualizado con las
  // opciones vigentes (cada re-render usa las clases/valores actuales).
  try {
    const filt = document.getElementById('personas-filters');
    if (filt && !document.getElementById('personas-multi-regimen')) {
      personasBuildFilters();
    } else if (filt) {
      personasMultiRender('regimen',          PERSONAS_MULTI_LABELS.regimen);
      personasMultiRender('requiere_factura', PERSONAS_MULTI_LABELS.requiere_factura);
      personasMultiRender('clasificacion',    PERSONAS_MULTI_LABELS.clasificacion);
    }
  } catch(_) {}
  if (!PERSONAS_STATE.loaded) {
    cont.innerHTML = '<div style="text-align:center;padding:60px;color:#94a3b8;font-size:13px">⏳ Cargando personas…</div>';
    return;
  }
  const rows = personasFilter_();
  if (lbl) lbl.textContent = `${rows.length} persona${rows.length===1?'':'s'} ${PERSONAS_STATE.search ? ' (filtrado)' : ''}`;
  if (!rows.length) {
    cont.innerHTML = '<div style="text-align:center;padding:60px;color:#94a3b8;font-size:13px">Sin resultados.</div>';
    return;
  }
  if (PERSONAS_STATE.view === 'tabla') cont.innerHTML = personasRenderTabla_(rows);
  else cont.innerHTML = personasRenderCards_(rows);
}

