  const fantasma = !!g.fantasma || (esHoyC && !esCopia && g.sal.length && !vivosEnt && selE === 'pendiente' && horaMx >= 15);
  const nsChip = xs && esHoyC && !esCopia ? aseoNoSaleChip_(xs.b.Id, g.hid) : '';
