      <div class="sn-chips" style="margin:0">${SN_IA_EJEMPLOS.map((x, i) => `<button class="sn-chip" style="font-weight:600;text-align:left" onclick="snIaEj_(${i})">${snEsc_(x)}</button>`).join('')}</div>
