window.icVerTarea_ = async function (lig) {
  const id = String(lig || '').slice(1);
  if (lig[0] === 'T') { const t = (ASEO.tareas || {})[id]; if (!t) return alert('La tarea aún se está cargando; intenta en unos segundos.'); IC.dr = null; atAbrir_(id, t.fecha); return; }
  if (!(ASEO.rt || []).some(r => String(r.ID) === id) && typeof adRtLoad_ === 'function') await adRtLoad_(true);
  const row = (ASEO.rt || []).find(r => String(r.ID) === id); if (!row) return alert('No se encontró el reporte técnico.');
  IC.dr = null; rtAbrirA_(id, String(row.Fecha || '').slice(0, 10) || aseoHoyIso_());
};
async function icLevantar_(F, incId) {
  const L = F.L, r = (INC_STATE.list || []).find(x => String(x.ID) === String(incId)) || {};
  const fotos = icSplit_(r.Fotos_URLs).filter(u => /\/incidencias\/foto\?/.test(u));
  const user = (typeof currentUser !== 'undefined' && currentUser) || '';
  const titulo = String(L.titulo != null ? L.titulo : icLevTitDef_(F)).trim() || icLevTitDef_(F);
  const desc = String(L.desc != null ? L.desc : icLevDescDef_(F, incId)).trim();
  const post = (u, b) => fetch(`${BACKEND}${u}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(b) }).then(r => r.json());
  let lig;
  if (L.depto === 'mantenimiento') {
    const a = atAloj_(F.hid);
    const payload = { Fecha: F.fecha, Estado: 'nuevo', Prioridad: F.prio, Tipo: 'correctivo', Categoria: L.cat || 'otros', Propiedad: a.propiedad || '', '# Departamento': a.depto || '',
      Alojamiento: a.propiedad ? `${a.propiedad} - #${a.depto}` : (a.nombre || ''), Activo: '', Titulo: titulo, Descripcion: desc, Descripcion_solucion: '', Reportado_por: F.rep || user,
      Asignado_a: L.asig.join(', '), Proveedor: '', Fecha_compromiso: L.comp || '', Bloquea_habitabilidad: !!L.bloq, Reincidente: !!L.rein, Responsabilidad: 'indeterminada', Costo_total: '', Cargar_a_huesped: false,
      Reservacion_id: F.reserva || '', Huesped_nombre: F.reserva ? (F.huesped || '') : '', Notas: '', Fotos_antes_urls: fotos.join(', '), UpdatedAt: new Date().toISOString(), Updated_by: user };
    const j = await post('/reportes-tecnicos-upsert', { payload });
    if (!j.ok) throw new Error(j.error || 'Error al crear el reporte técnico');
    const rid = String(j.id); lig = 'R' + rid;
    ASEO.rt = ASEO.rt || []; ASEO.rt.unshift(Object.assign({ Timestamp: new Date().toISOString() }, payload, { ID: rid, Folio: j.folio || rid }));
    setTimeout(() => { try { adRtLoad_(true); } catch (_) {} }, 1500);
  } else {
    const adjuntos = fotos.map((u, i) => ({ k: new URL(u).searchParams.get('k'), nombre: `Foto de la incidencia ${i + 1}`, tipo: 'image/jpeg', tam: 0 }));
    const tarea = { hid: F.hid, depto: L.depto, problema: !!L.problema, prioridad: F.prio, titulo, desc, fecha: F.fecha, hora: '', repite: L.repite, asignados: L.asig, etiquetas: L.etiq, adjuntos, reserva: F.reserva || '' };
    const j = await post('/aseo/tarea', { tarea, user });
    if (!j.ok) throw new Error(j.error || 'Error al crear la tarea');
    (ASEO.tareas = ASEO.tareas || {})[j.tarea.id] = j.tarea; lig = 'T' + j.tarea.id;
    if (typeof aseoRefresh_ === 'function') setTimeout(() => aseoRefresh_().catch(() => {}), 1200); // enlaces firmados de los adjuntos
  }
  axSet_(lig, Object.assign(axSrvPatch_(L.srv), { incidencia: true, incId: String(incId), incIds: [String(incId)], deInc: true }), F.hid);
  r.Tarea_ligada = icLigs_(r).concat(lig).join(', '); // se suma a los reportes ya levantados
  await post('/update-incidencia', { id: incId, user, fields: { tarea: r.Tarea_ligada } }).catch(() => null);
}
window.icDesarchivar_ = function (id) {
  const r = axIncRow_(id); if (!r) return;
  const hid = rtHid_(r);
  icPatch_(id, { archivada: '' }, { Archivada: '' });
  icLigs_(r).forEach(l => axSet_(l, { archivada: false, incidencia: true, incId: String(id), incIds: [String(id)] }, hid)); // las tareas vuelven al tablero
  if (r.Card_origen) axIncLigar_(String(r.Card_origen), hid, id, true); // y la card de origen recupera la marca
};
// ── «Historial de cambios» al final de las ventanas de cards (aseo, tareas, mantenimiento, incidencias) ──
// Servidor: GET /historial?k=A:…,T:…,R:…,I:… (quién cambió qué y cuándo).
const HIST = { cache: {}, abiertos: new Set() };
function histSecHtml_(keys) {
  const k = [...new Set((keys || []).filter(x => x && !/:$/.test(x)))].join(',');
  if (!k) return '';
  const ab = HIST.abiertos.has(k), c = HIST.cache[k];
  return `<details class="ad-res ad-hist" data-k="${pcEsc(k)}" ${ab ? 'open' : ''} ontoggle="histToggle_(this)"><summary>Historial de cambios</summary><div class="hist-box">${ab && c ? histListaHtml_(c.items) : '<div class="ad-hint">⏳ Cargando historial…</div>'}</div></details>`;
}
window.histToggle_ = async function (el) {
  const k = el.dataset.k;
  if (!el.open) { HIST.abiertos.delete(k); return; }
  HIST.abiertos.add(k);
  const c = HIST.cache[k];
  if (c && Date.now() - c.ts < 20_000) { el.querySelector('.hist-box').innerHTML = histListaHtml_(c.items); return; }
  try {
    const j = await fetch(`${BACKEND}/historial?k=${encodeURIComponent(k)}`, { cache: 'no-store' }).then(r => r.json());
    if (!j.ok) throw new Error(j.error || 'Error');
    HIST.cache[k] = { ts: Date.now(), items: j.items || [] };
    document.querySelectorAll(`#ad-drawer details.ad-hist[data-k="${CSS.escape(k)}"] .hist-box`).forEach(b => { b.innerHTML = histListaHtml_(j.items || []); });
  } catch (e) { el.querySelector('.hist-box').innerHTML = `<div class="ad-hint" style="color:#dc2626">No se pudo cargar: ${pcEsc(e.message || e)}</div>`; }
};
function histListaHtml_(L) {
  if (!L.length) return '<div class="ad-hint">Sin cambios registrados todavía.</div>';
  const f = iso => { const d = new Date(iso); return isNaN(d) ? '' : d.toLocaleString('es-MX', { day: 'numeric', month: 'short', hour: 'numeric', minute: '2-digit' }); };
  return `<div class="hist-list">${L.slice(0, 150).map(h => `<div class="hist-it"><div class="hist-h">${pcEsc(f(h.at))}${h.by ? ' · ' + pcEsc(h.by) : ''}</div><div><b>${pcEsc(h.campo || '')}</b>: ${h.antes ? `<s>${pcEsc(String(h.antes).slice(0, 120))}</s> → ` : ''}${pcEsc(String(h.despues || '—').slice(0, 160))}</div></div>`).join('')}</div>`;
}
